import { AnSaveData } from 'angine/utils/AnStorage.js';
import { PlatformInterface, PlatformBase, PlatformAds, PlatformAdsCallbacks, PlatformEvent } from './Platform.js';
import { AnLog } from 'angine/utils/AnLog.js';


export class PlatformY8 extends PlatformBase implements PlatformInterface
{


	async init(): Promise<void>
	{
		// @ts-ignore
		if (!window.adsbygoogle)
			throw new Error('[Y8 SDK] не загружен, произошла ошибка!');

		
		//await this.waitForY8SdkReady();

		this._initialized = true;
		AnLog.info('[Y8 SDK] успешно загружен и проинициализирован');
	}

	// Функция, которая возвращает промис, ожидающий появления window.y8SdkReady
	private async waitForY8SdkReady():Promise<void>
	{
		return new Promise((resolve) =>
		{
			// Проверяем каждые 100 мс, появилась ли переменная
			const interval = setInterval(() =>
			{
				// @ts-ignore
				if (window.y8SdkReady)
				{
					clearInterval(interval); // Останавливаем проверку
					resolve(); // Разрешаем промис
				}
			}, 100);
		});
	}


	// модификация параметров игры исходя из платформы
	public modifyGameParams(G: any): void
	{
		super.modifyGameParams(G);

		G.moreGamesURL = "";
		G.btnDoubleReward = true;
		G.btnMoreMoves = true;
		G.musicStreaming = false;

	};

	// === Реклама ===
	private get adsAvailable()
	{
		return Boolean(
			// @ts-ignore
			window.adsbygoogle &&
			// @ts-ignore
			window.y8SdkReady
		);
	}

	public showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks): void
	{
		super.showAds(type, callbacks);

		if (!this.adsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug('[Y8 SDK] реклама не доступна');
			callbacks.onError?.();
			return;
		}

		// @ts-ignore
		const ads = window.adsbygoogle as any;
		
		switch (type)
		{
			case PlatformAds.Fullscreen:

				ads.push(
					{
						type: 'start', // ad shows at start of next level
						name: 'start-game',
						beforeAd: () => callbacks.onOpen?.(),
						afterAd: () => undefined,
						adBreakDone: (info : { breakStatus : string}) =>
						{
							if (info.breakStatus !== 'viewed' && info.breakStatus !== 'dismissed')
								callbacks.onError?.();
							else
								callbacks.onClose?.();
						}
					}
				);
				// this.sdk!.adv.showFullscreenAdv({
				// 	callbacks: {
				// 		onOpen: () => callbacks.onOpen?.(),
				// 		onClose: () => callbacks.onClose?.(),
				// 		onError: () => callbacks.onError?.(),
				// 		onOffline: () => callbacks.onError?.(),
				// 	}
				// });
				break;
			case PlatformAds.Rewarded:

				ads.push(
					{
						type: 'reward',
						name: 'rewarded Ad',
						beforeAd: () => callbacks.onOpen?.(),
						afterAd: () => undefined,
						beforeReward: (showAdFn: Function) => showAdFn(0),
						adDismissed: () => callbacks.onClose?.(),
						adViewed: () => callbacks.onCloseRewarded?.(),
						adBreakDone: (info: { breakStatus: string }) =>
						{
							if (info.breakStatus !== 'viewed' && info.breakStatus !== 'dismissed')
									callbacks.onError?.();
						}
					}
				);
				// {
				// 	let rewarded = false;
				// 	this.sdk!.adv.showRewardedVideo({
				// 		callbacks: {
				// 			onOpen: () => callbacks.onOpen?.(),
				// 			onError: () => callbacks.onError?.(),

				// 			onClose: () =>
				// 			{
				// 				if (rewarded)
				// 					callbacks.onCloseRewarded?.();
				// 				else
				// 					callbacks.onClose?.();
				// 			},

				// 			onRewarded: () => rewarded = true,
				// 		}
				// 	});
				// }
				break;
		}

	}
}

