
import { Field, GridPos, CellSize } from "./Field.js";
import { PIXI } from "angine/singleton.js";
import { AnUIElement, AnUIElementConfig } from "angine/ui/AnUIElement.js";
import { AnViewport } from "angine/core/AnViewport.js";
import { AnUpdatableMixin, AnUpdatableInterface } from "angine/mixins/AnUpdatableMixin.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { enhance, safeDestroy, safeDestroyFunc } from "angine/utils/AnHelpers.js";
import { DropShadowFilter } from "pixi-filters";
import { KawaseBlurFilter } from "pixi-filters";
import { AnLog } from "angine/utils/AnLog.js";

/** Конфигурация для компонента UIFocus */
export interface UIFocusConfig extends AnUIElementConfig
{
	rows: number,
	cols: number,

	//сдвиг пресета, который нужно учитывать
	startPresetCol?: number,

	/** Ячейки, которые должны оставаться незатемненными */
	focusCells?: GridPos[];
	/** Цвет затемнения (по умолчанию серый) */
	backgroundColor?: number;
	/** Прозрачность затемнения (по умолчанию 0.7) */
	backgroundAlpha?: number;
	/** Сила размытия (по умолчанию 4) */
	blurStrength?: number;
	/** Использовать тень вместо/вместе с размытием */
	useDropShadow?: boolean;
}

/**
 * Класс UIFocus - выделяет определенные ячейки на игровом поле, 
 * затемняя все остальные области серым цветом с размытием.
 * 
 * Используется для привлечения внимания к определенным ячейкам.
 */
export class UIFocus
	extends enhance(AnUIElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{

	private grayOverlay: PIXI.Graphics;
	private _focusCells: GridPos[];
	private startPresetCol: number;

	constructor(config: UIFocusConfig)
	{
		config.anchor = config.anchor ?? AnAnchor.TopLeft;
		super(config);



		// === Создаём затемнённый оверлей ===
		this.grayOverlay = new PIXI.Graphics();
		this.addToCleanup(safeDestroyFunc(this.grayOverlay));

		// Рисуем прямоугольник на весь экран
		// this.grayOverlay.rect(0, 0, config.realWidth, config.realHeight);
		// this.grayOverlay.fill({
		// 	color: config.backgroundColor ?? 0x000000,
		// 	alpha: config.backgroundAlpha ?? 0.7
		// });

		// Инициализируем фокусные ячейки
		this._focusCells = config.focusCells ?? [];

		// сдвиг пресета если есть
		this.startPresetCol = config.startPresetCol ?? 0;

		// Проходим по всем ячейкам
		for (let row = 0; row < config.rows; row++)
		{
			for (let col = 0; col < config.cols; col++)
			{
				// Проверяем, является ли ячейка фокусной
				const isFocused = this._focusCells.some(fc => fc.row === row && fc.col + this.startPresetCol === col);

				if (!isFocused)
				{
					// Рисуем затемнённую ячейку
					this.grayOverlay.rect(col * CellSize, row * CellSize, CellSize, CellSize);
					this.grayOverlay.fill({
						color: config.backgroundColor ?? 0x000000,
						alpha: config.backgroundAlpha ?? 0.7
					});
				}
				// Фокусные ячейки остаются пустыми (прозрачными)
			}
		}



		// === Применяем фильтры (размытие или тень) ===
		const filters: PIXI.Filter[] = [];

		if (config.blurStrength || config.useDropShadow)
		{
			if (config.blurStrength)
			{
				const blurFilter = new KawaseBlurFilter();
				blurFilter.strength = config.blurStrength;
				blurFilter.quality = 2;
				filters.push(blurFilter);
			}

			if (config.useDropShadow)
			{
				const shadowFilter = new DropShadowFilter({
					alpha: 0.7,
					blur: 2,
					color: 0x222222
				});
				filters.push(shadowFilter);
			}

			this.grayOverlay.filters = filters;
		}

		// Добавляем оверлей в контейнер
		this.addGraphics(this.grayOverlay);


		this.cacheAsTexture({ resolution: 0.25, antialias: true });
	}

	public get focusCells(): GridPos[]
	{
		return this._focusCells;
	}


	/**
	 * Полностью очищает фокус (всё затемнено)
	 */
	public clearFocus(): void
	{
		this._focusCells = [];
	}

	/**
	 * Проверяет, попал ли клик в незатемнённую область
	 */
	public isPointInFocus(x: number, y: number): boolean
	{
		return this._focusCells.some(cell =>
			x >= (cell.col + this.startPresetCol) * CellSize &&
			x < (cell.col + this.startPresetCol + 1) * CellSize &&
			y >= cell.row * CellSize &&
			y < (cell.row + 1) * CellSize
		);
	}

	public isPosInFocus(pos: GridPos): boolean
	{
		return this._focusCells.some(cell =>
			cell.row === pos.row && (cell.col + this.startPresetCol) === pos.col
		);
	}



}