import { Default, PIXI } from "angine/singleton";
import { AnUIElement, AnUIElementConfig, AnUIResizeStrategyFunc } from "angine/ui/AnUIElement";
import { AnUI } from "angine/ui/AnUI";
import { notImplemented, safeDestroyFunc } from "angine/utils/AnHelpers";
import { AnViewport } from "angine/core/AnViewport";
import { AnInterpolator } from "angine/anim/AnInterpolator";
import { AnInterpolation } from "angine/anim/AnInterpolation";
import { enhance } from '../utils/AnHelpers';
import { AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";
import { AnAnchor } from "angine/ui/AnAnchor";
import { AnLog } from "angine/utils/AnLog";
import { AnImage, AnImageConfig } from "./AnImage";
import { AnMath } from "angine/utils/AnMath";
import { v8_0_0 } from "pixi.js";


export interface AnProgressBarConfig extends AnUIElementConfig
{
	value?: number; // всегда AnProgressBar в диапазоне 0.0-1.0
	speedAnim?: number; // скорость анимации между реальным значением и отображаемым
	foreground?: AnImageConfig;
	background?: AnImageConfig;
	tint?: number;
};

export class AnProgressBar
	extends enhance(AnUIElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{
	private simpleForeground: PIXI.Graphics | null = null;
	private simpleBackground: PIXI.Graphics | null = null;
	private simpleBackgroundShadow: PIXI.Graphics | null = null;

	private foregroundSprite: AnImage | null = null;
	private backgroundSprite: AnImage | null = null;

	//текущее значение прогресса, всегда AnProgressBar в диапазоне 0.0-1.0
	private _value: AnInterpolator;

	public constructor(config: AnProgressBarConfig)
	{
		super(config);

		this.foregroundSprite = config.foreground ? new AnImage({ anchor: AnAnchor.TopLeft, ...config.foreground }) : null;
		this.backgroundSprite = config.background ? new AnImage({ anchor: AnAnchor.TopLeft, ...config.background }) : null;

		this._value = new AnInterpolator(
			{
				initialValue: config.value ?? 0,
				speed: config.speedAnim ?? 1,
				autoStart: true,
				interpolation: AnInterpolation.sinusoidal,
				callbacks: {
					onUpdate: () => this.syncWithValue(),
				}
			}
		);


		this.scaledWidth = 100;
		this.scaledHeight = 5;
		if (this.simpleGraphics)
		{
			this.createSimpleGraphics();
		}
		else
		{
			this.createSpriteGraphics();
		}


		// +++ resize strategy +++
		this.defaultResizeStrategy = this.simpleGraphics ?
			() =>
			{
				this.syncWithValue();
				this.simpleBackground!.width = this._scaledWidth!;
				this.simpleBackgroundShadow!.width = this._scaledWidth!;
				this.simpleForeground!.height = this._scaledHeight!;
				this.simpleBackground!.height = this._scaledHeight!;
				this.simpleBackgroundShadow!.height = this._scaledHeight!;
				this.simpleBackgroundShadow!.x = this.simpleBackground!.x + AnUI.styleParams.shadowOffset * AnViewport.scale;
				this.simpleBackgroundShadow!.y = this.simpleBackground!.y + AnUI.styleParams.shadowOffset * AnViewport.scale;
				this.simpleForeground!.x = this.simpleBackground!.x;
				this.simpleForeground!.y = this.simpleBackground!.y;
			}
			:
			() =>
			{
				this.syncWithValue();
				this.backgroundSprite!.scaledWidth = this.scaledWidth;
				//this.foregroundSprite!.scaledWidth = this.scaledWidth;
				this.backgroundSprite!.scaledHeight = this.scaledHeight;
				this.foregroundSprite!.scaledHeight = this.scaledHeight;

				this.backgroundSprite!.scale9Adopt = AnViewport.scale;
				this.foregroundSprite!.scale9Adopt = AnViewport.scale;

				this.backgroundSprite!.applyDefaultResizeStrategy();
				this.foregroundSprite!.applyDefaultResizeStrategy();
			};

		this.configResizeStrategy(config.resizeStrategy);
	}




	private syncWithValue(): void
	{
		if (this.simpleGraphics)
			this.simpleForeground!.width = this._scaledWidth! * (this._value.currentValue as number);
		else
		{
			const value = (this._value.currentValue as number) === 0 ? 0.0001 : (this._value.currentValue as number);
			if (this.useClipping)
			{
				this.foregroundSprite!.clippingWidth = value;
				this.foregroundSprite!.scaledWidth = this.scaledWidth * value;
				this.foregroundSprite!.applyDefaultResizeStrategy();
			}
			else
			{
				this.foregroundSprite!.scale9Adopt = AnViewport.scale;
				this.foregroundSprite!.scaledWidth = this.scaledWidth * value;
				this.foregroundSprite!.scaledHeight = this.scaledHeight;
				this.foregroundSprite!.applyDefaultResizeStrategy();
			}
		}
	}

	/** используется простая графика исключительно через PIXI.Graphics */
	public get simpleGraphics()
	{
		return this.foregroundSprite === null && this.backgroundSprite === null;
	}

	/** используется ли для спрайтовой графики клиппинг */
	public get useClipping()
	{
		return this.foregroundSprite && !this.foregroundSprite.useSlice9;
	}

	private createSpriteGraphics()
	{
		if (!this.foregroundSprite || !this.backgroundSprite) return;

		this.addToCleanup(safeDestroyFunc(this.foregroundSprite));
		this.addToCleanup(safeDestroyFunc(this.backgroundSprite));

		this.addGraphics(this.backgroundSprite);
		this.addGraphics(this.foregroundSprite);

		// для отладки, добавляем ярлык для элемента (pixi devtools)
		if (AnConfig.devMode)
		{
			this.backgroundSprite.label = "sprite foreground";
			this.foregroundSprite.label = "sprite background";
		}
	}

	private createSimpleGraphics()
	{
		this.simpleForeground = new PIXI.Graphics();
		this.simpleBackground = new PIXI.Graphics();
		this.simpleBackgroundShadow = new PIXI.Graphics();

		this.addToCleanup(safeDestroyFunc(this.simpleForeground));
		this.addToCleanup(safeDestroyFunc(this.simpleBackground));
		this.addToCleanup(safeDestroyFunc(this.simpleBackgroundShadow));

		// Создание тени фона
		this.simpleBackgroundShadow.rect(0, 0, this._scaledWidth!, this._scaledHeight!);
		this.simpleBackgroundShadow.fill(AnUI.colorSheme.shadow);

		// Создание фона
		this.simpleBackground.rect(0, 0, this._scaledWidth!, this._scaledHeight!);
		this.simpleBackground.fill(AnUI.colorSheme.background);

		// Создание переднего плана (прогресс)
		this.simpleForeground.rect(0, 0, this._scaledWidth!, this._scaledHeight!);
		this.simpleForeground.fill(AnUI.colorSheme.foreground);

		// Добавление элементов в контейнер
		this.addGraphics(this.simpleBackgroundShadow);
		this.addGraphics(this.simpleBackground);
		this.addGraphics(this.simpleForeground);

		// для отладки, добавляем ярлык для элемента (pixi devtools)
		if (AnConfig.devMode)
		{
			this.simpleForeground.label = "solid foreground";
			this.simpleBackground.label = "solid background";
			this.simpleBackgroundShadow.label = "solid shadow";
		}
	}

	public get value()
	{
		return this._value.targetValue as number;
	}

	public set value(value: number)
	{
		this._value.targetValue = AnMath.clamp(value, 0, 1);
	}

	public update(dt: number)
	{
		super.update(dt);
		this._value.update(dt);
	}

}

