import { AnUpdater } from "angine/utils/AnUpdater";
import { className, dataClone, enhance } from "angine/utils/AnHelpers";
import { AnEase } from "angine/anim/AnEase";
import { AnUpdatableConfig, AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";
import { AnTaggableInterface, AnTaggableMixin } from "angine/mixins/AnTaggableMixin";
import { AnLog } from "angine/utils/AnLog";
import { AnMath } from "angine/utils/AnMath";


/**
 * Конфигурация твин-анимации
 */
export interface AnTweenConfig extends AnUpdatableConfig
{
	/** Объект, свойства которого будут анимироваться */
	target?: any;

	/** Объект с начальными значениями свойств (если не указано, берутся текущие значения целевого объекта) */
	from?: Record<string, any>;

	/** Объект с целевыми значениями свойств (например, {x: 100, alpha: 0}) */
	to?: Record<string, any>;

	/** точность сравнения прогресса с 1, можно завершить чуть раньше */
	tolerance?: number;

	/** Применять ли стартовые значения (`from`) сразу при создании твина (по умолчанию true) */
	applyFromOnCreate?: boolean;

	/** Длительность анимации в секундах */
	duration?: number;

	/** Задержка перед началом анимации в секундах (по умолчанию 0) */
	delay?: number;

	/** Округлять ли значения свойств до целых чисел (по умолчанию false) */
	round?: boolean;

	/** Сразу добавить теги к объекту */
	tags?: string[];

	/** 
	 * Количество повторений анимации:
	 * - 0 - без повторений
	 * - >0 - конкретное число повторений
	 * - Infinity - бесконечные повторения
	 * (по умолчанию 0)
	 */
	repeat?: number;

	/** 
	 * Должна ли анимация проигрываться в обратном направлении при повторениях
	 * (по умолчанию false)
	 */
	reverse?: boolean;


	/**
	 * Автоматический старт
	 */
	autoStart?: boolean;

	/** 
	 * Удалять ли твин из апдейтера после завершения анимации
	 * (по умолчанию true)
	 */
	autoRemove?: boolean;

	/** 
	 * Функция плавности (easing) для анимации
	 * (по умолчанию AnEase.linear)
	 */
	easing?: (t: number) => number;

	/**
	 * Коллбеки
	 */
	callbacks?: AnTweenCallbacks;
}

/**
 * Коллбеки для отслеживания событий анимации
 */
export interface AnTweenCallbacks
{
	/** Вызывается при старте анимации */
	onStart?: (tween: AnTween) => void;

	/** Вызывается при паузе анимации */
	onPause?: (tween: AnTween) => void;

	/** Вызывается при возобновлении анимации после паузы */
	onResume?: (tween: AnTween) => void;

	/** Вызывается при завершении анимации */
	onComplete?: (tween: AnTween) => void;

	/** 
	 * Вызывается при каждом обновлении анимации
	 * @param progress Текущий прогресс анимации (0-1)
	 */
	onUpdate?: (tween: AnTween, progress: number) => void;

	/** 
	 * Вызывается при начале каждого повторения анимации
	 * @param repeatCount Номер текущего повторения (начиная с 1)
	 */
	onRepeat?: (tween: AnTween, repeatCount: number) => void;
}

/**
 * Класс для создания и управления твин-анимациями
 */
export class AnTween
	extends enhance(Object).with(AnUpdatableMixin, AnTaggableMixin)
	implements AnUpdatableInterface, AnTaggableInterface
{

	// Конфигурационные параметры
	public readonly target: any;
	public readonly to: Record<string, any>;
	public readonly duration: number;
	public readonly delay: number;
	public readonly round: boolean;
	public readonly repeat: number;
	public readonly reverse: boolean;
	public readonly autoRemove: boolean;
	public readonly easing: (t: number) => number;

	// Внутреннее состояние
	private _callbacks: AnTweenCallbacks;
	private startValues: Record<string, any> = {};
	private elapsedTime: number = 0;
	private delayCounter: number = 0;
	private repeatCount: number = 0;
	private tolerance: number = 0;
	private isReversing: boolean = false;
	private _paused: boolean = false;
	private _running: boolean = false;
	//private nextTween: AnTween | null = null;

	/**
	 * Создает новый экземпляр твин-анимации
	 * @param config Конфигурация анимации
	 */
	constructor(config: AnTweenConfig)
	{
		super();

		// Инициализация параметров конфигурации
		this.target = config.target;
		this.to = config.to ?? { alpha: 1 };
		this.tolerance = config.tolerance ?? 0;
		this.duration = config.duration ?? 1;
		this.delay = config.delay ?? 0;
		this.round = config.round ?? false;
		this.repeat = config.repeat ?? 0;
		this.reverse = config.reverse ?? false;
		this.autoRemove = config.autoRemove ?? true;
		this.easing = config.easing ?? AnEase.linear;
		this._callbacks = config.callbacks ?? {};
		let autoStart = config.autoStart ?? true;
		let applyFromOnCreate = config.applyFromOnCreate ?? true;


		// Добавляем теги
		if (config.tags)
		{
			config.tags.forEach(tag => this.addTag(tag));
		}

		if (config.updater) this.addToUpdater(config.updater);

		// Сохраняем начальные значения всех анимируемых свойств
		for (const key in this.to)
		{
			if (!this.isValidProperty(key)) continue;

			const startVal = config.from && key in config.from ? config.from[key] : this.target[key];
			this.startValues[key] = typeof startVal === 'object' ? dataClone(startVal) : startVal;
		}

		// применяем сразу начальные значения к объекту
		if (config.from && applyFromOnCreate)
			this.applyFromValues();

		// Автоматический старт при создании, если указано в конфиге
		if (autoStart) this.start();
	}

	/** проверяет, можно ли данное свойство использовать для анимации */
	private isValidProperty(key: string): boolean
	{
		if (this.target[key] === undefined)
		{
			AnLog.warn(`Свойство "${key}" не существует в целевом объекте и не может быть анимированно`);
			return false;
		}
		if (Array.isArray(this.target[key]))
		{
			AnLog.warn(`Свойство "${key}" является массивом и не может быть анимированно`);
			return false;
		}
		return true;
	}

	/**
	 * получить коллбеки для переназначения
	 */
	public get callbacks(): AnTweenCallbacks
	{
		return this._callbacks;
	}

	/**
	 * Применяет стартовые значения из `from` к целевому объекту.
	 * Полезно для мгновенной установки начального состояния перед анимацией.
	 */
	public applyFromValues(): this
	{
		for (const key in this.startValues)
		{
			const startVal = this.startValues[key];
			this.target[key] = typeof startVal === 'object' ? dataClone(startVal) : startVal;
		}
		return this;
	}

	/**
	 * Запускает или перезапускает анимацию
	 * @returns Текущий экземпляр твина (для цепочки вызовов)
	 */
	public start(): this
	{
		if (this._running || !this.getUpdater()) return this;

		this._running = true;

		this.elapsedTime = 0;
		this.delayCounter = 0;
		this.repeatCount = 0;
		this.isReversing = false;

		if (this.delay === 0)
			this._callbacks.onStart?.(this);

		return this;
	}

	/**
	 * Ставит анимацию на паузу
	 * @returns Текущий экземпляр твина (для цепочки вызовов)
	 */
	public pause(): this
	{
		if (!this._running || this._paused || !this.getUpdater()) return this;

		this._paused = true;
		this._callbacks.onPause?.(this);
		return this;
	}

	/**
	 * Возобновляет анимацию после паузы
	 * @returns Текущий экземпляр твина (для цепочки вызовов)
	 */
	public resume(): this
	{
		if (!this._running || !this._paused || !this.getUpdater()) return this;

		this._paused = false;
		this._callbacks.onResume?.(this);
		return this;
	}

	/**
	 * Останавливает анимацию
	 * @returns Текущий экземпляр твина (для цепочки вызовов)
	 */
	public stop(): this
	{
		if (!this._running) return this;

		this._running = false;

		if (this.autoRemove)
			this.removeFromUpdater();

		return this;
	}

	/**
	 * Моментально завершает анимацию, устанавливая целевые значения
	 * @returns Текущий экземпляр твина (для цепочки вызовов)
	 */
	public finish(): this
	{
		if (!this._running) return this;

		// Принудительно завершаем анимацию
		this.elapsedTime = this.duration;
		this.delayCounter = this.delay; // Пропускаем задержку

		// Применяем конечные значения
		this.calcPropertyChanges(1.0);

		// Вызов коллбека завершения
		this._callbacks.onComplete?.(this);

		// Останавливаем
		this.stop();

		return this;
	}

	// /**
	//  * Связывает текущую анимацию с другой, которая начнется после ее завершения
	//  * @param nextTween Следующая анимация в цепочке
	//  * @returns Текущий экземпляр твина (для цепочки вызовов)
	//  */
	// public chain(nextTween: AnTween): this
	// {
	// 	this.nextTween = nextTween;
	// 	return this;
	// }

	/**
	 * Основной метод обновления, вызываемый системой AnUpdater
	 * @param dt Время, прошедшее с предыдущего обновления (в секундах)
	 */
	public update(dt: number): void
	{
		super.update(dt);

		if (!this._running || this._paused) return;

		if (this.target.destroyed)
		{
			AnLog.error(`AnTween: target[label:${this.target?.label} className:${className(this.target)}] уничтожен, но твин не остановлен!`);
			this.terminate();
			return;
		}

		// Обработка задержки перед началом анимации
		if (this.delayCounter < this.delay)
		{
			this.delayCounter += dt;

			if (this.delayCounter >= this.delay)
				this.callbacks.onStart?.(this);

			return;
		}

		// Обновление времени анимации
		this.elapsedTime += dt;
		const rawProgress = Math.min(this.elapsedTime / this.duration, 1);
		//AnLog.warn(`rawProgress: ${rawProgress}`);
		const easedProgress = this.easing(this.isReversing ? 1 - rawProgress : rawProgress);

		// Применение новых значений к целевому объекту
		this.calcPropertyChanges(easedProgress);

		// Вызов коллбека обновления
		this._callbacks.onUpdate?.(this, easedProgress);

		// Проверка завершения анимации
		if (rawProgress + this.tolerance >= 1)
		{
			if (!this.reverse) // !ИНАЧЕ БУДЕТ ДЕРГОТНЯ ПРИ РЕВЕРСЕ
				this.calcPropertyChanges(1); // доводим значения до запланированных

			this.handleCompletion();
		}
	}

	/** Применяет вычисленные значения к целевым свойствам */
	private applyValues(progress: number, target: any, key: any, start: any, end: any): void
	{
		let value: any;


		// Для числовых значений - интерполяция
		if (typeof start === 'number' && typeof end === 'number')
		{
			// для цвета своя интерполяция
			if (key === "tint")
			{
				value = AnMath.lerpColor(start, end, progress);
			}
			else
			{
				value = start + (end - start) * progress;
				if (this.round) value = Math.round(value);
			}
		}
		// Для других типов - просто переключение в конце анимации
		else
		{
			value = progress >= 1 ? end : start;
		}

		target[key] = value;
	}

	/** Расчет измененных значений свойств */
	private calcPropertyChanges(progress: number): void
	{
		for (const [key, end] of Object.entries(this.to))
		{
			const start = this.startValues[key];

			// Обрабатываем вложенные свойства объекта
			if (typeof start === 'object' && typeof end === 'object')
			{
				for (const innerKey in end)
					if (innerKey in start)
						this.applyValues(progress, this.target[key], innerKey, start[innerKey], end[innerKey]);
				continue;
			}

			// Обрабатываем обычные свойства
			this.applyValues(progress, this.target, key, start, end);

		}
	}

	/** Обрабатывает завершение текущего цикла анимации */
	private handleCompletion(): void
	{
		// Вызов коллбека завершения
		this._callbacks.onComplete?.(this);

		// Проверка необходимости повторения
		if (this.shouldRepeat())
		{
			this.repeatCount++;
			this.elapsedTime = 0;
			this.isReversing = this.reverse ? !this.isReversing : false;
			this._callbacks.onRepeat?.(this, this.repeatCount);
		} else
		{
			// Если повторений не требуется - завершаем анимацию
			this.stop();

			// // Запуск следующей анимации в цепочке
			// this.nextTween?.start();
		}
	}

	/** Проверяет, нужно ли повторять анимацию */
	private shouldRepeat(): boolean
	{
		return this.repeatCount < this.repeat || this.repeat === Infinity;
	}

	// Геттеры для состояния анимации

	/** Возвращает true, если анимация активна (не на паузе и не завершена) */
	public get playing(): boolean
	{
		return !this._paused && this.progress < 1;
	}

	/** Возвращает текущий прогресс анимации (0-1) */
	public get progress(): number
	{
		return Math.min(this.elapsedTime / this.duration, 1);
	}

	/** Активна ли анимация */
	get running(): boolean
	{
		return this._running;
	}

	/** Возвращает true, если анимация находится на паузе */
	public get paused(): boolean
	{
		return this._paused;
	}

	/** Возвращает номер текущего повторения (0 для первого проигрывания) */
	public get currentRepeat(): number
	{
		return this.repeatCount;
	}

	/** останавливаем и очищаем ссылки на твин */
	public terminate()
	{
		this.stop();
		if (!this.autoRemove)
			this.removeFromUpdater();
	}
}