import { AnViewport } from "angine/core/AnViewport.js";
import { PIXI } from "angine/singleton.js";
import { Constructor } from "angine/utils/AnHelpers.js";
import { DropShadowFilter } from "pixi-filters";
import { Block, BlockType } from "./Block.js";
import { Field, CellSize, GridPos } from "./Field.js";
import { CellModifier } from "./Cell.js";


export function FieldChainsMixin<TBase extends Constructor>(Base: TBase)
{
	return class extends Base
	{
		constructor(...args: any[])
		{
			super(...args);

			// Дополнительная проверка во время выполнения
			if (!(this instanceof Field))
				throw new Error('FieldChainsMixin может использоваться только с классом Field!');
		}


		/**
		 * Находит минимальную по длине цепочку на поле (не менее 3 блоков)
		 * Оптимизированная версия с поддержкой диагональных соединений
		 * @returns Минимальная цепочка или null, если подходящих цепочек нет
		 */
		public getMinChain(): Block[] | null
		{
			const field = this as unknown as Field;

			// Локальные переменные для оптимизации
			const visited = new Set<Block>();
			const usedBlocks = new Set<string>(); // Уже использованные блоки (в формате "row,col")
			let minChain: Block[] | null = null;

			// Оптимизированный метод для получения соседей с диагоналями
			const getNeighbors = (block: Block): Block[] =>
			{
				const neighbors: Block[] = [];
				const { row, col } = block.gridPos;

				// Проверяем все 8 направлений (включая диагонали)
				const directions = [
					// Основные направления
					{ dr: -1, dc: 0 },  // Север
					{ dr: 0, dc: 1 },   // Восток
					{ dr: 1, dc: 0 },   // Юг
					{ dr: 0, dc: -1 },  // Запад
					// Диагональные направления
					{ dr: -1, dc: 1 },  // Северо-восток
					{ dr: 1, dc: 1 },   // Юго-восток
					{ dr: 1, dc: -1 },  // Юго-запад
					{ dr: -1, dc: -1 }  // Северо-запад
				];

				for (const dir of directions)
				{
					const newRow = row + dir.dr;
					const newCol = col + dir.dc;

					const cell = field.getCell(newRow, newCol);
					if (cell && !cell.hasModifier(CellModifier.Cage))
					{
						const neighbor = cell.block;
						if (neighbor &&
							neighbor.type === block.type &&
							!visited.has(neighbor) &&
							!neighbor.special)
						{
							neighbors.push(neighbor);
						}
					}
				}

				return neighbors;
			};

			// Основной цикл по всем блокам поля
			for (const startBlock of field.blocks)
			{
				// Пропускаем блоки в клетках с клеткой
				const startCell = field.getCell(startBlock.gridPos.row, startBlock.gridPos.col);
				if (startCell && startCell.hasModifier(CellModifier.Cage)) continue;

				// Пропускаем уже посещенные блоки
				if (visited.has(startBlock)) continue;

				// Пропускаем блоки, которые уже были использованы в других цепочках
				const blockKey = `${startBlock.gridPos.row},${startBlock.gridPos.col}`;
				if (usedBlocks.has(blockKey)) continue;

				const blockType = startBlock.type;

				// Для каждого типа блока запускаем поиск цепочек
				const blocksOfType = field.blocks.filter(b =>
				{
					const cell = field.getCell(b.gridPos.row, b.gridPos.col);
					return b.type === blockType &&
						!visited.has(b) &&
						cell && !cell.hasModifier(CellModifier.Cage);
				});

				for (const currentBlock of blocksOfType)
				{
					if (visited.has(currentBlock)) continue;

					// Используем итеративный DFS для построения цепочки
					const stack: { block: Block, path: Block[], neighbors: Block[], index: number }[] = [];
					const initialNeighbors = getNeighbors(currentBlock);

					if (initialNeighbors.length > 0)
					{
						stack.push({
							block: currentBlock,
							path: [currentBlock],
							neighbors: initialNeighbors,
							index: 0
						});
						visited.add(currentBlock);
					}

					while (stack.length > 0)
					{
						const current = stack[stack.length - 1];

						// Если есть еще соседи для обработки
						if (current.index < current.neighbors.length)
						{
							const nextBlock = current.neighbors[current.index];
							current.index++;

							if (!visited.has(nextBlock))
							{
								visited.add(nextBlock);
								const newPath = [...current.path, nextBlock];

								// Проверяем, достигли ли минимальной длины
								if (newPath.length >= 3)
								{
									// Обновляем минимальную цепочку
									if (!minChain || newPath.length < minChain.length)
									{
										minChain = newPath;

										// Ранний выход - если нашли минимально возможную длину
										if (minChain.length === 3)
										{
											// Помечаем блоки цепочки как использованные
											for (const block of minChain)
											{
												const key = `${block.gridPos.row},${block.gridPos.col}`;
												usedBlocks.add(key);
											}
											return minChain;
										}
									}
								}

								// Продолжаем поиск, если цепочка еще может расти
								if (newPath.length < 8)
								{ // Ограничение на максимальную длину цепочки
									const nextNeighbors = getNeighbors(nextBlock);
									if (nextNeighbors.length > 0)
									{
										stack.push({
											block: nextBlock,
											path: newPath,
											neighbors: nextNeighbors,
											index: 0
										});
									}
								}
							}
						} else
						{
							// Backtracking - удаляем текущий уровень из стека
							stack.pop();
						}
					}

					// Очищаем посещенные блоки для следующей итерации
					if (stack.length === 0)
					{
						// Удаляем только те блоки, которые были добавлены в этой итерации
						for (const block of visited)
						{
							const key = `${block.gridPos.row},${block.gridPos.col}`;
							if (!usedBlocks.has(key))
							{
								visited.delete(block);
							}
						}
					}
				}

				// Помечаем начальный блок как посещенный
				visited.add(startBlock);
			}

			// Если нашли цепочку, помечаем ее блоки как использованные
			if (minChain)
			{
				for (const block of minChain)
				{
					const key = `${block.gridPos.row},${block.gridPos.col}`;
					usedBlocks.add(key);
				}
			}

			return minChain;
		}

		// ************************************************************ //

		public getUniqueChainsForType(blockType: BlockType): Block[][]
		{
			const field = this as unknown as Field;

			// Локальные переменные и функции
			const allChains: Block[][] = [];
			const visited = new Set<Block>();
			const usedBlocks = new Set<string>(); // Уже использованные блоки (в формате "row,col")

			// Получаем все блоки нужного типа
			const blocks = field.blocks.filter(b => b.type === blockType);

			/**
			 * Получает всех непосещенных соседей блока
			 */
			const getNeighbors = (currentBlock: Block, visitedLocal: Set<Block>): Block[] =>
			{
				const neighbors: Block[] = [];
				const row = currentBlock.gridPos.row;
				const col = currentBlock.gridPos.col;

				// Проверяем все 8 направлений
				for (let dy = -1; dy <= 1; dy++)
				{
					for (let dx = -1; dx <= 1; dx++)
					{
						if (dx === 0 && dy === 0) continue;

						const newRow = row + dy;
						const newCol = col + dx;

						const cell = field.getCell(newRow, newCol);
						if (cell && !cell.hasModifier(CellModifier.Cage))
						{
							const neighbor = cell.block;
							if (neighbor &&
								neighbor.type === blockType &&
								!visitedLocal.has(neighbor))
							{
								neighbors.push(neighbor);
							}
						}
					}
				}

				return neighbors;
			};

			/**
			 * Поиск в глубину для построения всех возможных цепочек
			 */
			const dfsChainBuilder = (
				currentBlock: Block,
				path: Block[],
				visitedLocal: Set<Block>,
				chains: Block[][],
				maxLengthRef: { value: number }
			): void =>
			{
				// Добавляем текущий блок в путь
				path.push(currentBlock);
				visitedLocal.add(currentBlock);

				// Получаем всех соседей текущего блока
				const neighbors = getNeighbors(currentBlock, visitedLocal);

				// Если нет соседей, проверяем длину текущей цепочки
				if (neighbors.length === 0)
				{
					if (path.length >= 3)
					{
						// Если нашли цепочку длиннее текущей максимальной
						if (path.length > maxLengthRef.value)
						{
							maxLengthRef.value = path.length;
							chains.length = 0; // Очищаем предыдущие результаты
							chains.push([...path]);
						}
						// Если длина равна текущей максимальной
						else if (path.length === maxLengthRef.value)
						{
							chains.push([...path]);
						}
					}
				}
				// Если есть соседи, продолжаем поиск
				else
				{
					for (const neighbor of neighbors)
					{
						dfsChainBuilder(neighbor, path, visitedLocal, chains, maxLengthRef);
					}
				}

				// Backtracking
				path.pop();
				visitedLocal.delete(currentBlock);
			};

			/**
			 * Находит все возможные цепочки от начального блока
			 */
			const findAllChainsFromBlock = (startBlock: Block): Block[][] =>
			{
				const chains: Block[][] = [];
				const path: Block[] = [];
				const maxLengthRef = { value: 0 };

				// Отмечаем блок как глобально посещенный
				visited.add(startBlock);

				// Запускаем DFS
				dfsChainBuilder(
					startBlock,
					path,
					new Set<Block>([startBlock]),
					chains,
					maxLengthRef
				);

				return chains;
			};

			// Основной цикл поиска цепочек
			for (const startBlock of blocks)
			{
				if (!visited.has(startBlock))
				{
					// Ищем все возможные пути от этого блока
					const chainsFromBlock = findAllChainsFromBlock(startBlock);

					// Оставляем только самые длинные уникальные цепочки
					if (chainsFromBlock.length > 0)
					{
						// Находим максимальную длину
						const maxLength = Math.max(...chainsFromBlock.map(chain => chain.length));

						// Фильтруем, оставляя только самые длинные
						const longestChains = chainsFromBlock.filter(chain => chain.length === maxLength);

						// Добавляем в результат
						allChains.push(...longestChains);
					}
				}
			}

			// Фильтрация пересекающихся цепочек
			const result: Block[][] = [];

			// Обрабатываем цепочки в порядке убывания длины
			allChains
				.sort((a, b) => b.length - a.length)
				.forEach(chain =>
				{
					// Проверяем, нет ли пересечения с уже выбранными цепочками
					const hasOverlap = chain.some(block =>
					{
						const blockKey = `${block.gridPos.row},${block.gridPos.col} `;
						return usedBlocks.has(blockKey);
					});

					if (!hasOverlap)
					{
						// Добавляем цепочку в результат
						result.push(chain);
						// Помечаем все блоки цепочки как использованные
						chain.forEach(block =>
						{
							const blockKey = `${block.gridPos.row},${block.gridPos.col} `;
							usedBlocks.add(blockKey);
						});
					}
				});

			return result;
		}

		/** +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
		 * ++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
		 * Визуализирует цепочки блоков с помощью PIXI.Graphics
		 * @param chains Массив цепочек для визуализации
		 * @param options Опции отображения (цвета, толщина линии и т.д.)
		 * @returns Созданный графический объект (можно удалить позже)
		 */
		protected debugGraphics: PIXI.Graphics | undefined;
		public visualizeChains(chains: Block[][], debugContainer?: PIXI.Graphics, options?: {
			colors?: number[],
			lineWidth?: number,
			alpha?: number,
			showLabels?: boolean
		}): PIXI.Graphics
		{
			const field = this as unknown as Field;

			// Настройки по умолчанию
			const defaultOptions = {
				colors: [0xFF0000, 0x00FF00, 0x0000FF, 0xFFFF00, 0xFF00FF, 0x00FFFF],
				lineWidth: 4,
				alpha: 0.7,
				showLabels: true,
				...options
			};

			// Создаем фильтр тени
			const dropShadowFilter = new DropShadowFilter();
			dropShadowFilter.offsetX = 2; // расстояние тени
			dropShadowFilter.offsetY = 2; // расстояние тени
			dropShadowFilter.color = 0x000000; // цвет тени
			dropShadowFilter.alpha = 1; // прозрачность тени
			dropShadowFilter.blur = 2; // размытие тени
			dropShadowFilter.quality = 2;

			// Создаем графический объект
			const graphics = debugContainer ?? new PIXI.Graphics();
			field.addChild(graphics); // Добавляем на поле
			this.debugGraphics = graphics; // Сохраняем ссылку для последующего удаления

			const fontSize = 25 * AnViewport.scale;

			// Рисуем каждую цепочку
			chains.forEach((chain, chainIndex) =>
			{
				if (chain.length < 3) return;

				const color = defaultOptions.colors[chainIndex % defaultOptions.colors.length];

				// Начинаем новую линию для каждой цепочки
				graphics.moveTo(0, 0); // Инициализация пути

				// Соединяем блоки линиями
				for (let i = 0; i < chain.length; i++)
				{
					const pos = chain[i].gridPos.toPixelPos();
					if (i === 0)
					{
						graphics.moveTo(pos.x, pos.y);
					} else
					{
						graphics.lineTo(pos.x, pos.y);
					}

					// Добавляем номер блока в цепочке и его координаты
					if (defaultOptions.showLabels)
					{
						const blockLabel = new PIXI.Text({
							text: `${i + 1} \n[${chain[i].gridPos.row},${chain[i].gridPos.col}]`,
							style: {
								fontFamily: 'Arial',
								fontSize,
								fill: color,
								fontWeight: 'bold',
								align: 'center',
							}
						});

						// Размещаем метку над блоком
						blockLabel.position.set(
							pos.x,
							pos.y - CellSize * 0.4 * AnViewport.scale
						);
						blockLabel.anchor.set(0.5, 1); // Центрируем по горизонтали, выравниваем по низу
						// Применяем фильтр к тексту
						blockLabel.filters = [dropShadowFilter];
						graphics.addChild(blockLabel);
					}
				}

				// Применяем стиль линии (PIXI v8+)
				graphics.stroke({
					width: defaultOptions.lineWidth,
					color: color,
					alpha: defaultOptions.alpha
				});

				// Добавляем общую метку цепочки
				if (defaultOptions.showLabels)
				{
					const firstPos = chain[0].gridPos.toPixelPos();
					const chainLabel = new PIXI.Text({
						text: `Цепочка ${chainIndex + 1} `,
						style: {
							fontFamily: 'Arial',
							fontSize,
							fill: color,
							fontWeight: 'bold',
							// dropShadow: true,
							// dropShadowColor: 0x000000,
							// dropShadowDistance: 1
						}
					});

					// Применяем фильтр к тексту
					chainLabel.filters = [dropShadowFilter];

					// Размещаем метку над первым блоком цепочки
					chainLabel.position.set(
						firstPos.x,
						firstPos.y + CellSize * 0.4 * AnViewport.scale
					);
					chainLabel.anchor.set(0.5);
					graphics.addChild(chainLabel);
				}
			});

			return graphics;
		}

		/**
		 * Удаляет отладочную графику
		 */
		public clearDebugGraphics(): void
		{
			if (this.debugGraphics)
			{
				const field = this as unknown as Field;
				field.removeChild(this.debugGraphics);
				this.debugGraphics.destroy();
				this.debugGraphics = undefined;
			}
		}
	}
}