	// рассчитаем результаты уровня
	private calcLevelResult(isWin: boolean): LevelResult
	{
		let stars: 0 | 1 | 2 | 3 = isWin ? G.calculateStars(this.totalMoves - this.currentMoves, this.totalMoves) : 0;
		let coins: number = G.calculateCoinReward(this.levelNum!, stars);

		return { stars, coins };
	}

