	public addMoves(count: number = 0, pos: GridPos = new GridPos(0, 0))
	{
		AnSounds.play(
			`sounds/moves.snd.mp3`,
			0.6
		);

		this.currentMoves += count;
		this.updateMovesAnim();
		this.showBigTitle(AnLang.get("spec_chest_moves").replace("%%count%%", count.toString()), 0, 0.5);

	}
	public addCoins(count: number = 0, pos: GridPos)
	{
		this.showBigTitle(AnLang.get("spec_chest_coins").replace("%%count%%", count.toString()), 0, 0.5);

		//save
		GameApp.self.gameData.coins += count;

		Analytics.onGetResource('coins', count, 'rewardChest', 'coins');

		const pixelPos = pos.toPixelPos();
		this.runCoinsAnims(count, new PIXI.Point(this.field.x + pixelPos.x * this.field.scale.x, this.field.y + pixelPos.y * this.field.scale.y), pos);
	}
	public addActualProps(count: number = 0, pos: GridPos)
	{
		this.showBigTitle(AnLang.get("spec_chest_props").replace("%%count%%", count.toString()), 0, 0.5);


		let type: BlockType = "prop_0";
		if (this.mode === GameMode.TotalCollect)
		{
			type = PropBlockTypeArray[this.field.specRndSeed.seed_int(0, PropBlockTypeArray.length - 1)];
		}
		else if (this.mode === GameMode.TypesCollect)
		{
			const typesCollect = this.goalCounters!.reduce<string[]>((acc, counter) =>
			{
				if (!counter.finished && counter.iconType.startsWith("prop_") && counter.iconType != "prop_heart") acc.push(counter.iconType);
				return acc;
			}, []);

			if (typesCollect.length)
				type = typesCollect[this.field.specRndSeed.seed_int(0, typesCollect.length - 1)] as BlockType;
			else // если нет целей - пропов
				type = PropBlockTypeArray[this.field.specRndSeed.seed_int(0, PropBlockTypeArray.length - 1)];
		}
		else
			notImplemented();

		for (let i = 0; i < count; ++i)
		{
			runAfterSafe(i * 0.3, this.field, () =>
			{
				AnSounds.play(
					`sounds/prop.snd.mp3`,
					AnRnd.float(0.4, 0.6) * 0.5,
					AnMath.remapClamp(pos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
					AnRnd.float(0.9, 1.1)
				);

				const block = new Block({
					pos,
					type,
					theme: this.theme,
					skipCreatingAnim: true,
					updater: this.field.getUpdater(),
					selectionLayer: this.field.selectionLayer,
					blockLayer: this.field.blockLayer,
				});
				//this.field.cells[heart.gridPos.row][heart.gridPos.col].block = block;
				//this.field.blocks.push(block);
				this.field.addUIElement(block);
				this.field.applyBlock(block);
			});
		}
	}

	private runCoinsAnims(rewardCoins: number, globalPosStart: PIXI.Point, pos: GridPos): void
	{
		const chunkValue = Math.trunc(rewardCoins * 0.2);
		const totalChunks = Math.ceil(rewardCoins / chunkValue);


		this.coinsCounter!.scale.set(1, 1);

		const posStart = globalPosStart;
		const posEnd = this.coinsCounter!.getMainIconGlobalPos();

		this.showCoinsCounter();

		for (let i = 0; i < totalChunks; ++i)
		{
			const coinValue = i === totalChunks - 1 ? rewardCoins - chunkValue * i : chunkValue;



			const coin = this.addUIElement(new AnImage({
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './coin_mod',
				anchor: AnAnchor.Center,
				resizeStrategy: () =>
				{
					coin.scaledWidth = scaled(20);
					coin.scaledHeight = scaled(20);
					coin.applyDefaultResizeStrategy();
				}
			}));

			coin.visible = false;

			const tween = new AnTween({
				target: coin,
				from: { alpha: 0.5, position: { x: posStart.x, y: posStart.y } },
				to: { alpha: 1, position: { x: posEnd.x, y: posEnd.y } },
				delay: i * 0.3,
				duration: 0.7,
				tolerance: 0.3,
				easing: AnEase.easeOutBack,
				updater: this.getUpdater(),
				callbacks: {
					onStart: () =>
					{
						coin.visible = true;

						AnSounds.play(
							`sounds/coin.snd.mp3`,
							AnRnd.float(0.4, 0.6) * 0.5,
							AnMath.remapClamp(pos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
							AnRnd.float(0.9, 1.1)
						);
					},
					onComplete: () =>
					{
						removeByValue(this.coinTweens, tween);
						const tweenOut = new AnTween({
							target: coin,
							to: { alpha: 0, scale: { x: 0.5, y: 0.5 } },
							tolerance: 0.01,
							duration: 0.8,
							easing: AnEase.easeInBack,
							updater: this.getUpdater(),
							callbacks: {
								onComplete: () =>
								{
									this.coinsCounter!.updateValue(this.coinsCounter!.currentCount + coinValue);
									this.terminateUIElement(coin);
									removeByValue(this.coinTweens, tweenOut);

									if (i === totalChunks - 1)
										this.hideCoinsCounter();
								}
							}
						}
						);
						this.coinTweens.push(tweenOut);
					}
				}
			});

			this.coinTweens.push(tween);
		}
	}

	public continue(newMoves: number = 0)
	{
		this.addMoves(newMoves);
		this.field.forbidSelectBlocks = false;
		this.winLoseState = false;

		this.playerContinueCount++;
	}

