import { enhance, AnVoidCallback, removeByValue, calculateDialogDisplayTime } from "angine/utils/AnHelpers";
import { AnUIElement, AnUIElementConfig } from "angine/ui/AnUIElement";
import { AnText, AnTextConfig } from "angine/2D/AnText";
import { AnTween, AnTweenConfig } from "angine/anim/AnTween";
import { AnUpdatableConfig, AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";
import { AnUpdater } from "angine/utils/AnUpdater";
import { AnAnchor } from "angine/ui/AnAnchor";
import { AnEase } from "angine/anim/AnEase";
import { PIXI } from "angine/singleton";
import { AnLabel, AnLabelConfig } from "./AnLabel";
import { AnLog } from "angine/utils/AnLog";
import { AnRnd } from "angine/utils/AnRnd";
import { AnTextSource } from '../2D/AnText';
import { AnEvents } from "angine/utils/AnEvents";


interface AnDialogueCallbacks
{
	onComplete?: AnVoidCallback;
}

export interface AnDialogueConfig extends AnLabelConfig, AnUIElementConfig
{
	baseRealWidth?: number; // НЕ МАСШТАБИРОВАННАЯ ШИРИНА для расчета переносов
	speedFactor?: number; // 0.5 = быстрее, 1.0 = норма, 2.0 = медленнее
	callbacks?: AnDialogueCallbacks;
}

export class AnDialogue
	extends enhance(AnUIElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface 
{
	private labelConfig: AnLabelConfig;
	private speedFactor: number; // 0.5 = быстрее, 1.0 = норма, 2.0 = медленнее
	private baseRealWidth: number;
	private callbacks: AnDialogueCallbacks;



	private spaceSize: number;
	private tokensLabelsIn: AnLabel[] = [];
	private tokensTweensIn: AnTween[] = [];
	private tokensLabelsOut: AnLabel[] = [];
	private tokensTweensOut: AnTween[] = [];
	private tokensContainer: PIXI.Container;



	constructor(config: AnDialogueConfig)
	{
		super(config);

		this.spaceSize = config.text.fontSize ? config.text.fontSize * 0.15 : 10;
		this.labelConfig = { ...config as AnLabelConfig };
		this.speedFactor = config.speedFactor ?? 1.0;
		this.baseRealWidth = config.baseRealWidth ?? 800;
		this.callbacks = config.callbacks ?? {};

		this.tokensContainer = new PIXI.Container();
		this.addGraphics(this.tokensContainer);

		this.prepareTokens();


		// +++ resize strategy +++
		this.defaultResizeStrategy =
			() =>
			{
				//this.tokensContainer.setSize(this.scaledWidth, this.scaledHeight);

				const scaleX = this.scaledWidth / this.realWidth;
				const scaleY = this.scaledHeight / this.realHeight;
				const finalScale = Math.min(scaleX, scaleY);

				// Применяем масштаб
				this.anchorContainer.scale.set(finalScale);
			};

		this.configResizeStrategy(config.resizeStrategy);

		this.addToCleanup(AnEvents.on("settings:changed:lang", () => this.updateTextLang()).unsub);
	}

	private updateTextLang(): void
	{
		//if (this.tokensTweensOut.length) return;

		//AnLog.debug(`tweensIn:${this.tokensTweensIn.length} tweensOut:${this.tokensTweensOut.length} labelsIn:${this.tokensLabelsIn.length} labelsOut:${this.tokensLabelsOut.length}`);

		if (this.tokensTweensIn.length === 0 &&
			this.tokensTweensOut.length === 0 &&
			this.tokensLabelsIn.length === 0 &&
			this.tokensLabelsOut.length === 0)
			return;


		this.cleanUp();
		this.prepareTokens();
		this.startAnimation();
		// this.tokensTweensOut.forEach(tween => tween.finish());
		// this.tokensTweensIn.forEach(tween => tween.finish());
	}

	private prepareTokens()
	{
		const allText = AnText.textSourceResolver(this.labelConfig.text.textSource, this.labelConfig.text.autoUpdateLang ?? true);

		const tokenizeText = function (text: string): string[]
		{
			// Разбиваем текст на слова и пробелы, сохраняя структуру
			return text
				.split(/(\s+|[\wа-яёA-Z]+[.,;:!?]*)/i)
				.filter(token => token.length > 0);
		}

		const tokenStrings = tokenizeText(allText);

		// очистим старые метки и анимации к ним
		this.exitAnimation();

		for (const labelOut of this.tokensLabelsOut)
			labelOut.visible = false;

		let currentX = 0, currentY = 0;
		let lineHeight = 0;
		for (const token of tokenStrings)
		{
			if (token === "|") 
			{
				currentX = 0;
				currentY += lineHeight;
				continue;
			}

			if (token === " ")
			{
				if (currentX !== 0) // не добавляем пробел в начале
				{
					currentX += this.spaceSize;
					if (currentX >= this.baseRealWidth)
					{
						currentX = 0;
						currentY += lineHeight;
					}
				}
				continue;
			}

			const label = new AnLabel({
				...this.labelConfig,
				text: { ...this.labelConfig.text, textSource: token, autoUpdateLang: false },
				// backgroundColor: 0xff0000,
				// backgroundAlpha: 0.5,
				anchor: AnAnchor.Center,
			});
			if (lineHeight === 0) lineHeight = label.height * 0.8;
			label.alpha = 0;
			label.position.set(currentX + label.width * 0.5, currentY + label.height * 0.5 - label.textOffsetY);
			label.updateShadowRealPixels();
			this.tokensContainer.addChild(label);
			this.tokensLabelsIn.push(label);

			currentX += label.width;

			if (currentX >= this.baseRealWidth)
			{
				currentX = 0;
				currentY += lineHeight;
			}
		}

		this.realWidth = this.tokensContainer.width;
		this.realHeight = this.tokensContainer.height;

		for (const labelOut of this.tokensLabelsOut)
			labelOut.visible = true;
	}

	public get labelsCount(): number
	{
		return this.tokensLabelsOut.length;
	}

	public get textSource(): AnTextSource
	{
		return this.labelConfig.text.textSource;
	}
	public set textSource(textSource: AnTextSource)
	{
		this.labelConfig.text.textSource = textSource;
		this.prepareTokens();
	}

	public calculateDisplayTime(): number
	{
		const allText = AnText.textSourceResolver(this.labelConfig.text.textSource, this.labelConfig.text.autoUpdateLang ?? true);
		return calculateDialogDisplayTime(allText, 120);
	}

	private calculateDelay(token: string): number
	{
		if (/^[.,;:]$/.test(token))
			return AnRnd.float(0.6, 1) * this.speedFactor;

		if (/[.!?]$/.test(token))
			return AnRnd.float(2, 3) * this.speedFactor;


		return AnRnd.float(0.2, 0.6) * this.speedFactor;
	}

	public startAnimation(onComplete?: AnVoidCallback, onShowNextWord?: AnVoidCallback)
	{
		let i = 0;
		let delay = 0;

		for (const label of this.tokensLabelsIn)
		{
			const tween = new AnTween({
				target: label,
				from: { alpha: 0, scale: { x: 0.8, y: 0.8 }, rotation: Math.PI / 40, position: { x: label.x, y: label.y + 50 } },
				to: { alpha: 1, scale: { x: 1, y: 1 }, rotation: 0, position: { x: label.x, y: label.y } },
				duration: 2 * this.speedFactor,
				delay,
				easing: AnEase.easeOutBack,
				updater: this.getUpdater(),
				autoRemove: true,
				callbacks: {
					onComplete: () =>
					{
						removeByValue(this.tokensTweensIn, tween);
						onShowNextWord?.();
						if (i === this.tokensLabelsIn.length - 1) onComplete?.();
					}
				}
			});
			this.tokensTweensIn.push(tween);
			delay += this.calculateDelay(label.getText());
			++i;
		}
	}

	public exitAnimation(onComplete?: AnVoidCallback)
	{
		let i = 0;
		for (const label of this.tokensLabelsIn)
		{
			const tween = new AnTween({
				target: label,
				//from: { alpha: 0, scale: { x: 0.8, y: 0.8 }, rotation: Math.PI / 40, position: { x: label.x, y: label.y + 50 } },
				to: { alpha: 0, scale: { x: 0.8, y: 0.4 }, rotation: Math.PI / 20, position: { x: label.x, y: label.y - 20 } },
				duration: 1 * this.speedFactor,
				delay: 0.1 * i * this.speedFactor,
				easing: AnEase.easeIn,
				updater: this.getUpdater(),
				autoRemove: true,
				callbacks: {
					onComplete: () =>
					{
						removeByValue(this.tokensLabelsOut, label);
						label.terminate();

						removeByValue(this.tokensTweensOut, tween);
						if (i === this.tokensLabelsOut.length - 1) onComplete?.();
					}
				}
			});
			this.tokensLabelsOut.push(label);
			this.tokensTweensOut.push(tween);
			++i;
		}

		if (this.tokensLabelsIn.length) this.tokensLabelsIn = [];
		this.cleanUp(true);
	}


	override terminate()
	{
		this.cleanUp();

		super.terminate();
	}

	private cleanUp(onlyIn: boolean = false)
	{

		for (const tween of this.tokensTweensIn) tween.terminate();
		for (const label of this.tokensLabelsIn) label.terminate();
		this.tokensTweensIn = [];
		this.tokensLabelsIn = [];

		if (!onlyIn)
		{
			for (const tween of this.tokensTweensOut) tween.terminate();
			for (const label of this.tokensLabelsOut) label.terminate();
			this.tokensTweensOut = [];
			this.tokensLabelsOut = [];
		}
	}
}