// src/app/AnApp.ts

import { AnCore } from "angine/core/AnCore";
import { AnControls } from "angine/input/AnControls";
import { AnEvent, AnEvents } from "angine/utils/AnEvents";
import { AnPreloader } from "angine/app/AnPreloader";
import { AnMenu } from "angine/menu/AnMenu";
import { AnGameInterface } from "angine/app/AnGame";
import { runAfter, removeByValue, className } from "angine/utils/AnHelpers";
import { AnControlsEvent } from "angine/input/AnControlsEnums";
import { AnLog } from "angine/utils/AnLog";
import { AnMainLoop } from "angine/core/AnMainLoop";

export type AnAppConfig = {
	preloaderSkipExitAnimations?: boolean;
};

/**
 * Класс AnApp — главная точка входа приложения
 */
export abstract class AnApp
{
	private static instance: AnApp;

	private menus: AnMenu[] = [];

	private isStarted: boolean = false;
	private preloaderSkipExitAnimations: boolean = false;

	constructor(config: AnAppConfig)
	{
		if (AnApp.instance)
			return AnApp.instance;


		this.preloaderSkipExitAnimations = config.preloaderSkipExitAnimations ?? false;
		AnApp.instance = this;
	}

	public static get self(): AnApp
	{
		if (!AnApp.instance)
			throw new Error("AnApp ещё не инициализирован");

		return AnApp.instance;
	}

	/**
	 * Запускает приложение
	 */
	public async start(): Promise<void>
	{
		if (this.isStarted) return;

		// Инициализация ядра игры
		await AnCore.init();
		// Инициализация управления
		AnControls.init();
		this.setupInputRouting();

		await this.startPreloader();
		this.isStarted = true;
	}

	/**
	 * Перенаправление событий ввода в текущее меню
	 */
	private setupInputRouting(): void
	{
		AnEvents.on(AnControlsEvent.PointerDown, this.forwardEvents.bind(this));
		AnEvents.on(AnControlsEvent.PointerMove, this.forwardEvents.bind(this));
		AnEvents.on(AnControlsEvent.PointerUp, this.forwardEvents.bind(this));
		AnEvents.on(AnControlsEvent.PointerCancel, this.forwardEvents.bind(this));
		AnEvents.on(AnControlsEvent.MouseWheel, this.forwardEvents.bind(this));


		// Отслеживаем потерю фокуса окном браузера
		window.addEventListener('blur', () =>
		{
			if (AnConfig.devMode) AnLog.debug('Приложение потеряло фокус');
			this.paused = true;

			AnEvents.emit('app:lostFocus');
		});

		// Отслеживаем возвращение фокуса окну браузера
		window.addEventListener('focus', () =>
		{
			if (AnConfig.devMode) AnLog.debug('Приложение получило фокус');
			this.paused = false;
			AnEvents.emit('app:getFocus');
		});
	}

	private forwardEvents(e: AnEvent)
	{
		const activeMenu = this.getActiveMenu();

		// Эмулируем событие ввода, только для данного меню, например:
		// 'mainmenu:controls:mouse:mouseup'
		if (activeMenu) AnEvents.emit(`${className(activeMenu)}:${e.event}`, e.data);

	}

	/**
	 * Запуск прелоадера
	 */
	private async startPreloader(): Promise<void>
	{
		const preloader = new AnPreloader({
			skipExitAnimations: this.preloaderSkipExitAnimations
		}, {
			onStart: () => this.onPreloaderStart(),
			onProgress: (percent: number) => this.onPreloaderProgress(percent),
			onComplete: () =>
			{
				preloader.hide(() =>
				{
					runAfter(0.1, () => this.onPreloaderComplete());
				});
			},
		});


		await preloader.start();
	}

	/**
	 * Здесь можно добавить паралельные загрузки музыки, sdk, и т.д.
	 */
	protected onPreloaderStart(): void { };

	/**
	 * Здесь можно прокидывать значение прогресса
	 */
	protected onPreloaderProgress(percent: number): void { };

	/**
	 * Запуск основной игры
	 */
	protected onPreloaderComplete(): void { };

	/**
	 * Регистрация нового меню
	 */
	public registerMenu(menu: AnMenu): void
	{
		this.menus.push(menu);
	}

	/**
	 * Удаление меню из списка
	 */
	public unregisterMenu(menu: AnMenu): void
	{
		removeByValue(this.menus, menu);
	}

	/**
	 * Получить активное меню
	 */
	public getActiveMenu(): AnMenu | null
	{
		return this.menus.length > 0 ? this.menus[this.menus.length - 1] : null;
	}


	// ПАУЗА при потере фокуса
	private _paused: boolean = false;

	public get paused(): boolean
	{
		return this._paused;
	}

	public set paused(paused: boolean)
	{
		if (this._paused === paused) return;

		this._paused = paused;

		if (paused)
		{
			AnMainLoop.stop();
			Howler.mute(true);
		}
		else
		{
			AnMainLoop.start();
			Howler.mute(false);
		}
	}
}