import { PIXI } from "angine/singleton";

export const AnAnchor = {
	// Угловые
	TopLeft: new PIXI.Point(0, 0),
	TopRight: new PIXI.Point(1, 0),
	BottomLeft: new PIXI.Point(0, 1),
	BottomRight: new PIXI.Point(1, 1),

	// Центральные
	Center: new PIXI.Point(0.5, 0.5),
	TopCenter: new PIXI.Point(0.5, 0),
	BottomCenter: new PIXI.Point(0.5, 1),
	LeftCenter: new PIXI.Point(0, 0.5),
	RightCenter: new PIXI.Point(1, 0.5),

	// Дополнительные полезные варианты
	MiddleTop: new PIXI.Point(0.5, 0),    // Алиас для TopCenter
	MiddleBottom: new PIXI.Point(0.5, 1),  // Алиас для BottomCenter
	MiddleLeft: new PIXI.Point(0, 0.5),    // Алиас для LeftCenter
	MiddleRight: new PIXI.Point(1, 0.5)    // Алиас для RightCenter
} as const;

export type AnAnchor = typeof AnAnchor[keyof typeof AnAnchor] | PIXI.Point;