import { AnVoidCallback, uptime } from "angine/utils/AnHelpers.js";
import { AnLog } from "angine/utils/AnLog.js";
import { AnSaveData, AnSaveInterface } from "angine/utils/AnStorage.js";
import { G } from "../game/G.js";


export enum PlatformType
{
	Standalone = "standalone",
	Yandex = "yandex",
	CrazyGames = "crazygames",
	VK = "vk",
	GamePix = "gamepix",
	GameMonetize = "gamemonetize",
	Y8 = "y8",
	PlayDeck = "playdeck",
	WGPlayground = "wgplayground",
}

// список платформ для которых запрещена аналитика
export function forbidAnalyticsForPlatform() { return [PlatformType.GamePix].includes(Platform.type); };


export enum PlatformAds
{
	Rewarded = "Rewarded",
	Fullscreen = "Fullscreen",
}


export interface PlatformAdsCallbacks
{
	onOpen?: AnVoidCallback;
	onClose?: AnVoidCallback;
	onError?: AnVoidCallback;
	onCloseRewarded?: AnVoidCallback;
}

export enum PlatformEvent
{
	/*
		GameLoaded вызывается, когда игра загрузила все ресурсы 
		и готова к взаимодействию с пользователем 
	*/
	GameLoaded = "GameLoaded",

	/*
		NewLevel вызывается каждый раз, когда пользователь 
		переходит на новый уровень
	*/
	NewLevel = "NewLevel",

	/*
		CoolMoment вызывается если в вашей игре произошел какой-либо 
		«счастливый момент». Это может быть разблокировка особого 
		предмета или запуск интересного события в игре.
	*/
	CoolMoment = "CoolMoment",

	/** 
		GameplayStart вызывается, когда игрок начинает или возобновляет 
		игровой процесс:
		- запуск уровня
		- закрытие меню
		- снятие с паузы
		- возобновление игры после показа рекламы
		- возвращение в текущую вкладку браузера
	 * */
	GameplayStart = "GameplayStart",


	/** 
		GameplayStart вызывается, когда игрок приостанавливает 
		или завершает игровой процесс:
		- прохождение уровня или проигрыш
		- вызов меню
		- пауза в игре
		- показ полноэкранной или rewarded-рекламы
		- уход в другую вкладку браузера
	 */
	GameplayStop = "GameplayStop",
}



export interface PlatformInterface extends AnSaveInterface
{
	// === Инициализация ===
	init(): Promise<void>;
	get initialized(): boolean;
	get visualName(): string | null;

	onLoadProgress: ((percent: number) => void) | null;


	// модификация параметров игры исходя из платформы
	modifyGameParams(G: any): void;

	//можно ли переходить к самой игре (для реализации например кнопки play в оболочке платформы)
	get lastPrepareToPlayEnded(): boolean;


	// === Пользователь ===
	get playerName(): string; //пустая строка если гость или не доступно
	get playerLoggedIn(): boolean;
	get currentLanguage(): string | null;

	// === Таблицы рекордов ===
	sendScoreToLeaderboard(boardID: string, score: number): void;

	// === Реклама ===
	get canShowAds(): boolean;
	showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks): void;

	// === Разметка событий для платформы ===
	reportEvent(event: PlatformEvent, data?: any): void;
}

// Глобальная константа для доступа к платформе, инициализируется в PlatformLoader
// name - для визуального отображения имени платформы
export const Platform: { type: PlatformType, sdk: PlatformInterface | null, visualName: string | null } =
	{ type: PlatformType.Standalone, sdk: null, visualName: null };



export abstract class PlatformBase implements PlatformInterface
{
	protected _initialized = false;

	// можно повесить обработчик события загрузки игры
	public onLoadProgress: ((percent: number) => void) | null = null;

	abstract init(): Promise<void>;

	public get initialized(): boolean
	{
		return this._initialized;
	}

	public get visualName(): string | null { return null; };


	//можно ли переходить к самой игре (для реализации например кнопки play в оболочке платформы)
	public get lastPrepareToPlayEnded(): boolean { return true; };

	// модификация параметров игры исходя из платформы
	public modifyGameParams(G: any): void { };


	// === Пользователь ===
	get playerName(): string { return ""; }; //пустая строка если гость или не доступно
	get playerLoggedIn(): boolean { return false; };
	get currentLanguage(): string | null { return null; }

	// === Таблицы рекордов (по умолчанию ничего не делает) ===
	public sendScoreToLeaderboard(boardID: string, score: number): void { }

	// === Реклама ===
	private _lastTimeShown: number = uptime();
	private _adsCooldownSec: number = G.adsCooldownMin * 60; // кулдаун перед показом следующей рекламы
	public get canShowAds(): boolean
	{
		const currentCooldown = uptime() - this._lastTimeShown;
		const result = currentCooldown > this._adsCooldownSec;

		if (AnConfig.devMode) AnLog.debug(`[canShowAds] с последней рекламы прошло ${currentCooldown / 60} мин. (текущий куллдаун ${this._adsCooldownSec / 60} мин.) ${result ? ' рекламу можно показать опять' : ' рекламу нельзя показывать'}`);
		return result;
	}

	public showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks): void
	{
		// только для фуллскрина используем куллдаун
		if (type === PlatformAds.Fullscreen)
			this._lastTimeShown = uptime();

	}

	// === Облачные сохранения (по умолчанию не работает) ===
	public async loadData(): Promise<AnSaveData> { throw new Error("Облачные сохранения не реализованы"); };
	public async saveData(data: AnSaveData): Promise<void> { throw new Error("Облачные сохранения не реализованы"); };
	public async clearData(): Promise<void> { throw new Error("Облачные сохранения не реализованы"); };

	// === Разметка событий для платформы ===
	public reportEvent(event: PlatformEvent, data?: any): void
	{
		// по умолчанию ничего не делаем
	}
}