import { AnEvents } from "angine/utils/AnEvents";

enum AnLogLevel
{
	DEBUG = 0,
	INFO = 1,
	WARN = 2,
	ERROR = 3,

	/**
	 * Полное отключение логирования. Используется:
	 * - В production-сборках
	 * - Для тестов производительности
	 * - В релизных версиях библиотек
	 */
	SILENT = 4
}

const badgesStyle: Record<AnLogLevel, string> = {
	[AnLogLevel.SILENT]: '',
	[AnLogLevel.DEBUG]: 'color: #666; background: #e0e0e0; padding: 2px 4px; border-radius: 10px; font-weight: bold;',
	[AnLogLevel.INFO]: 'color: #fff; background: #2196F3; padding: 2px 4px; border-radius: 10px; font-weight: bold;',
	[AnLogLevel.WARN]: 'color: #000; background: #FFC107; padding: 2px 4px; border-radius: 10px; font-weight: bold;',
	[AnLogLevel.ERROR]: 'color: #fff; background: #F44336; padding: 2px 4px; border-radius: 10px; font-weight: bold;',
};


const badgesEmoji: Record<AnLogLevel, string> = {
	[AnLogLevel.SILENT]: '',
	[AnLogLevel.DEBUG]: '🐛',
	[AnLogLevel.INFO]: 'ℹ️',
	[AnLogLevel.WARN]: '⚠️',
	[AnLogLevel.ERROR]: '🔥',
};

const timestampStyle = 'color: #888; font-style: italic;';

type AnLogMessage = {
	level: AnLogLevel;
	message: string;
	data?: any;
	timestamp: Date;
};


/**
 * Статический класс для многоуровневого логирования с расширенными возможностями:
 * - Поддержка уровней логирования: DEBUG, INFO, WARN, ERROR, SILENT
 * - Ведение журнала сообщений с ограничением размера истории
 * - Интеграция с системой событий (AnEvents)
 * - Гибкая конфигурация параметров логирования  
 */
export class AnLog
{
	private static level: AnLogLevel = AnLogLevel.DEBUG;
	private static history: AnLogMessage[] = [];
	private static maxHistory: number = AnParams.maxLogHistory;
	private static enableHistory: boolean = false;
	private static enableEvents = false;

	// Приватный конструктор т.к. класс статический
	private constructor() { }

	/**
	 * Конфигурация логгера
	 */
	public static init(options: {
		level?: AnLogLevel;
		maxHistory?: number;
		enableHistory?: boolean;
		enableEvents?: boolean;
	}): void
	{
		if (options.level !== undefined) this.level = options.level;
		if (options.maxHistory !== undefined) this.maxHistory = options.maxHistory;
		if (options.enableHistory !== undefined) this.enableHistory = options.enableHistory;
		if (options.enableEvents !== undefined) this.enableEvents = options.enableEvents;
	}

	/**
	 * Самый детализированный отладочный уровень. Используется для:
	 * - Отладки сложных участков кода
	 * - Логирования промежуточных значений
	 * - Трассировки вызовов методов
	 * В production обычно отключается.
	 * Пример: "Render loop started (frameId: 42)"
	 */
	public static debug(message: string, data?: any): void
	{
		if (AnConfig.devMode) // отладочные сообщения выводим только при разработке
		{
			this.log(AnLogLevel.DEBUG, message, data);
		}
	}

	/**
	 * Информационные сообщения о работе системы. Используется для:
	 * - Старта/остановки модулей
	 * - Важных, но не критичных событий
	 * - Основных этапов работы
	 * Пример: "Game scene loaded in 1.25s"
	 */
	public static info(message: string, data?: any): void
	{
		this.log(AnLogLevel.INFO, message, data);
	}

	/**
	 * Потенциально проблемные ситуации. Используется для:
	 * - Нестандартных, но обработанных случаев
	 * - Устаревших API (deprecation warnings)
	 * - Подозрительного поведения
	 * Пример: "Texture 'grass.png' has unusual size 513x513"
	 */
	public static warn(message: string, data?: any): void
	{
		this.log(AnLogLevel.WARN, message, data);
	}

	/**
	 * Критические ошибки. Используется для:
	 * - Необработанных исключений
	 * - Некритичных сбоев (например, потеря соединения)
	 * - Ошибок валидации
	 * Пример: "Failed to load asset: 404 Not Found"
	 */
	public static error(message: string, data?: any): void
	{
		this.log(AnLogLevel.ERROR, message, data);
	}


	/**
	 * Выводит "пинг" с информацией о месте вызова:
	 * - Имя функции
	 * - Файл:строка:колонка
	 */
	public static ping(extra?: string): void
	{
		if (!AnConfig.devMode) return;

		if (this.level > AnLogLevel.DEBUG) return;

		const stack = new Error().stack;
		if (!stack) return;

		const lines = stack.split('\n');

		let callerLine: string | null = null;

		// Пропускаем первые 2 строки: "Error" и "AnLog.pingHere"
		for (let i = 2; i < lines.length; i++)
		{
			const line = lines[i].trim();
			if (!line.includes('AnLog.ping') && !line.includes('at Object.'))
			{
				callerLine = line;
				break;
			}
		}

		if (!callerLine) return;

		// Просто выводим строку из стека
		this.log(AnLogLevel.DEBUG, extra ? `📍 PING[${extra}] ${callerLine}` : `📍 PING ${callerLine}`);
	}

	/**
	 * Получение истории логов
	 */
	public static getHistory(filter?: AnLogLevel): AnLogMessage[]
	{
		return filter !== undefined
			? this.history.filter(entry => entry.level >= filter)
			: [...this.history];
	}

	/**
	 * Логирование с учетом всех настроек
	 */
	private static log(level: AnLogLevel, message: string, data?: any): void
	{
		if (level < this.level) return;

		const timestamp = new Date();

		if (this.enableHistory || this.enableEvents)
		{
			const logEntry: AnLogMessage = {
				level,
				message,
				data,
				timestamp
			};

			// Сохранение в историю (если включено)
			if (this.enableHistory)
			{
				this.history.push(logEntry);
				if (this.history.length > this.maxHistory)
				{
					this.history.shift();
				}
			}
			// Отправка события (если включено)
			if (this.enableEvents)
			{
				AnEvents.emit('log-message', logEntry);
			}
		}

		// console.log(
		// 	'%cВнимание! Это важное сообщение!',
		// 	'color: white; background: red; font-weight: bold; padding: 5px; border-radius: 3px;',
		// 	'',
		// 	'просто текст'
		// );

		// Вывод в консоль
		const badge = `${badgesEmoji[level]} ${AnLogLevel[level]}`;
		const timestampText = `${timestamp.toLocaleTimeString()}`;
		const messageWithData = data !== undefined ? `${message} %o` : message; // %o для объекта data

		// Собираем строку с %c и аргументы
		const formatLogString = `%c${badge}%c ${timestampText}%c ${messageWithData}`;

		//добавляем стили
		const styleArgs = [
			badgesStyle[level], // стиль для badge
			timestampStyle,    // стиль для timestamp
			'',                // сброс стилей для message
		];

		// Добавляем data, если есть
		const consoleArgs = [formatLogString, ...styleArgs];
		if (data !== undefined) consoleArgs.push(data);

		switch (level)
		{
			case AnLogLevel.DEBUG: console.debug(...consoleArgs); break;
			case AnLogLevel.INFO: console.info(...consoleArgs); break;
			case AnLogLevel.WARN: console.warn(...consoleArgs); break;
			case AnLogLevel.ERROR: console.error(...consoleArgs); break;
		}
	}
}