import { AnEvents } from "angine/utils/AnEvents";
import { AnLog } from "angine/utils/AnLog";




/** Макрос для value * AnViewport.scale */
export const scaled = (value: number) => value * AnViewport.scale;

/**
 * Класс для управления viewport (холстом) приложения.
 * Обеспечивает:
 * - Создание и управление canvas элементом
 * - Инициализацию WebGL контекста
 * - Управление размерами и масштабированием
 * - Автоматическую подстройку под DPI устройства
 */
export class AnViewport
{
	private static _canvas: HTMLCanvasElement;
	private static _glContext: WebGLRenderingContext | WebGL2RenderingContext | GPUCanvasContext;

	// Базовое разрешение для масштабирования
	private static _baseWidth = AnParams.baseWidth;
	private static _baseHeight = AnParams.baseHeight;

	// Масштабирование
	private static _scale = 1;
	private static _scaleWidth = 1;
	private static _scaleHeight = 1;

	// Размеры
	private static _physWidth = 0;
	private static _physHeight = 0;
	private static _width = 0;
	private static _height = 0;
	private static _maxWidth = 0;



	private constructor() { }

	public static async init()
	{
		AnViewport.createCanvas();
		await AnViewport.initGLContext();

		document.body.appendChild(AnViewport._canvas);

		// Инициализируем размеры
		AnViewport.resize(window.innerWidth, window.innerHeight);
	}

	// --- Публичные свойства ---

	/** Canvas элемент */
	public static get canvas(): HTMLCanvasElement
	{
		return AnViewport._canvas;
	}

	/** WebGL2 контекст */
	public static get glContext(): WebGLRenderingContext | WebGL2RenderingContext | GPUCanvasContext
	{
		return AnViewport._glContext;
	}

	/** Ширина viewport в физических пикселях (с учетом devicePixelRatio) */
	public static get physWidth(): number
	{
		return AnViewport._physWidth;
	}

	/** Высота viewport в физических пикселях (с учетом devicePixelRatio) */
	public static get physHeight(): number
	{
		return AnViewport._physHeight;
	}

	/** Половина ширины viewport */
	public static get halfWidth(): number
	{
		return AnViewport._width * 0.5;
	}

	/** Половина высоты viewport */
	public static get halfHeight(): number
	{
		return AnViewport._height * 0.5;
	}

	/** Максимальный размер по ширине для интерфейса (чтобы не разъезжалось на ultra-wide) */
	public static get maxWidth()
	{
		return AnViewport._maxWidth;
	}

	/** Соотношение сторон экрана */
	public static get aspectRatio(): number
	{
		return AnViewport._physWidth / AnViewport._physHeight;
	}

	/** Портретный режим отображения */
	public static get portraitMode(): boolean
	{
		return AnViewport.width < AnViewport.height;
	}

	/** Альбомный режим отображения */
	public static get landscapeMode(): boolean
	{
		return AnViewport.width >= AnViewport.height;
	}

	/** Ширина viewport в логических (CSS) пикселях */
	public static get width(): number
	{
		return AnViewport._width;
	}

	/** Высота viewport в логических (CSS) пикселях */
	public static get height(): number
	{
		return AnViewport._height;
	}

	/** Коэффициент масштабирования */
	public static get scale(): number
	{
		return AnViewport._scale;
	}

	/** Базовое разрешение (ширина) */
	public static get baseWidth(): number
	{
		return AnViewport._baseWidth;
	}

	/** Базовое разрешение (высота) */
	public static get baseHeight(): number
	{
		return AnViewport._baseHeight;
	}

	// --- Публичные методы ---

	/**
	 * Устанавливает базовое разрешение для масштабирования
	 * @param width - Ширина базового разрешения
	 * @param height - Высота базового разрешения
	 */
	public static setBaseSize(width: number, height: number): void
	{
		AnViewport._baseWidth = width;
		AnViewport._baseHeight = height;
		AnViewport.updateScaleFactor();
	}

	/**
	 * Изменяет размеры viewport
	 * @param newLogicalWidth - Новая ширина в логических пикселях
	 * @param newLogicalHeight - Новая высота в логических пикселях
	 */
	public static resize(newLogicalWidth: number, newLogicalHeight: number): void
	{

		AnViewport._width = newLogicalWidth;
		AnViewport._height = newLogicalHeight;

		AnViewport._maxWidth = Math.min(AnViewport._width, AnViewport._height);

		// Физические размеры с учетом DPI
		AnViewport._physWidth = Math.floor(newLogicalWidth * devicePixelRatio);
		AnViewport._physHeight = Math.floor(newLogicalHeight * devicePixelRatio);

		// Применяем размеры к canvas
		// AnViewport._canvas.width = AnViewport._physWidth;
		// AnViewport._canvas.height = AnViewport._physHeight;
		// AnViewport._canvas.style.width = `${newLogicalWidth}px`;
		// AnViewport._canvas.style.height = `${newLogicalHeight}px`;

		// Обновляем масштаб
		AnViewport.updateScaleFactor();

		// посылаем сообщение по пересчету всех позиций и размеров
		AnViewport.invalidate();


		AnLog.info(`Размеры вьюпорта: ${AnViewport._physWidth}x${AnViewport._physHeight} масштаб: ${AnViewport._scale.toFixed(3)}`);
	}

	// посылаем сообщение по пересчету всех позиций и размеров
	public static invalidate()
	{
		AnEvents.emit("viewport:resize", { width: AnViewport._width, height: AnViewport._height });
	}

	// --- Приватные методы ---

	/** Создает canvas элемент */
	private static createCanvas()
	{
		AnViewport._canvas = document.createElement('canvas');
	}

	/** Инициализирует WebGL2 контекст */
	private static async initGLContext()
	{
		//TODO: проверка существования канваса


		// Пытаемся создать WebGPU контекст
		if ('gpu' in navigator)
		{
			try
			{
				const adapter = await navigator.gpu.requestAdapter({
					//powerPreference: 'high-performance'
				});

				if (adapter)
				{
					const device = await adapter.requestDevice();
					const gpuContext = AnViewport._canvas.getContext('webgpu');

					if (gpuContext)
					{
						const presentationFormat = navigator.gpu.getPreferredCanvasFormat();
						gpuContext.configure({
							device: device,
							format: presentationFormat,
							alphaMode: 'premultiplied', // аналог alpha: true
							// antialias настраивается через multisample в render pipeline
							// preserveDrawingBuffer не имеет прямого аналога
							// stencil настраивается через depthStencilFormat
						});

						AnViewport._glContext = gpuContext;
						AnLog.info("Используется рендер через WebGPU");
						return;
					}
				}
			} catch (e)
			{
				AnLog.warn("WebGPU доступен, но инициализация не удалась: ", e);
			}
		}

		const glConfing = {
			alpha: true,
			antialias: true,
			powerPreference: 'high-performance',
			preserveDrawingBuffer: true,
			stencil: true
		};

		// Пытаемся создать WebGL2 контекст
		const webGL2Context = AnViewport._canvas.getContext('webgl2', glConfing) as WebGL2RenderingContext;

		if (webGL2Context)
		{
			AnViewport._glContext = webGL2Context;
			AnLog.info("Используется рендер через WebGL2");
			return;
		}

		// Пытаемся создать WebGL1 контекст
		const webGL1Context = AnViewport._canvas.getContext('webgl', glConfing) as WebGLRenderingContext;

		if (webGL1Context)
		{
			AnViewport._glContext = webGL1Context;
			AnLog.info("Используется рендер через WebGL1");
			return;
		}

		throw new Error('Аппаратное ускорение (WebGPU/WebGL2/WebGL) не поддерживается, продолжение невозможно :(');
	}

	/** Обновляет коэффициент масштабирования */
	private static updateScaleFactor(): void
	{
		// AnViewport._scaleWidth = AnViewport._width / AnViewport._baseWidth;
		// AnViewport._scaleHeight = AnViewport._height / AnViewport._baseHeight;
		// AnViewport._scale = Math.min(AnViewport._scaleWidth, AnViewport._scaleHeight);




		AnViewport._scaleWidth = AnViewport._width / AnViewport._baseWidth;
		AnViewport._scaleHeight = AnViewport._height / AnViewport._baseHeight;
		AnViewport._scale = (AnViewport._scaleWidth + AnViewport._scaleHeight) * 0.5;

		//AnLog.warn(`${AnViewport._width} ${AnViewport._baseWidth} ${AnViewport._height} ${AnViewport._baseHeight}`);

		// AnViewport._scaleWidth = Math.min(AnViewport._width, AnViewport._height) / AnViewport._baseWidth;
		// AnViewport._scaleHeight = Math.min(AnViewport._width, AnViewport._height) / AnViewport._baseHeight;
		// AnViewport._scale = Math.min(AnViewport._scaleWidth, AnViewport._scaleHeight);
	}
}