// src/ui/AnFader.ts
import { AnImage, AnImageConfig } from "angine/ui/AnImage";
import { AnTween, AnTweenConfig } from "angine/anim/AnTween";
import { AnEase } from "angine/anim/AnEase";
import { AnCore } from "angine/core/AnCore";
import { AnEvents } from "angine/utils/AnEvents";
import { AnViewport } from "angine/core/AnViewport";
import { AnVoidCallback } from "angine/utils/AnHelpers";
import { AnLog } from "angine/utils/AnLog";
import { PIXI } from "angine/singleton";
import { AnAnchor } from "./AnAnchor";


export interface AnFaderCallbacks
{
	onComplete?: AnVoidCallback;
}

export interface AnFaderConfig
{
	type: 'in' | 'out';
	delay?: number; // задержка фейдера
	duration?: number; // длительность фейдера
	tint?: number; // Цвет заливки (по умолчанию 0x000000)
	alpha?: number; // Начальная прозрачность (по умолчанию 0)
	autoTerminate?: boolean;
	callbacks?: AnFaderCallbacks;
}

export class AnFader extends AnImage
{
	private faderType: 'in' | 'out';
	private duration: number;
	private delay: number;
	private autoTerminate: boolean;
	private callbacks?: AnFaderCallbacks;

	constructor(config: AnFaderConfig)
	{
		// const {
		// 	color = 0x000000,
		// 	alpha = 0,
		// 	...imageConfig
		// } = config;

		super({
			anchor: AnAnchor.TopLeft,
			resizeStrategy: () =>
			{
				this.width = AnViewport.width;
				this.height = AnViewport.height;
			},
			...config,
		});

		this.faderType = config.type;
		this.delay = config.delay ?? 0;
		this.duration = config.duration ?? 2;
		this.autoTerminate = config.autoTerminate ?? true;
		this.callbacks = config.callbacks;

		//this.recalcPositionAndSize();

		this.createTween();

		this.addToCleanup(AnEvents.on("viewport:resize", () => this.resizeUI()).unsub);
		this.resizeUI();
	}

	private createTween()
	{

		const tween = new AnTween({
			target: this,
			from: { alpha: this.faderType == 'in' ? 0 : 1 },
			to: { alpha: this.faderType == 'in' ? 1 : 0 },
			duration: this.duration,
			delay: this.delay,
			easing: this.faderType === 'in' ? AnEase.easeOut : AnEase.easeIn,
			updater: AnCore.updater, //FIXME: не уверен что добавлять в глобальный апдейтер хорошая идея

			callbacks: {
				onComplete: () =>
				{
					this.callbacks?.onComplete?.();

					if (this.autoTerminate)
						this.terminate();
				}
			}
		}
		);

		this.addToCleanup(() => tween.terminate());
	}

	protected resizeUI()
	{
		this.applyResizeStrategy();
	}
}