import { AnUIGroupElement } from "angine/ui/AnUIGroupElement";
import { AnImage } from "angine/ui/AnImage";
import { AnLabel, AnLabelTextStyleConfig } from "angine/ui/AnLabel";
import { AnAnchor } from "angine/ui/AnAnchor";
import { AnEvents } from "angine/utils/AnEvents";
import { AnLog } from "angine/utils/AnLog";
import { AnUIGroupElementConfig } from "angine/ui/AnUIGroupElement";
import { AnImageConfig } from "angine/ui/AnImage";
import { AnTextAlign, AnTextConfig, AnTextStyleConfig } from "angine/2D/AnText";
import { AnViewport, scaled } from "angine/core/AnViewport";
import { PIXI, Default } from 'angine/singleton';
import { AnUIResizeStrategyFunc } from "./AnUIElement";

// Тип ориентации
export enum AnCounterLayout
{
	Horizontal = "horizontal", // Иконка слева, текст справа
	Vertical = "vertical"       // Иконка сверху, текст снизу
}

// Тип отображения
export enum AnCounterDisplayMode
{
	Counter = "counter", // Отображается счётчик
	Status = "status",   // Отображается статус
}

// Тип смены статуса
export enum AnCounterStatusChange
{
	Zero = "zero", // Статус отображается при достижении нуля
	Max = "max", // Статус отображается при достижении максимума
}

// Конфиг
export interface AnCounterConfig extends AnUIGroupElementConfig
{
	// Счётчик
	currentCount: number;
	maxCount?: number;

	layout?: AnCounterLayout; // horizontal | vertical
	displayMode?: AnCounterDisplayMode; // counter | status
	statusChange?: AnCounterStatusChange; // zero | max

	mainIcon?: AnImageConfig; // иконка всегда отображается

	labelTextStyle?: AnLabelTextStyleConfig;

	// Статус
	statusIcon?: AnImageConfig;
	statusIconSizeFactor?: number;
}

export class AnCounter extends AnUIGroupElement
{
	private _currentCount: number = 0;
	private _maxCount: number = 100;

	private readonly counterOffset = 5;

	protected mainIcon: AnImage;
	private labelCounter: AnLabel;
	private statusIcon?: AnImage;
	private statusIconSizeFactor?: number;

	private layout: AnCounterLayout;
	private _displayMode: AnCounterDisplayMode;
	private statusChange: AnCounterStatusChange;



	constructor(config: AnCounterConfig)
	{
		super(config);

		this.layout = config.layout ?? AnCounterLayout.Horizontal;
		this._displayMode = config.displayMode ?? AnCounterDisplayMode.Counter;
		this.statusChange = config.statusChange ?? AnCounterStatusChange.Zero;

		this._maxCount = config.maxCount ?? config.currentCount;
		this._currentCount = config.currentCount;


		// Иконка (всегда отображается)
		this.mainIcon = this.addUIElement(
			"mainIcon",
			new AnImage({
				...config.mainIcon,
				anchor: AnAnchor.TopLeft,
			})
		);

		// Счетчик
		this.labelCounter = this.addUIElement(
			"counter",
			new AnLabel({
				text: {
					...config.labelTextStyle,
					textSource: () => this._currentCount.toString(),
					textAlign: this.layout === AnCounterLayout.Horizontal ? AnTextAlign.Left : AnTextAlign.Center,
					autoUpdateLang: false,
				},
				//backgroundColor: 0x333333,
				labelAlign: this.layout === AnCounterLayout.Horizontal ? AnTextAlign.Left : AnTextAlign.Center,
				anchor: this.layout === AnCounterLayout.Horizontal ? AnAnchor.LeftCenter : AnAnchor.TopCenter,
			})
		);
		this.labelCounter.visible = this._displayMode === AnCounterDisplayMode.Counter;

		// Статус-изображение
		if (config.statusIcon)
		{
			this.statusIcon = this.addUIElement(
				"statusIcon",
				new AnImage({
					...config.statusIcon,
					anchor: this.layout === AnCounterLayout.Horizontal ? AnAnchor.LeftCenter : AnAnchor.TopCenter,
				})
			);

			this.statusIconSizeFactor = config.statusIconSizeFactor ?? 1;

			this.statusIcon.visible = this._displayMode === AnCounterDisplayMode.Status;
		}


		// +++ resize strategy +++
		this.defaultResizeStrategy =
			() =>
			{

				const counterOffsetScaled = scaled(this.counterOffset);

				if (this.layout === AnCounterLayout.Horizontal)
				{
					this.mainIcon.width = this.mainIcon.realWidth * (this.scaledHeight / this.mainIcon.realHeight);
					this.mainIcon.height = this.scaledHeight;
					this.mainIcon.position.set(0, 0);

					this.labelCounter.scaledWidth = this.scaledWidth - (this.mainIcon.width + counterOffsetScaled);
					this.labelCounter.scaledHeight = this.scaledHeight;
					this.labelCounter.applyDefaultResizeStrategy();
					this.labelCounter.position.set(this.mainIcon.width + counterOffsetScaled, this.mainIcon.height * 0.5);

					if (this.statusIcon)
					{
						this.statusIcon.width = this.scaledHeight * 0.5;
						this.statusIcon.height = this.scaledHeight * 0.5;
						this.statusIcon.position.set(this.labelCounter.x, this.labelCounter.y);
					}
				}
				else
				{
					this.mainIcon.width = this.scaledWidth;
					this.mainIcon.height = this.mainIcon.realHeight * (this.scaledWidth / this.mainIcon.realWidth);
					this.mainIcon.position.set(0, 0);

					this.labelCounter.scaledWidth = this.scaledWidth;
					this.labelCounter.scaledHeight = this.scaledHeight - (this.mainIcon.height + counterOffsetScaled);
					this.labelCounter.applyDefaultResizeStrategy();
					this.labelCounter.position.set(this.mainIcon.width * 0.5, this.mainIcon.height + counterOffsetScaled - this.labelCounter.scaledHeight * 0.3);

					if (this.statusIcon)
					{
						this.statusIcon.width = this.scaledWidth * 0.5;
						this.statusIcon.height = this.scaledWidth * 0.5;
						this.statusIcon.position.set(this.labelCounter.x, this.labelCounter.y);
					}
				}



			};

		this.configResizeStrategy(config.resizeStrategy);
	}

	public get nopadScaledWidth(): number
	{
		return this.mainIcon.width + scaled(this.counterOffset) + this.labelCounter.getTextWidth();
	}

	public getMainIconGlobalPos(): PIXI.Point
	{
		const globalIconPos = this.mainIcon.getGlobalPosition();
		return new PIXI.Point(globalIconPos.x + this.mainIcon.width * 0.5, globalIconPos.y + this.mainIcon.height * 0.5);
		// return this.layout === AnCounterLayout.Horizontal ?
		// 	new PIXI.Point(globalIconPos.x + this.mainIcon.scaledWidth * 0.5, globalIconPos.y + this.mainIcon.scaledWidth * 0.5) :
		// 	new PIXI.Point(globalIconPos.x, globalIconPos.y + this.mainIcon.scaledHeight * 0.5);
	}


	public modify(value: number = 1): void
	{
		this._currentCount = Math.min(this._currentCount + value, this._maxCount);
		if (this._currentCount < 0) this._currentCount = 0;
		this.updateCounter();
	}

	public set(current: number = 0): void
	{
		this._currentCount = Math.min(current, this._maxCount);
		if (this._currentCount < 0) this._currentCount = 0;
		this.updateCounter();
	}

	public updateTextColor(color: number): void
	{
		this.labelCounter.textColor = color;
	}

	public get currentCount(): number
	{
		return this._currentCount;
	}

	public set displayMode(mode: AnCounterDisplayMode)
	{
		this._displayMode = mode;
		this.labelCounter.visible = this._displayMode === AnCounterDisplayMode.Counter;

		if (this.statusIcon)
			this.statusIcon.visible = this._displayMode === AnCounterDisplayMode.Status;
	}

	public get finished(): boolean
	{
		return this.statusIcon?.visible ?? false;
	}


	private updateCounter(): void
	{
		if (this.labelCounter)
		{
			this.labelCounter.updateText();
		}


		if (this._displayMode === AnCounterDisplayMode.Counter &&
			((this.statusChange === AnCounterStatusChange.Zero && this._currentCount === 0) ||
				(this.statusChange === AnCounterStatusChange.Max && this._currentCount === this._maxCount))
		)
		{
			this.displayMode = AnCounterDisplayMode.Status;
			this.onShowStatus();
		}

	}

	protected onShowStatus()
	{

	}

	public override terminate(): void
	{
		super.terminate();
	}
}