import { AnLog } from "angine/utils/AnLog";
import { AnVoidCallback, struct } from "angine/utils/AnHelpers";

/**
 * тип событие
 */
export type AnEvent = { event: string, data?: any };

/**
 * тип обработчика события
 */
export type AnEventCallback = (event: AnEvent) => void;

export class AnEvents
{
	private static listeners: Map<string, Map<symbol, AnEventCallback>> = new Map();

	// Приватный конструктор т.к. класс статический
	private constructor() { }

	/**
	 * Подписка на событие
	 * @param event - Название события (предпочтительно event:item)
	 * @param callback - Функция-обработчик
	 * @returns id и функция для отписки
	 */
	public static on(event: string, callback: AnEventCallback): { unsub: AnVoidCallback, id: symbol }
	{
		if (!AnEvents.listeners.has(event))
			AnEvents.listeners.set(event, new Map());

		const id = Symbol("AnEvents");
		AnEvents.listeners.get(event)!.set(id, callback);

		return { unsub: () => AnEvents.off(event, id), id };
	}

	/**
	 * Отписка от события
	 * @param event - Название события
	 * @param id - ID подписки (символ)
	 */
	public static off(event: string, id: symbol): void
	{
		AnEvents.listeners.get(event)?.delete(id);
	}

	/**
	 * Одноразовая подписка
	 * @param event - Название события
	 * @param callback - Функция-обработчик
	 */
	public static once(event: string, callback: AnEventCallback): void
	{
		const { unsub } = AnEvents.on(event, (event: AnEvent) =>
		{
			callback(event);
			unsub();
		});
	}

	/**
	 * Отправка события
	 * @param event - Название события (предпочтительно event:item)
	 * @param data - Данные для передачи
	 */
	public static emit(event: string, data?: any): void
	{
		AnEvents.listeners.get(event)?.forEach(callback => callback({ event, data }));
	}

	/**
	 * Очистка всех подписок
	 * @param event - Опционально: очистка конкретного события
	 */
	public static clear(event?: string): void
	{
		if (event)
			AnEvents.listeners.delete(event);
		else
			AnEvents.listeners.clear();
	}
}
