import { AnUIElement, AnUIElementConfig, AnUIResizeStrategyFunc } from "angine/ui/AnUIElement";
import { removeByValue, safeDestroyFunc } from "angine/utils/AnHelpers";
import { AnLog } from "angine/utils/AnLog";


/**
 * Конфиг для компонента UIGoalProgress
 */
export interface AnUIGroupElementConfig extends AnUIElementConfig
{
}

/**
 * Базовый класс для группировки UI-элементов
 */
export class AnUIGroupElement extends AnUIElement
{
	public elements: Record<string, AnUIElement> = {};
	public elementsOrder: AnUIElement[] = [];

	//TODO: aligment options?

	constructor(config?: AnUIGroupElementConfig)
	{
		super(config);
	}

	/**
	 * Добавляет UI-элемент в группу
	 * @param name Имя элемента
	 * @param element Элемент
	 */
	public addUIElement<T extends AnUIElement>(
		name: string,
		element: T,
	): T;
	/**
	 * Добавляет UI-элемент в группу (без доступа по имени)
	 * @param element Элемент
	 */
	public addUIElement<T extends AnUIElement>(
		element: T,
	): T;

	// реализация метода с учетом перегрузок
	public addUIElement<T extends AnUIElement>(
		arg1: string | T,
		arg2?: T
	): T
	{
		let name: string | undefined;
		let element: T;

		if (typeof arg1 === "string")
		{
			// Первый случай: name + element
			name = arg1;
			element = arg2 as T;
		} else
		{
			// Второй случай: только element
			element = arg1;
		}

		if (name)
		{
			this.elements[name] = element;
			// для отладки, добавляем ярлык для элемента (pixi devtools)
			if (AnConfig.devMode) element.label = name;
		}
		else
		{
			// для отладки, добавляем ярлык для элемента (pixi devtools)
			if (AnConfig.devMode) element.label = "unnamed ui element";
		}

		this.elementsOrder.push(element);
		this.addGraphics(element); // PIXI.Container method
		return element;
	}


	/**
	 * Удаляет UI-элемент из группы (по имени)
	 * @param name Имя элемента
	 */
	public removeUIElement<T extends AnUIElement>(name: string): T | null;

	/**
	 * Удаляет UI-элемент из группы (по ссылке на объект)
	 * @param element Ссылка на элемент
	 */
	public removeUIElement<T extends AnUIElement>(element: T): T | null;

	/**
	 * Общая реализация метода removeUIElement
	 */
	public removeUIElement<T extends AnUIElement>(arg: string | T): T | null
	{
		let element: T;
		if (typeof arg === "string")
		{
			const name = arg;
			const elem = this.elements[name];
			if (!elem)
			{
				AnLog.warn(`Попытка удалить несуществующий элемент: ${name}`);
				return null;
			}
			element = elem as T;
			delete this.elements[name];
		}
		else
			element = arg;

		removeByValue(this.elementsOrder, element);
		this.removeChild(element);
		return element;
	}

	/**
	 * Удаляет UI-элемент из группы и очищает его (по имени)
	 * @param name Имя элемента
	 */
	public terminateUIElement(name: string): void;

	/**
	 * Удаляет UI-элемент из группы и очищает его (по ссылке)
	 * @param element Ссылка на элемент
	 */
	public terminateUIElement<T extends AnUIElement>(element: T): void;

	/**
	 * Общая реализация метода terminateUIElement
	 */
	public terminateUIElement<T extends AnUIElement>(arg: string | T): void
	{
		const element: T | null = typeof arg === "string" ?
			this.removeUIElement(arg) :
			this.removeUIElement<T>(arg);
		element?.terminate();
	}

	/**
	 * Очищает все элементы группы
	 */
	public cleanUIGroup(): void
	{
		this.elements = {};
		this.elementsOrder.length = 0;
	}

	/**
	 * Завершает работу группы
	 */
	public override terminate(): void
	{
		// удаляем все элементы
		for (const element of this.elementsOrder)
			element.terminate();

		this.cleanUIGroup();
		super.terminate();
	}

	/**
	 * Переопределяем applyResizeStrategy, чтобы обновлять все дочерние элементы
	 */
	public override applyResizeStrategy(): void
	{
		super.applyResizeStrategy(); // вызываем базовый метод для текущего элемента

		// Обновляем все дочерние элементы
		for (const element of this.elementsOrder)
			element.applyResizeStrategy();
	}
}