import { PIXI } from 'angine/singleton';
import { AnViewport } from 'angine/core/AnViewport';
import { initDevtools } from '@pixi/devtools';
import { AnLog } from 'angine/utils/AnLog';
import { AnUI } from 'angine/ui/AnUI';
import { SCALE_MODES } from 'pixi.js';

export class AnRender2D
{
	private static pixiRender: PIXI.Renderer;
	private static _stage: PIXI.Container;

	private constructor() { }

	public static async init()
	{
		//TODO: проверка на инициализацию вьюпорта AnCoreViewport

		// выбираем рендер WebGPU или WebGL
		this.pixiRender = (typeof GPUCanvasContext !== 'undefined') && (AnViewport.glContext instanceof GPUCanvasContext) ? new PIXI.WebGPURenderer() : new PIXI.WebGLRenderer();

		await this.pixiRender.init({
			// @ts-ignore не ругайся на несоотвествие контекста, всё нормально!
			context: AnViewport.glContext,
			canvas: AnViewport.canvas,
			width: AnViewport.physWidth,
			height: AnViewport.physHeight,

			//resolution: window.devicePixelRatio || 1,
			resolution: 1, // Важно: отключаем авто-DPR!
			autoDensity: false, // Отключаем автоматическое масштабирование
			antialias: true, // сглаживание

			//useBackBuffer: true,

			backgroundColor: new PIXI.Color(AnUI.colorSheme.shadow),
			clearBeforeRender: !AnConfig.use3D, // Не очищай холст, если используется Three.js.
		});

		// в этом контейнере будет все находится
		this._stage = new PIXI.Container();

		if (AnConfig.devMode)
		{
			AnLog.warn("PIXI DevTools включен!");
			initDevtools({ stage: this._stage, renderer: this.pixiRender });
		}
	}

	public static get stage()
	{
		return this._stage;
	}

	public static addToFront<T extends PIXI.Container>(child: T): T
	{
		return AnRender2D.stage.addChild(child);
	}

	public static addToBack<T extends PIXI.Container>(child: T): T
	{
		return AnRender2D.stage.addChildAt(child, 0);
	}

	public static terminate(): void
	{
		this.pixiRender.destroy();
	}

	public static resize(width: number, height: number): void
	{
		//this.pixiRender.resolution = window.devicePixelRatio || 1;
		this.pixiRender.resize(width, height);

		// console.log("canvas:", AnViewport.canvas.width, AnViewport.canvas.height);
		// console.log("Viewport (phys):", AnViewport.physWidth, AnViewport.physHeight);
		// console.log("Viewport (logical):", AnViewport.width, AnViewport.height);
		// console.log("DPR:", window.devicePixelRatio);
		// console.log("PIXI renderer resolution:", this.pixiRender.resolution);
		// console.log("Stage scale:", this._stage.scale); // Должно быть (1, 1) или (1/dpr, 1/dpr)
	}

	public static render(): void
	{
		//if (AnConfig.use3D)
		this.pixiRender.resetState();

		this.pixiRender.render(this._stage);
	}
}