export function declarePolyfills()
{

	/**
	 * Полифил для structuredClone через JSON (для старых iOS/Safari)
	 * Вставлять в начало entry-point файла (main.ts / index.ts)
	 */
	if (typeof window.structuredClone !== 'function')
	{
		(window as any).structuredClone = <T>(obj: T): T =>
		{
			if (obj === undefined) return undefined as any;
			return JSON.parse(JSON.stringify(obj));
		};
	}

}