import { addUniqueValue, removeByValue } from "angine/utils/AnHelpers";
import { AnUpdatableInterface } from "angine/mixins/AnUpdatableMixin";


/**
 * Менеджер обновления игровых объектов.
 * Оптимизирован для работы с большим количеством динамических объектов.
 * 
 * Особенности:
 * - Автоматически обрабатывает привязку/отвязку объектов
 * - Гарантирует безопасность при обновлении
 */
export class AnUpdater
{
    private updatables: AnUpdatableInterface[] = [];

    /**
     * Добавляет объект(ы) в список обновляемых
     * @param items - Объект(ы), реализующий интерфейс AnUpdatableInterface
     */
    add(items: AnUpdatableInterface | AnUpdatableInterface[]): void
    {
        if (Array.isArray(items))
            items.forEach(updatable => addUniqueValue(this.updatables, updatable));
        else
            addUniqueValue(this.updatables, items);

    }

    /**
     * Удаляет объект(ы) из списка обновляемых
     * @param items - Объект(ы) для удаления
     */
    remove(items: AnUpdatableInterface | AnUpdatableInterface[]): void
    {
        if (Array.isArray(items))
        {
            items.reduceRight((_, updatable) =>
            {
                removeByValue(this.updatables, updatable);
                return _;
            }, null);
        }
        else
            removeByValue(this.updatables, items);
    }

    /**
     * Обновляет все объекты
     * @param dt - Дельта времени в секундах
     */
    update(dt: number): void
    {
        //this.updatables.forEach(obj => obj.update(dt));
        for (let i = 0; i < this.updatables.length; ++i)
            this.updatables[i].update(dt);
    }

    /**
     * применить заданную функцию ко всем объектам апдейтера 
     * (ради безопасности при удалении или добавлении перебираем в обратном порядке!)
     */
    public forEach(callback: (obj: AnUpdatableInterface) => void) 
    {
        // this.updatables.slice().forEach(callback);
        for (let i = this.updatables.length - 1; i >= 0; i--)
            callback(this.updatables[i]);
    }

    /**
     * Получить количество обновляемых объектов
     */
    get count(): number
    {
        return this.updatables.length;
    }

    /**
     * Очищает список обновляемых объектов
     */
    clear(): void
    {
        this.updatables = [];
    }
}