import { AnDestructibleInterface, AnDestructibleMixin } from "angine/mixins/AnDestructibleMixin";
import { AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";
import { Default, None, PIXI } from "angine/singleton";
import { className, createDebugCross, enhance, safeDestroy, safeDestroyFunc } from "angine/utils/AnHelpers";
import { AnLog } from "angine/utils/AnLog";
import { AnAnchor } from "angine/ui/AnAnchor";
import { AnBounds } from "angine/utils/AnMath";





export type AnUIResizeStrategyFunc = () => void;

export interface AnUIElementConfig 
{
	anchor?: AnAnchor;
	resizeStrategy?: AnUIResizeStrategyFunc | typeof Default;
	controlsRouter?: string;
}


export class AnUIElement
	extends enhance(PIXI.Container).with(AnDestructibleMixin)
	implements AnDestructibleInterface
{
	protected _scaledWidth: number | null = null;
	protected _scaledHeight: number | null = null;

	protected _realWidth: number | null = null;
	protected _realHeight: number | null = null;


	protected anchorContainer: PIXI.Container; // контейнер для корректного anchor, все добавлять в него
	private _anchor: AnAnchor = AnAnchor.TopLeft;


	// нужен для приема событий именно от активного меню
	protected controlsRouter: string = "";

	public resizeStrategy: AnUIResizeStrategyFunc | null = null;
	protected defaultResizeStrategy: AnUIResizeStrategyFunc | null = null;

	public constructor(config?: AnUIElementConfig)
	{
		super();
		if (config)
		{
			if (config.anchor !== undefined) this._anchor = config.anchor;
			if (config.controlsRouter !== undefined) this.controlsRouter = config.controlsRouter;
		}

		super.addChild(this.anchorContainer = new PIXI.Container());

		// const cross = createDebugCross();
		// this.addChild(cross);
		// this.addToCleanup(safeDestroyFunc(cross));

		this.alignGraphicsToAnchor();
	}

	public addGraphics<T extends PIXI.Container | PIXI.IRenderLayer>(graphics: T, at?: number)
	{
		if (at !== undefined)
		{
			this.anchorContainer.addChildAt(graphics, at);
		}
		else
			this.anchorContainer.addChild(graphics);
		this.alignGraphicsToAnchor();
	}

	protected get anchor(): AnAnchor
	{
		return this._anchor;
	}
	protected set anchor(value: AnAnchor)
	{
		this._anchor = value;
		this.alignGraphicsToAnchor();
	}

	public alignGraphicsToAnchor(): void
	{
		// Скорректируем позицию всех элементов на основе заданного anchor
		if (this._scaledWidth !== null && this._scaledHeight !== null)
		{
			this.anchorContainer.position.set(
				-1 * this.scaledWidth * this.anchor.x,
				-1 * this.scaledHeight * this.anchor.y
			);
		}
		else
		{
			this.anchorContainer.position.set(
				-1 * this.width * this.anchor.x,
				-1 * this.height * this.anchor.y
			);
		}
	}

	// для конфигурирования в конструкторе дочерних классов
	public configResizeStrategy(resizeStrategy: AnUIResizeStrategyFunc | typeof Default | null | undefined)
	{
		this.assignResizeStrategy(resizeStrategy === undefined || resizeStrategy === null ? null :
			(resizeStrategy === Default ? this.defaultResizeStrategy :
				resizeStrategy as AnUIResizeStrategyFunc));
	}

	public assignResizeStrategy(resizeStrategy: AnUIResizeStrategyFunc | null)
	{
		this.resizeStrategy = resizeStrategy;
	}

	public clearResizeStrategy()
	{
		this.assignResizeStrategy(null);
	}

	public setScaledSize(scaledWidth: number, scaledHeight: number)
	{
		this.scaledWidth = scaledWidth;
		this.scaledHeight = scaledHeight;
	}

	public get scaledWidth()
	{
		return this._scaledWidth ?? this.anchorContainer.width;
	}

	public get scaledHeight()
	{
		return this._scaledHeight ?? this.anchorContainer.height;
	}

	public set scaledWidth(width: number)
	{
		this._scaledWidth = width;
	}

	public set scaledHeight(height: number)
	{
		this._scaledHeight = height;
	}

	public get realHeight()
	{
		return this._realHeight ?? this.anchorContainer.height;
	}

	public get realWidth()
	{
		return this._realWidth ?? this.anchorContainer.width;
	}

	public get realSizeRatio()
	{
		return this.realWidth / this.realHeight;
	}

	public set realHeight(height: number)
	{
		this._realHeight = height;
	}

	public set realWidth(width: number)
	{
		this._realWidth = width;
	}


	/**
	 * Левая граница объекта с учётом anchor
	 * @example (0.5, 0.5) → left = x - width/2
	 */
	public get left(): number
	{
		return this.x - this._anchor.x * this.scaledWidth;
	}

	/**
	 * Правая граница объекта с учётом anchor
	 * @example (0.5, 0.5) → right = x + width/2
	 */
	public get right(): number
	{
		return this.x + (1 - this._anchor.x) * this.scaledWidth;
	}

	/**
	 * Верхняя граница объекта с учётом anchor
	 * @example (0.5, 0.5) → top = y - height/2
	 */
	public get top(): number
	{
		return this.y - this._anchor.y * this.scaledHeight;
	}

	/**
	 * Нижняя граница объекта с учётом anchor
	 * @example (0.5, 0.5) → bottom = y + height/2
	 */
	public get bottom(): number
	{
		return this.y + (1 - this._anchor.y) * this.scaledHeight;
	}

	/**
	 * Полная информация о границах объекта
	 */
	get bounds(): AnBounds
	{
		return {
			left: this.left,
			right: this.right,
			top: this.top,
			bottom: this.bottom
		};
	}

	/**
	 * Проверяет, находится ли точка (x, y) внутри видимой области элемента
	 * @param x - координата X указателя (в системе окна)
	 * @param y - координата Y указателя (в системе окна)
	 * @returns true, если точка внутри элемента
	 */
	public isPointInside(point: PIXI.Point): boolean
	{
		const localPoint = this.parent.toLocal(point);
		return (
			localPoint.x >= this.left &&
			localPoint.x <= this.right &&
			localPoint.y >= this.top &&
			localPoint.y <= this.bottom
		);
	}

	public applyResizeStrategy()
	{
		if (this.resizeStrategy)
		{
			this.resizeStrategy();
			this.alignGraphicsToAnchor();
		}
	}

	public applyDefaultResizeStrategy()
	{
		if (this.defaultResizeStrategy)
		{
			this.defaultResizeStrategy();
			this.alignGraphicsToAnchor();
		}
	}
	public override terminate()
	{
		super.terminate();
		safeDestroy(this);
	}
}