import { Default, PIXI } from "angine/singleton";
import { AnUIElement, AnUIElementConfig, AnUIResizeStrategyFunc } from "angine/ui/AnUIElement";
import { AnAssets } from "angine/assets/AnAssets";
import { notImplemented, safeDestroyFunc, struct } from "angine/utils/AnHelpers";
import { AnViewport } from "angine/core/AnViewport";
import { AnUI } from "angine/ui/AnUI";
import { AnAnchor } from "./AnAnchor";
import { AnLog } from "angine/utils/AnLog";
import { AnBounds } from "angine/utils/AnMath";

export enum AnImageType
{
	Solid = 'solid',
	Sprite = 'sprite',
	AtlasSprite = 'atlasSprite'
}


export interface AnImageConfig extends AnUIElementConfig
{
	atlas?: string,
	sprite?: string,
	tint?: number;
	alpha?: number;
	slice9?: AnBounds;
};

export class AnImage extends AnUIElement
{
	protected type: AnImageType;
	private sprite: PIXI.Sprite | PIXI.NineSliceSprite | null = null;
	private graphics: PIXI.Graphics | null = null;

	// изображение использует масштабирование slice9
	private _useSlice9 = false;
	public scale9Adopt: number = 1;

	constructor(config: AnImageConfig)
	{
		super(config);

		// определяем тип изображения
		this._useSlice9 = config.slice9 !== undefined;
		this.type = config.sprite ? (config.atlas ? AnImageType.AtlasSprite : AnImageType.Sprite) : AnImageType.Solid;

		if (this.type == AnImageType.Solid)
		{
			this.graphics = new PIXI.Graphics();
			this.addToCleanup(safeDestroyFunc(this.graphics));

			// Создание тени фона
			this.graphics.rect(0, 0, 256, 256);
			this.graphics.fill(config.tint ?? AnUI.colorSheme.shadow);
			this.graphics.alpha = config.alpha ?? 1;
			this.addGraphics(this.graphics);

			// для отладки, добавляем ярлык для элемента (pixi devtools)
			if (AnConfig.devMode) this.graphics.label = "solid color";
		}
		else
		{
			// 	// Выводим все текстуры из атласа в консоль
			// 	// for (const textureName in atlas.textures)
			// 	// 	if (atlas.textures.hasOwnProperty(textureName))
			// 	// 		console.log(`Texture name: ${textureName}`);

			// Загружаем текстуру с помощью универсального метода
			const texture = AnImage.loadTexture(config.sprite!, config.atlas);
			this.realWidth = texture.width;
			this.realHeight = texture.height;

			if (this._useSlice9)
			{
				this.sprite = new PIXI.NineSliceSprite({
					texture,
					leftWidth: config.slice9?.left,
					topHeight: config.slice9?.top,
					rightWidth: config.slice9?.right,
					bottomHeight: config.slice9?.bottom,
					// width: 200,
					// height: 80,
				});

			}
			else
				this.sprite = new PIXI.Sprite(texture);

			this.sprite.anchor = AnAnchor.TopLeft;
			this.sprite.alpha = config.alpha ?? 1;
			this.addToCleanup(safeDestroyFunc(this.sprite));
			this.sprite.tint = config.tint ?? 0xFFFFFF;
			this.addGraphics(this.sprite);

			// для отладки, добавляем ярлык для элемента (pixi devtools)
			if (AnConfig.devMode) this.sprite.label = "sprite";
		}

		// +++ resize strategy +++
		this.defaultResizeStrategy = this.simpleGraphics ?
			() =>
			{
				this.graphics!.width = this._scaledWidth!;
				this.graphics!.height = this._scaledHeight!;
			} :
			() =>
			{
				if (this.scaledWidth && this.scaledHeight)
				{
					if (this._useSlice9)
					{
						this.sprite!.scale.set(this.scale9Adopt);
						this.sprite!.setSize(this.scaledWidth / this.scale9Adopt, this.scaledHeight / this.scale9Adopt);
					}
					else
					{
						this.sprite!.setSize(this.scaledWidth, this.scaledHeight);
					}
				}
				else
					this.sprite!.scale.set(AnViewport.scale);
			};

		this.configResizeStrategy(config.resizeStrategy);
	}

	/** используется простая графика исключительно через PIXI.Graphics */
	public get simpleGraphics()
	{
		return this.type === AnImageType.Solid;
	}

	/** используются Slice9 спрайты */
	public get useSlice9()
	{
		return this._useSlice9;
	}


	/** обрезать по ширине */
	public set clippingWidth(factor: number)
	{
		if (this.sprite && !this.useSlice9)
		{
			this.sprite.texture.frame.width = this.sprite.texture.orig.width * factor;
			this.sprite.texture.updateUvs();
		}
	}
	/** обрезать по высоте */
	public set clippingHeight(factor: number)
	{
		notImplemented();
		//return this._useSlice9;
	}

	/**
	 * Загружает текстуру по указанному пути или из атласа
	 * @param sprite Имя спрайта
	 * @param atlas Опциональный путь к атласу
	 * @public
	 */
	public static loadTexture(sprite: string, atlas?: string): PIXI.Texture
	{
		let texture: PIXI.Texture;

		if (atlas)
		{
			// Загрузка из атласа
			const atlasData = AnAssets.get<PIXI.Spritesheet>(atlas);
			if (!atlasData)
			{
				throw new Error(`Атлас не найден: ${atlas}`);
			}
			texture = atlasData.textures[sprite];
			if (!texture)
			{
				throw new Error(`Спрайт "${sprite}" не найден в атласе "${atlas}"`);
			}
		} else
		{
			// Прямая загрузка текстуры
			texture = AnAssets.get<PIXI.Texture>(sprite);
			if (!texture)
			{
				throw new Error(`Текстура не найдена: ${sprite}`);
			}
		}

		return texture;
	}

	/**
	 * Меняет текстуру спрайта на новую
	 * @param sprite Имя спрайта из атласа или путь к текстуре
	 * @param atlas Опционально, путь к атласу, если используется
	 */
	public changeTexture(sprite: string, atlas?: string): void
	{
		if (!this.sprite)
		{
			AnLog.warn("Не могу изменить текстуру: спрайт не создан");
			return;
		}

		try
		{
			// Загружаем новую текстуру
			const newTexture = AnImage.loadTexture(sprite, atlas);

			// Применяем новую текстуру
			this.sprite.texture = newTexture;

			// Обновляем внутренние размеры
			this.realWidth = newTexture.width;
			this.realHeight = newTexture.height;
		}
		catch (error)
		{
			AnLog.error(`Ошибка при смене текстуры: ${error}`);
		}
	}
}