

type AnColorSheme = {
	readonly foreground: number;
	readonly background: number;
	readonly shadow: number;
};

const defaultColorSheme: AnColorSheme = {
	foreground: 0xffffff,
	background: 0x333333,
	shadow: 0x111111,
};


type AnStyleParams = {
	readonly shadowOffset: number;
	readonly roundCorners: number;
};

const defaultStyleParams: AnStyleParams = {
	shadowOffset: 3,
	roundCorners: 10,
};




export class AnUI
{
	private constructor() { }

	private static currentColorSheme = defaultColorSheme;
	private static currentStyleParams = defaultStyleParams;

	public static get colorSheme(): AnColorSheme
	{
		return AnUI.currentColorSheme;
	}

	public static set colorSheme(colorSheme: AnColorSheme)
	{
		AnUI.currentColorSheme = colorSheme;
	}

	public static get styleParams(): AnStyleParams
	{
		return AnUI.currentStyleParams;
	}

	public static set styleParams(styleParams: AnStyleParams)
	{
		AnUI.currentStyleParams = styleParams;
	}

}