
import { AnRender3D } from "angine/3D/AnRender3D";
import { AnRender2D } from "angine/2D/AnRender2D";
import { AnLog } from "angine/utils/AnLog";
import { AnViewport } from "angine/core/AnViewport.js";
import { AnMainLoop } from "angine/core/AnMainLoop.js";
import { AnUpdater } from "angine/utils/AnUpdater.js";

export class AnCore 
{
	public static updater: AnUpdater;

	private constructor() { }

	public static get fullGameVersion(): string
	{
		return `${AnConfig.gameVersion} [${AnConfig.platform}]`;
	}

	public static async init()
	{
		AnLog.info(`--- Старт AnGINE версия ${AnConfig.angineVersion} ${AnConfig.prodMode ? 'prod' : 'dev'}  ---`);


		// Инициализируем вьюпорт (тамже и канвас)
		await AnViewport.init();
		// Создаём менеджер обновлений
		AnCore.updater = new AnUpdater();

		//AnLog.info(`Конфигурация сборки: use3D=${AnConfig.use3D} usePhysics3D=${AnConfig.usePhysics3D} usePhysics2D=${AnConfig.usePhysics2D}`);

		AnLog.info(`Версия игры: ${this.fullGameVersion}`);

		AnMainLoop.init(
			(dt) => AnCore.update(dt), // Логика
			() => AnCore.render()      // Рендер
		);

		if (AnConfig.use3D)
		{
			AnRender3D.init();
		}

		await AnRender2D.init();


		AnCore.setupEventHandlers();

		AnMainLoop.start();
	}

	public static terminate()
	{
		AnMainLoop.stop();

		if (AnConfig.use3D)
		{
			AnRender3D.terminate();
		}
		AnRender2D.terminate();

		AnLog.info(`--- AnGINE отключен  ---`);
	}

	private static setupEventHandlers()
	{
		const resize = (width: number, height: number) =>
		{
			AnViewport.resize(width, height);

			// Обновляем рендереры
			if (AnConfig.use3D)
			{
				AnRender3D.resize(width, height);
			}

			AnRender2D.resize(width, height);
		}


		resize(window.innerWidth, window.innerHeight);

		window.addEventListener('resize', () =>
		{
			resize(window.innerWidth, window.innerHeight);
		});
	}

	private static update(dt: number)
	{
		AnCore.updater.update(dt);
	}

	private static render()
	{
		if (AnConfig.use3D)
		{
			AnRender3D.render();
		}
		AnRender2D.render();
	}
}
