import { AnViewport } from "angine/core/AnViewport";
import { AnEvent, AnEvents } from "./AnEvents";
import { AnLog } from "./AnLog";

/**
 * Статический класс для управления локализациями.
 * 
 * Основные возможности:
 * - Загрузка языков из XML-строк
 * - Хранение метаданных языков (название, код)
 * - Получение локализованных строк
 * - Управление текущим языком
 * 
 * Пример использования:
 * 
 * // Инициализация с XML-строками
 * const enLang = `<langData name="English" code="en">...</langData>`;
 * const ruLang = `<langData name="Русский" code="ru">...</langData>`;
 * await AnLang.loadLanguages([enLang, ruLang]);
 * 
 * // Установка текущего языка
 * AnLang.currentLanguage = 'en';
 * 
 * // Получение локализованной строки
 * console.log(AnLang.getString('GameTitle')); // SUPER UTILIZER
 * 
 * // Получение метаданных языка
 * const meta = AnLang.getLanguageMeta('en');
 * console.log(meta?.name); // "English"
 */
export class AnLang
{
	/**
	 * Хранилище загруженных языков.
	 * Ключ - код языка (например 'en', 'ru')
	 * Значение - объект с:
	 *   - strings: Map с локализованными строками
	 *   - name: название языка (например "English")
	 *   - code: код языка (дублируется для удобства)
	 */
	private static _loadedLanguages: Record<string, {
		strings: Record<string, string>;
		name: string;
		code: string;
	}> = {};

	/**
	 * Текущий выбранный язык (код из двух символов).
	 * По умолчанию 'en' - английский.
	 */
	private static _currentLanguage: string = 'en';

	// Запрещаем создание экземпляров класса
	private constructor() { }

	/**
	 * Основной метод загрузки языков.
	 * Принимает массив XML-строк и парсит их.
	 * 
	 * @param xmlLangsData - Массив XML-строк в формате:
	 *   `<langData name="..." code="..."><text id="...">...</text>...</langData>`
	 * @throws Error если возникли проблемы с парсингом XML
	 * 
	 * @example
	 * await AnLang.loadLanguages([enXml, ruXml]);
	 */
	private static eventSubscribed: boolean = false;
	public static async loadLanguages(xmlLangsData: string[]): Promise<void>
	{
		try
		{
			// Параллельно обрабатываем все XML
			await Promise.all(
				xmlLangsData.map(xml => this.parseLanguage(xml))
			);
		} catch (error)
		{
			console.error('Failed to load languages:', error);
			throw new Error('Language loading failed');
		}

		if (!this.eventSubscribed)
		{
			this.eventSubscribed = true;
			AnEvents.on("storage:language:update", (e: AnEvent) =>
			{
				this.currentLanguage = e.data.value;
			});
		}
	}

	/**
	 * Парсит XML одного языка и сохраняет данные.
	 * 
	 * @param xml - XML-строка с локализацией
	 * @throws Error если:
	 *   - XML некорректен
	 *   - Отсутствуют обязательные атрибуты (name/code)
	 *   - Нет ни одной локализованной строки
	 */
	private static async parseLanguage(xml: string): Promise<void>
	{
		try
		{
			const parser = new DOMParser();
			const xmlDoc = parser.parseFromString(xml, "text/xml");

			// Проверяем, что парсинг прошел без ошибок
			if (xmlDoc.getElementsByTagName("parsererror").length > 0)
			{
				throw new Error('Invalid XML format');
			}

			const langData = xmlDoc.documentElement;

			// Извлекаем обязательные атрибуты
			const code = langData.getAttribute('code');
			const name = langData.getAttribute('name');

			if (!code || !name)
			{
				throw new Error('Missing required attributes (code/name) in langData');
			}

			// Собираем все локализованные строки
			let strings: Record<string, string> = {};
			let inited: boolean = false;
			const textNodes = langData.getElementsByTagName('text');

			for (let i = 0; i < textNodes.length; i++)
			{
				const node = textNodes[i];
				const id = node.getAttribute('id');
				const text = node.textContent;

				if (id && text)
				{
					strings[id] = text;
					inited = true;
				}
			}

			// Проверяем, что есть хотя бы одна строка
			if (!inited)
			{
				throw new Error('No localized strings found');
			}

			// Сохраняем язык в хранилище
			this._loadedLanguages[code] = {
				strings,
				name,
				code
			};

		} catch (error)
		{
			console.error('Failed to parse language XML:', error);
			throw error; // Пробрасываем ошибку выше
		}
	}

	/**
	 * Возвращает локализованную строку по идентификатору.
	 * 
	 * @param id - Идентификатор строки (например 'GameTitle')
	 * @returns Локализованная строка или заглушка вида:
	 *   - [LANG_NOT_LOADED:...] если язык не загружен
	 *   - [MISSING:...] если строка не найдена
	 * 
	 * @example
	 * AnLang.getString('GameTitle'); // "SUPER UTILIZER"
	 */
	public static get(id: string): string
	{
		const lang = this._loadedLanguages[this._currentLanguage];

		if (!lang)
		{
			console.warn(`Language '${this._currentLanguage}' not loaded`);
			return `[LANG_NOT_LOADED:${id}]`;
		}

		//return lang.strings[id] ?? `[MISSING:${id}]`;

		// делаем замену некоторых символов
		return (lang.strings[id] ?? `[MISSING:${id}]`).replace(
			/[ё]/g,
			(match) =>
			{
				switch (match)
				{
					case "ё": return "е";
					default: return match;
				}
			}
		).replace(/\\n/g, '\n') ?? `[MISSING:${id}]`;
	}

	/**
	 * Геттер/сеттер для текущего языка.
	 * При установке проверяет, что язык был загружен.
	 * 
	 * @throws Error если пытаемся установить незагруженный язык
	 */
	public static get currentLanguage(): string
	{
		return this._currentLanguage;
	}

	public static set currentLanguage(lang: string)
	{
		if (this._loadedLanguages[lang] === undefined)
		{
			AnLog.error(`Язык '${lang}' не загружен. Сначала вызовите loadLanguages()`);
			return;
		}

		if (AnConfig.devMode)
			AnLog.debug(`Меняем язык на ${lang}`);

		this._currentLanguage = lang;
		AnEvents.emit("settings:changed:lang", lang);
		AnViewport.invalidate();
	}

	/**
	 * Возвращает метаданные языка (название и код).
	 * 
	 * @param code - Код языка (например 'en')
	 * @returns Объект с name и code или undefined если язык не найден
	 * 
	 * @example
	 * const meta = AnLang.getLanguageMeta('en');
	 * console.log(meta?.name); // "English"
	 */
	public static getLanguageMeta(code: string): { name: string; code: string } | undefined
	{
		const lang = this._loadedLanguages[code];
		return lang ? {
			name: lang.name,
			code: lang.code
		} : undefined;
	}

	/**
	 * Возвращает список кодов загруженных языков.
	 * 
	 * @returns Массив строк (например ['en', 'ru'])
	 */
	public static get loadedLanguages(): string[]
	{
		return Object.keys(this._loadedLanguages);
	}

	/**
	 * Проверяет, загружен ли указанный язык.
	 * 
	 * @param code - Код языка для проверки
	 * @returns true если язык загружен
	 */
	public static hasLanguage(code: string): boolean
	{
		return this._loadedLanguages[code] !== undefined;
	}
}