import { AnCounter, AnCounterConfig, AnCounterDisplayMode, AnCounterLayout } from "angine/ui/AnCounter.js";
import { AnTween } from "angine/anim/AnTween.js";
import { AnEase } from "angine/anim/AnEase.js";
import { enhance, getComplementaryColor } from "angine/utils/AnHelpers.js";
import { AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin.js";
import { GameColor, GameColorsDB, GameTheme } from "./Game.js";
import { AnEvent, AnEvents } from "angine/utils/AnEvents.js";
import { GameApp } from "../GameApp.js";
import { Cell } from "./Cell.js";
import { AnSounds } from "angine/audio/AnSounds.js";
import { AnRnd } from "angine/utils/AnRnd.js";
import { AnLog } from "angine/utils/AnLog.js";

/**
 * Конфигурация для UIGoalCounter
 */
export interface UIGoalCounterConfig extends AnCounterConfig
{
	iconType: string;
	blockTheme?: GameTheme;
}

/**
 * Класс UIGoalCounter - счетчик целей для конкретного типа блока
 * Наследует AnCounter и добавляет возможность хранить тип блока
 */
export class UIGoalCounter
	extends enhance(AnCounter).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{
	private _iconType: string;
	private _blockTheme: GameTheme;
	private labelTween: AnTween | null = null;

	constructor(config: UIGoalCounterConfig)
	{
		// Создаем иконку с правильным спрайтом на основе типа блока
		const iconConfig = {
			...config.mainIcon,
			atlas: 'atlases/game.ss.pixi.atlas',
			sprite: './' + config.iconType + (config.iconType.startsWith("prop") && config.iconType !== "prop_heart" ? "_" + config.blockTheme : ""),
		};

		const iconStatusConfig = {
			...config.statusIcon,
			atlas: 'atlases/game.ss.pixi.atlas',
			sprite: './v',
		};

		// Вызываем конструктор родителя с модифицированной конфигурацией
		super({
			...config,
			labelTextStyle: {
				fontName: "mainFont",
				fontSize: 60,
				shadowAlpha: 0.7,
				shadowOffsetX: 2,
				shadowOffsetY: 2,
			},
			mainIcon: iconConfig,
			statusIcon: iconStatusConfig,
			layout: AnCounterLayout.Horizontal,
		});

		this._iconType = config.iconType ?? "star_mod";
		this._blockTheme = config.blockTheme ?? GameTheme.Toys;

		this.addToCleanup(AnEvents.on("storage:theme:update",
			(e: AnEvent) => this.onSettingsThemeUpdate(e.data.value as GameTheme)).unsub);

		this.addToCleanup(AnEvents.on("storage:color:update",
			(e: AnEvent) => this.onSettingsColorUpdate(e.data.value as GameColor)).unsub);


		this.onSettingsColorUpdate(GameApp.self.gameData.color);
	}

	private onSettingsColorUpdate(color: GameColor): void
	{
		if (this._iconType === "cellPainted")
		{
			this.mainIcon.tint = Cell.getCellPaintedColor(GameColorsDB[color].baseColorTint);
		}
	}

	private onSettingsThemeUpdate(theme: GameTheme): void
	{
		this._blockTheme = theme;
		if (this._iconType.startsWith("prop_") && this._iconType != "prop_heart")
		{
			this.mainIcon.changeTexture('./' + this._iconType.split("_", 2).join("_") + `_${this._blockTheme}`, 'atlases/game.ss.pixi.atlas');
		}
	}

	/**
	 * Возвращает тип блока, который отслеживает этот счетчик
	 */
	public get iconType(): string
	{
		return this._iconType;
	}

	protected override onShowStatus()
	{
		super.onShowStatus();

		AnSounds.play(
			`sounds/goal.snd.mp3`,
			0.6,
		);
	}

	public setTextColor(color: number)
	{
		this.elements['counter'].tint = color;
	}

	public updateValue(current: number, withAnim: boolean = true): void
	{
		const lastCounterVisible = this.elements['counter'].visible;
		this.set(current);

		if (withAnim)
		{
			if (this.elements['counter'].visible)
			{
				if (this.labelTween)
				{
					this.labelTween.terminate();
					this.labelTween = null;
				}

				this.labelTween = new AnTween({
					target: this.elements['counter'],
					from: { scale: { x: 1.25, y: 1.25 }, tint: 0x00ff00 },
					to: { scale: { x: 1, y: 1 }, tint: 0xffffff },
					duration: 2,
					easing: AnEase.easeInOutBack,
					updater: this.getUpdater(),
					autoRemove: true,
					callbacks: {
						onComplete: () => this.labelTween = null
					}
				});
			}
			else if (lastCounterVisible)
			{
				if (this.labelTween)
				{
					this.labelTween.terminate();
					this.labelTween = null;
				}

				this.labelTween = new AnTween({
					target: this.elements['statusIcon'],
					from: { scale: { x: 0.3, y: 0.3 }, tint: 0x00ff00 },
					to: { scale: { x: 0.5, y: 0.5 }, tint: 0xffffff },
					duration: 2,
					easing: AnEase.easeOutElastic,
					updater: this.getUpdater(),
					autoRemove: true,
					callbacks: {
						onComplete: () => this.labelTween = null
					}
				});
			}
		}
	}
}