// src/core/AnFunctor.ts
import { AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";
import { AnUpdater } from "angine/utils/AnUpdater";
import { AnVoidCallback } from "./AnHelpers";
import { AnCore } from "angine/core/AnCore";

/**
 * Конфигурация 
 */
export interface AnTaskConfig<T = any>
{
	handler: (this: T, dt: number) => void;
	updater?: AnUpdater | null;       // Кастомный апдейтер
	autoStart?: boolean;       // Автостарт
	runOnce?: boolean;      // Автоудаление после выполнения
	context?: T;               // Контекст выполнения
}

/**
 * Класс задачи для выполнения операций в цикле обновления
 */
export class AnTask<T = any> extends AnUpdatableMixin(Object) implements AnUpdatableInterface
{
	private _active: boolean = false;
	private _runOnce: boolean;
	private _context?: T;
	private _handler: (this: T, dt: number) => void;

	constructor(config: AnTaskConfig<T>)
	{
		super();

		this._handler = config.handler;
		let autoStart = config.autoStart ?? true;
		this._context = config.context;
		this._runOnce = config.runOnce ?? false;
		if (config.updater) this.addToUpdater(config.updater);

		if (autoStart) this.start();
	}

	/**
	 * Запускает выполнение задачи
	 */
	start(): this
	{
		if (this._active || !this.getUpdater()) return this;

		this._active = true;
		return this;
	}

	/**
	 * Останавливает выполнение задачи
	 */
	stop(): this
	{
		if (!this._active) return this;

		this._active = false;
		return this;
	}

	/**
	 * Основной метод обновления
	 * @param dt Дельта времени в секундах
	 */
	update(dt: number): void
	{
		if (!this._active) return;

		// Вызываем обработчик с правильным контекстом
		this._handler.call(this._context as T, dt);

		// Автоматическое остановка при необходимости
		if (this._runOnce)
		{
			this.stop();
			this.removeFromUpdater();
		}
	}

	/**
	 * Устанавливает контекст выполнения
	 */
	set context(_context: T)
	{
		this._context = _context;
	}

	/**
	 * возвращает контекст выполнения
	 */
	get context(): T
	{
		return this._context as T;
	}

	/**
	 * Статус активности функтора
	 */
	get active(): boolean
	{
		return this._active;
	}


	// --------------------------------------------------------
	// 🆕 Статический метод: запуск в следующем обновлении
	// --------------------------------------------------------

	/**
	 * Выполняет функцию один раз в следующем кадре обновления и автоматически удаляется.
	 *
	 * @param handler Функция, которая будет вызвана в следующем update
	 * @param updater Экземпляр AnUpdater, в который добавится задача
	 * @param context Контекст (this) для выполнения функции
	 */
	static runNextUpdate<T = any>(
		handler: AnVoidCallback,
		context?: T,
	): AnTask<T>
	{
		const task = new AnTask<T>({
			handler,
			updater: AnCore.updater,
			runOnce: true,           // автоудаление после одного вызова
			autoStart: true,         // стартует сразу
			context
		});

		return task;
	}
}
