// src/loader/AnBundle.ts

import { AnLog } from "angine/utils/AnLog";



/**
 * Метаданные бандла
 */
export type AnBundleMetadata = {

	/** Название бандла (совпадает с именем файла без расширения) */
	name: string;

	/** Версия формата архива */
	version: string;

	/** Использованный метод сжатия */
	compression: 'DEFLATE' | 'LZMA' | 'NONE';

	/** если parts > 1, то архив был многотомный */
	parts: number;

	/** Дата создания архива */
	created: Date;
};


/**
 * Класс представляет распакованный бандл ресурсов.
 * Содержит все файлы из архива в виде бинарных данных
 * и метаинформацию о бандле.
 */
export class AnBundle
{
	/**
	 * Хранилище файлов в формате: 
	 * ключ - путь к файлу в архиве,
	 * значение - бинарные данные файла
	 */
	private readonly files: Record<string, Blob> = {};

	/**
	 * Метаданные бандла
	 */
	public readonly metadata: AnBundleMetadata;

	constructor(
		metadata: AnBundleMetadata,
		files: Array<{ path: string; data: Blob }>
	)
	{
		this.metadata = metadata;

		// Добавляем все файлы в хранилище
		files.forEach(file =>
		{
			if (file.data && file.path)
			{
				this.files[file.path] = file.data;
			}
		});
	}

	/**
	 * Получает файл из бандла по его пути
	 * @param path - Путь к файлу внутри архива (например, 'textures/main.png')
	 * @returns Uint8Array с данными файла или null если файл не найден
	 */
	public getFile(path: string): Blob | null
	{
		if (path.includes('\\'))
		{
			AnLog.warn(`(исправлено) используйте слеш /, а не обратный слеш \\ в путях: ${path}`);
			path = path.replace(/\\/g, "/");
		}
		let file = this.files[path] ?? null;
		if (!file) AnLog.error(`В бандле ${this.metadata.name} Не найден запрошенный файл: ${path}`);
		return file;
	}

	/**
	 * Получает файл как текстовое содержимое
	 * @param path - Путь к файлу в бандле
	 * @returns Promise с текстовым содержимым
	 */
	public async getTextFile(path: string): Promise<string | null>
	{
		const blob = this.getFile(path);
		if (!blob) return null;
		return blob.text();
	}

	/**
	 * Получает файл как JSON
	 * @param path - Путь к JSON-файлу в бандле
	 * @returns Promise с распарсенным JSON
	 */
	public async getJsonFile(path: string): Promise<any | null>
	{
		const text = await this.getTextFile(path);

		if (text)
		{
			try
			{
				return JSON.parse(text);
			} catch (error)
			{
				const err = error as Error;
				AnLog.error(`Неверный формат JSON в файле ${path}: ${err.message}`);
			}
		}
		return null;
	}

	/**
	 * Возвращает список всех файлов в бандле
	 * @returns Массив строк с путями файлов
	 */
	public listFiles(): string[]
	{
		return Object.keys(this.files);
	}

	/**
	 * Проверяет наличие файла в бандле
	 * @param path - Путь к файлу
	 * @returns true если файл существует
	 */
	public hasFile(path: string): boolean
	{
		return this.files[path] !== undefined;
	}
}
