// src/core/AnCoreLoop.ts

import { AnLog } from "angine/utils/AnLog";

/**
 * Управляет главным циклом движка:
 * - Расчёт dt (время между кадрами)
 * - Контроль FPS (ограничение min/max)
 * - Статистика (текущий FPS, нормализованная производительность)
 */
export class AnMainLoop
{
	// Флаг, указывающий, активен ли в данный момент игровой цикл
	private static _isRunning: boolean = false;

	// ID последнего запроса анимационного кадра (requestAnimationFrame)
	// Используется для остановки цикла через cancelAnimationFrame
	// null - когда цикл не активен
	private static _requestId: number | null = null;

	// Временная метка (в миллисекундах) последнего кадра
	// Используется для расчета dt между кадрами
	// Инициализируется при старте цикла через performance.now()
	private static _lastTime: number = 0;

	// Время, прошедшее между предыдущим и текущим кадром (в секундах)
	// Рассчитывается как (текущее время - _lastTime) / 1000
	// Важно для плавной анимации независимо от FPS
	private static _dt: number = 0;

	// Текущее количество кадров в секунду (FPS)
	// Обновляется каждую секунду на основе _frameCount
	private static _FPS: number = 0;

	// Счетчик кадров, используемый для расчета FPS
	// Инкрементируется каждый кадр, сбрасывается каждую секунду
	private static _frameCount: number = 0;

	// Минимальный допустимый FPS (кадров в секунду)
	// Если производительность падает ниже этого значения:
	// - dt искусственно ограничивается (maxFrameTime)
	// - система пытается поддерживать хотя бы этот FPS
	// Рекомендуемое значение для игр: 25-30 FPS
	private static _minFPS: number = AnParams.minFPS;

	// Максимальный целевой FPS (кадров в секунду)
	// Если производительность позволяет:
	// - Цикл не будет работать быстрее этого значения
	// - Экономит ресурсы процессора/GPU
	// Обычно устанавливается в частоту обновления монитора (60, 120, 144 и т.д.)
	private static _maxFPS: number = AnParams.maxFPS;

	// Базовый FPS для нормализации (по умолчанию 60)
	private static _baseFPS: number = AnParams.baseFPS;

	private static _onUpdate: (dt: number) => void;
	private static _onRender: () => void;

	public static init(
		_onUpdate: (dt: number) => void,
		_onRender: () => void
	)
	{
		AnLog.info(`Лимит FPS: [${AnMainLoop._minFPS}..${AnMainLoop._maxFPS}] базовый FPS: ${AnMainLoop._baseFPS}`);
		AnMainLoop._onUpdate = _onUpdate;
		AnMainLoop._onRender = _onRender;
	}

	// --- Публичные методы ---


	/**
	 * Запускает игровой цикл.
	 * Если цикл уже запущен, метод ничего не делает.
	 * Инициализирует начальные значения времени и счетчика кадров.
	 */
	public static start()
	{
		//TODO: добавить проверку что коллбеки добавлены

		if (AnMainLoop._isRunning) return;
		AnMainLoop._isRunning = true;
		AnMainLoop._lastTime = performance.now();
		AnMainLoop._frameCount = 0;
		AnMainLoop._run();
	}

	/**
	 * Останавливает игровой цикл.
	 * Если цикл не был запущен, метод ничего не делает.
	 * Отменяет запланированный кадр анимации через cancelAnimationFrame.
	 */
	public static stop(): void
	{
		if (!AnMainLoop._isRunning) return;
		AnMainLoop._isRunning = false;
		if (AnMainLoop._requestId) cancelAnimationFrame(AnMainLoop._requestId);
	}

	/** Устанавливает лимиты FPS (например, min: 30, max: 60) */
	public static setFPSLimits(min: number, max: number): void
	{
		AnMainLoop._minFPS = min;
		AnMainLoop._maxFPS = max;
	}


	// --- Геттеры ---

	/** Дельта времени в секундах (например, 0.016 для 60 FPS) */
	public static get dt(): number { return AnMainLoop._dt; }

	/** Текущий FPS (актуально после первого секунды работы) */
	public static get FPS(): number { return AnMainLoop._FPS; }

	/** Относительная производительность (1.0 = 60 FPS, 2.0 = 120 FPS) */
	public static get performanceFactor(): number { return AnMainLoop._FPS / AnMainLoop._baseFPS; }

	/** Возвращает текущее значение базового FPS*/
	public static get baseFPS(): number
	{
		return AnMainLoop._baseFPS;
	}

	// --- Приватная логика ---


	/**
	 * Основной цикл рендеринга и обновления игры.
	 * Выполняется рекурсивно через requestAnimationFrame.
	 * Рассчитывает dt, ограничивает FPS, вызывает коллбэки обновления и рендеринга.
	 */
	private static _run(): void
	{
		if (!AnMainLoop._isRunning) return;

		// Получаем текущее время
		const now = performance.now();

		// Вычисляем время, прошедшее с предыдущего кадра
		const delta = now - AnMainLoop._lastTime;

		// Рассчитываем минимальное время между кадрами (для ограничения maxFPS)
		const minFrameTime = 1000 / AnMainLoop._maxFPS;

		// Рассчитываем максимальное время между кадрами (для ограничения minFPS)
		const maxFrameTime = 1000 / AnMainLoop._minFPS;

		// Проверяем, нужно ли обрабатывать этот кадр (ограничение FPS)
		if (delta >= minFrameTime)
		{
			// Вычисляем dt в секундах, ограничивая сверху для minFPS
			AnMainLoop._dt = Math.min(delta, maxFrameTime) / 1000;

			// Корректируем время последнего кадра с учетом пропущенных фреймов
			AnMainLoop._lastTime = now - (delta % minFrameTime);

			// Обновляем счетчик FPS 
			AnMainLoop._frameCount++;
			if (now >= AnMainLoop._lastTime + 1000)
			{
				AnMainLoop._FPS = AnMainLoop._frameCount;
				AnMainLoop._frameCount = 0;
			}

			// Вызываем пользовательские обработчики
			AnMainLoop._onUpdate(AnMainLoop._dt); // Сначала обновляем логику
			AnMainLoop._onRender();                // Затем рендерим кадр
		}

		// Планируем следующий кадр анимации
		AnMainLoop._requestId = requestAnimationFrame(() => AnMainLoop._run());
	}
}