// src/mixins/AnDestructibleMixin.ts

import { addUniqueValue, AnVoidCallback, className, Constructor } from "angine/utils/AnHelpers";
import { AnLog } from "angine/utils/AnLog";


/**
 * Интерфейс для объектов, поддерживающих очистку ресурсов
 */
export interface AnDestructibleInterface
{
	/**
	 * Добавляет функцию отписки в список
	 */
	addToCleanup(cleanupFunc: AnVoidCallback): void;

	// проверить объект на существование
	get isDestroyed(): boolean;

	/**
	 * Метод вызывается при уничтожении объекта
	 * Здесь описываются действия по освобождению ресурсов
	 */
	terminate(): void;
}

/**
 * Миксин для добавления функциональности очистки ресурсов
 * @param Base - Базовый класс
 * @returns Расширенный класс с поддержкой onDestroy и отписки от событий
 */
export function AnDestructibleMixin<TBase extends Constructor>(Base: TBase)
{
	return class AnDestructible extends Base implements AnDestructibleInterface
	{
		// Список функций для отписки
		private cleanupFuncs: AnVoidCallback[] | null = null;

		//флаг предотвращающий удаление уже удаленого объекта
		private _destroyed: boolean = false;

		constructor(...args: any[])
		{
			super(...args);
		}

		/**
		 * Проверить, уничтожен ли уже объект
		 */
		public get isDestroyed(): boolean
		{
			return this._destroyed;
		}

		/**
		 * Вызывается при уничтожении объекта
		 * Здесь освобождаются ресурсы и отписываются события
		 */
		public terminate(): void
		{
			if (this._destroyed)
			{
				AnLog.warn(`Объект ${className(this)} уже был удален!`);
				return;
			}

			this._destroyed = true;
			// Вызываем все сохранённые отписки
			if (this.cleanupFuncs !== null)
			{
				this.cleanupFuncs.forEach(func => func());
				this.cleanupFuncs.length = 0; // очищаем массив
			}
		}

		/**
		 * Добавляет функцию отписки в список
		 * @param cleanupFunc Функция отписки
		 */
		public addToCleanup(cleanupFunc: AnVoidCallback): void
		{
			//ленивая инициализация
			if (this.cleanupFuncs === null)
				this.cleanupFuncs = [];

			addUniqueValue(this.cleanupFuncs, cleanupFunc);
		}

		// /**
		//  * Удаляет конкретную отписку из списка
		//  * @param id ID подписки
		//  */
		// public removeFromCleanup(id: symbol): void
		// {
		// 	// Этот метод можно реализовать, если нужна точечная отписка
		// 	// Но пока оставим как заглушку — можно улучшить позже
		// }
	};
}