import { AnAppConfig } from "angine/app/AnApp.js";
import { GameApp } from "./GameApp.js";
import { G } from "./game/G.js";
import { Analytics } from "./api/Analytics.js";
import { uptime } from "angine/utils/AnHelpers.js";
import { declarePolyfills } from "./polyfills.js";

// отключить все флаги отладки если собираем для продакшена
if (AnConfig.prodMode) G.disableDevFeatures();

// добавляем полифилы для долбаного safari
declarePolyfills();

// стартуем аналитику как можно раньше
Analytics.init({ currencies: ['coins'], itemTypes: ['color', 'theme', 'rewardWin', 'reward2X', 'rewardChest'] });

// событие первичной инициализации
export const firstTouchInitTime = uptime();
Analytics.onEvent("FirstTouchInitInSec", firstTouchInitTime);

const config: AnAppConfig =
{
  preloaderSkipExitAnimations: G.dev_preloaderSkipExitAnimations
};

const gameApp = new GameApp(config);

(async () =>
{
  await gameApp.start();
})();