import { AnApp, AnAppConfig } from "angine/app/AnApp.js";
import { Game, GameTheme, GameConfig, GameColor } from "./game/Game.js";
import { AnLang } from "angine/utils/AnLang.js";
import { AnRender2D } from "angine/2D/AnRender2D.js";
import { Intro } from "./game/Intro.js";
import { AnFader } from "angine/ui/AnFader.js";
import { MenuResult, MenuResultState } from "./game/MenuResult.js";
import { LevelData } from "./game/LevelData.js";
import { AnSaveData, AnStorage } from 'angine/utils/AnStorage.js';
import { G } from "./game/G.js";
import { MenuInfo } from "./game/MenuInfo.js";
import { DevStatsAPI } from "./api/DevStatsAPI.js";
import { AnLog } from "angine/utils/AnLog.js";
import { getCurrentOSLanguage, shuffle, struct, uptime } from "angine/utils/AnHelpers.js";
import { AnSounds } from 'angine/audio/AnSounds.js';
import { AnMusicPlaylist } from 'angine/audio/AnMusicPlaylist.js';
import { PlatformLoader } from "./platform/PlatformLoader.js";
import { Platform, PlatformAds, PlatformEvent } from "./platform/Platform.js";
import { Analytics } from "./api/Analytics.js";
import { update } from "three/examples/jsm/libs/tween.module.js";
import { firstTouchInitTime } from "./main.js";


export interface StorageInterface
{
	// настройки
	get theme(): GameTheme, set theme(value: GameTheme),
	get color(): GameColor, set color(value: GameColor),
	get soundVolume(): number, set soundVolume(value: number),
	get musicVolume(): number, set musicVolume(value: number),
	get voiceVolume(): number, set voiceVolume(value: number),
	get language(): string, set language(value: string),
	// игровые данные
	get level(): number, set level(value: number),
	get coins(): number, set coins(value: number),
	get stars(): number, set stars(value: number),
	get shownGameplayElements(): string[], set shownGameplayElements(value: string[]),
	get lastUnlockedColor(): number, set lastUnlockedColor(value: number),
	get lastUnlockedTheme(): number, set lastUnlockedTheme(value: number),
}

export class GameApp extends AnApp
{
	private _game!: Game;
	private _gameData!: AnStorage;

	public devStatsAPI: DevStatsAPI = new DevStatsAPI();

	constructor(config: AnAppConfig)
	{
		super(config);
	}

	public get game(): Game
	{
		return this._game;
	}

	public get gameData(): StorageInterface
	{
		return this._gameData as unknown as StorageInterface;
	}

	public async start(): Promise<void>
	{
		super.start();
	}

	public static get self(): GameApp
	{
		return AnApp.self as GameApp;
	}

	protected override onPreloaderProgress(percent: number): void
	{
		Platform.sdk?.onLoadProgress?.(percent);
	}

	private platformLoaderEnded: boolean = false;
	private storageLoaderEnded: boolean = false;
	protected override onPreloaderStart(): void
	{
		PlatformLoader.load()
			.finally(
				() =>
				{
					this.platformLoaderEnded = true;

					// загружаем данные
					this._gameData = new AnStorage(G.storageName, "1.0", {
						// настройки
						theme: GameTheme.Toys,
						color: GameColor.Color0,
						soundVolume: 100,
						musicVolume: 100,
						voiceVolume: 100,
						language: this.getDefaultLanguage(),
						// игровые данные
						level: 1,
						coins: 0,
						stars: 0,
						// открытые элементы
						shownGameplayElements: [],

						// разблокированные элементы
						lastUnlockedColor: 0,
						lastUnlockedTheme: 0,
					},
						["soundVolume", "musicVolume", "language", "theme", "color"],
						Platform.sdk ?? undefined,
						(localData: AnSaveData, cloudData: AnSaveData) =>
						{
							if (localData.level === cloudData.level)
							{
								if (AnConfig.devMode) AnLog.debug(`[STORAGE] номера уровней тоже сопадают, значит берем тот у кого монет больше`);
								return localData.coins > cloudData.coins ? localData : cloudData;
							}
							else
							{
								if (AnConfig.devMode) AnLog.debug(`[STORAGE] номера уровней не сопадают, выбираем тот, где больший`);
								return localData.level > cloudData.level ? localData : cloudData;
							}
						});

					// если нужно сбросить сохранение на дефолт
					if (AnConfig.devMode && G.dev_startWithFullReset)
					{
						this.storageLoaderEnded = true;
						AnParams.firstRun = true;
						this._gameData.resetToDefaultAndSave();
					}
					else
					{
						// загружаем данные сохранения
						this._gameData.load().finally(() =>
						{
							this.storageLoaderEnded = true;
						});
					}
				}
			);
	}


	private getDefaultLanguage(): string
	{
		// при первом запуске выставляем язык, который по умолчанию выставлен у пользователя в системе

		//! плохой говнокод, но языки на данный момент ещё не загружены
		//! нужно подгружать наверно из файла сборки
		const loadedLangs = ['en', 'ru'];//AnLang.loadedLanguages;

		const currentLang = Platform.sdk?.currentLanguage ?? getCurrentOSLanguage();
		const defaultLang = loadedLangs.includes(currentLang) ? currentLang : 'en'; //по умолчанию англ.

		AnLog.info(`При первом запуске выставлен язык ${defaultLang}`);

		return defaultLang;

	}

	protected override onPreloaderComplete(): void
	{
		const nextRun = () =>
		{
			this.startGame();
			//this.runTestMenu();
		}

		const loadersEnded = () => this.platformLoaderEnded && this.storageLoaderEnded && (Platform.sdk?.lastPrepareToPlayEnded ?? true);

		if (loadersEnded())
			nextRun();
		else
		{
			//? нужен ли таймаут?
			const intervalID = setInterval(() =>
			{
				if (loadersEnded())
				{
					clearInterval(intervalID);
					nextRun();
				}
			}, 500);
		}


	}

	public startGame()
	{
		// форсировать первый запуск
		if (AnConfig.devMode && G.dev_forceFirstRun) AnParams.firstRun = true;
		if (AnConfig.devMode) AnLog.debug(`ПЕРВЫЙ ЗАПУСК ИГРЫ: ${AnParams.firstRun}`);

		//////////////////////////////////////////////////////////////////////////////////


		// модификация параметров игры в зависимости от варианта сборки
		Platform.sdk?.modifyGameParams(G);

		// инициализируем звуковую систему
		AnSounds.init({ soundVolume: this.gameData.soundVolume });

		// инициализируем музыкальную систему
		const tracks = Array.from({ length: 6 }, (_, i) => `music${i + 1}.mus.mp3`);
		if (AnConfig.devMode) AnLog.debug(`Музыка: ${struct(tracks)}`);

		if (!AnParams.firstRun)
			shuffle(tracks);

		AnMusicPlaylist.init({ crossfadeDuration: 2, streaming: G.musicStreaming, musicVolume: this.gameData.musicVolume, autoplay: true });
		if (!(AnConfig.devMode && G.dev_forceNoMusic))
			AnMusicPlaylist.addTracks(tracks);



		if (AnConfig.devMode) AnLog.debug(`Оценка награды за 100 уровней: ${struct(G.evalTotalRewardForLevels(100))}`);


		//Все нужное загруженно, сообщаем платформе об этомо
		Platform.sdk?.reportEvent(PlatformEvent.GameLoaded);

		// игра полностью загружена
		Analytics.onEvent("GameLoadedInSec", uptime() - firstTouchInitTime);


		// меняем правила в режиме разработки
		if (AnConfig.devMode)
		{
			/////////////////////////////////////////
			/// ПОСЛЕДНИЙ ОТЛАЖЕННЫЙ УРОВЕНЬ: 101
			/////////////////////////////////////////
			//this.gameData.language = 'ru';
			this.gameData.theme = GameTheme.Toys;
			this.gameData.level = 8; // 123456
			this.gameData.coins = 15000;
		}


		//! обновляем на всякий случай язык
		//! говнокод связан с ранней инициализацией настроек
		//! нужно будет потом исправить эту ерунду
		const curlang = this.gameData.language;
		this.gameData.language = curlang;

		if (AnConfig.devMode)
			AnLog.debug(`текущий язык ${this.gameData.language}`);


		// показываем начальную рекламу при загрузке, если это требуется
		if (G.adsShowAfterLoading && Platform.sdk)
		{
			let doNextExecute = false;
			const placement = "preloader";

			Platform.sdk.showAds(PlatformAds.Fullscreen, {
				onOpen: () =>
				{
					Analytics.onFullscreenAdShow(placement);
					GameApp.self.paused = true;
				},
				onClose: () =>
				{
					GameApp.self.paused = false;
					if (!doNextExecute)
					{
						doNextExecute = true;
						this.runNextGame();
					}
				},
				onError: () =>
				{
					Analytics.onFullscreenAdError(placement);

					GameApp.self.paused = false;

					if (AnConfig.devMode) AnLog.debug(`Ошибка отображения FullscreenAds`);
					if (!doNextExecute)
					{
						doNextExecute = true;
						this.runNextGame();
					}
				},

			});
		}
		else
			this.runNextGame();
	}

	// продолжаем игру
	public runNextGame()
	{
		this.terminateGame();


		const showNextGameplayElement: string = LevelData.getNextGamePlayElement();
		if (showNextGameplayElement && (!AnConfig.devMode || !G.dev_disableMenuInfo))
		{
			const menuInfo = new MenuInfo({ type: showNextGameplayElement });
			menuInfo.start();
		}
		else
		{
			GameApp.self.runLevel(LevelData.get(GameApp.self.gameData.level));
		}
		AnRender2D.addToFront(new AnFader({ type: 'out', duration: 2 }));
	}

	// загрузить заданный уровень через GameConfig
	public runLevel(config?: GameConfig)
	{
		this.terminateGame();

		this._game = new Game(config ?? LevelData.get());
		this._game.start();
	}

	// полностью сбрасываем прогресс и начинаем сначала
	public fullReset()
	{
		Analytics.onEvent("fullResetGameProgress");
		this._gameData.resetToDefaultAndSave();
		this.runNextGame();
	}

	public terminateGame()
	{
		if (this._game && !this._game.isDestroyed)
			this._game.hide();
	}


	////////////////////////////////////////////////////////////////////////
	////////////////////////////////////////////////////////////////////////
	////////////////////////////////////////////////////////////////////////

	// здесь тестово отлаживаем отдельные меню
	protected runTestMenu()
	{
		const menuResult = new MenuResult({ state: MenuResultState.Win, activeStars: 3, rewardCoins: 5600 });
		menuResult.start();

		// const menuInfo = new MenuInfo({ type: "spec_bomb" });
		// menuInfo.start();
	}

	protected runIntro()
	{
		const intro = new Intro({
			callbacks: {
				onComplete: () => this.runLevel()
			}
		});
		intro.start();
	}

}