	async init(): Promise<void>
	{
		// @ts-ignore
		if (!window.vkBridge)
			throw new Error('[VK SDK] не загружен, произошла ошибка!');


		// @ts-ignore
		this.sdk = window.vkBridge;

		if (AnConfig.devMode)
			this.sdk!.subscribe((e) => AnLog.debug(struct(e)));

		// инициализируем платформу
		if (AnConfig.devMode) AnLog.debug(`[VK SDK] инициализируем платформу....`);
		await this.sdk!.send("VKWebAppInit");
		if (AnConfig.devMode) AnLog.debug(`[VK SDK] проинициализированно!`);

		// предзагружаем сразу рекламу
		this.sdk!.send("VKWebAppCheckNativeAds", { ad_format: EAdsFormats.REWARD });
		this.sdk!.send("VKWebAppCheckNativeAds", { ad_format: EAdsFormats.INTERSTITIAL });

		this._initialized = true;
		AnLog.info('[VK SDK] успешно загружен и проинициализирован');
	}


