	// === Реклама ===

	private get adsAvailable()
	{
		return Boolean(
			this.sdk
		);
	}

	public showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks)
	{
		super.showAds(type, callbacks);

		if (!this.adsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug(`[VK SDK] реклама не доступна!`);
			callbacks.onError?.();
			return;
		}

		switch (type)
		{
			case PlatformAds.Fullscreen:
				callbacks.onOpen?.();
				this.sdk!.send('VKWebAppShowNativeAds', { ad_format: EAdsFormats.INTERSTITIAL })
					.then((data) =>
					{
						if (data.result)
						{
							//console.log('Реклама показана');
							callbacks.onClose?.();
						}
						else
						{
							//console.log('Ошибка при показе');
							callbacks.onError?.()
						}
					})
					.catch((error) =>
					{
						if (AnConfig.devMode) AnLog.debug(`[VK SDK] ошибка загрузки рекламы: ${error}`);
						//console.log(error); /* Ошибка */
						callbacks.onError?.();
					});
				break;
			case PlatformAds.Rewarded:
				callbacks.onOpen?.();
				this.sdk!.send('VKWebAppShowNativeAds', { ad_format: EAdsFormats.REWARD })
					.then((data) =>
					{
						if (data.result) // Успех
						{
							//console.log('Реклама показана');
							callbacks.onCloseRewarded?.();
						}
						else // Ошибка 
						{
							//console.log('Ошибка при показе');
							callbacks.onError?.();
						}
					})
					.catch((error) =>
					{
						if (AnConfig.devMode) AnLog.debug(`[VK SDK] ошибка загрузки рекламы: ${error}`);
						//console.log(error); /* Ошибка */
						callbacks.onError?.();
					});
				break;
		}
	}

	// === Облачные сохранения ===

	private get cloudDataAvailable()
	{
		return Boolean(
			this.sdk
		);
	}

	public async loadData(): Promise<AnSaveData>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		let data: any = null;

		try
		{
			data = await this.sdk?.send('VKWebAppStorageGet', { keys: [this.storageName] });
		}
		catch (error)
		{
			throw new Error('Ошибка чтения данных из облачного хранилища!');
		}

		if (!data || !data.length)
			throw new Error('Данные в облачном хранилище недоступны!');

		const json = data[0].value; // храним как поле в формате json

		if (!json) throw new Error("[VK SDK] данные в облачном хранилище отсуствуют");

		if (AnConfig.devMode) AnLog.debug(`[VK SDK] данные успешно загружены из облачного хранилища`);

		return JSON.parse(json);
	}

	public async saveData(data: AnSaveData): Promise<void>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		try
		{
			const json = JSON.stringify(data);
			await this.sdk?.send('VKWebAppStorageSet', { key: this.storageName, value: json });
			if (AnConfig.devMode) AnLog.debug(`[VK SDK] данные успешно сохранены в облачном хранилище`);
			return;
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[VK SDK] данные НЕ сохранены, ошибка в облачном хранилище: ${error}`);
			return;
		}
	}

	public async clearData(): Promise<void>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		try
		{
			await this.sdk?.send('VKWebAppStorageSet', { key: this.storageName, value: '' });
			if (AnConfig.devMode) AnLog.debug(`[VK SDK] облачное хранилище успешно очищено`);
			return;
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[VK SDK] ошибка очистки облачного хранилища: ${error}`);
			return;
		}
	}
