import { AnUpdater } from "angine/utils/AnUpdater";
import { dataClone, enhance } from "angine/utils/AnHelpers";
import { AnInterpolation } from "angine/anim/AnInterpolation";
import { AnUpdatableConfig, AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";

// Тип, поддерживающий как число, так и объект с числовыми значениями
type AnInterpolatableValue = any; //number | Record<string, number>;
type AnInterpolationFunction = (t: number, current: number, target: number) => number;

export interface AnInterpolatorCallbacks
{
	onUpdate?: (currentValue: AnInterpolatableValue, targetValue: AnInterpolatableValue) => void;
	onComplete?: () => void;
}

export interface AnInterpolatorConfig extends AnUpdatableConfig
{
	initialValue?: AnInterpolatableValue;
	speed?: number; /** чем больше тем быстрее*/
	eps?: number;
	interpolation?: AnInterpolationFunction;
	autoStart?: boolean;
	callbacks?: AnInterpolatorCallbacks;
}

export class AnInterpolator extends enhance(Object).with(AnUpdatableMixin) implements AnUpdatableInterface
{
	private _currentValue: AnInterpolatableValue;
	private _targetValue: AnInterpolatableValue;
	private _speed: number;
	private _interpolation: AnInterpolationFunction;
	private _callbacks: AnInterpolatorCallbacks;
	private _isActive: boolean = false;
	private eps: number;

	constructor(config: AnInterpolatorConfig)
	{
		super();

		this._currentValue = config.initialValue ?? 0;
		this._targetValue = typeof this._currentValue === 'object' ? dataClone(this._currentValue) : this._currentValue;
		this._speed = config.speed ?? 1;
		this.eps = config.eps ?? 0.0001;
		this._interpolation = config.interpolation ?? AnInterpolation.linear;
		this._callbacks = config.callbacks ?? {};

		if (config.updater) this.addToUpdater(config.updater);
		if (config.autoStart !== false) this.start();
	}

	public start(): void
	{
		this._isActive = true;
	}

	public stop(): void
	{
		this._isActive = false;
	}

	public update(dt: number): void
	{
		super.update(dt);

		if (!this._isActive || this.isTargetReached()) return;

		const t = Math.min(this._speed * dt, 1);

		if (typeof this._currentValue === 'number' && typeof this._targetValue === 'number')
		{
			this._currentValue = this._interpolation(t, this._currentValue, this._targetValue);
		} else if (this.isObject(this._currentValue) && this.isObject(this._targetValue))
		{
			for (const key in this._currentValue)
			{
				if (this._targetValue.hasOwnProperty(key))
				{
					(this._currentValue as Record<string, number>)[key] = this._interpolation(
						t,
						(this._currentValue as Record<string, number>)[key],
						(this._targetValue as Record<string, number>)[key]
					);
				}
			}
		}

		this._callbacks.onUpdate?.(this._currentValue, this._targetValue);

		if (this.isTargetReached())
		{
			this.finish();
		}
	}

	private isTargetReached(): boolean
	{
		if (typeof this._currentValue === 'number' && typeof this._targetValue === 'number')
		{
			return Math.abs(this._targetValue - this._currentValue) < this.eps;
		} else if (this.isObject(this._currentValue) && this.isObject(this._targetValue))
		{
			for (const key in this._currentValue)
			{
				if (this._targetValue.hasOwnProperty(key))
				{
					if (Math.abs((this._targetValue as Record<string, number>)[key] - (this._currentValue as Record<string, number>)[key]) >= this.eps)
					{
						return false;
					}
				}
			}
			return true;
		}
		return true;
	}

	private isObject(value: any): value is Record<string, number>
	{
		return typeof value === 'object' && value !== null && !Array.isArray(value);
	}

	public get currentValue(): AnInterpolatableValue
	{
		return this._currentValue;
	}

	public get targetValue(): AnInterpolatableValue
	{
		return this._targetValue;
	}

	public set targetValue(value: AnInterpolatableValue)
	{
		if (typeof this._currentValue !== typeof value)
		{
			throw new Error("Target value must be of the same type as current value");
		}
		this._targetValue = value;
	}

	public setSpeed(speed: number): void
	{
		this._speed = speed;
	}

	public setInterpolation(fn: AnInterpolationFunction): void
	{
		this._interpolation = fn;
	}

	public finish(): void
	{
		if (typeof this._currentValue === 'number')
		{
			this._currentValue = this._targetValue as number;
		} else if (this.isObject(this._currentValue) && this.isObject(this._targetValue))
		{
			for (const key in this._currentValue)
			{
				if (this._targetValue.hasOwnProperty(key))
				{
					(this._currentValue as Record<string, number>)[key] = (this._targetValue as Record<string, number>)[key];
				}
			}
		}

		this._callbacks.onUpdate?.(this._currentValue, this._targetValue);
		this._callbacks.onComplete?.();
	}
}