import { Constructor, shuffle } from "angine/utils/AnHelpers.js";
import { Block, BlockType, BonusSpecBlockTypeArray, PropBlockType, PropBlockTypeArray } from "./Block.js";
import { Field, GridPos } from "./Field.js";
import { G } from "./G.js";
import { AnChanceAction, AnRnd } from "angine/utils/AnRnd.js";
import { AnMath } from "angine/utils/AnMath.js";
import { AnCore } from "angine/core/AnCore.js";
import { BlockGen, GameMode, LevelRuleType, TypesCollectModeData } from "./Game.js";
import { GameApp } from "../GameApp.js";


export function FieldBlockGenMixin<TBase extends Constructor>(Base: TBase)
{
	return class extends Base
	{
		constructor(...args: any[])
		{
			super(...args);

			// Дополнительная проверка во время выполнения
			if (!(this instanceof Field))
				throw new Error('FieldBlockGenMixin может использоваться только с классом Field!');
		}

		// Веса для бонусных спецблоков (чем выше — тем чаще)
		//  * Бомба: ~35 %
		//  * Ракеты: ~28 %
		//  * Зеркало: ~18 %
		//  * Радуга: ~12 %
		//  * Кость: ~7 %
		private readonly SpecBlockWeights: Record<string, number> = {
			"spec_bomb": 35,
			"spec_rocket_horizontal": 7,
			"spec_rocket_vertical": 7,
			"spec_rocket_diagonal1": 7,
			"spec_rocket_diagonal2": 7,  // итого ракеты = 28
			"spec_mirror": 18,
			"spec_rainbow": 12,
			"spec_dice": 7,
		};

		public tryToCreateBlocks(): boolean
		{
			const field = this as unknown as Field;
			const game = GameApp.self.game;
			let anyCreating = false; // был ли создан хоть один блок

			//найдём свободные колонки для генерации
			const freeCols: number[] = [];
			for (let col = 0; col < field.colsCount; col++)
			{
				if (field.cells[0][col].block === null && field.getOccupiedBlockByGridPos(new GridPos(0, col)) === null)
				{
					freeCols.push(col);
				}
			}

			// запланируем генерацию
			const genBlocks: BlockGen[] = [];
			if (freeCols.length && !field.forbidAllSpecBlocks)
			{
				shuffle(freeCols, field.specRndSeed);

				field.generators.forEach(gen =>
				{
					if (freeCols.length && game.currentMoves! % gen.num === 0 && gen.last < field.genCounter)
					{
						gen.last = field.genCounter; // не генерируем больше на этом ходу
						genBlocks.push({ type: gen.type, num: freeCols.pop()!, last: 0 });
					}
				});
			}

			//запрет на другие типы блоков в данный момент
			const moreForbidSpecials: BlockType[] = [];
			//если на поле есть кость - исключаем её из генерированных
			if (field.blocks.some(block => block.type === "spec_dice")) moreForbidSpecials.push("spec_dice");


			// создаём новые блоки если есть место
			for (let col = 0; col < field.colsCount; col++)
			{
				if (field.cells[0][col].block === null && field.getOccupiedBlockByGridPos(new GridPos(0, col)) === null)
				{
					anyCreating = true;


					let type: BlockType;
					if (field.preset6x6 === null)
					{
						type = this.generateRandomBlockType(col, moreForbidSpecials);
					}
					else
					{
						const isInPresetArea = AnMath.inRange(col, field.startPresetCol, field.startPresetCol + field.presetWidth - 1);
						const hasEnoughBlocksBelow = field.getBlocksCountInColumn(col) >= field.rowsCount - field.presetHeight;
						const presetID = col - field.startPresetCol;
						const hasPresetData = field.preset6x6[presetID]?.length > 0;

						type = isInPresetArea && hasEnoughBlocksBelow && hasPresetData ?
							field.preset6x6[presetID].pop()! :
							this.generateRandomBlockType(col, moreForbidSpecials);
					}

					// если используем генератор c фиксированными выпадениями за ход
					const genType = genBlocks.find(gen => gen.num === col);
					if (genType)
					{
						type = genType.type;
					}

					const block = new Block({
						theme: type.startsWith("prop") ? field.theme : undefined,
						pos: new GridPos(0, col),
						type,
						updater: field.getUpdater() ?? AnCore.updater,
						selectionLayer: field.selectionLayer,
						blockLayer: field.blockLayer,
					});

					field.cells[0][col].block = block;
					block.updateGridPos(0, col);
					field.blocks.push(block);
					field.addUIElement(block);

				}
			}



			return anyCreating;
		}


		/**
		 * генерирует тип блока для заданного столбца
		 * 
		 */
		public generateRandomBlockType(col: number, moreForbidSpecials: BlockType[] = []): BlockType
		{
			const field = this as unknown as Field;
			const rndSeed = field.colRndSeed[col];

			// Сначала обычный блок
			//let type: BlockType = PropBlockTypeArray[rndSeed.seed_int(0, PropBlockTypeArray.length - 1)];
			let type: BlockType = this.generateRandomPropBlockType(rndSeed, this.calcGoalsWeights()) as BlockType;

			// Исключаем запрещённые
			const allowedSpecs = BonusSpecBlockTypeArray.filter(type => !field.forbidSpecials.includes(type) && !moreForbidSpecials.includes(type));
			// Если бонусов открыто мало - снизим вероятность появления блока
			const maxEffectiveSpecs = 6; // при скольки блоках открыть полностью вероятность
			const clampedCount = Math.min(allowedSpecs.length, maxEffectiveSpecs);

			const adjustedDropChance = AnMath.remap(clampedCount, 0, maxEffectiveSpecs, G.specialBlockDropChance * 0.5, G.specialBlockDropChance);
			if (
				allowedSpecs.length > 0 &&
				!field.forbidAllSpecBlocks &&
				rndSeed.seed_bool(adjustedDropChance)
			)
			{
				const chosen: string = this.generateRandomSpecBlockType(rndSeed, allowedSpecs);
				if (chosen) // если не пустая строка - значит выбрали спецблок
				{
					type = chosen as BlockType;
				}
			}
			else // если спешал не выпал, пройдёмся по правилам уровня, возможно нужно ещё что-то генерировать
			{
				const chanceActions: AnChanceAction[] = [];

				// вероятность обычного блока
				chanceActions.push({ chance: G.propBlockDropChance, action: () => { } });

				for (const rule of field.rules)
				{
					if (rule.type === LevelRuleType.DropRandomStones)
						chanceActions.push({ chance: rule.num, action: () => type = "spec_stone" });
				}

				AnRnd.executeByChance(chanceActions, rndSeed);
			}

			return type;
		}


		protected generateRandomSpecBlockType(rndSeed: AnRnd, candidates: string[]): string
		{
			//Считаем общий вес
			let totalWeight = 0;
			for (const type of candidates)
				totalWeight += this.SpecBlockWeights[type] ?? 0;

			if (totalWeight <= 0) return "";

			// Генерируем случайное число в диапазоне [0, totalWeight)
			const rand = rndSeed.seed_float(0, totalWeight);

			// Находим блок по весу
			let acc = 0;
			for (const type of candidates)
			{
				const weight = this.SpecBlockWeights[type] ?? 0;
				acc += weight;
				if (rand < acc)
				{
					return type;
				}
			}

			// fallback (на случай ошибки округления)
			return candidates[candidates.length - 1];
		}

		protected generateRandomPropBlockType(rndSeed: AnRnd, goalsWeights?: Record<string, number>): string
		{
			const result = PropBlockTypeArray[rndSeed.seed_int(0, PropBlockTypeArray.length - 1)];
			//если целей предметов нет - вероятности равные
			if (goalsWeights === undefined)
				return result;

			//Считаем общий вес
			let totalWeight = 0;

			for (let i = 0; i < 7; ++i)
			{
				const type = "prop_" + i;
				totalWeight += goalsWeights[type] !== undefined ? goalsWeights[type] : 1;
			}


			if (totalWeight <= 0) return result;

			// Генерируем случайное число в диапазоне [0, totalWeight)
			const rand = rndSeed.seed_float(0, totalWeight);

			// Находим блок по весу
			let acc = 0;
			for (let i = 0; i < 7; ++i)
			{
				const type = "prop_" + i;

				let weight = goalsWeights[type] !== undefined ? goalsWeights[type] : 1;

				acc += weight;
				if (rand < acc)
				{
					return type;
				}
			}

			// fallback (на случай ошибки округления)
			return result;
		}

		protected calcGoalsWeights(): Record<string, number> | undefined
		{
			const game = GameApp.self.game;

			if (game.mode === GameMode.TypesCollect)
			{
				const goals: Record<string, number> = {};

				for (const counter of (game.modeData as TypesCollectModeData).types)
				{
					if (PropBlockTypeArray.includes(counter.type as PropBlockType) && counter.current! < counter.total)
					{
						goals[counter.type] = AnMath.remapClamp(counter.current!, 0, counter.total - G.maxChanceDropPropTypeCount, 1, G.maxChanceDropPropType);
					}
				}

				return goals;
			}

			return undefined;
		}
	}
}