import { AnEvent, AnEvents } from 'angine/utils/AnEvents';
import { AnLog } from 'angine/utils/AnLog';
import { AnRnd } from 'angine/utils/AnRnd';
import { Howl } from 'howler';

export interface AnMusicPlaylistConfig
{
	crossfadeDuration?: number;
	streaming?: boolean;
	autoplay?: boolean;
	musicVolume?: number;
}

export interface AnMusicPlaylistTrack
{
	name: string;
	howl: Howl | null;
}

export class AnMusicPlaylist
{
	private static tracks: AnMusicPlaylistTrack[] = []; // Хранит Howl-объекты
	private static currentTrackIndex: number = -1; // никто не проигрывается если -1

	private static crossfadeDuration: number;
	private static streaming: boolean = false;
	private static autoplay: boolean = false;
	private static _musicVolume: number;
	private static _enabled: boolean;


	public static init(config: AnMusicPlaylistConfig)
	{
		this.crossfadeDuration = config.crossfadeDuration ?? 2;
		this.streaming = config.streaming ?? false;
		this.autoplay = config.autoplay ?? false;
		this._musicVolume = config.musicVolume ?? 100;

		AnEvents.on("storage:musicVolume:update", (e: AnEvent) => this.updateVolume(e.data.value));
	}

	static updateVolume(value: number): void
	{
		if (this._musicVolume === value) return;
		this._musicVolume = value;

		const index = this.currentTrackIndex;
		if (index !== -1 && this.tracks[index].howl?.playing)
			this.tracks[index].howl?.fade(0, this._musicVolume / 100, this.crossfadeDuration);
	}


	public static async addTracks(trackUrls: string[]): Promise<void>
	{
		if (trackUrls.length === 0)
		{
			AnLog.error('AnMusicPlaylist: список треков пуст!');
			return;
		}

		this.loadNextTrack([...trackUrls], this.autoplay);
	}


	private static loadNextTrack(trackUrls: string[], autoplay: boolean = false)
	{
		if (trackUrls.length === 0) return; // загрузка завершена

		const trackUrl = trackUrls.shift()!;

		const howl = new Howl({
			src: [trackUrl],
			html5: this.streaming,
			volume: 0,
			onload: () =>
			{
				AnLog.info(`Трек ${trackUrl} загружен.`);

				const index = this.tracks.push({ name: trackUrl, howl: howl }) - 1;

				// если ничего не играло, начинаем проигрывание
				if (autoplay && this.currentTrackIndex === -1) 
				{
					AnMusicPlaylist.playTrack(index);
				}

				// грузим следующий трек
				this.loadNextTrack(trackUrls);
			},
			onloaderror: (id, err) =>
			{
				AnLog.error(`Ошибка загрузки трека ${trackUrl}:`, err);

				// грузим следующий трек
				this.loadNextTrack(trackUrls);
			},
			onend: () =>
			{
				// перебираем циклически треки
				this.playTrack((this.currentTrackIndex + 1) % this.tracks.length);
			}
		});
	}


	private static playTrack(index: number)
	{
		this.currentTrackIndex = index;

		if (AnConfig.devMode) AnLog.debug(`Проигрывается трек ${this.tracks[index].name}`);
		this.tracks[index].howl?.play();
		this.tracks[index].howl?.fade(0, this._musicVolume / 100, this.crossfadeDuration);
	}

	static set volume(value: number)
	{
		this._musicVolume = Math.min(100, Math.max(0, value));
	}

	static get volume(): number
	{
		return this._musicVolume;
	}

	static set enabled(value: boolean)
	{
		if (this._enabled === value) return;

		this._enabled = value;

		if (this._enabled)
		{
			if (this.currentTrackIndex === -1)
			{
				const index = AnRnd.int(0, this.tracks.length - 1);
				this.playTrack(index);
			}
		}
		else
		{
			this.tracks[this.currentTrackIndex].howl?.stop();
			this.currentTrackIndex = -1;
		}
	}

	static get enabled()
	{
		return this._enabled;
	}
}
