import { AnLog } from "angine/utils/AnLog";
import { AnValidator } from "angine/utils/AnValidator";
import { AnTask } from "./AnTask";
import { AnCore } from "angine/core/AnCore";
import { AnEvents } from "./AnEvents";
import { delay, runAfter } from "./AnHelpers";



/*
	Интерфейс для сохранений (локальных и облачных)
*/
export type AnSaveData = Record<string, any>;

/*
	Интерфейс для сохранений (локальных и облачных)
*/
export interface AnSaveInterface
{
	loadData(): Promise<AnSaveData>;
	saveData(data: AnSaveData): Promise<void>;
	clearData(): Promise<void>;
}

/** одно поле данных */
type AnStorageEntry<T> = {
	default: T; // значение по умолчанию
	current?: T; // текущее значение
	//validator?: AnValidator; // валидатор для значения
};


/** в интерфейс добавляем все поля данных для подсказки типов */
// export interface AnStorageInterface
// {
// 	soundVolume: number,
// 	musicVolume: number,
// 	voiceVolume: number
// }

/*
	Стратегия синхронизации если saveID совпадает
*/
export type AnStorageSyncStrategy = (localData: AnSaveData, cloudData: AnSaveData) => AnSaveData;


/**
 * Класс для управления хранения данных с динамическими свойствами
 */
export class AnStorage
{
	// Локальное хранилище
	private localSave: AnSaveInterface;

	// Облачное хранилище
	private cloudSave: AnSaveInterface | null;

	// Счетчик сохранений для синхронизации
	private saveID: number = 0;

	// Синхронизация данных через дополнительный анализ данных, если saveID совпадает
	private syncStrategy: AnStorageSyncStrategy | null;

	// Версия формата сохранений (для миграций)
	private version: string;

	// для этих настроек эмитировать события изменения
	private emitUpdateEvents: string[];

	// Хранилище данных
	private storage: Record<string, AnStorageEntry<any>> = {};

	public constructor(storageName: string, version: string, entries: Record<string, any>, emitUpdateEvents: string[] = [], cloudSave?: AnSaveInterface, syncStrategy?: AnStorageSyncStrategy)
	{
		this.version = version;

		if (!cloudSave) AnLog.warn("Облачное хранилище не добавлено. Сохранения будут локальными");

		this.localSave = new AnLocalSave(storageName);
		this.cloudSave = cloudSave ?? null;
		this.syncStrategy = syncStrategy ?? null;

		this.emitUpdateEvents = emitUpdateEvents;

		this.define(entries);
	}


	/**
	 * Определяет новые данные
	 */
	private define(entries: Record<string, any>): void
	{
		Object.keys(entries).forEach(key =>
		{
			const value = entries[key];

			this.storage[key] = { current: value, default: value };

			Object.defineProperty(this, key, {
				get() { return this.storage[key].current; },
				set(value) { this.setValue(key, value); },
				enumerable: true,
				configurable: true
			});
		});
	}

	/**
	 * Универсальный метод установки значения
	 */
	private setValue<T>(key: string, value: T): void
	{
		const def = this.storage[key];
		if (!def)
		{
			AnLog.warn(`Попытка установить неопределенные данные: ${key}`);
			return;
		}

		// Валидация
		// if (def.validator)
		// {
		// 	let validatorResult = def.validator.validate(value);
		// 	if (!validatorResult.isValid)
		// 	{
		// 		AnLog.warn(`Некорректное значение для ${key}: ${value} [${validatorResult.message ?? 'нет описания'}]`);
		// 		return;
		// 	}
		// }

		this.storage[key].current = value;

		// рассылаем события если это нужно
		if (this.emitUpdateEvents.includes(key))
		{
			AnEvents.emit(`storage:${key}:update`, { key, value });
		}

		this.saveDelayed();
	}



	/**
	 * Загружает данные 
	 */
	public async load(): Promise<void>
	{
		let localData: AnSaveData | null = null;
		let cloudData: AnSaveData | null = null;

		//пробуем загрузить локальные данные
		try
		{
			localData = await this.localSave.loadData();
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] данные из локального хранилища успешно загружены`);
		}
		catch (error)
		{
			localData = null;
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] ошибка загрузки данных из локального хранилища: ${error}`);
		}

		//пробуем загрузить облачные данные, если они есть
		if (this.cloudSave)
		{
			try
			{
				cloudData = await this.cloudSave.loadData();
				if (AnConfig.devMode) AnLog.debug(`[STORAGE] данные из облачного хранилища успешно загружены`);
			}
			catch (error)
			{
				cloudData = null;
				if (AnConfig.devMode) AnLog.debug(`[STORAGE] ошибка загрузки данных из облачного хранилища: ${error}`);
			}
		}


		// данных нет, это первый запуск игры
		if (!localData && !cloudData)
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] Данных нет, это первый запуск, загружаем дефолтные значения`);
			AnParams.firstRun = true;
			this.resetToDefaultAndSave();
			return;
		}

		// значит запуск не первый
		AnParams.firstRun = false;

		// данные есть в одном из двух хранилищ
		if (localData !== null || cloudData !== null)
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] Данные есть в ${localData !== null ? 'локальном' : 'облачном'} хранилище`);

			const validData: AnSaveData = localData !== null ? localData : cloudData!;

			this.migrateDataToActualVersion(validData);

			this.applyDataToStorage(validData);

			// сохраняем данные на всякий случай во второе хранилище
			await this.backupDataToOtherSave(validData, localData === validData ? this.cloudSave : this.localSave);
			return;
		}

		// данные есть в двух хранилищаx сразу, нужна сихронизация
		if (localData !== null && cloudData !== null)
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] Данные есть в двух хранилищах сразу, нужно выбрать одно из них`);

			const validData: AnSaveData = this.syncDataForNewer(localData, cloudData);

			this.migrateDataToActualVersion(validData);

			this.applyDataToStorage(validData);

			// сохраняем данные на всякий случай во второе хранилище
			await this.backupDataToOtherSave(validData, localData === validData ? this.cloudSave : this.localSave);
			return;
		}
	}

	private async backupDataToOtherSave(data: AnSaveData, save: AnSaveInterface | null): Promise<void>
	{
		if (!save)
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] Второе хранилище не доступно для бекапа данных`);
			return;
		}

		try
		{
			await save.saveData(data);
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] данные успешно забекаплены во второе хранилище`);
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] ошибка бекапа во второе хранилище`);
		}
	}

	private syncDataForNewer(localData: AnSaveData, cloudData: AnSaveData): AnSaveData
	{
		if (AnConfig.devMode) AnLog.debug(`[STORAGE] Проверяем хранилища...`);

		// если данные совпадают, проверяем по номеру уровня
		if (localData.saveID === cloudData.saveID)
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] saveID у них совпадают, проверяем сами данные....`);

			//применяем синхронизацию по добавленной стратегии, если такая есть
			return this.syncStrategy ? this.syncStrategy(localData, cloudData) : localData;
		}

		if (AnConfig.devMode) AnLog.debug(`[STORAGE] saveID не совпадает, возвращаем старшие данные`);

		return localData.saveID > cloudData.saveID ? localData : cloudData;
	}


	/**
	 * здесь можно модифицировать данные по миграции, если версии данных не совпадают
	 */
	private migrateDataToActualVersion(data: AnSaveData)
	{
		if (this.version !== data.version)
		{
			// здесь модифицируем data в соотвествии с его версией
		}
		else
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] миграция данных не требуется, версии совпадают`);
		}
	}


	/**
	 * получаем объект только с текущими данными и ключами (для дальнейшего сохранения)
	 */
	private getCurrentData(): AnSaveData
	{
		let data: AnSaveData = { saveID: this.saveID, version: this.version };
		Object.keys(this.storage).forEach(key =>
			data[key] = this.storage[key].current);

		return data;
	}

	// сохраняем данные в полях объекта
	private applyDataToStorage(data: AnSaveData): void
	{
		Object.keys(data).forEach(key =>
		{
			if (this.storage[key] !== undefined)
				this.storage[key].current = data[key];

		});
		this.saveID = data.saveID + 1;
	}

	/**
	 * Очищает данные
	 */
	public async clear(): Promise<void>
	{
		//localStorage.removeItem(this.storageName);
		try
		{
			await this.localSave.clearData();
			await this.cloudSave?.clearData();

			if (AnConfig.devMode) AnLog.debug(`[STORAGE] данные успешно очищены`);
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[STORAGE] ошибка очистки данных: ${error}`);
		}
	}

	/**
	 * Сохраняет текущие данные
	 */
	public async save(): Promise<void>
	{
		// уберем запланированное сохранение
		if (this.saveDelayedTimerID !== null)
		{
			clearTimeout(this.saveDelayedTimerID);
			this.saveDelayedTimerID = null;
		}

		const data = this.getCurrentData();

		// увеличиваем номер сохранения чтобы понимать какой был позже
		// важно увеличить перед промисами!
		this.saveID++;
		if (AnConfig.devMode) AnLog.debug(`[STORAGE] Новый saveID: ${this.saveID}`);

		// Сохраняем локально сразу
		const localSavePromise = this.localSave.saveData(data);

		// Облачное сохранение с задержкой
		const cloudSavePromise = this.cloudSave
			? this.cloudSave!.saveData(data)
			: Promise.resolve();

		// Ожидаем результаты
		const results = await Promise.allSettled([localSavePromise, cloudSavePromise]);

		results.forEach((result, index) =>
		{
			if (result.status === "fulfilled")
			{
				if (AnConfig.devMode) AnLog.debug(`Сохранение ${index === 0 ? "локальное" : "в облаке"} успешно.`);
			}
			else
			{
				if (AnConfig.devMode) AnLog.debug(`Ошибка при сохранении ${index === 0 ? "локальном" : "в облаке"}: ${result.reason}`);
			}

		});
	}

	/**
	 * Запланировать сохранение данных в следующем кадре
	 */
	private saveDelayedTimerID: number | null = null;
	private saveDelayed(delay: number = 2)
	{
		if (this.saveDelayedTimerID === null)
		{
			this.saveDelayedTimerID = runAfter(delay, () =>
			{
				this.saveDelayedTimerID = null;
				this.save();
			});
		}
	}

	/**
	 * Сбрасывает данные к значениям по умолчанию
	 */
	public resetToDefaultAndSave(): void
	{
		Object.keys(this.storage).forEach(key =>
		{
			const defaultValue = this.storage[key].default;
			this.storage[key].current = typeof defaultValue === "object" ? structuredClone(defaultValue) : defaultValue;
		});

		this.save();
	}

}



// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// LOCAL SAVE
// +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


export class AnLocalSave implements AnSaveInterface
{
	// Название хранилища
	private _storageName: string;

	constructor(storageName: string)
	{
		this._storageName = storageName;
	}

	public get storageName(): string { return this._storageName; }

	public async loadData(): Promise<AnSaveData>
	{
		const json = localStorage.getItem(this._storageName); // храним как поле в формате json

		if (!json) throw new Error("[AnLocalSave] данные отсуствуют");

		return JSON.parse(json);

	}

	public async saveData(data: AnSaveData): Promise<void>
	{
		const json = JSON.stringify(data);
		localStorage.setItem(this._storageName, json);
	}

	public async clearData(): Promise<void>
	{
		localStorage.removeItem(this._storageName);
	}
}