import { AnUIGroupElement, AnUIGroupElementConfig } from "angine/ui/AnUIGroupElement.js";
import { AnImage, AnImageConfig } from "angine/ui/AnImage.js";
import { AnLabel, AnLabelConfig } from "angine/ui/AnLabel.js";
import { AnTween, AnTweenConfig } from "angine/anim/AnTween.js";
import { AnEase } from "angine/anim/AnEase.js";
import { enhance, safeDestroyFunc } from "angine/utils/AnHelpers.js";
import { AnUpdatableConfig, AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin.js";
import { AnViewport } from "angine/core/AnViewport.js";
import { AnVoidCallback } from "angine/utils/AnHelpers.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnTextAlign } from "angine/2D/AnText.js";
import { AnRnd } from "angine/utils/AnRnd.js";
import { AnMath } from "angine/utils/AnMath.js";

export interface UITipCallbacks
{
	/** Вызывается при завершении анимации */
	onComplete?: () => void;
}
export interface UITipConfig extends AnUIGroupElementConfig, AnUpdatableConfig
{
	/** Конфигурация фонового изображения */
	background: AnImageConfig;
	/** Дополнительная конфигурация для надписи */
	labelText: AnLabelConfig;
	/** Длительность анимации появления (в секундах) */
	appearDuration?: number;
	/** Длительность анимации исчезновения (в секундах) */
	disappearDuration?: number;

	appearDelay?: number;
	stayDelay?: number;

	backgroundAlpha?: number;

	callbacks?: UITipCallbacks;
}

/**
 * Класс UITip - компонент подсказки с надписью
 * Состоит из фонового изображения и текстовой надписи с последовательными анимациями
 */
export class UITip
	extends enhance(AnUIGroupElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{
	private background: AnImage;
	private labelText: AnLabel;

	private bgTween: AnTween | null = null;
	private labelTween: AnTween | null = null;

	private appearDuration: number;
	private disappearDuration: number;
	private appearDelay: number;
	private stayDelay: number;

	private backgroundAlpha: number;

	private callbacks: UITipCallbacks;

	constructor(config: UITipConfig)
	{
		super(config);

		//? не нужно?
		if (config.updater) this.addToUpdater(config.updater);

		// Устанавливаем значения по умолчанию
		this.appearDuration = config.appearDuration ?? 2;
		this.disappearDuration = config.disappearDuration ?? 0.5;
		this.appearDelay = config.appearDelay ?? 0;
		this.stayDelay = config.stayDelay ?? 2;
		this.backgroundAlpha = config.backgroundAlpha ?? 0.9;
		this.callbacks = config.callbacks ?? {};

		// Создаем фоновое изображение
		this.background = this.addUIElement("background",
			new AnImage({
				...config.background,
				anchor: AnAnchor.Center
			}));

		this.labelText = this.addUIElement("labelText",
			new AnLabel({
				...config.labelText,
				anchor: AnAnchor.Center,
			}));


		this.addToCleanup(() => this.cleanupTweens());

		//this.startAnimation();

		// +++ resize strategy +++
		this.defaultResizeStrategy =
			() =>
			{
				this.background.setScaledSize(this.scaledWidth, this.scaledHeight);
				this.labelText.setScaledSize(this.scaledWidth, this.scaledHeight);
				this.background.applyDefaultResizeStrategy();
				this.labelText.applyDefaultResizeStrategy();

				this.background.position.set(this.scaledWidth * 0.5, this.scaledHeight * 0.5);
				this.labelText.position.set(this.scaledWidth * 0.5, this.scaledHeight * 0.5);
			};

		this.configResizeStrategy(config.resizeStrategy);
	}


	public startAnimation()
	{
		this.bgTween = new AnTween({
			target: this.background,
			from: { scale: { x: 0.1, y: 1 }, alpha: 0 },
			to: { scale: { x: 1, y: 1 }, alpha: this.backgroundAlpha },
			delay: this.appearDelay,
			duration: this.appearDuration,
			easing: AnEase.easeOutElastic,
			updater: this.getUpdater(),
			autoRemove: true,
			callbacks: {
				onComplete: () =>
				{
					this.bgTween = new AnTween({
						target: this.background,
						to: { scale: { x: 0.1, y: 1 }, alpha: 0 },
						from: { scale: { x: 1, y: 1 }, alpha: this.backgroundAlpha },
						delay: this.stayDelay,
						duration: this.disappearDuration,
						easing: AnEase.easeInBack,
						updater: this.getUpdater(),
						autoRemove: true,
						callbacks: {
							onComplete: () =>
							{
								this.bgTween?.terminate();
								this.bgTween = null;

								this.callbacks.onComplete?.();
							}
						}
					});
				}
			}
		});


		this.labelTween = new AnTween({
			target: this.labelText,
			from: { scale: { x: 0.8, y: 0.8 }, alpha: 0, rotation: -5 * AnMath.toRad },
			to: { scale: { x: 1, y: 1 }, alpha: 1, rotation: 0 * AnMath.toRad },
			delay: this.appearDelay,
			duration: this.appearDuration,
			easing: AnEase.easeOutElastic,
			updater: this.getUpdater(),
			autoRemove: true,
			callbacks: {
				onComplete: () =>
				{
					this.labelTween = new AnTween({
						target: this.labelText,
						to: { scale: { x: 0.5, y: 0.5 }, alpha: 0 },
						from: { scale: { x: 1, y: 1 }, alpha: 1 },
						delay: this.stayDelay,
						duration: this.disappearDuration,
						easing: AnEase.easeInBack,
						updater: this.getUpdater(),
						autoRemove: true,
						callbacks: {
							onComplete: () =>
							{
								this.labelTween?.terminate();
								this.labelTween = null;
							}
						}
					});
				}
			}
		});
	}



	private cleanupTweens(): void
	{
		// Очищаем твин, если он существует
		if (this.bgTween)
		{
			this.bgTween.terminate();
			this.bgTween = null;
		}

		if (this.labelTween)
		{
			this.labelTween.terminate();
			this.labelTween = null;
		}
	}
}