import { AnTween } from "angine/anim/AnTween.js";
import { AnEase } from "angine/anim/AnEase.js";
import { AnViewport, scaled } from "angine/core/AnViewport.js";
import { AnMenu, AnMenuConfig } from "angine/menu/AnMenu.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnButton, AnButtonState, AnIconAlign } from "angine/ui/AnButton.js";
import { AnImage } from "angine/ui/AnImage.js";
import { AnLabel } from "angine/ui/AnLabel.js";
import { AnVoidCallback, runAfter, runAfterSafe, safeDestroyFunc } from "angine/utils/AnHelpers.js";
import { AnLog } from "angine/utils/AnLog.js";
import { AnTextAlign, AnTextSource } from "angine/2D/AnText.js";
import { AnEvents } from "angine/utils/AnEvents.js";
import { AnControlsEvent } from "angine/input/AnControlsEnums.js";
import { AnLang } from "angine/utils/AnLang.js";

export interface MenuConfirmCallbacks
{
	onConfirm?: AnVoidCallback;
	onCancel?: AnVoidCallback;
}

export interface MenuConfirmConfig extends AnMenuConfig
{
	text: string;
	confirmText?: string;
	cancelText?: string;
	callbacks?: MenuConfirmCallbacks;
	forceWait?: boolean;
}

export class MenuConfirm extends AnMenu
{
	private callbacks: MenuConfirmCallbacks;
	private background!: AnImage;
	private title!: AnLabel;
	private buttonConfirm!: AnButton;
	private buttonCancel!: AnButton;

	private text!: string;
	private confirmText?: string;
	private cancelText?: string;

	private forceWait: boolean = false;
	private forceWaitCnt: number = 10;

	public constructor(config: MenuConfirmConfig)
	{
		super(config);
		this.callbacks = config.callbacks ?? {};

		this.text = config.text;
		this.confirmText = config.confirmText;
		this.cancelText = config.cancelText;
		this.forceWait = config.forceWait ?? false;

		this.addToCleanup(AnEvents.on("ui:menuResult:started", () => this.hide()).unsub);

	}

	public start()
	{
		this.createUI();
		this.resizeUI();
		this.show();
	}

	protected createUI(): void
	{
		// Создаем фон
		this.background = this.addUIElement("background",
			new AnImage({
				sprite: 'images/hoverbg.tex.pixi.jpg',
				anchor: AnAnchor.TopLeft,
				resizeStrategy: () =>
				{
					this.background.position.set(0, 0);
					this.background.scaledWidth = AnViewport.width;
					this.background.scaledHeight = AnViewport.height;
					this.background.applyDefaultResizeStrategy();
				}
			})
		);
		this.background.tint = 0xFF0000;
		//this.background.alpha = 0.95;

		// Создаем заголовок
		this.title = this.addUIElement("title",
			new AnLabel({
				text: {
					textSource: this.text,
					fontName: "mainFont",
					fontSize: 80,
					textAlign: AnTextAlign.Center,
					autoUpdateLang: true,
					shadowAlpha: 0.7,
					shadowOffsetX: 5,
					shadowOffsetY: 5,
					wordWarp: true,
				},
				labelAlign: AnTextAlign.Center,
				anchor: AnAnchor.Center,
				resizeStrategy: () =>
				{
					this.title.scaledWidth = Math.min(AnViewport.width, AnViewport.height) * 0.9;
					//this.title.scaledHeight = scaled(300);
					this.title.applyDefaultResizeStrategy();
					this.title.position.set(AnViewport.halfWidth, AnViewport.halfHeight - scaled(200));
				}
			})
		);

		// Создаем кнопку подтверждения
		if (this.confirmText)
		{
			this.buttonConfirm = this.addUIElement("buttonConfirm",
				new AnButton({
					sprite: {
						atlas: 'atlases/game.ss.pixi.atlas',
						sprite: './button',
						slice9: {
							left: 20, right: 20, top: 20, bottom: 20
						}
					},
					labelText: {
						text: {
							textSource: this.confirmText,
							fontName: "mainFont",
							fontSize: 70,
							textAlign: AnTextAlign.Center,
							color: 0x333333,
						},
						labelAlign: AnTextAlign.Center,
						anchor: AnAnchor.Center,
					},
					//labelTextOffset: { x: 0, y: -3 },
					padding: 5,
					anchor: AnAnchor.Center,
					controlsRouter: this.controlsRouter,
					resizeStrategy: () =>
					{
						this.buttonConfirm.scaledHeight = scaled(90);
						this.buttonConfirm.scaledWidth = scaled(300);
						this.buttonConfirm.applyDefaultResizeStrategy();
						this.buttonConfirm.position.set(
							AnViewport.halfWidth - this.buttonConfirm.scaledWidth * 0.625,
							AnViewport.halfHeight + scaled(200)
						);
					},
					callbacks: {
						onClick: () => this.onConfirm()
					}
				})
			);

			if (this.forceWait)
			{
				this.buttonConfirm.enabled = false;
				this.startForceWaitCounter(3);
			}
		}

		// Создаем кнопку отмены
		if (this.cancelText)
		{
			this.buttonCancel = this.addUIElement("buttonCancel",
				new AnButton({
					sprite: {
						atlas: 'atlases/game.ss.pixi.atlas',
						sprite: './button',
						slice9: {
							left: 20, right: 20, top: 20, bottom: 20
						}
					},
					labelText: {
						text: {
							textSource: this.cancelText,
							fontName: "mainFont",
							fontSize: 70,
							textAlign: AnTextAlign.Center,
							color: 0x333333,
						},
						labelAlign: AnTextAlign.Center,
						anchor: AnAnchor.Center,
					},
					padding: 5,
					anchor: AnAnchor.Center,
					controlsRouter: this.controlsRouter,
					resizeStrategy: () =>
					{
						this.buttonCancel.scaledHeight = scaled(90);
						this.buttonCancel.scaledWidth = scaled(300);
						this.buttonCancel.applyDefaultResizeStrategy();
						this.buttonCancel.position.set(
							AnViewport.halfWidth + this.buttonCancel.scaledWidth * 0.625,
							AnViewport.halfHeight + scaled(200)
						);
					},
					callbacks: {
						onClick: () => this.onCancel()
					}
				})
			);
		}
	}
	startForceWaitCounter(sec: number)
	{
		if (sec < 0)
		{
			this.buttonConfirm.enabled = true;
			this.buttonConfirm.setText(this.confirmText!);
			return;
		}

		this.buttonConfirm.setText(() => AnLang.get(this.confirmText!) + ` (${sec})`);

		runAfterSafe(1, this.buttonConfirm, () => this.startForceWaitCounter(sec - 1));
	}

	private onConfirm(): void
	{
		this.callbacks.onConfirm?.();
		this.hide();
	}

	private onCancel(): void
	{
		this.callbacks.onCancel?.();
		this.hide();
	}

	protected createEntranceTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		// Анимация появления фона
		tweens.push(new AnTween({
			target: this.background,
			from: { alpha: 0 },
			to: { alpha: 0.95 },
			duration: 0.5,
			easing: AnEase.easeOut,
		}));

		// Анимация появления заголовка
		tweens.push(new AnTween({
			target: this.title,
			from: { alpha: 0, position: { x: this.title.x, y: this.title.y - scaled(50) } },
			to: { alpha: 1, position: { x: this.title.x, y: this.title.y } },
			delay: 0.2,
			duration: 1,
			easing: AnEase.easeOutBack,
		}));

		// Анимация появления кнопки подтверждения
		tweens.push(new AnTween({
			target: this.buttonConfirm,
			from: { alpha: 0, position: { x: this.buttonConfirm.x - scaled(100), y: this.buttonConfirm.y } },
			to: { alpha: 1, position: { x: this.buttonConfirm.x, y: this.buttonConfirm.y } },
			delay: 0.4,
			duration: 1,
			easing: AnEase.easeOutBack,
		}));

		// Анимация появления кнопки отмены
		tweens.push(new AnTween({
			target: this.buttonCancel,
			from: { alpha: 0, position: { x: this.buttonCancel.x + scaled(100), y: this.buttonCancel.y } },
			to: { alpha: 1, position: { x: this.buttonCancel.x, y: this.buttonCancel.y } },
			delay: 0.5,
			duration: 1,
			easing: AnEase.easeOutBack,
		}));

		return tweens;
	}

	protected createExitTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		// Анимация исчезания заголовка
		tweens.push(new AnTween({
			target: this.title,
			to: { alpha: 0, position: { x: this.title.x, y: this.title.y - scaled(50) } },
			from: { alpha: 1, position: { x: this.title.x, y: this.title.y } },
			duration: 0.5,
			easing: AnEase.easeIn,
		}));

		// Анимация исчезания кнопки подтверждения
		tweens.push(new AnTween({
			target: this.buttonConfirm,
			to: { alpha: 0, position: { x: this.buttonConfirm.x - scaled(100), y: this.buttonConfirm.y } },
			from: { alpha: 1, position: { x: this.buttonConfirm.x, y: this.buttonConfirm.y } },
			duration: 0.5,
			easing: AnEase.easeIn,
		}));

		// Анимация исчезания кнопки отмены
		tweens.push(new AnTween({
			target: this.buttonCancel,
			to: { alpha: 0, position: { x: this.buttonCancel.x + scaled(100), y: this.buttonCancel.y } },
			from: { alpha: 1, position: { x: this.buttonCancel.x, y: this.buttonCancel.y } },
			duration: 0.5,
			easing: AnEase.easeIn,
		}));

		// Анимация исчезания фона
		tweens.push(new AnTween({
			target: this.background,
			to: { alpha: 0 },
			from: { alpha: 0.95 },
			delay: 0.3,
			duration: 0.5,
			easing: AnEase.easeIn,
			tags: ["terminate"],
			// callbacks: {
			// 	onComplete: () => this.terminate()
			// }
		}));

		return tweens;
	}
}