import { AnLog } from "angine/utils/AnLog.js";

/**
 * Интерфейс данных, отправляемых в статистику
 */
export interface LevelStatsData
{
	levelNum: number;
	timeToComplete: number;
	moves: number;
	specialUsed: number;
}

/**
 * Ответ от сервера
 */
export interface DevStatsResponse
{
	status?: 'success';
	error?: string;
}

/**
 * Класс для отправки игровой статистики на сервер
 */
export class DevStatsAPI
{
	private static readonly endpoint: string = "https://olegantipov.com/utils/devstats/save_data.php";

	/**
	 * Создаёт новый экземпляр API
	 */
	constructor()
	{
	}

	/**
	 * Отправляет данные уровня на сервер
	 * @param data Объект с данными уровня
	 * @returns Promise<boolean> true — успех, false — ошибка
	 */
	async sendLevelStats(data: LevelStatsData): Promise<boolean>
	{
		try
		{
			const response = await fetch(DevStatsAPI.endpoint, {
				method: 'POST',
				body: JSON.stringify(data), // ← Отправляем как JSON
				headers: {
					'Content-Type': 'application/json',
				},
			});

			if (!response.ok)
			{
				AnLog.error(`HTTP error! Status: ${response.status}`);
				return false;
			}

			const result: DevStatsResponse = await response.json();

			if (result.status === 'success')
			{
				if (AnConfig.devMode) AnLog.debug(`DevStats: данные успешно отправлены!`);
				return true;
			} else
			{
				AnLog.error(`Server error: ${result.error}`);
				return false;
			}
		} catch (error)
		{
			AnLog.error(`Network or fetch error: ${error}`);
			return false;
		}
	}
}