/**
 * Класс, содержащий функции плавности (easing) для анимаций.
 * Все функции принимают значение прогресса от 0 до 1 и возвращают
 * преобразованное значение, обычно тоже в диапазоне 0-1.
 */
export class AnEase
{
	/**
	 * Линейная интерполяция без плавности
	 * @param t Прогресс анимации (0-1)
	 */
	public static linear(t: number): number { return t; }

	/**
	 * Плавное ускорение в начале
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeIn(t: number): number { return t * t; }

	/**
	 * Плавное замедление в конце
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeOut(t: number): number { return t * (2 - t); }

	/**
	 * Ускорение в начале и замедление в конце
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeInOut(t: number): number
	{
		return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
	}

	/**
	 * Замедление в начале и ускорение в конце
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeOutIn(t: number): number
	{
		return t < 0.5
			? 0.5 * (1 - AnEase.easeOut(1 - 2 * t))
			: 0.5 * AnEase.easeIn(2 * t - 1) + 0.5;
	}

	/**
	 * Эффект "отката" в начале анимации
	 * @param t Прогресс анимации (0-1)
	 * @param s Величина отката (по умолчанию 1.70158)
	 */
	public static easeInBack(t: number, s: number = 1.70158): number
	{
		return t * t * ((s + 1) * t - s);
	}

	/**
	 * Эффект "отката" в конце анимации
	 * @param t Прогресс анимации (0-1)
	 * @param s Величина отката (по умолчанию 1.70158)
	 */
	public static easeOutBack(t: number, s: number = 1.70158): number
	{
		return 1 + (--t) * t * ((s + 1) * t + s);
	}

	/**
	 * Эффект "отката" в начале и конце анимации
	 * @param t Прогресс анимации (0-1)
	 * @param s Величина отката (по умолчанию 1.70158)
	 */
	public static easeInOutBack(t: number, s: number = 1.70158): number
	{
		return (t *= 2) < 1
			? 0.5 * (t * t * (((s *= 1.525) + 1) * t - s))
			: 0.5 * ((t -= 2) * t * (((s *= 1.525) + 1) * t + s) + 2);
	}

	/**
	 * Эффект "отката" в конце и начале анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeOutInBack(t: number): number
	{
		return t < 0.5
			? AnEase.easeOutBack(t * 2) / 2
			: AnEase.easeInBack(2 * t - 1) / 2 + 0.5;
	}

	/**
	 * Эффект "пружины" в начале анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeInElastic(t: number): number
	{
		if (t === 0 || t === 1) return t;
		return -Math.pow(2, 10 * (t - 1)) * Math.sin((t - 1.075) * (2 * Math.PI) / 0.3);
	}

	/**
	 * Эффект "пружины" в конце анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeOutElastic(t: number): number
	{
		if (t === 0 || t === 1) return t;
		return Math.pow(2, -10 * t) * Math.sin((t - 0.075) * (2 * Math.PI) / 0.3) + 1;
	}

	/**
	 * Эффект "пружины" в начале и конце анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeInOutElastic(t: number): number
	{
		return t < 0.5
			? 0.5 * AnEase.easeInElastic(2 * t)
			: 0.5 * AnEase.easeOutElastic(2 * t - 1) + 0.5;
	}

	/**
	 * Эффект "пружины" в конце и начале анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeOutInElastic(t: number): number
	{
		return t < 0.5
			? AnEase.easeOutElastic(2 * t) / 2
			: AnEase.easeInElastic(2 * t - 1) / 2 + 0.5;
	}

	/**
	 * Эффект "отскока" в начале анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeInBounce(t: number): number
	{
		return 1 - AnEase.easeOutBounce(1 - t);
	}

	/**
	 * Эффект "отскока" в конце анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeOutBounce(t: number): number
	{
		if (t < 1 / 2.75) return 7.5625 * t * t;
		if (t < 2 / 2.75) return 7.5625 * (t -= 1.5 / 2.75) * t + 0.75;
		if (t < 2.5 / 2.75) return 7.5625 * (t -= 2.25 / 2.75) * t + 0.9375;
		return 7.5625 * (t -= 2.625 / 2.75) * t + 0.984375;
	}

	/**
	 * Эффект "отскока" в начале и конце анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeInOutBounce(t: number): number
	{
		return t < 0.5
			? AnEase.easeInBounce(2 * t) / 2
			: AnEase.easeOutBounce(2 * t - 1) / 2 + 0.5;
	}

	/**
	 * Эффект "отскока" в конце и начале анимации
	 * @param t Прогресс анимации (0-1)
	 */
	public static easeOutInBounce(t: number): number
	{
		return t < 0.5
			? AnEase.easeOutBounce(2 * t) / 2
			: AnEase.easeInBounce(2 * t - 1) / 2 + 0.5;
	}
}
