// src/audio/AnSound.ts
import { Howl } from 'angine/singleton';
import { AnLog } from "angine/utils/AnLog";
import { AnAssets } from "angine/assets/AnAssets";
import { AnEvent, AnEvents } from 'angine/utils/AnEvents';

/**
 * Конфигурация звуковой подсистемы
 * @property maxInstances - Макс. одновременных воспроизведений для каждого звука
 * @property baseVolume - Базовая громкость (0-1)
 * @property enabled - Глобальное включение звуков
 */
type AnSoundsConfig = {
	maxInstances?: number;
	soundVolume?: number;
	enabled?: boolean;
};

export class AnSounds
{
	private static _instanceCounter: Map<string, number> = new Map();
	private static _maxInstances: number;
	private static _soundVolume: number;
	private static _enabled: boolean;

	/**
	 * Инициализирует звуковую подсистему
	 */
	static init(config?: AnSoundsConfig)
	{
		this._soundVolume = config?.soundVolume ?? 100;
		this._enabled = config?.enabled ?? true;
		this._maxInstances = config?.maxInstances ?? 5;

		AnEvents.on("storage:soundVolume:update", (e: AnEvent) => this.volume = e.data.value);
	}

	/**
	 * Воспроизводит звуковой эффект
	 * @param name - Ключ ресурса в AnAssets
	 * @param volumeMultipler - Множитель громкости (0-1)
	 * @param panning - Панорамирование (-1 слева, 1 справа)
	 */
	static play(name: string, volumeMultipler: number = 1.0, panning?: number, rate?: number): void
	{
		if (!this._enabled) return;

		const count = this._instanceCounter.get(name) || 0;
		if (count >= this._maxInstances)
		{
			//if (AnConfig.devMode) AnLog.debug(`Максимум количества звуков: ${this._maxInstances} для ${name}`);
			return;
		}

		const sound = AnAssets.get<Howl>(name);
		if (sound)
		{
			this._instanceCounter.set(name, count + 1);

			sound.volume(this._soundVolume / 100 * volumeMultipler);
			if (panning !== undefined) sound.stereo(panning);
			if (rate !== undefined) sound.rate(rate);

			sound.play();

			sound.once('end', () =>
			{
				let count = this._instanceCounter.get(name) ?? 0;
				if (count <= 1)
					this._instanceCounter.delete(name);
				else
					this._instanceCounter.set(name, count - 1);

			});
		}
	}

	static set volume(value: number)
	{
		this._soundVolume = Math.min(100, Math.max(0, value));
	}

	static get volume(): number
	{
		return this._soundVolume;
	}

	static set enabled(value: boolean)
	{
		this._enabled = value;
	}

	static get enabled()
	{
		return this._enabled;
	}
}