import { AnImage, AnImageConfig } from "angine/ui/AnImage";
import { AnTween, AnTweenConfig } from "angine/anim/AnTween";
import { enhance, safeDestroy } from "angine/utils/AnHelpers";
import { AnUpdatableConfig, AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";
import { AnUpdater } from "angine/utils/AnUpdater";
import { AnLog } from "angine/utils/AnLog";

export interface AnFXConfig extends AnImageConfig, AnUpdatableConfig
{
	/** Твин для анимации появления (начала) */
	entranceTween?: AnTweenConfig;
	/** Твин для анимации продолжения (цикла) */
	loopTween?: AnTweenConfig;
	/** Твин для анимации завершения (выхода) */
	exitTween?: AnTweenConfig;
	/** Автоматический запуск анимации при создании объекта (по умолчанию true) */
	autoPlay?: boolean;

	autoTerminate?: boolean;
}

/**
 * Класс для создания эффектов с последовательной анимацией
 * Наследуется от AnImage и позволяет задавать три этапа анимации:
 * 1. entranceTween - анимация появления
 * 2. loopTween - анимация продолжения (цикла)
 * 3. exitTween - анимация завершения
 * 
 * Если какой-либо твин не задан, соответствующий этап анимации пропускается
 * После завершения всех анимаций объект автоматически терминируется
 */
export class AnFX extends AnImage
{
	private entranceTweenConfig: AnTweenConfig | null = null;
	private loopTweenConfig: AnTweenConfig | null = null;
	private exitTweenConfig: AnTweenConfig | null = null;
	private currentTween: AnTween | null = null;
	private isPlaying: boolean = false;
	private autoTerminate: boolean = false;

	private updater: AnUpdater | null = null;

	constructor(config: AnFXConfig)
	{
		super(config);

		if (config.updater) this.updater = config.updater;

		this.autoTerminate = config.autoTerminate ?? true;

		// Сохраняем твины из конфига
		if (config.entranceTween)
			this.entranceTweenConfig = config.entranceTween;
		if (config.loopTween)
			this.loopTweenConfig = config.loopTween;

		if (config.exitTween)
			this.exitTweenConfig = config.exitTween;

		// Регистрируем функцию очистки в системе управления ресурсами
		this.addToCleanup(() => this.cleanupTween());

		// Автоматический запуск анимации, если не отключено
		if (config.autoPlay !== false)
		{
			this.play();
		}
	}

	/**
	 * Запускает последовательность анимаций
	 */
	public play(): void
	{
		if (this.isPlaying) return;
		this.isPlaying = true;

		// Начинаем с анимации входа
		this.playEntrance();
	}

	/**
	 * Запускает анимацию появления
	 */
	private playEntrance(): void
	{
		// Если твин появления не задан, переходим к следующему этапу
		if (!this.entranceTweenConfig)
		{
			this.playLoop();
			return;
		}

		this.cleanupTween();

		this.currentTween = new AnTween({
			...this.entranceTweenConfig,
			target: this,
			updater: this.updater,
			callbacks: {
				...this.entranceTweenConfig.callbacks,
				// Настройка коллбека для перехода к следующей анимации
				onComplete: () =>
				{
					this.entranceTweenConfig?.callbacks?.onComplete?.(this.currentTween!);
					this.playLoop();
				}
			}
		});
	}

	/**
	 * Запускает цикличную анимацию
	 */
	private playLoop(): void
	{
		// Если цикличная анимация не задана, переходим к анимации выхода
		if (!this.loopTweenConfig)
		{
			this.playExit();
			return;
		}

		this.cleanupTween();

		this.currentTween = new AnTween({
			...this.loopTweenConfig,
			target: this,
			updater: this.updater,
			callbacks: {
				...this.loopTweenConfig.callbacks,
				// Настройка коллбека для перехода к следующей анимации
				onComplete: () =>
				{
					this.loopTweenConfig?.callbacks?.onComplete?.(this.currentTween!);
					this.playExit();
				}
			}
		});
	}

	/**
	 * Запускает анимацию завершения
	 */
	private playExit(): void
	{
		// Если анимация выхода не задана, завершаем последовательность
		if (!this.exitTweenConfig)
		{
			this.finish();
			return;
		}

		this.cleanupTween();

		this.currentTween = new AnTween({
			...this.exitTweenConfig,
			target: this,
			updater: this.updater,
			callbacks: {
				...this.exitTweenConfig.callbacks,
				// Настройка коллбека для перехода к следующей анимации
				onComplete: () =>
				{
					this.exitTweenConfig?.callbacks?.onComplete?.(this.currentTween!);
					this.finish();
				}
			}
		});
	}

	/**
	 * Завершает анимацию и инициирует очистку ресурсов
	 */
	private finish(): void
	{
		this.isPlaying = false;

		if (this.autoTerminate)
			this.terminate();
	}

	/**
	 * Очищает твин
	 */
	private cleanupTween(): void
	{
		// Очищаем твин, если он существует
		if (this.currentTween)
		{
			this.currentTween.terminate();
			this.currentTween = null;
		}
	}
}