	constructor(config: MenuSystemConfig)
	{
		super(config);

		this.callbacks = config.callbacks ?? {};


		this.addToCleanup(AnEvents.on("ui:menuResult:started", () => this.hide()).unsub);
	}

	public start()
	{
		this.createUI();
		this.resizeUI();

		// Настройка обработчиков скролла
		this.setupScrollHandlers();

		this.show();

		// сообщаем платформе что приостановили игру
		Platform.sdk?.reportEvent(PlatformEvent.GameplayStop);
	}

