	private onMoreGamesButtonClick(): void
	{
		if (G.moreGamesURL.length > 0)
		{
			Analytics.onEvent("MoreGamesButtonClick");
			openURL(G.moreGamesURL);
		}
	}


	// подбираем нужный вариант иконки для настроек
	//! внимание, говнокод
	private getOptButtonIconVar(opt: string)
	{
		let vol = 0;
		switch (opt)
		{
			case "optLang":
				if (GameApp.self.gameData.language === "ru") return "09";
				return "10"; // en
			//break;
			case "optSound":
				vol = GameApp.self.gameData.soundVolume;
				if (AnMath.floatEqual(vol, 0)) return "05"; else
					if (AnMath.floatEqual(vol, 30)) return "06"; else
						if (AnMath.floatEqual(vol, 60)) return "07";
				return "08";
			//break;
			case "optMusic":
				vol = GameApp.self.gameData.musicVolume;
				if (AnMath.floatEqual(vol, 0)) return "01"; else
					if (AnMath.floatEqual(vol, 30)) return "02"; else
						if (AnMath.floatEqual(vol, 60)) return "03";
				return "04";
			//break;
		}
		return "11";
	}

	private lastTip: UITip | null = null;
	public showTip(text: string, color: number = 0xffffff, appearDelay: number = 0, stayDelay: number = 0)
	{
		const pos = {
			x: AnViewport.halfWidth,
			y: scaled(100)
		};

		if (this.lastTip)
			this.terminateUIElement(this.lastTip);

		const fontSize = 40;
		const lenFactor = text.length * scaled(fontSize);
		const tip = this.addUIElement(new UITip({
			updater: this.getUpdater(),
			appearDelay,
			stayDelay,
			backgroundAlpha: 1,
			background: {
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './greySpot2',
			},
			labelText: {
				text: {
					textSource: text,
					autoUpdateLang: false,

					fontName: "mainFont",
					fontSize: 90,
					textAlign: AnTextAlign.Center,
					shadowAlpha: 0.7,
					shadowOffsetX: 4,
					shadowOffsetY: 4,
					color,

				},
				labelAlign: AnTextAlign.Center,
			},
			anchor: AnAnchor.Center,
			resizeStrategy: () =>
			{
				const scaledFactor = 1.75;
				tip.scaledWidth = lenFactor * scaledFactor;
				tip.scaledHeight = scaled(fontSize * 2) * scaledFactor;
				tip.applyDefaultResizeStrategy();

				// Расчёт offset для удержания внутри вьюпорта
				const halfWidth = tip.scaledWidth / 2;
				const halfHeight = tip.scaledHeight / 2;

				const minX = halfWidth;
				const maxX = AnViewport.width - halfWidth;
				const minY = halfHeight;
				const maxY = AnViewport.height - halfHeight;

				const clampedX = Math.max(minX, Math.min(maxX, pos.x));
				const clampedY = Math.max(minY, Math.min(maxY, pos.y));

				const offset = {
					x: clampedX - pos.x,
					y: clampedY - pos.y
				};

				tip.position.set(pos.x + offset.x, pos.y + offset.y);
			},
			callbacks: {
				onComplete: () =>
				{
					this.terminateUIElement(tip);
					this.lastTip = null;
				}
			}
		}));
		this.lastTip = tip;
		tip.applyResizeStrategy();
		tip.startAnimation();

		//this.attach(tip);
	}

	private onOptButtonClick(buttonId: string): void
	{
		const gameData = GameApp.self.gameData;


		// <text id="OptLangEN" > ENGLISH </text>
		// < text id = "OptLangRU" > RUSSIAN </text>
		// < text id = "OptSound" > Sound </text>
		// < text id = "OptSoundNo" > Mute sound </text>
		// < text id = "OptMusic" > Music </text>
		// < text id = "OptMusicNo" > Mute music </text>
		//const OptionButtons = ["optLang", "optSound", "optMusic", "optReset"];
		switch (buttonId)
		{
			case "optLang":
				gameData.language = getNextElement(AnLang.loadedLanguages, AnLang.currentLanguage);
				if (AnConfig.devMode) AnLog.debug(`language: ${gameData.language}`);
				this.showTip(AnLang.get(`OptLang${gameData.language.toUpperCase()}`));
				break;
			case "optSound":
				gameData.soundVolume =
					AnMath.floatEqual(gameData.soundVolume, 0) ? 30 :
						(AnMath.floatEqual(gameData.soundVolume, 30) ? 60 :
							(AnMath.floatEqual(gameData.soundVolume, 60) ? 100 : 0));

				AnSounds.play(
					`sounds/stone.snd.mp3`,
					0.6
				);
				if (AnConfig.devMode) AnLog.debug(`soundVolume: ${gameData.soundVolume}`);

				{
					const textID = gameData.soundVolume !== 0 ? `OptSound` : `OptSoundNo`;
					const textAppend = gameData.soundVolume !== 0 ? `: ${gameData.soundVolume}%` : ``;
					this.showTip(AnLang.get(textID) + textAppend);
				}
				break;
			case "optMusic":
				gameData.musicVolume =
					AnMath.floatEqual(gameData.musicVolume, 0) ? 30 :
						(AnMath.floatEqual(gameData.musicVolume, 30) ? 60 :
							(AnMath.floatEqual(gameData.musicVolume, 60) ? 100 : 0));
				if (AnConfig.devMode) AnLog.debug(`musicVolume: ${gameData.musicVolume}`);

				{
					const textID = gameData.musicVolume !== 0 ? `OptMusic` : `OptMusicNo`;
					const textAppend = gameData.musicVolume !== 0 ? `: ${gameData.musicVolume}%` : ``;
					this.showTip(AnLang.get(textID) + textAppend);
				}
				break;
			case "optReset":
				AnSounds.play(
					`sounds/buy_no.snd.mp3`,
					0.4,
				);
				AnSounds.play(
					`sounds/lose.snd.mp3`,
					0.4,
				);


				const confirmMenu = new MenuConfirm({
					text: "OptResetAllWarn",
					confirmText: "confirmReset",
					cancelText: "cancelReset",
					forceWait: true,
					callbacks: {
						onConfirm: () =>
						{
							this.hide();
							// Полный сброс и перезапуск
							GameApp.self.fullReset();
						},
						onCancel: () =>
						{
							// Действия при отмене
						}
					}
				});
				confirmMenu.start();
				break;
		}
	}

	private onItemButtonClick(type: 'theme' | 'color', index: number): void
	{
		const gameData = GameApp.self.gameData;

		// Определяем конфигурацию в зависимости от типа
		const config = {
			theme: {
				lastUnlocked: gameData.lastUnlockedTheme,
				setCurrent: (value: any) =>
				{
					gameData.theme = value;
					this.titleTheme.updateText();
				},
				array: gameThemesArray,
				calcCost: G.calcThemeCostByID,
				updateUnlocked: (value: number) => gameData.lastUnlockedTheme = value,
			},
			color: {
				lastUnlocked: gameData.lastUnlockedColor,
				setCurrent: (value: any) =>
				{
					gameData.color = value;
					this.titleColor.updateText();
				},
				array: gameColorsArray,
				calcCost: G.calcColorCostByID,
				updateUnlocked: (value: number) => gameData.lastUnlockedColor = value,
			}
		}[type];

		// Получаем соответствующие данные из конфигурации
		const { lastUnlocked, setCurrent, array, calcCost, updateUnlocked } = config;

		if (index <= lastUnlocked)
		{
			// unlocked
			setCurrent(array[index]);
			this.applyResizeStrategy();
			this.syncScroll();
		}
		else
		{
			if (index === lastUnlocked + 1)
			{
				// item to buy
				const cost = calcCost(index);
				if (cost <= gameData.coins)
				{
					AnSounds.play(
						`sounds/buy.snd.mp3`,
						0.6,
					);

					Analytics.onLostResource('coins', cost, type, index.toString());

					updateUnlocked(lastUnlocked + 1);
					gameData.coins -= cost;
					setCurrent(array[index]);
					this.applyResizeStrategy();
					this.syncScroll();
				}
				else
				{
					// can't buy this item
					AnSounds.play(
						`sounds/buy_no.snd.mp3`,
						0.6,
					);
				}
			} else
			{
				// locked
			}
		}
	}

