import { AnTextAlign, AnTextSource } from "angine/2D/AnText.js";
import { AnTween } from "angine/anim/AnTween.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnImage } from "angine/ui/AnImage.js";
import { AnDialogue } from 'angine/ui/AnDialogue.js';
import { AnVoidCallback, enhance, runAfterSafe } from "angine/utils/AnHelpers.js";
import { AnEase } from "angine/anim/AnEase.js";
import { AnUIGroupElement, AnUIGroupElementConfig } from "angine/ui/AnUIGroupElement.js";
import { AnUpdatableConfig, AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin.js";
import { AnMath } from "angine/utils/AnMath.js";
import { AnRnd } from "angine/utils/AnRnd.js";
import { AnSounds } from "angine/audio/AnSounds.js";
import { AnLog } from "angine/utils/AnLog.js";


export interface UIDialogueCallbacks 
{
	onComplete?: AnVoidCallback;
}

export interface UIDialogueConfig extends AnUIGroupElementConfig, AnUpdatableConfig
{
	fontSize?: number;
	baseRealWidth?: number;
	bgScale9Adopt?: number;
	useBackground?: boolean;
	callbacks?: UIDialogueCallbacks;
}

export class UIDialogue
	extends enhance(AnUIGroupElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{
	private callbacks: UIDialogueCallbacks;
	private background: AnImage | null = null;
	private dialogue: AnDialogue;

	public constructor(config: UIDialogueConfig)
	{
		super(config);

		this.callbacks = config.callbacks ?? {};

		const useBackground = config.useBackground ?? true;

		// Создаем фоновое изображение
		if (useBackground)
		{
			this.background = this.addUIElement(
				"background",
				new AnImage({
					anchor: AnAnchor.Center,
					//tint: 0x333333,
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './gradEdges',
					slice9: {
						left: 32,
						right: 32,
						top: 32,
						bottom: 32,
					}
				}));
			this.background.scale9Adopt = config.bgScale9Adopt ?? 1;
		}

		// const filters: PIXI.Filter[] = [];
		// const backblurFilter = new BackdropBlurFilter();
		// backblurFilter.strength = 5;
		// backblurFilter.quality = 2;
		// filters.push(backblurFilter);

		// const blurFilter = new KawaseBlurFilter();
		// blurFilter.strength = 3;
		// blurFilter.quality = 2;
		// filters.push(blurFilter);

		// this.background.filters = filters;

		// Создаем диалог
		this.dialogue = this.addUIElement(
			"dialogue",
			new AnDialogue({
				text: {
					textSource: "...",
					fontName: "mainFont",
					fontSize: config.fontSize ?? 60,
					textAlign: AnTextAlign.Center,
					autoUpdateLang: true,
					shadowAlpha: 0.6,
					shadowOffsetX: 3,
					shadowOffsetY: 3,
				},
				anchor: AnAnchor.Center,
				speedFactor: 0.4,
				baseRealWidth: config.baseRealWidth ?? 1200,
			}));


		// +++ resize strategy +++
		this.defaultResizeStrategy =
			() =>
			{
				this.background?.setScaledSize(this.scaledWidth, this.scaledHeight);
				const fitRect = AnMath.fitRectangleToRectangle(this.scaledWidth, this.scaledHeight, this.dialogue.realWidth, this.dialogue.realHeight);
				this.dialogue.setScaledSize(fitRect.width * 0.9, fitRect.height * 0.9);

				this.background?.applyDefaultResizeStrategy();
				this.dialogue.applyDefaultResizeStrategy();

				this.background?.position.set(this.scaledWidth * 0.5, this.scaledHeight * 0.5);
				this.dialogue.position.set(this.scaledWidth * 0.5, this.scaledHeight * 0.5);
			};

		this.configResizeStrategy(config.resizeStrategy);

	}

	public showText(textSource: AnTextSource)
	{
		this.dialogue.textSource = textSource;

		// нужно обновить размеры
		this.applyResizeStrategy();

		if (!this.visible)
		{
			this.visible = true;
			if (this.background)
			{
				new AnTween({
					target: this.background,
					from: { scale: { x: 0.1, y: 1 }, alpha: 0 },
					to: { scale: { x: 1, y: 1 }, alpha: 0.95 },
					duration: 1,
					easing: AnEase.easeOut,
					updater: this.getUpdater(),
					autoRemove: true,
					callbacks: {
						onComplete: () => { }
					}
				});
			}
		}

		if (!this.dialogue.getUpdater())
			this.dialogue.addToUpdater(this.getUpdater()!);



		runAfterSafe(0.8, this, () => this.dialogue!.startAnimation(undefined, () =>
		{
			AnSounds.play(
				`sounds/type0${AnRnd.int(1, 6)}.snd.mp3`,
				AnRnd.float(0.4, 0.6),
				0,
				AnRnd.float(0.9, 1.1)
			);
		}));
	}

	public calculateDisplayTime(): number
	{
		return this.dialogue!.calculateDisplayTime();
	}

	public hideText(onComplete?: AnVoidCallback)
	{

		if (this.visible)
		{
			if (this.background)
			{
				new AnTween({
					target: this.background,
					to: { scale: { x: 0.1, y: 1 }, alpha: 0 },
					from: { scale: { x: 1, y: 1 }, alpha: 0.95 },
					duration: 1,
					delay: this.dialogue!.labelsCount * 0.1 * 0.3,
					easing: AnEase.easeOut,
					updater: this.getUpdater(),
					autoRemove: true,
					callbacks: {
						onComplete: () => { this.visible = false; onComplete?.(); }
					}
				});
			}
		}

		runAfterSafe(0.1, this, () => this.dialogue!.exitAnimation());
	}
}