// src/2D/AnText.ts
import { AnAssets } from "angine/assets/AnAssets";
import { AnViewport, scaled } from "angine/core/AnViewport";
import { PIXI } from "angine/singleton";
import { AnAnchor } from "angine/ui/AnAnchor";
import { AnEvents } from "angine/utils/AnEvents";
import { AnLang } from "angine/utils/AnLang";
import { AnLog } from "angine/utils/AnLog";

export enum AnTextAlign
{
    Left = "left",
    Center = "center",
    Right = "right"
}

export interface AnTextStyleConfig
{
    fontName?: string;
    fontSize?: number;
    textAlign?: AnTextAlign;
    color?: number;
};

export type AnTextSource = string | (() => string);

export interface AnTextConfig extends AnTextStyleConfig
{
    textSource: AnTextSource,
    wordWarp?: boolean,
    anchor?: AnAnchor;
    autoUpdateLang?: boolean;
};

export class AnText extends PIXI.BitmapText
{
    private _textSource: AnTextSource;
    private _autoUpdateLang: boolean;

    private _fontSize: number; // не масштабируемый размер шрифтра
    //private _assetFontSize: number; // реальный размер шрифта в текстуре
    //private _baseLineOffset: number; // сдвиг относительно линии написания текста
    private font: PIXI.BitmapFont;
    private _textColor: number;

    private wordWarp: boolean;


    // text: string -> это ID из AnLang
    constructor(
        config: AnTextConfig,
    )
    {
        const fontName = config.fontName ?? "sysFont";
        const font = AnAssets.getFont(fontName);
        const textColor = config.color ?? 0xffffff;
        const wordWrap = config.wordWarp !== undefined;

        if (font === null)
        {
            AnLog.error(`Шрифт не установлен: ${fontName}`);
            throw `Установите шрифт ${fontName}`;
        }

        super(
            {
                text: "text",
                anchor: config.anchor ?? AnAnchor.TopLeft,
                style: {
                    wordWrap,
                    //wordWrapWidth: 100,
                    // maxWidth: config.maxWidthForWordWarp,
                    fontFamily: fontName,
                    fontSize: config.fontSize ?? font!.baseMeasurementFontSize,
                    align: config.textAlign ?? AnTextAlign.Left,
                    fill: textColor
                }
            });


        //this.style.letterSpacing = 25;
        this.wordWarp = wordWrap;
        this._textColor = textColor;
        this.font = font;
        this._fontSize = config.fontSize ?? font!.baseMeasurementFontSize;
        //this._assetFontSize = font!.baseMeasurementFontSize;
        //this._baseLineOffset = font!.baseLineOffset;

        this._textSource = config.textSource;
        this._autoUpdateLang = config.autoUpdateLang ?? true;
        this.setupEventHandlers();

        this.updateText();
    }

    public get textColor(): number
    {
        return this._textColor;
    }
    public set textColor(color: number)
    {
        this._textColor = color;
        this.style.fill = color;
    }


    public static textSourceResolver(textSource: AnTextSource, autoUpdateLang: boolean = false)
    {
        return typeof textSource === "function" ?
            textSource() :
            (autoUpdateLang ?
                AnLang.get(textSource) :
                textSource);
    }

    public resolveTextSource()
    {
        return AnText.textSourceResolver(this._textSource, this._autoUpdateLang);
    }

    public updateText()
    {
        this.text = this.resolveTextSource();
    }

    private setupEventHandlers(): void
    {
        if (this._autoUpdateLang)
        {
            const { unsub } = AnEvents.on("settings:changed:lang", () => this.updateText());

            // Автоматическая отписка при уничтожении
            this.on("destroyed", () => unsub());
        }
    }

    public get autoUpdateLang(): boolean
    {
        return this._autoUpdateLang;
    }

    public set textSource(value: AnTextSource)
    {
        this._textSource = value;
        this.updateText();
    }

    public calcOffsetY(): number
    {
        return this.fontSize * this.baseLineOffset / this.assetFontSize;
    }

    public get scaledFontSize(): number
    {
        return this.style.fontSize;
    }

    // public set scaledFontSize(size: number)
    // {
    //     this.style.fontSize = size;
    // }

    public get fontSize(): number
    {
        return this._fontSize;
    }

    public get assetFontSize(): number
    {
        return this.font.baseMeasurementFontSize;
    }

    public get baseLineOffset(): number
    {
        return this.font.baseLineOffset;
    }

    public applyResize(scaleFactor: number)
    {
        this.scale.set(scaleFactor);
    }

    public applyFontResize()
    {
        this.style.lineHeight = scaled(this.fontSize);
        this.style.fontSize = scaled(this.fontSize);
    }
}