import { AnImage } from "angine/ui/AnImage.js";

/**
 * Конфиг для компонента UIGoalProgress
 */
export interface UIRaysConfig extends AnUIGroupElementConfig
{
	raysCount?: number;
	raysScale?: number,
	rotateSpeed?: number;
}

export class UIRays
	extends enhance(AnUIGroupElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{

	private raysCount: number;
	private raysScale: number;
	private rotateSpeed: number;
	private galo: AnImage;
	private rays: AnImage[] = [];

	constructor(config: UIRaysConfig)
	{
		config.anchor = config.anchor ?? AnAnchor.Center;
		super(config); // Передаем конфиг в базовый класс

		this.raysCount = config.raysCount ?? 16;
		this.rotateSpeed = config.rotateSpeed ?? 0.1;
		this.raysScale = config.raysScale ?? 1;

		// Угол между лучами
		const angleStep = (Math.PI * 2) / this.raysCount;
		// Создаём и добавляем лучи
		for (let i = 0; i < this.raysCount; i++)
		{
			const ray = new AnImage(
				{
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './galoRay',
					anchor: AnAnchor.TopCenter,
				}
			);

			// Поворачиваем луч
			ray.rotation = i * angleStep;
			ray.scale.x = this.raysScale;

			ray.alpha = 0.1;

			// Дополнительно: можно сместить луч немного наружу
			// ray.y = -ray.height / 2; // если нужно, чтобы луч начинался из центра

			// Добавляем луч в контейнер
			this.addUIElement("ray" + i, ray);
			this.rays.push(ray);
		}


		this.galo = new AnImage(
			{
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './galoCircle',
				anchor: AnAnchor.Center,
			}
		);
		this.galo.alpha = 0.3;

		this.addUIElement(this.galo);

		// +++ resize strategy +++
		this.defaultResizeStrategy =
			() =>
			{
				this.setSize(this.scaledWidth, this.scaledHeight);

				const galoSize = this.rays[0].height * 0.7;
				this.galo.setSize(galoSize, galoSize);
			};

		this.configResizeStrategy(config.resizeStrategy);
	}


	public update(dt: number)
	{
		super.update(dt);

		// Поворачиваем весь контейнер лучей
		this.rotation += this.rotateSpeed * dt;
	}
} 