import { THREE } from 'angine/singleton';
import { AnViewport } from 'angine/core/AnViewport';


export class AnRender3D
{
	public static threeRender: THREE.WebGLRenderer;

	public static scene: THREE.Scene;
	public static camera: THREE.PerspectiveCamera;
	public static cube: THREE.Mesh;


	private constructor() { }


	public static init()
	{
		//TODO: проверка существования контекста и канваса

		AnRender3D.threeRender = new THREE.WebGLRenderer({
			canvas: AnViewport.canvas,
			context: AnViewport.glContext as WebGLRenderingContext,
			antialias: true,
			//alpha: true,
			//stencil: true,
		});

		// Сцена
		AnRender3D.scene = new THREE.Scene();
		AnRender3D.scene.background = new THREE.Color(0x222222);

		AnRender3D.camera = new THREE.PerspectiveCamera(75, AnViewport.aspectRatio, 0.1, 1000);
		AnRender3D.resize(AnViewport.physWidth, AnViewport.physHeight);

		AnRender3D.scene.add(this.camera);

		//////////
		AnRender3D.camera.position.z = 5;
		// Геометрия
		const geometry = new THREE.BoxGeometry();
		const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
		AnRender3D.cube = new THREE.Mesh(geometry, material);
		AnRender3D.scene.add(AnRender3D.cube);
	}

	public static terminate(): void
	{
		AnRender3D.threeRender.dispose();
	}

	public static resize(width: number, height: number): void
	{
		AnRender3D.threeRender.setSize(width, height);
		AnRender3D.camera.aspect = width / height;
		AnRender3D.camera.updateProjectionMatrix();
	}


	public static render(): void
	{
		AnRender3D.threeRender.resetState();
		AnRender3D.threeRender.render(this.scene, this.camera);
	}
}