import { Default, PIXI } from "angine/singleton";
import { AnUIElement, AnUIElementConfig, AnUIResizeStrategyFunc } from "angine/ui/AnUIElement";
import { AnAssets } from "angine/assets/AnAssets";
import { enhance, notImplemented, safeDestroyFunc, struct } from "angine/utils/AnHelpers";
import { AnViewport, scaled } from "angine/core/AnViewport";
import { AnUI } from "angine/ui/AnUI";
import { AnAnchor } from "./AnAnchor";
import { AnLog } from "angine/utils/AnLog";
import { AnBounds } from "angine/utils/AnMath";
import { AnUpdatableMixin, AnUpdatableInterface, AnUpdatableConfig } from "angine/mixins/AnUpdatableMixin";

export enum AnBorderType
{
	Solid = 'solid',
	Dashed = 'dashed',
}


export interface AnBorderConfig extends AnUIElementConfig, AnUpdatableConfig
{
	type?: AnBorderType,
	dashSize?: number,
	dashGap?: number,
	dashWidth?: number,
	dashSpeed?: number,
	dashAnimCW?: boolean; // анимация по часовой стрелке
	alpha?: number;
};

export class AnBorder
	extends enhance(AnUIElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{
	protected type: AnBorderType;

	protected dashSize: number;
	protected dashGap: number;
	protected dashWidth: number;
	protected dashSpeed: number;
	protected dashAnimCW: boolean;
	private dashCurrentOffset: number = 0;

	private graphics: PIXI.Graphics | null = null;


	constructor(config: AnBorderConfig)
	{
		super(config);

		this.type = config.type ?? AnBorderType.Dashed;
		this.dashSize = config.dashSize ?? 15;
		this.dashGap = config.dashGap ?? 8;
		this.dashWidth = config.dashWidth ?? 3;
		this.dashSpeed = config.dashSpeed ?? 10;
		this.dashAnimCW = config.dashAnimCW ?? true;

		if (this.type == AnBorderType.Dashed)
		{
			this.graphics = new PIXI.Graphics();
			this.addToCleanup(safeDestroyFunc(this.graphics));
			this.graphics.alpha = config.alpha ?? 1;
			this.addGraphics(this.graphics);

			// для отладки, добавляем ярлык для элемента (pixi devtools)
			if (AnConfig.devMode) this.graphics.label = "anim rect";
		}
		else
			notImplemented();

		// +++ resize strategy +++
		this.defaultResizeStrategy =
			() => // AnBorderType.Dashed
			{
				// this.graphics!.width = this._scaledWidth!;
				// this.graphics!.height = this._scaledHeight!;
				this.rebuldGraphics();
			};

		this.configResizeStrategy(config.resizeStrategy);
	}

	private drawDashedLine(x1: number, y1: number, x2: number, y2: number, dash: number, gap: number): void
	{
		if (!this.graphics) return;

		const dx = x2 - x1;
		const dy = y2 - y1;
		const dist = Math.sqrt(dx * dx + dy * dy);
		if (dist === 0) return;

		const normalX = dx / dist;
		const normalY = dy / dist;

		const patternLength = dash + gap;
		let position = 0;
		let isDrawing = true;

		// Вычисляем начальное состояние с учетом смещения
		let phase = this.dashCurrentOffset;
		while (phase >= patternLength)
		{
			phase -= patternLength;
		}

		if (phase < dash)
		{
			isDrawing = true;
			// Начинаем с частичного штриха
			const partialDash = dash - phase;
			const drawLength = Math.min(partialDash, dist);
			const endX = x1 + normalX * drawLength;
			const endY = y1 + normalY * drawLength;

			this.graphics.moveTo(x1, y1);
			this.graphics.lineTo(endX, endY);
			position = drawLength;
			isDrawing = false; // После штриха идет пробел
		} else
		{
			isDrawing = false;
			// Начинаем с частичного пробела
			const partialGap = patternLength - phase;
			const skipLength = Math.min(partialGap, dist);
			const endX = x1 + normalX * skipLength;
			const endY = y1 + normalY * skipLength;

			this.graphics.moveTo(endX, endY);
			position = skipLength;
			isDrawing = true; // После пробела идет штрих
		}

		// Продолжаем рисовать оставшуюся часть
		while (position < dist)
		{
			const segmentLength = isDrawing ? dash : gap;
			const remaining = dist - position;

			if (remaining <= 0) break;

			const drawLength = Math.min(segmentLength, remaining);
			const endX = x1 + normalX * (position + drawLength);
			const endY = y1 + normalY * (position + drawLength);

			if (isDrawing)
			{
				this.graphics.lineTo(endX, endY);
			} else
			{
				this.graphics.moveTo(endX, endY);
			}

			position += drawLength;
			isDrawing = !isDrawing;
		}
	}

	private rebuldGraphics(dt: number = 0)
	{
		if (!this.graphics || !this.visible) return;

		this.graphics.clear();

		if (this.type === AnBorderType.Dashed)
		{
			const dash = scaled(this.dashSize);
			const gap = scaled(this.dashGap);
			const patternLength = dash + gap;

			// Анимируем смещение 
			if (this.dashAnimCW)
			{
				this.dashCurrentOffset -= this.dashSpeed * dt;
				if (this.dashCurrentOffset < 0)
				{
					this.dashCurrentOffset += patternLength;
				}
			} else
			{
				this.dashCurrentOffset += this.dashSpeed * dt;
				if (this.dashCurrentOffset >= patternLength)
				{
					this.dashCurrentOffset -= patternLength;
				}
			}
			// this.dashCurrentOffset += this.dashSpeed * dt;
			// while (this.dashCurrentOffset >= patternLength)
			// {
			// 	this.dashCurrentOffset -= patternLength;
			// }

			// Рисуем четыре стороны с пунктиром
			this.drawDashedLine(0, 0, this.scaledWidth, 0, dash, gap); // Верх
			this.drawDashedLine(this.scaledWidth, 0, this.scaledWidth, this.scaledHeight, dash, gap); // Право
			this.drawDashedLine(this.scaledWidth, this.scaledHeight, 0, this.scaledHeight, dash, gap); // Низ
			this.drawDashedLine(0, this.scaledHeight, 0, 0, dash, gap); // Лево

			this.graphics.stroke({ color: 0xffffff, width: this.dashWidth });
		}
		else
			notImplemented();
	}

	public override update(dt: number)
	{
		super.update(dt);
		this.rebuldGraphics(dt);
	}
}