	// расчет ходов
	public static calculateTotalMoves(perfectMoves: number): number
	{
		// в режиме разработчика много ходов
		if (AnConfig.devMode && G.dev_totalMovesInfinity) return 999;

		return perfectMoves * G.totalMovesMultipler + G.totalMovesAddMore;
		//return AnMath.ceilToMultiple(perfectMoves * G.totalMovesMultipler[difficult] + G.totalMovesAddMore, 5);
	}

	// расчет идеальных ходов
	public static calculatePerfectMoves(totalMoves: number): number
	{
		if (AnConfig.devMode && G.dev_totalMovesInfinity)
		{
			return 999;
		}
		const adjustedTotalMoves = totalMoves - G.totalMovesAddMore;
		const multiplier = G.totalMovesMultipler;

		return Math.trunc(adjustedTotalMoves / multiplier);
		//return AnMath.floorToMultiple(adjustedTotalMoves / multiplier, 5);
	}


	// расчет звезд
	public static calculateStars(usedMoves: number, totalMoves: number): 0 | 1 | 2 | 3
	{
		if (G.zeroStarsForComplete && usedMoves === totalMoves) return 0;

		if (usedMoves <= totalMoves * G.threeStarsPerc) return 3;
		if (usedMoves <= totalMoves * G.twoStarsPerc) return 2;

		return 1;
	}

	// расчет прогресс бара (равные сегменты для равномерно расположенных звезд)
	public static calculateStarsProgressbar(usedMoves: number, totalMoves: number): number
	{
		if (G.zeroStarsForComplete && usedMoves === totalMoves) return 0;

		const threeStarsThreshold = totalMoves * G.threeStarsPerc;
		const twoStarsThreshold = totalMoves * G.twoStarsPerc;

		// Равные сегменты для равномерного расположения звезд:
		// ★☆☆ - 0.00-0.33
		// ★★☆ - 0.33-0.66  
		// ★★★ - 0.66-1.00

		// 3 звезды
		if (usedMoves <= threeStarsThreshold)
		{
			// Прогресс от 0.66 до 1.00 для 3 звезд
			const segmentProgress = (threeStarsThreshold - usedMoves) / threeStarsThreshold;
			return 0.66 + (segmentProgress * 0.34);
		}

		// 2 звезды
		if (usedMoves <= twoStarsThreshold)
		{
			// Прогресс от 0.33 до 0.66 для 2 звезд
			const segmentSize = twoStarsThreshold - threeStarsThreshold;
			const segmentProgress = 1 - (usedMoves - threeStarsThreshold) / segmentSize;
			return 0.33 + (segmentProgress * 0.33);
		}

		// 1 звезда
		if (usedMoves < totalMoves)
		{
			// Прогресс от 0.00 до 0.33 для 1 звезды
			const segmentSize = totalMoves - twoStarsThreshold;
			const segmentProgress = 1 - (usedMoves - twoStarsThreshold) / segmentSize;
			return segmentProgress * 0.33;
		}

		return 0;
	}

	// Геометрическая прогрессия с насыщением
	private static calculateLevelMultiplier(levelNumber: number): number
	{
		// Формула: multiplier = 1 + (1 - e^(-level/30)) × 2
		// Максимальный множитель: 3.0 (на бесконечности)
		// На уровне 100: ~2.8x
		const saturation = 1 - Math.exp(-levelNumber / 30);
		return 1 + saturation * 2;
	}

	// расчет награды за уровень
	static calculateCoinReward(levelNum: number, stars: number): number
	{
		const baseReward = G.coinRewardForStars[stars];
		const multiplier = G.calculateLevelMultiplier(levelNum);

		return AnMath.floorToMultiple(baseReward * multiplier, 5);
	}

	// расчитать награду для первых levels уровней
	private static calculateForLevels(levels: number, stars: number): number
	{
		let total = 0;
		for (let i = 1; i <= levels; i++)
		{
			total += G.calculateCoinReward(i, stars);
		}
		return total;
	}

	// расчитать минимальную и среднюю и максимальную награду за уровни
	public static evalTotalRewardForLevels(levels: number = 100): { min: number, avg: number, max: number }
	{
		return {
			min: G.calculateForLevels(levels, 1),
			avg: G.calculateForLevels(levels, 2),
			max: G.calculateForLevels(levels, 3)
		};
	}

	// расчет стоимости цветов для магазина
	public static calcColorCostByID(id: number)
	{
		if (id > 0)
			return AnMath.ceilToMultiple(AnMath.remap(id, 1, gameColorsArray.length - 1, 20, 500), 5);

		return 0;
	}

	// расчет стоимости тем для магазина
	public static calcThemeCostByID(id: number)
	{
		if (id > 0)
			return AnMath.ceilToMultiple(AnMath.remap(id, 1, gameThemesArray.length - 1, 150, 1500), 5); //800

		return 0;
	}
