// platform/PlatformLoader.ts
import { PlatformYandex } from './PlatformYandex.js';
import { Platform, PlatformInterface, PlatformType } from './Platform.js';
import { AnLog } from 'angine/utils/AnLog.js';
import { PlatformVK } from './PlatformVK.js';
import { PlatformGamePix } from './PlatformGamePix.js';
import { PlatformGameMonetize } from './PlatformGameMonetize.js';
import { PlatformY8 } from './PlatformY8.js';
import { PlatformPlayDeck } from './PlatformPlayDeck.js';
import { PlatformWGPlayground } from './PlatformWGPlayground.js';


export class PlatformLoader
{
	public static async load(): Promise<void>
	{
		// Если уже загружена - возвращаем
		if (Platform.sdk) return;

		// Определяем платформу
		const platformType: PlatformType = AnConfig.platform as PlatformType || PlatformType.Standalone;

		AnLog.info(`Загружаем платформу: ${platformType}`);


		await this.createPlatform(platformType);

		AnLog.info(`Загрузка платформы завершена!`);
	}


	private static async createPlatform(platform: PlatformType): Promise<void>
	{
		let platformType: PlatformType = platform;
		let platformInstance: PlatformInterface | null = null;

		if (platform !== PlatformType.Standalone)
		{
			try
			{
				switch (platform)
				{
					case PlatformType.Yandex:
						platformInstance = new PlatformYandex();
						break;
					case PlatformType.VK:
						platformInstance = new PlatformVK();
						break;
					case PlatformType.GamePix:
						platformInstance = new PlatformGamePix();
						break;
					case PlatformType.GameMonetize:
						platformInstance = new PlatformGameMonetize();
						break;
					case PlatformType.Y8:
						platformInstance = new PlatformY8();
						break;
					case PlatformType.PlayDeck:
						platformInstance = new PlatformPlayDeck();
						break;
					case PlatformType.WGPlayground:
						platformInstance = new PlatformWGPlayground();
						break;
				}

				if (!platformInstance) throw new Error(`реализация платформы ${platform} не найдена!`);
				await platformInstance?.init();
			}
			catch (error)
			{
				AnLog.error(`Невозможно загрузить платформу ${platform}:`, error);
			}
		}

		// Fallback на standalone
		if (!platformInstance)
			platformType = PlatformType.Standalone;


		Platform.type = platformType;
		Platform.sdk = platformInstance;
		Platform.visualName = platformInstance?.visualName ?? null;
	}
}