export type Constructor<T = {}> = new (...args: any[]) => T;
export type AnyConstructor = Constructor<any>;

/**
 * Тип для миксинов, принимающий базовый конструктор и возвращающий новый конструктор
 */
export type Mixin<T extends AnyConstructor> = (base: T) => AnyConstructor;

/**
 * Утилита для преобразования union типов в intersection
 */
export type UnionToIntersection<U> =
	(U extends any ? (k: U) => void : never) extends ((k: infer I) => void) ? I : never;

/**
 * Получает тип экземпляра из конструктора
 */
export type InstanceType<T extends AnyConstructor> = T extends new (...args: any[]) => infer I ? I : never;

/**
 * Фабрика для создания цепочки миксинов
 */
export function enhance<TBase extends AnyConstructor>(baseClass: TBase)
{
	return {
		/**
		 * Добавляет миксины к базовому классу
		 */
		with: <TMixins extends Array<Mixin<TBase>>>(...mixins: TMixins) =>
		{
			// Начинаем с базового класса правильного типа
			let currentClass: TBase = baseClass;

			// Применяем миксины последовательно
			for (const mixin of mixins)
			{
				currentClass = mixin(currentClass) as TBase;
			}

			// Получаем типы экземпляров из каждого миксина
			type MixedInstance = UnionToIntersection<
				InstanceType<TBase> | {
					[K in keyof TMixins]: InstanceType<ReturnType<TMixins[K]>>
				}[number]
			>;

			// Возвращаем класс с правильным типом
			return currentClass as unknown as Constructor<MixedInstance>;
		}
	};
}

/**
 * Возвращает имя самого дочернего экземпляра класса в строковом виде
 */
export function className(object: Object): string
{
	return object.constructor.name;
}

/**
 * Подсчитать кол-во вхождений substr в str
 */
function countOccurrences(str: string, substr: string): number
{
	const regex = new RegExp(substr, 'g');
	const matches = str.match(regex);
	return matches ? matches.length : 0;
}

/**
 * Первая буква в верхнем регистре
 */
export function capitalize(str: string): string
{
	if (!str) return str; // Проверка на пустую строку
	return str.charAt(0).toUpperCase() + str.slice(1);
}

/**
 * Возвращает структуру объекта в строковом виде
 */
export function struct(object: Object): string
{
	return JSON.stringify(object, undefined, 3);
}

/** 
 * эмулирует метод Object.values() 
 * */
export function values(object: Object)
{
	const result = [];

	// Проверяем, что передан объект
	if (object === null || object === undefined)
	{
		throw new TypeError('Cannot convert undefined or null to object');
	}

	// Приводим к объекту, чтобы работать с примитивами
	object = Object(object);

	// Проходим по всем перечисляемым свойствам объекта
	for (const key in object)
	{
		// Проверяем, что это собственное свойство (не унаследованное)
		if (Object.prototype.hasOwnProperty.call(object, key))
		{
			result.push((object as any)[key]);
		}
	}

	return result;
}


/**
 * Добавляет объект в список обновляемых, если он уникален
 */
export function addUniqueValue<T>(array: T[], item: T): void 
{
	if (!array.includes(item))
		array.push(item);
	else
		AnLog.error(`Объект ${className(item as Object)} уже добавлен в массив ${array}`);
}

/**
 * Удаляет первое вхождение элемента в массиве по значению
 */
export function removeByValue<T>(array: T[], value: T): T[]
{
	const index = array.indexOf(value);
	if (index !== -1)
		array.splice(index, 1);

	return array;
}

/**
 * универсальная функция shuffle<T>, которая перемешивает массив
 * по алгоритму Фишера–Йейтса (Knuth shuffle)
 * @param array 
 * @returns 
 */

export function shuffle<T>(array: T[], rnd?: AnRnd): T[]
{
	for (let i = array.length - 1; i > 0; i--)
	{
		const j = Math.floor((rnd ? rnd.seed_float(0, 1) : Math.random()) * (i + 1)); // случайный индекс от 0 до i
		[array[i], array[j]] = [array[j], array[i]];   // меняем местами
	}
	return array;
}

/**
 * получить следующий за заданным элемент массива, циклически переходя через конец массива
 */
export function getNextElement<T>(array: T[], currentElement: T): T
{
	const currentIndex = array.indexOf(currentElement);
	if (currentIndex === -1)
	{
		throw new Error("Элемент не найден в массиве");
	}
	const nextIndex = (currentIndex + 1) % array.length;
	return array[nextIndex];
}

// Функция для открытия новой вкладки с заданным URL
export function openURL(url: string, newTab: boolean = true): void
{
	window.open(url, newTab ? '_blank' : '_self');
}

// Нормализуем URL (в нижний регистр и убираем параметры после ?)
export function normalizeURL(url: string): string
{
	return url.split('?')[0].toLowerCase();
}

