/**
 * Возвращает текущий язык браузера в формате ISO 639-1 (например, "ru", "en").
 * @returns Код языка (например, "ru").
 */
export function getCurrentOSLanguage(): string
{
	// Получаем язык браузера в формате "ru-RU" или "en-US"
	const browserLanguage: string = navigator.language || (navigator as any).userLanguage;

	// Извлекаем первые два символа (ISO 639-1)
	return browserLanguage.split('-')[0].toLowerCase(); // по идее всегда нижний регистр, но мало ли....
}



/**
 * Динамически загружает JavaScript файл
 * @param url URL скрипта
 * @param options Опции загрузки
 * @returns Promise, который резолвится когда скрипт загружен
 */
export function loadScript(
	url: string,
	options: {
		/** Атрибут async */
		async?: boolean;
		/** Атрибут defer */
		defer?: boolean;
		/** Тип скрипта */
		type?: string;
		/** Дополнительные атрибуты */
		attributes?: Record<string, string>;
		/** Таймаут загрузки (сек) */
		timeout?: number;
	} = {}
): Promise<void>
{
	// Быстрая проверка на пустой URL
	if (!url)
	{
		AnLog.error('URL скрипта не указан!');
		return Promise.resolve();
	}

	AnLog.info(`Загружаем скрипт: ${url}`);

	return new Promise((resolve) =>
	{
		// Проверяем, не загружен ли уже скрипт с таким URL
		if (isScriptLoaded(url))
		{

			AnLog.warn(`Скрипт уже загружен с таким URL: ${url}`);
			resolve();
			return;
		}

		// Создаем элемент script
		const script = document.createElement('script');
		script.src = url;

		// Устанавливаем атрибуты
		if (options.async) script.async = true;
		if (options.defer) script.defer = true;
		if (options.type) script.type = options.type;

		// Добавляем кастомные атрибуты
		if (options.attributes)
			Object.entries(options.attributes).forEach(([key, value]) => script.setAttribute(key, value));


		// Функция для завершения загрузки
		const finish = (success: boolean, message?: string) =>
		{
			if (timeoutId !== null)
			{
				clearTimeout(timeoutId);
				timeoutId = null;
			}

			// Очищаем обработчики
			script.onload = null;
			script.onerror = null;

			// Удаляем скрипт если была ошибка
			if (!success && script.parentNode)
				script.parentNode.removeChild(script);


			if (message)
				success ? AnLog.info(message) : AnLog.error(message);

			resolve();
		};

		// Таймаут загрузки
		const timeoutSec = options.timeout ?? 10;
		let timeoutId: number | null = null;

		if (timeoutSec > 0)
			timeoutId = runAfter(
				timeoutSec,
				() => finish(false, `Таймаут загрузки скрипта: ${url}`)
			);

		// Обработчики событий
		script.onload = () => finish(true, `Скрипт загружен: ${url}`);
		script.onerror = () => finish(false, `Ошибка загрузки скрипта: ${url}`);

		// Добавляем скрипт в DOM
		document.head.appendChild(script);
	});
}

/**
 * Проверяет, загружен ли уже скрипт
 * @param url URL скрипта 
 * @returns true если скрипт уже загружен
 */
export function isScriptLoaded(url: string): boolean
{
	const targetUrl = normalizeURL(url);
	const scripts = document.scripts;

	for (let i = 0; i < scripts.length; i++)
		if (normalizeURL(scripts[i].src) === targetUrl)
			return true;

	return false;
}

/**
 * Делает поверхностную копию (включая поля прототипа) всех примитивных полей и гетеры превращает в поля, методы игнорируются
 */
export function dataClone(source: any): any
{
	const target: any = {};
	const propertyNames = [...Object.getOwnPropertyNames(Object.getPrototypeOf(source)), ...Object.getOwnPropertyNames(source)];

	for (const i in propertyNames)
	{
		const key = propertyNames[i];

		// Если это простое поле простое значение или геттер (а не метод и не объект), копируем его значение
		if (typeof source[key] !== 'function' && typeof source[key] !== 'object')
		{

			target[key] = source[key];
		}
	}

	return target;
}


/**
 * Возвращает количество секунд с начала работы скрипта
 */
export function uptime(): number
{
	return performance.now() / 1000;
}

/**
 * Возвращает Promise, который резолвится через указанное время.
 * @param sec Задержка в секундах.
 * @returns Promise<void>
 */
export function delay(sec: number): Promise<void> 
{
	return new Promise<void>((resolve) => setTimeout(resolve, sec * 1000));
}

/**
 * Функция для отложенного запуска другой функции.
 * @param delay - Задержка в секундах перед выполнением функции.
 * @param callback - Функция, которую нужно выполнить.
 * @returns Возвращает идентификатор таймера (number), который можно использовать для отмены выполнения.
 */
export function runAfter(delay: number, callback: () => void): number
{
	// Запускаем таймер и возвращаем его идентификатор
	return setTimeout(callback, delay * 1000);
}

/**
 * Функция для отложенного запуска другой функции. (с проверкой на удаление контекста вызова)
 */
export function runAfterSafe(delay: number, destructible: AnDestructibleInterface, callback: () => void): number
{
	// Запускаем таймер и возвращаем его идентификатор
	return setTimeout(() =>
	{
		if (!destructible.isDestroyed) callback();
	}, delay * 1000);
}

/** прервать выполнение т.к. метод не реализован */
export function notImplemented(info?: string)
{
	const message = info ?? "Функция не реализована";

	if (AnConfig.devMode)
	{
		const stack = new Error().stack;
		const callerLine = stack?.split("\n")[2]?.trim() || "<неизвестный вызов>";
		throw new Error(`NotImplementedError: ${message} (${callerLine})`);
	}
	else
		AnLog.error(message);
}

