/**удаляем все tween-анимации с заданным целевым объектом анимации */
export function removeAllTweensByTarget<T>(updater: AnUpdater, target: T): void
{
	updater.forEach(
		tween =>
		{
			if (tween instanceof AnTween && (tween as AnTween).target === target)
				tween.terminate();
		}
	);
}

/**досрочно завершаем все tween-анимации с заданным тегом */
export function finishAllTweensByTag(updater: AnUpdater, tag: string, andRemove: boolean = true)
{
	updater.forEach(
		tween =>
		{
			if (tween instanceof AnTween && (tween as AnTween).hasTag(tag)) 
			{
				tween.finish();
				if (!tween.autoRemove && andRemove)
					tween.removeFromUpdater();
			}
		}
	);
}

/** найти родительское меню для UI элемента */
export function findParentMenu(element: AnUIElement): AnMenu | null
{
	let parent = element.parent;
	while (parent)
	{
		if (parent instanceof AnMenu) return parent;
		parent = parent.parent;
	}
	return null; // не добавлен в меню
}

/**
 * Рассчитывает время отображения диалога на экране (в секундах).
 * @param text Текст диалога.
 * @param wordsPerMinute Средняя скорость чтения игрока (слов в минуту).
 * @param baseTime Базовое время отображения (например, минимальное время для коротких фраз).
 * @param complexity Коэффициент сложности текста (например, 1.0 для простого текста, 1.5 для сложного).
 * @returns Количество секунд для отображения диалога.
 */
export function calculateDialogDisplayTime(
	text: string,
	wordsPerMinute: number = 200, // Средняя скорость чтения
	baseTime: number = 2,        // Базовое время (секунды)
	complexity: number = 1.0     // Коэффициент сложности
): number
{
	// Разбиваем текст на слова (простая логика)
	const words = text.trim().split(/\s+/).length;

	// Рассчитываем время чтения в секундах
	const readingTime = (words / wordsPerMinute) * 60;

	// Учитываем сложность текста
	const adjustedTime = readingTime * complexity;

	// Возвращаем максимальное значение между базовым временем и рассчитанным
	return Math.max(baseTime, adjustedTime);
}


