export enum MenuResultState
{
	Win = "win",
	Lose = "lose",
}

export interface MenuResultCallbacks
{
	onGameRestart?: AnVoidCallback;
	onGameContinue?: AnVoidCallback;
}

export interface MenuResultConfig extends AnMenuConfig
{
	state: MenuResultState;
	activeStars?: 0 | 1 | 2 | 3;
	totalStars?: number;
	rewardCoins?: number;
	totalCoins?: number;
	callbacks?: MenuResultCallbacks;
}


export class MenuResult extends AnMenu
{
	private callbacks: MenuResultCallbacks;

	private state: MenuResultState;
	private title!: AnLabel;
	private starsBG: AnImage[] = [];
	private starsEarned: AnImage[] = [];
	private activeStars: 0 | 1 | 2 | 3;
	private totalStars: number;
	private rewardCoins: number;
	private totalCoins: number;

	private buttons: AnButton[] = [];
	private starsCounter!: UIGoalCounter;
	private coinsCounter!: UIGoalCounter;

	private rewardText!: AnLabel;
	private rewardCounter!: UIGoalCounter;
	private coinTweens: AnTween[] = [];

	constructor(config: MenuResultConfig)
	{
		super(config);

		this.callbacks = config.callbacks ?? {};

		this.state = config.state;
		this.activeStars = config.activeStars ?? 0;
		this.totalStars = config.totalStars ?? 0;
		this.rewardCoins = config.rewardCoins ?? 0;
		this.totalCoins = config.totalCoins ?? 0;




		this.addToCleanup(() =>
		{
			this.coinTweens.forEach(tween => tween.terminate());
		});

	}

	public start()
	{
		this.createUI();
		this.resizeUI();
		this.show();

		// сообщаем платформе что приостановили игру
		Platform.sdk?.reportEvent(PlatformEvent.GameplayStop);

		AnEvents.emit(`ui:menuResult:started`);
	}

	protected createUI()
	{
		const background = this.addUIElement("background",
			new AnImage({
				sprite: 'images/hoverbg.tex.pixi.jpg',
				anchor: AnAnchor.TopLeft,
				resizeStrategy: () =>
				{
					background.position.set(0, 0);
					background.scaledWidth = AnViewport.width;
					background.scaledHeight = AnViewport.height;
					background.applyDefaultResizeStrategy();

				}
			}
			)
		);
		background.tint = 0xab947f;

		this.title = this.addUIElement(
			"title",
			new AnLabel({
				text: {
					textSource: this.state === MenuResultState.Win ? "menuResultWin" : "menuResultLose",
					fontName: "mainFont",
					fontSize: 120,
					textAlign: AnTextAlign.Center,
					autoUpdateLang: true,
					shadowAlpha: 0.7,
					//anchor: AnAnchor.TopLeft,
				},
				//backgroundColor: 0x333333,
				labelAlign: AnTextAlign.Center,
				anchor: AnAnchor.Center,
				resizeStrategy: () =>
				{
					this.title!.applyDefaultResizeStrategy();

					this.title!.position.set(AnViewport.halfWidth, scaled(200));
				}
			})
		);


		const counterHeight = 70;
		const counterWidth = 200;
		this.starsCounter = this.addUIElement("starsCounter",
			new UIGoalCounter(
				{
					currentCount: this.totalStars,
					maxCount: Infinity,
					iconType: "star_mod",
					anchor: AnAnchor.LeftCenter,
					layout: AnCounterLayout.Vertical,
					resizeStrategy: () =>
					{
						this.starsCounter.scaledWidth = scaled(counterWidth);
						this.starsCounter.scaledHeight = scaled(counterHeight);
						this.starsCounter.applyDefaultResizeStrategy();

						this.starsCounter.position.set(AnViewport.halfWidth - this.starsCounter.width/*this.starsCounter.nopadScaledWidth*/ - scaled(90), scaled(counterHeight * 0.7));
					}
				}
			)
		);

		this.coinsCounter = this.addUIElement("coinsCounter",
			new UIGoalCounter(
				{
					currentCount: this.totalCoins,
					maxCount: Infinity,
					iconType: "coin_mod",
					anchor: AnAnchor.LeftCenter,
					layout: AnCounterLayout.Vertical,
					resizeStrategy: () =>
					{
						this.coinsCounter.scaledWidth = scaled(counterWidth);
						this.coinsCounter.scaledHeight = scaled(counterHeight);
						this.coinsCounter.applyDefaultResizeStrategy();

						this.coinsCounter.position.set(AnViewport.halfWidth + scaled(90), scaled(counterHeight * 0.7));
					}
				}
			)
		);


		for (let i = 0; i < 3; i++) 
		{
			const starBG = this.addUIElement("starBG" + i,
				new AnImage({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './roundStarGrey',
					anchor: AnAnchor.Center,
					resizeStrategy: () =>
					{
						starBG.scaledWidth = scaled(200);
						starBG.scaledHeight = scaled(200);
						starBG.applyDefaultResizeStrategy();
						starBG.position.set(AnViewport.halfWidth + (i - 1) * (starBG.scaledWidth * 1.2), this.title.y + scaled(180));
					}
				}
				)
			);
			this.starsBG.push(starBG);
		}

		for (let i = 0; i < this.activeStars; i++) 
		{
			const star = this.addUIElement("star" + i,
				new AnImage({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './roundStar',
					anchor: AnAnchor.Center,
					resizeStrategy: () =>
					{
						star.scaledWidth = scaled(200);
						star.scaledHeight = scaled(200);
						star.applyDefaultResizeStrategy();
						star.position.set(AnViewport.halfWidth + (i - 1) * (star.scaledWidth * 1.2), this.title.y + scaled(180));
					}
				}
				)
			);
			this.starsEarned.push(star);
		}


		const rewardGap = 30;
		this.rewardText = this.addUIElement(
			"reward",
			new AnLabel({
				text: {
					textSource: "menuResultReward",
					fontName: "mainFont",
					fontSize: 80,
					textAlign: AnTextAlign.Center,
					autoUpdateLang: true,
					shadowAlpha: 0.7,
					//anchor: AnAnchor.TopLeft,
				},
				//backgroundColor: 0x333333,
				labelAlign: AnTextAlign.Center,
				anchor: AnAnchor.Center,
				resizeStrategy: () =>
				{
					this.rewardCounter.scaledWidth = scaled(counterWidth);
					this.rewardCounter.scaledHeight = scaled(counterHeight);
					this.rewardCounter.applyDefaultResizeStrategy();

					//const counterScaledWidth = scaled(counterWidth);
					this.rewardText!.applyDefaultResizeStrategy();
					this.rewardText!.position.set(AnViewport.halfWidth - (this.rewardText!.scaledWidth + this.rewardCounter.width/*this.rewardCounter.nopadScaledWidth*/) * 0.5 + this.rewardText!.scaledWidth * 0.5 - scaled(rewardGap) * 0.5, this.starsBG[0].bottom + scaled(100));

					this.rewardCounter.position.set(this.rewardText!.right + scaled(rewardGap), this.starsBG[0].bottom + scaled(100));
				}
			})
		);
		this.rewardCounter = this.addUIElement("rewardCounter",
			new UIGoalCounter(
				{
					currentCount: this.rewardCoins,
					maxCount: Infinity,
					iconType: "coin_mod",
					anchor: AnAnchor.LeftCenter,
					layout: AnCounterLayout.Vertical,
					resizeStrategy: () =>
					{

					}
				}
			)
		);

		if (this.rewardCoins === 0)
		{
			this.rewardCounter.visible = this.rewardText.visible = false;
		}


		// выбираем какие кнопки нужны
		const ResultButtonsWin = ["DoubleReward", "NextLevel"];
		const ResultButtonsLose = ["MoreMoves", "Restart"];
		const ResultButtons = this.state === MenuResultState.Win ? ResultButtonsWin : ResultButtonsLose;
		const iconNames: Record<string, string> = {
			"MoreMoves": "ads_ico",
			"DoubleReward": "ads_ico",
			"NextLevel": "next_ico",
			"Restart": "restart_ico",
		};
		const callbacks: Record<string, AnVoidCallback> = {
			"MoreMoves": () => this.onButtonMoreMoves(),
			"DoubleReward": () => this.onButtonDoubleReward(),
			"NextLevel": () => this.onButtonNextLevel(),
			"Restart": () => this.onButtonRestart(),
		};
		for (let i = 0; i < ResultButtons.length; i++) 
		{
			const button = this.addUIElement(
				"button" + ResultButtons[i],
				new AnButton({
					sprite: {
						atlas: 'atlases/game.ss.pixi.atlas',
						sprite: './button',
						slice9: {
							left: 20, right: 20, top: 20, bottom: 20
						}
					},
					icon: {
						atlas: 'atlases/game.ss.pixi.atlas',
						sprite: './' + iconNames[ResultButtons[i]],
					},
					iconAlign: AnIconAlign.Left,
					iconScale: { x: 0.9, y: 0.9 },
					// hoverSprite: {
					// 	atlas: 'atlases/game.ss.pixi.atlas',
					// 	sprite: './buttonHover',
					// 	slice9: {
					// 		left: 20, right: 20, top: 20, bottom: 20
					// 	}
					// },
					labelText: {
						text:
						{
							textSource: ResultButtons[i] === "MoreMoves" ?
								() => AnLang.get("menuResult" + ResultButtons[i]).replace("%%moves%%", G.continueMoreMoves.toString())
								:
								"menuResult" + ResultButtons[i],
							fontName: "mainFont",
							fontSize: 70,
							textAlign: AnTextAlign.Center,
							color: 0x333333,
						},
						// backgroundColor: 0x333333,
						// backgroundAlpha: 0.7,
						labelAlign: AnTextAlign.Center,
						anchor: AnAnchor.Center,
					},
					labelTextOffset: { x: 0, y: -3 },
					//labelTextColorHover: 0xffffff,
					padding: 5,
					anchor: AnAnchor.Center,
					controlsRouter: this.controlsRouter,
					resizeStrategy: () =>
					{
						const moreOffsetY =
							((ResultButtons[i] === "NextLevel" && !G.btnDoubleReward) ||
								(ResultButtons[i] === "Restart" && !G.btnMoreMoves)) ?
								45 : 0;

						const buttonsOffsetY = 130 + moreOffsetY;
						const buttonsPosStartY = AnViewport.height - scaled(buttonsOffsetY) * ResultButtons.length + scaled(45);

						button.scaledHeight = scaled(90);
						button.scaledWidth = scaled(430);
						button.applyDefaultResizeStrategy();


						button.position.set(AnViewport.halfWidth, buttonsPosStartY + i * scaled(buttonsOffsetY));
					},
					callbacks: {
						onClick: callbacks[ResultButtons[i]]
					}
				})
			);

			this.buttons.push(button);


			// убираем кнопки в зависимости от платформы
			if (ResultButtons[i] === "DoubleReward")
				button.visible = G.btnDoubleReward;

			if (ResultButtons[i] === "MoreMoves")
				button.visible = G.btnMoreMoves;
		}
	}


	private lastTip: UITip | null = null;
	public showTip(text: string, color: number = 0xffffff, appearDelay: number = 0, stayDelay: number = 0)
	{
		const pos = {
			x: AnViewport.halfWidth,
			y: AnViewport.halfHeight
		};

		if (this.lastTip)
			this.terminateUIElement(this.lastTip);

		const fontSize = 40;
		const lenFactor = text.length * scaled(fontSize);
		const tip = this.addUIElement(new UITip({
			updater: this.getUpdater(),
			appearDelay,
			stayDelay,
			backgroundAlpha: 1,
			background: {
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './greySpot2',
			},
			labelText: {
				text: {
					textSource: text,
					autoUpdateLang: false,

					fontName: "mainFont",
					fontSize: 75,
					textAlign: AnTextAlign.Center,
					shadowAlpha: 0.7,
					shadowOffsetX: 4,
					shadowOffsetY: 4,
					color,

				},
				labelAlign: AnTextAlign.Center,
			},
			anchor: AnAnchor.Center,
			resizeStrategy: () =>
			{
				const scaledFactor = 1;
				tip.scaledWidth = lenFactor * scaledFactor;
				tip.scaledHeight = scaled(fontSize * 3) * scaledFactor;
				tip.applyDefaultResizeStrategy();

				// // Расчёт offset для удержания внутри вьюпорта
				// const halfWidth = tip.scaledWidth / 2;
				// const halfHeight = tip.scaledHeight / 2;

				// const minX = halfWidth;
				// const maxX = AnViewport.width - halfWidth;
				// const minY = halfHeight;
				// const maxY = AnViewport.height - halfHeight;

				// const clampedX = Math.max(minX, Math.min(maxX, pos.x));
				// const clampedY = Math.max(minY, Math.min(maxY, pos.y));

				// const offset = {
				// 	x: clampedX - pos.x,
				// 	y: clampedY - pos.y
				// };

				//tip.position.set(pos.x + offset.x, pos.y + offset.y);

				tip.position.set(pos.x, pos.y);
			},
			callbacks: {
				onComplete: () =>
				{
					this.terminateUIElement(tip);
					this.lastTip = null;
				}
			}
		}));
		this.lastTip = tip;
		tip.applyResizeStrategy();
		tip.startAnimation();
	}

	private tryToShowFullscreenAds(doNext: AnVoidCallback, placement: string)
	{
		let doNextExecute = false;


		// error
		if (!Platform.sdk || !Platform.sdk.canShowAds)
		{
			doNext();
			return;
		}

		Platform.sdk.showAds(PlatformAds.Fullscreen, {
			onOpen: () =>
			{
				Analytics.onFullscreenAdShow(placement);
				GameApp.self.paused = true;
			},
			onClose: () =>
			{
				GameApp.self.paused = false;
				if (!doNextExecute)
				{
					doNextExecute = true;
					doNext();
				}
			},
			onError: () =>
			{
				Analytics.onFullscreenAdError(placement);

				GameApp.self.paused = false;

				if (AnConfig.devMode) AnLog.debug(`Ошибка отображения FullscreenAds`);
				if (!doNextExecute)
				{
					doNextExecute = true;
					doNext();
				}
			},

		});

	}

	private onButtonRestart(): void
	{
		Analytics.onEvent("ResultMenuRestart");

		this.tryToShowFullscreenAds(() =>
		{
			AnRender2D.addToFront(new AnFader({
				type: 'in', duration: 1, callbacks: {
					onComplete: () =>
					{
						this.callbacks.onGameRestart?.();
						AnRender2D.addToFront(new AnFader({ type: 'out', duration: 2 }));

						// сообщаем платформе что продолжили игру
						Platform.sdk?.reportEvent(PlatformEvent.GameplayStart);
					}
				}
			}));

			this.hide();
		}, 'ButtonRestart');

	}

	private onButtonDoubleReward(): void
	{
		const button = this.elements['buttonDoubleReward'] as AnButton;

		Analytics.onEvent("ResultMenuDoubleReward");

		// error
		if (!Platform.sdk)
		{
			this.showTip(AnLang.get('adsError'));
			return;
		}


		Platform.sdk.showAds(PlatformAds.Rewarded, {
			onOpen: () =>
			{
				Analytics.onRewardedAdShow("ButtonDoubleReward");
				GameApp.self.paused = true;
			},
			onClose: () =>
			{
				GameApp.self.paused = false;
			},
			onCloseRewarded: () =>
			{
				Analytics.onRewardedAdReceived("ButtonDoubleReward");
				GameApp.self.paused = false;

				if (button)
				{
					button.enabled = false;
				}

				//menuResultReward2x
				this.rewardText.setText("menuResultReward2x");
				this.rewardCounter.set(this.rewardCoins * 2);
				this.rewardCounter.setTextColor(0x00ff00);

				// обновляем сохранение
				GameApp.self.gameData.coins += this.rewardCoins;

				Analytics.onGetResource('coins', this.rewardCoins, 'reward2X', 'coins');

				this.runCoinsAnims();

				AnSounds.play(
					`sounds/info.snd.mp3`,
					0.6,
				);

				AnSounds.play(
					`sounds/cheer.snd.mp3`,
					0.6,
				);

				this.applyResizeStrategy();
			},
			onError: () =>
			{
				GameApp.self.paused = false;
				Analytics.onRewardedAdError("ButtonDoubleReward");
				this.showTip(AnLang.get('adsError'));
			},

		});
	}

	private onButtonMoreMoves(): void
	{
		Analytics.onEvent("ResultMenuMoreMoves");

		// error
		if (!Platform.sdk)
		{
			this.showTip(AnLang.get('adsError'));
			return;
		}


		Platform.sdk.showAds(PlatformAds.Rewarded, {
			onOpen: () =>
			{
				Analytics.onRewardedAdShow("ButtonMoreMoves");
				GameApp.self.paused = true;
			},
			onClose: () =>
			{
				GameApp.self.paused = false;
			},
			onCloseRewarded: () =>
			{
				Analytics.onRewardedAdReceived("ButtonMoreMoves");
				GameApp.self.paused = false;

				this.callbacks.onGameContinue?.();
				this.hide();
			},
			onError: () =>
			{
				GameApp.self.paused = false;
				Analytics.onRewardedAdError("ButtonMoreMoves");
				this.showTip(AnLang.get('adsError'));
			},

		});
	}
	private onButtonNextLevel(): void
	{
		Analytics.onEvent("ResultMenuNextLevel");

		this.tryToShowFullscreenAds(() =>
		{
			AnRender2D.addToFront(new AnFader({
				type: 'in', duration: 2, callbacks: {
					onComplete: () =>
					{
						GameApp.self.runNextGame();
					}
				}
			}));

			this.hide();
		}, 'ButtonNextLevel');
	}

	protected createEntranceTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		tweens.push(new AnTween({
			target: this.elements['background'],
			from: { alpha: 0 },
			to: { alpha: 0.95 },
			duration: 2,
			easing: AnEase.easeOut,
		}));

		let titleSndPlayed = false;
		tweens.push(new AnTween({
			target: this.title,
			from: { alpha: 0, position: { x: this.title.x, y: this.title.y + scaled(100) } },
			to: { alpha: 1, position: { x: this.title.x, y: this.title.y } },
			delay: 1,
			duration: 3,
			easing: AnEase.easeOutElastic,
			callbacks: {
				onUpdate: (tween: AnTween, progress: number) =>
				{
					if (progress > 0.5 && !titleSndPlayed)
					{
						titleSndPlayed = true;
						AnSounds.play(
							this.state === MenuResultState.Win ? `sounds/win.snd.mp3` : `sounds/lose.snd.mp3`,
							0.6,
						);
					}
				}
			}
		}));

		tweens.push(new AnTween({
			target: this.starsCounter,
			from: { alpha: 0, position: { x: this.starsCounter.x, y: this.starsCounter.y - scaled(100) } },
			to: { alpha: 1, position: { x: this.starsCounter.x, y: this.starsCounter.y } },
			delay: 1.5,
			duration: 1,
			easing: AnEase.easeOutBack,
		}));

		tweens.push(new AnTween({
			target: this.coinsCounter,
			from: { alpha: 0, position: { x: this.coinsCounter.x, y: this.coinsCounter.y - scaled(100) } },
			to: { alpha: 1, position: { x: this.coinsCounter.x, y: this.coinsCounter.y } },
			delay: 2,
			duration: 1,
			easing: AnEase.easeOutBack,
		}));

		if (this.rewardCoins !== 0)
		{
			tweens.push(new AnTween({
				target: this.rewardText,
				from: { alpha: 0, position: { x: this.rewardText.x - scaled(100), y: this.rewardText.y } },
				to: { alpha: 1, position: { x: this.rewardText.x, y: this.rewardText.y } },
				delay: 2,
				duration: 1.5,
				tolerance: 0.1,
				easing: AnEase.easeOutBack,
			}));

			tweens.push(new AnTween({
				target: this.rewardCounter,
				from: { alpha: 0, position: { x: this.rewardCounter.x + scaled(100), y: this.rewardCounter.y } },
				to: { alpha: 1, position: { x: this.rewardCounter.x, y: this.rewardCounter.y } },
				delay: 2,
				duration: 1.5,
				tolerance: 0.1,
				easing: AnEase.easeOutBack,
				callbacks: {
					onComplete: () => this.runCoinsAnims()
				}
			}));
		}


		for (let i = 0; i < this.starsBG.length; i++) 
		{
			tweens.push(new AnTween({
				target: this.starsBG[i],
				from: { alpha: 0, scale: { x: 0.8, y: 0.8 } },
				to: { alpha: 1, scale: { x: 1, y: 1 } },
				delay: 2 + i * 0.2,
				duration: 1.5,
				easing: AnEase.easeOut,
			}));
		}

		for (let i = 0; i < this.starsEarned.length; i++) 
		{
			tweens.push(new AnTween({
				target: this.starsEarned[i],
				from: { alpha: 0, scale: { x: 2, y: 2 } },
				to: { alpha: 1, scale: { x: 1, y: 1 } },
				delay: 3 + i * 0.4,
				duration: 1.5,
				easing: AnEase.easeOutBounce,
				callbacks: {
					onStart: () =>
					{
						AnSounds.play(
							`sounds/star.snd.mp3`,
							0.6,
						);
					},
					onComplete: () =>
					{
						this.starsCounter.updateValue(this.starsCounter.currentCount + 1)
					}
				}
			}));
		}

		for (let i = 0; i < this.buttons.length; i++) 
		{
			tweens.push(new AnTween({
				target: this.buttons[i],
				from: { alpha: 0, position: { x: this.buttons[i].x + scaled(150) * (AnMath.isEven(i) ? 1 : -1), y: this.buttons[i].y } },
				to: { alpha: 1, position: { x: this.buttons[i].x, y: this.buttons[i].y } },
				delay: 3,// + i * 0.4,
				duration: 1,
				easing: AnEase.easeOutBack,
			}));
		}

		if (this.state === MenuResultState.Win)
		{
			runAfterSafe(2, this, () =>
			{
				AnSounds.play(
					`sounds/cheer.snd.mp3`,
					0.6,
				);
			});
		}


		return tweens;
	}


	private runCoinsAnims(): void
	{
		const chunkValue = Math.trunc(this.rewardCoins * 0.2);
		const totalChunks = Math.ceil(this.rewardCoins / chunkValue);

		for (let i = 0; i < totalChunks; ++i)
		{
			const coinValue = i === totalChunks - 1 ? this.rewardCoins - chunkValue * i : chunkValue;
			const posStart = this.rewardCounter.getMainIconGlobalPos();
			const posEnd = this.coinsCounter.getMainIconGlobalPos();

			const coin = this.addUIElement(new AnImage({
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './coin_mod',
				anchor: AnAnchor.Center,
				resizeStrategy: () =>
				{
					coin.scaledWidth = scaled(70);
					coin.scaledHeight = scaled(70);
					coin.applyDefaultResizeStrategy();
				}
			}));

			coin.applyResizeStrategy();
			coin.visible = false;

			let starsSndPlayed = false;
			const tween = new AnTween({
				target: coin,
				from: { alpha: 0.5, position: { x: posStart.x, y: posStart.y } },
				to: { alpha: 1, position: { x: posEnd.x, y: posEnd.y } },
				delay: 1 + i * 0.3,
				duration: 0.7,
				tolerance: 0.3,
				easing: AnEase.easeOutBack,
				updater: this.getUpdater(),
				callbacks: {
					onStart: () =>
					{
						coin.visible = true;
					},
					onUpdate: (tween: AnTween, progress: number) =>
					{

						if (progress > 0.5 && !starsSndPlayed)
						{
							starsSndPlayed = true;
							AnSounds.play(
								`sounds/coin.snd.mp3`,
								AnRnd.float(0.4, 0.6) * 0.5,
								0,
								AnRnd.float(0.9, 1.1)
							);
						}
					},
					onComplete: () =>
					{
						removeByValue(this.coinTweens, tween);
						const tweenOut = new AnTween({
							target: coin,
							to: { alpha: 0, scale: { x: 0.5, y: 0.5 } },
							tolerance: 0.01,
							duration: 0.8,
							easing: AnEase.easeInBack,
							updater: this.getUpdater(),
							callbacks: {
								onComplete: () =>
								{
									this.coinsCounter.updateValue(this.coinsCounter.currentCount + coinValue);
									this.terminateUIElement(coin);
									removeByValue(this.coinTweens, tweenOut);
								}
							}
						}
						);
						this.coinTweens.push(tweenOut);
					}
				}
			});


			this.coinTweens.push(tween);
		}
	}

	protected createExitTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		tweens.push(new AnTween({
			target: this.elements['background'],
			to: { alpha: 0 },
			from: { alpha: 0.95 },
			duration: 2.1,
			easing: AnEase.easeOut,
			tags: ["terminate"]
		}));

		tweens.push(new AnTween({
			target: this.title,
			to: { alpha: 0, position: { x: this.title.x, y: this.title.y - scaled(100) } },
			from: { alpha: 1, position: { x: this.title.x, y: this.title.y } },
			duration: 0.8,
			easing: AnEase.easeOut,
		}));

		tweens.push(new AnTween({
			target: this.starsCounter,
			to: { alpha: 0, position: { x: this.starsCounter.x, y: this.starsCounter.y - scaled(200) } },
			from: { alpha: 1, position: { x: this.starsCounter.x, y: this.starsCounter.y } },
			duration: 0.8,
			easing: AnEase.easeOut,
		}));

		tweens.push(new AnTween({
			target: this.coinsCounter,
			to: { alpha: 0, position: { x: this.coinsCounter.x, y: this.coinsCounter.y - scaled(200) } },
			from: { alpha: 1, position: { x: this.coinsCounter.x, y: this.coinsCounter.y } },
			duration: 0.8,
			easing: AnEase.easeOut,
		}));


		if (this.rewardCoins !== 0)
		{
			tweens.push(new AnTween({
				target: this.rewardText,
				to: { alpha: 0, position: { x: this.rewardText.x - scaled(100), y: this.rewardText.y } },
				from: { alpha: 1, position: { x: this.rewardText.x, y: this.rewardText.y } },
				duration: 1.5,
				easing: AnEase.easeOut,
			}));

			tweens.push(new AnTween({
				target: this.rewardCounter,
				to: { alpha: 0, position: { x: this.rewardCounter.x + scaled(100), y: this.rewardCounter.y } },
				from: { alpha: 1, position: { x: this.rewardCounter.x, y: this.rewardCounter.y } },
				duration: 1.5,
				easing: AnEase.easeOut,
			}));
		}

		for (let i = 0; i < this.starsBG.length; i++) 
		{
			tweens.push(new AnTween({
				target: this.starsBG[i],
				to: { alpha: 0, scale: { x: 0.8, y: 0.8 } },
				from: { alpha: 1, scale: { x: 1, y: 1 } },
				duration: 2,
				easing: AnEase.easeOut,
			}));
		}

		for (let i = 0; i < this.starsEarned.length; i++) 
		{
			tweens.push(new AnTween({
				target: this.starsEarned[i],
				to: { alpha: 0, scale: { x: 0.8, y: 0.8 } },
				from: { alpha: 1, scale: { x: 1, y: 1 } },
				duration: 1,
				easing: AnEase.easeInBack,
			}));
		}

		for (let i = 0; i < this.buttons.length; i++) 
		{
			tweens.push(new AnTween({
				target: this.buttons[i],
				to: { alpha: 0, position: { x: this.buttons[i].x + scaled(150) * (AnMath.isEven(i) ? 1 : -1), y: this.buttons[i].y } },
				from: { alpha: 1, position: { x: this.buttons[i].x, y: this.buttons[i].y } },
				duration: 0.5,
				easing: AnEase.easeOut,
			}));
		}
		return tweens;
	}
}
