export class AnInterpolation
{
	/**
	 * Линейная интерполяция между значениями a и b.
	 * @param t Параметр, изменяющийся от 0 до 1.
	 * @param a Начальное значение.
	 * @param b Конечное значение.
	 * @returns Интерполированное значение.
	 */
	static linear(t: number, a: number, b: number): number
	{
		return a + (b - a) * t;
	}

	/**
	 * Экспоненциальная интерполяция между значениями a и b.
	 * @param t Параметр, изменяющийся от 0 до 1.
	 * @param a Начальное значение.
	 * @param b Конечное значение.
	 * @returns Интерполированное значение.
	 */
	static exponential(t: number, a: number, b: number): number
	{
		return a * Math.pow(b / a, t);
	}

	/**
	 * Синусоидальная интерполяция между значениями a и b.
	 * @param t Параметр, изменяющийся от 0 до 1.
	 * @param a Начальное значение.
	 * @param b Конечное значение.
	 * @returns Интерполированное значение.
	 */
	static sinusoidal(t: number, a: number, b: number): number
	{
		return a + (b - a) * Math.sin((Math.PI / 2) * t);
	}

}


export class AnInterpolationExtended
{
	/**
	 * Квадратичная интерполяция между значениями a и b с промежуточной точкой c.
	 * @param t Параметр, изменяющийся от 0 до 1.
	 * @param a Начальное значение.
	 * @param b Конечное значение.
	 * @param c Промежуточное значение при t = 0.5.
	 * @returns Интерполированное значение.
	 */
	static quadratic(t: number, a: number, b: number, c: number): number
	{
		return a + (4 * c - 2 * a - 2 * b) * t + (a + 4 * b - 4 * c) * t * t;
	}

	/**
	 * Кубическая интерполяция между значениями a и b с промежуточными точками c и d.
	 * @param t Параметр, изменяющийся от 0 до 1.
	 * @param a Начальное значение.
	 * @param b Конечное значение.
	 * @param c Промежуточное значение при t = 1/3.
	 * @param d Промежуточное значение при t = 2/3.
	 * @returns Интерполированное значение.
	 */
	static cubic(t: number, a: number, b: number, c: number, d: number): number
	{
		return a + (2 * c - 2 * b + d - a) * t + (3 * a - 3 * c + 3 * b - d) * t * t + (c + b - a - d) * t * t * t;
	}

	/**
	 * Интерполяция на основе радиальных базисных функций (RBF) между значениями a и b.
	 * @param t Параметр, изменяющийся от 0 до 1.
	 * @param a Начальное значение.
	 * @param b Конечное значение.
	 * @param sigma Параметр, определяющий ширину гауссовой функции.
	 * @returns Интерполированное значение.
	 */
	static rbf(t: number, a: number, b: number, sigma: number = 0.2): number
	{
		return a + (b - a) * Math.exp(-Math.pow(t - 0.5, 2) / (2 * sigma * sigma));
	}

}