import { AnLog } from "angine/utils/AnLog";
import { AnEvents } from "angine/utils/AnEvents";
import { AnControlsEvent, AnKey, AnMouseButton } from "angine/input/AnControlsEnums";

export class AnControls
{
	private static _pointerPos: { x: number, y: number } = { x: 0, y: 0 };
	private static _pointerClick: boolean;
	//private static _mouseButtons = new Set<AnMouseButton>();
	private static _mouseWheel: number = 0;

	private static _key = new Set<AnKey>();
	private static _keyNew = new Set<AnKey>();


	private constructor() { }

	public static init()
	{
		// добавляем события обработчиков устройств

		window.addEventListener('keydown', (e) =>
		{
			//Отключить нежелательные события клавиш и прокрутку с помощью пробела.
			if (["ArrowUp", "ArrowDown", " "].includes(e.key))
				e.preventDefault();

			AnControls.handleKeyboardEvent(AnControlsEvent.KeyboardDown, e)
		}, { passive: false });
		window.addEventListener('keyup', (e) => AnControls.handleKeyboardEvent(AnControlsEvent.KeyboardUp, e));



		window.addEventListener('pointerdown', (e) => AnControls.handlePointerEvent(AnControlsEvent.PointerDown, e));
		window.addEventListener('pointerup', (e) => AnControls.handlePointerEvent(AnControlsEvent.PointerUp, e));
		window.addEventListener('pointermove', (e) => AnControls.handlePointerEvent(AnControlsEvent.PointerMove, e));
		window.addEventListener('pointercancel', (e) => AnControls.handlePointerEvent(AnControlsEvent.PointerCancel, e));

		// window.addEventListener('mousedown', (e) => AnControls.handleMouseEvent(AnControlsEvent.MouseDown, e));
		// window.addEventListener('mouseup', (e) => AnControls.handleMouseEvent(AnControlsEvent.MouseUp, e));
		// window.addEventListener('mousemove', (e) => AnControls.handleMouseEvent(AnControlsEvent.MouseMove, e));
		window.addEventListener('wheel', (e) => { e.preventDefault(); AnControls.handleMouseEvent(AnControlsEvent.MouseWheel, e) }, { passive: false });
		// window.addEventListener('mouseleave', (e) => AnControls.handleMouseEvent(AnControlsEvent.MouseCancel, e));

		// window.addEventListener('touchstart', (e) => { e.preventDefault(); AnControls.handleTouchEvent(AnControlsEvent.TouchStart, e) }, { passive: false });
		// window.addEventListener('touchmove', (e) => { e.preventDefault(); AnControls.handleTouchEvent(AnControlsEvent.TouchMove, e) }, { passive: false });
		// window.addEventListener('touchend', (e) => { e.preventDefault(); AnControls.handleTouchEvent(AnControlsEvent.TouchEnd, e) }, { passive: false });
		// window.addEventListener('touchcancel', (e) => { e.preventDefault(); AnControls.handleTouchEvent(AnControlsEvent.TouchCancel, e) }, { passive: false });



		window.addEventListener('gamepadconnected', (e) => AnControls.handleGamepadEvent(AnControlsEvent.GamepadConnected, e));
		window.addEventListener('gamepaddisconnected', (e) => AnControls.handleGamepadEvent(AnControlsEvent.GamepadDisconnected, e));

		// отключаем вызов контекстного меню
		window.addEventListener('contextmenu', (e) => e.preventDefault(), { passive: false });

	}

	private static handleKeyboardEvent(type: AnControlsEvent, event: KeyboardEvent)
	{
		switch (type)
		{
			case AnControlsEvent.KeyboardDown:
				this._key.add(event.code as AnKey);
				this._keyNew.add(event.code as AnKey);
				break;
			case AnControlsEvent.KeyboardUp:
				this._key.delete(event.code as AnKey);
				break;
		}

		AnEvents.emit(type, event);
	}




	private static handlePointerEvent(type: AnControlsEvent, event: PointerEvent)
	{
		switch (type)
		{
			case AnControlsEvent.PointerMove:
				this._pointerPos.x = event.x;
				this._pointerPos.y = event.y;
				break;
			case AnControlsEvent.PointerDown:
				this._pointerClick = true;
				break;
			case AnControlsEvent.PointerUp:
				this._pointerClick = false;
				break;
			case AnControlsEvent.PointerCancel:
				//cancel
				break;
		}

		AnEvents.emit(type, event);
	}

	private static handleMouseEvent(type: AnControlsEvent, event: MouseEvent)
	{
		switch (type)
		{
			// case AnControlsEvent.MouseMove:
			// 	this._mousePos.x = event.x;
			// 	this._mousePos.y = event.y;
			// 	break;
			// case AnControlsEvent.MouseDown:
			// 	this._mouseButtons.add(event.button); // ЛКМ - 0 ПКМ - 2 КОЛЕСО - 1
			// 	break;
			// case AnControlsEvent.MouseUp:
			// 	this._mouseButtons.delete(event.button); // ЛКМ - 0 ПКМ - 2 КОЛЕСО - 1
			// 	break;
			case AnControlsEvent.MouseWheel:
				this._mouseWheel = (event as WheelEvent).deltaY;
				// (event as WheelEvent).deltaY -100 колесико вверх
				// (event as WheelEvent).deltaY 100 колесико вниз
				break;
			// case AnControlsEvent.MouseCancel:
			// 	//cancel
			// 	break;
		}

		AnEvents.emit(type, event);
	}

	// private static handleTouchEvent(type: AnControlsEvent, event: TouchEvent)
	// {
	// }

	private static handleGamepadEvent(type: AnControlsEvent, event: GamepadEvent)
	{
	}


	public static vibrate(pattern: number | number[] = 20): void
	{
		navigator.vibrate?.(pattern);
	}

	// устройство поддерживает тач управление
	public static get isTouchEnabled(): boolean
	{
		return 'ontouchstart' in window || navigator.maxTouchPoints > 0;
	}

	public static get pointerX(): number
	{
		return this._pointerPos.x;
	}

	public static get pointerY(): number
	{
		return this._pointerPos.y;
	}

	public static update()
	{
		this._keyNew.clear();
	}
}