// platform/PlatformYandex.ts
import { AnSaveData } from 'angine/utils/AnStorage.js';
import { PlatformInterface, PlatformBase, PlatformAds, PlatformAdsCallbacks, PlatformEvent } from './Platform.js';
import { AnLog } from 'angine/utils/AnLog.js';
import { struct } from 'angine/utils/AnHelpers.js';

export class PlatformGamePix extends PlatformBase implements PlatformInterface
{
	private sdk: any | null = null;

	private readonly storageName: string = "CloudStorageGamePix";

	async init(): Promise<void>
	{
		// @ts-ignore
		if (!window.GamePix)
			throw new Error('[GamePix SDK] не загружен, произошла ошибка!');


		// @ts-ignore
		this.sdk = window.GamePix;


		this._initialized = true;
		AnLog.info('[GamePix SDK] успешно загружен и проинициализирован');
	}


	// // модификация параметров игры исходя из платформы
	public modifyGameParams(G: any): void
	{
		super.modifyGameParams(G);

		// Параметры для яндекса
		G.moreGamesURL = "";
		G.btnDoubleReward = true;
		G.btnMoreMoves = true;
		G.musicStreaming = false;

	};


	// // === Пользователь ===

	// get playerName(): string
	// {
	// 	//return this.playerLoggedIn ? this.player!.getName() : "";
	// 	return "";
	// };

	// get playerLoggedIn(): boolean
	// {
	// 	return this.player?.isAuthorized() ?? false;
	// };

	get currentLanguage(): string | null
	{
		const lang = (this.sdk?.lang() as string).toLowerCase() ?? null;

		if (lang === null)
			return null;

		// ru для be, kk, uk, uz;
		// en для остальных языков.

		if (['ru', 'be', 'kk', 'uk', 'uz'].includes(lang)) return 'ru';

		return 'en';
	}

	// === Разметка событий для платформы ===
	public reportEvent(event: PlatformEvent, data?: any): void
	{
		super.reportEvent(event);

		if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] Сообщаем о новом событии: ${event}` + (data ? struct(data) : ''));

		switch (event)
		{
			case PlatformEvent.NewLevel:
				const currentLevel = data as number;
				this.sdk?.updateLevel(currentLevel);
				break;
			case PlatformEvent.CoolMoment:
				this.sdk?.happyMoment();
				break;
		}
	}

	// // === Таблицы рекордов ===
	private get leaderboardsAvailable()
	{
		return Boolean(
			this.sdk &&
			typeof this.sdk.updateScore === 'function'
		);
	}


	public sendScoreToLeaderboard(boardID: string, score: number): void
	{
		//имя таблицы рекордов для этой платформы не задается
		boardID = '';

		if (!this.leaderboardsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] таблицы рекордов не доступны!`);
			return;
		}

		if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] пробуем отправить данные [${score}] в таблицу рекордов ${boardID}...`);

		this.sdk!.updateScore(score);
		// .then(() =>
		// {
		// 	if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] успешно отправили данные в таблицу рекордов!`);
		// })
		// .catch((error: unknown) =>
		// {
		// 	if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] ошибка при отправке данных в таблицу рекордов: ${error}`);
		// });
	}

	// === Реклама ===
	private get adsAvailable()
	{
		return Boolean(
			this.sdk &&
			typeof this.sdk.rewardAd === 'function' &&
			typeof this.sdk.interstitialAd === 'function'
		);
	}

	public showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks)
	{
		super.showAds(type, callbacks);

		if (!this.adsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] реклама не доступна!`);
			callbacks.onError?.();
			return;
		}

		switch (type)
		{
			case PlatformAds.Fullscreen:
				callbacks.onOpen?.();

				this.sdk!.interstitialAd()
					.then((res: any) =>
					{
						// IMPORTANT: *** RESUME YOUR GAME ***

						if (res.success)
						{
							// Log the success if you want
							callbacks.onClose?.();
						} else
						{
							// Log the error if you want
							callbacks.onError?.();
						}
					})
					.catch((error: any) =>
					{
						if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] ошибка загрузки рекламы: ${error}`);
						/* Ошибка */
						callbacks.onError?.();
					});
				break;
			case PlatformAds.Rewarded:
				callbacks.onOpen?.();
				this.sdk!.rewardAd()
					.then((res: any) =>
					{
						if (res.success)
						{
							//assignReward();
							callbacks.onCloseRewarded?.();
						}
						else
						{
							//denyReward();
							callbacks.onClose?.();
						}
					})
					.catch((error: any) =>
					{
						if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] ошибка загрузки рекламы: ${error}`);
						//console.log(error); /* Ошибка */
						callbacks.onError?.();
					});
				break;
		}
	}

	// === Облачные сохранения ===

	private get cloudDataAvailable()
	{
		return Boolean(
			this.sdk &&
			typeof this.sdk.localStorage.setItem === 'function' &&
			typeof this.sdk.localStorage.getItem === 'function'
		);
	}

	public async loadData(): Promise<AnSaveData>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		let data: any = null;

		try
		{
			const json = await this.sdk.localStorage.getItem(this.storageName);
			data = JSON.parse(json);
		}
		catch (error)
		{
			throw new Error('Ошибка чтения данных из облачного хранилища!');
		}

		if (!data)
			throw new Error('Данные в облачном хранилище недоступны!');

		if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] данные успешно загружены из облачного хранилища`);

		return data;
	}

	public async saveData(data: AnSaveData): Promise<void>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		try
		{
			const json = JSON.stringify(data);
			await this.sdk.localStorage.setItem(this.storageName, json);
			if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] данные успешно сохранены в облачном хранилище`);
			return;
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] данные НЕ сохранены, ошибка в облачном хранилище: ${error}`);
			return;
		}
	}

	public async clearData(): Promise<void>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		try
		{
			await this.sdk.localStorage.removeItem(this.storageName);
			if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] облачное хранилище успешно очищено`);
			return;
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[GamePix SDK] ошибка очистки облачного хранилища: ${error}`);
			return;
		}
	}
}