// src/core/AnTimer.ts
import { AnCore } from "angine/core/AnCore";
import { enhance } from "angine/utils/AnHelpers";
import { AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin";
import { AnUpdater } from "angine/utils/AnUpdater";

/**
 * Конфигурация таймера
 */
export interface AnTimerConfig
{
    duration: number;          // Длительность таймера (сек)
    updater?: AnUpdater | null;       // Ссылка на апдейтер 
    callbacks?: AnTimerCallbacks;
    autoStart?: boolean;       // Автоматический старт
    autoRemove?: boolean;      // Удалить из апдейтера при завершении
    loopCount?: number;        // Количество повторов (Infinity = бесконечно, 0 = один раз)
}

/**
 * Коллбеки таймера
 */
export interface AnTimerCallbacks
{
    onStart?: (timer: AnTimer) => void;       // При старте/перезапуске
    onUpdate?: (elapsed: number) => void;     // Каждый кадр
    onComplete?: (timer: AnTimer) => void;    // При завершении
    onStop?: (timer: AnTimer) => void;        // При ручной остановке
    onPause?: (timer: AnTimer) => void;       // При паузе
    onResume?: (timer: AnTimer) => void;      // При возобновлении
}


/**
 * Класс таймера с полным циклом жизни и интеграцией в систему обновления.
 * 
 * Основные возможности:
 * - Точное отслеживание времени с поддержкой паузы
 * - Гибкая система коллбеков на все события
 * - Поддержка цикличного выполнения (с ограничением повторов)
 * - Автоматическое управление подпиской на обновления
 */
export class AnTimer extends enhance(Object).with(AnUpdatableMixin) implements AnUpdatableInterface
{
    // Приватные поля класса
    private _duration: number;          // Общая длительность таймера в секундах
    private _elapsed: number = 0;       // Прошедшее время с момента старта
    private _running: boolean = false; // Флаг активности таймера
    private _paused: boolean = false; // Флаг состояния паузы
    private _loopCount: number;         // Оставшееся количество повторов (Infinity если повторять бесконечно)
    private _initialLoopCount: number;  // Начальное количество повторов
    private _autoRemove: boolean;       // Удалять ли из апдейтера после завершения (по умолчанию true)
    private _callbacks: AnTimerCallbacks; // Коллекция коллбеков

    /**
     * Конструктор таймера
     * @param config - Конфигурация таймера
     */
    constructor(config: AnTimerConfig)
    {

        super();

        // Инициализация основных параметров
        this._duration = config.duration;
        this._loopCount = config.loopCount ?? 0;
        this._initialLoopCount = this._loopCount;
        this._autoRemove = config.autoRemove ?? true;
        this._callbacks = config.callbacks ?? {};
        let autoStart = config.autoStart ?? true;

        // Определяем используемый апдейтер:
        if (config.updater) this.addToUpdater(config.updater);

        // Автоматический старт при создании, если указано в конфиге
        if (autoStart) this.start();
    }

    /**
     * получить коллбеки для переназначения
     */
    public get callbacks(): AnTimerCallbacks
    {
        return this._callbacks;
    }

    /**
     * Запускает или перезапускает таймер
     */
    start(): void
    {
        if (this._running || !this.getUpdater()) return;

        this._running = true;
        this._paused = false;

        // Вызываем коллбек старта
        this._callbacks.onStart?.(this);
    }

    /**
     * Останавливает таймер (без завершения)
     */
    stop(): void
    {
        if (!this._running) return;

        this._running = false;

        // Вызываем коллбек остановки
        this._callbacks.onStop?.(this);

        // При необходимости удаляем из системы обновления
        if (this._autoRemove) this.removeFromUpdater();
    }

    /**
     * Ставит таймер на паузу
     */
    pause(): void
    {
        if (!this._running || this._paused || !this.getUpdater()) return;

        this._paused = true;

        // Вызываем коллбек паузы
        this._callbacks.onPause?.(this);
    }

    /**
     * Возобновляет работу таймера после паузы
     */
    resume(): void
    {
        if (!this._running || !this._paused || !this.getUpdater()) return;

        this._paused = false;

        // Вызываем коллбек возобновления
        this._callbacks.onResume?.(this);
    }

    /**
     * Полностью сбрасывает состояние таймера
     */
    reset(): void
    {
        this._elapsed = 0;
        this._loopCount = this._initialLoopCount;
        this.stop();
    }

    /**
     * Основной метод обновления, вызываемый системой AnUpdater
     * @param dt - Дельта времени в секундах
     */
    update(dt: number): void
    {
        // Не обновляем, если таймер не активен или на паузе
        if (!this._running || this._paused) return;

        // Обновляем прошедшее время
        this._elapsed += dt;

        // Вызываем коллбек обновления
        this._callbacks.onUpdate?.(this._elapsed);

        // Проверяем завершение таймера
        if (this._elapsed >= this._duration)
        {
            // Вызываем коллбек завершения
            this._callbacks.onComplete?.(this);

            if (this._loopCount > 0)
            {
                // Обработка циклического режима
                this._loopCount--;
                this._elapsed = 0;

                // Вызываем коллбек старта для нового цикла
                this._callbacks.onStart?.(this);
            } else
            {
                // Завершаем работу таймера
                this.stop();
            }
        }
    }

    // =====================
    // Геттеры для состояния
    // =====================

    /** Текущий прогресс (от 0 до 1) */
    get progress(): number { return this._elapsed / this._duration; }

    /** Активен ли таймер */
    get running(): boolean { return this._running; }

    /** На паузе ли таймер */
    get paused(): boolean { return this._paused; }

    /** Прошедшее время в секундах */
    get elapsed(): number { return this._elapsed; }

    /** Оставшееся время в секундах */
    get remaining(): number { return this._duration - this._elapsed; }

    public terminate()
    {
        this._callbacks = {};
        this.removeFromUpdater();
    }
}