import { AnImage } from "angine/ui/AnImage.js";
import { Block } from "./Block.js";
import { CellSize, GridPos } from "./Field.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnEase } from "angine/anim/AnEase.js";
import { AnTween } from "angine/anim/AnTween.js";
import { AnUpdatableMixin, AnUpdatableInterface, AnUpdatableConfig } from "angine/mixins/AnUpdatableMixin.js";
import { AnUIGroupElement, AnUIGroupElementConfig } from "angine/ui/AnUIGroupElement.js";
import { AnVoidCallback, enhance, getComplementaryColor, getSplitComplementaryColors } from "angine/utils/AnHelpers.js";
import { AnLog } from "angine/utils/AnLog.js";
import { IRenderLayer } from "pixi.js";
import { AnRnd } from "angine/utils/AnRnd.js";
import { G } from "./G.js";
import { GameColor, GameColorsDB } from "./Game.js";
import { GameApp } from "../GameApp.js";
import { AnEvent, AnEvents } from "angine/utils/AnEvents.js";

/** Типы модификаторов для игровой ячейки */
export enum CellModifier
{
	None = 0,
	Paint = 1 << 0,
	Cage = 1 << 1,
	// Можно добавить другие 
}

// описываем модификации ячейки
export interface CellMod
{
	pos: GridPos;
	mods: CellModifier[];
}

export interface CellConfig extends AnUpdatableConfig, AnUIGroupElementConfig
{
	pos: GridPos;
	modifiers?: CellModifier[];
	cellModifierLayer?: IRenderLayer,
	onAnimInitialCellComplete?: AnVoidCallback;
}

/** Класс, представляющий игровую ячейку с модификаторами */
export class Cell
	extends enhance(AnUIGroupElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{

	private _grid: AnImage;
	private modifierPic: AnImage | null = null;
	private highlightPic: AnImage | null = null;
	private highlightPicTween: AnTween | null = null;
	private _gridPos: GridPos = new GridPos(0, 0);
	private _block: Block | null = null;
	private _modifiers: CellModifier = CellModifier.None;

	private cellModifierLayer: IRenderLayer | null = null;

	constructor(config: CellConfig)
	{
		super(config);

		//? не нужно?
		if (config.updater) this.addToUpdater(config.updater);


		this._gridPos.set(config.pos);
		const { x, y } = config.pos.toPixelPos();
		this.position.set(x, y);

		this.cellModifierLayer = config.cellModifierLayer ?? null;

		// записываем все модификаторы если они есть
		if (config.modifiers)
		{
			this._modifiers = CellModifier.None;
			for (const modifier of config.modifiers)
				this._modifiers |= modifier;

		}

		this._grid = new AnImage({
			atlas: 'atlases/game.ss.pixi.atlas',
			sprite: './cell',
			anchor: AnAnchor.Center,
		});
		this.addUIElement(this._grid);

		this._grid.alpha = G.UIBackgroundTransparent;

		this.highlightPic = new AnImage({
			atlas: 'atlases/game.ss.pixi.atlas',
			sprite: './cellHighlighted',
			anchor: AnAnchor.Center,
		});
		this.addUIElement(this.highlightPic);
		this.highlightPic.visible = false;

		const tween = new AnTween({
			target: this,
			from: { alpha: 0, scale: { x: 0.5, y: 0.5 } },
			to: { alpha: 1, scale: { x: 1, y: 1 } },
			tolerance: 0.2,
			delay: (this._gridPos.row + this._gridPos.col) * 0.1,
			duration: 1.2,
			easing: AnEase.easeOutElastic,
			updater: this.getUpdater(),
		});

		// для продолжения начальных анимаций определим когда оканчиваются анимации клеток
		if (config.onAnimInitialCellComplete)
			tween.callbacks.onComplete = config.onAnimInitialCellComplete;

		this.updateVisualModifiers();

		this.addToCleanup(() => this.highlightPicTween?.terminate());

		this.addToCleanup(AnEvents.on("storage:color:update",
			(e: AnEvent) => this.onSettingsColorUpdate(e.data.value as GameColor)).unsub);
	}

	private onSettingsColorUpdate(color: GameColor): void
	{
		if (this.hasModifier(CellModifier.Paint))
		{
			this._grid.tint = Cell.getCellPaintedColor(GameColorsDB[color].baseColorTint);
		}
	}

	/** Получить текущий блок в ячейке */
	get block(): Block | null
	{
		return this._block;
	}

	/** Установить блок в ячейку */
	set block(value: Block | null)
	{
		this._block = value;
	}

	/** Получить текущие модификаторы ячейки */
	get modifiers(): CellModifier
	{
		return this._modifiers;
	}

	/** Проверить наличие модификатора */
	hasModifier(modifier: CellModifier): boolean
	{
		return (this._modifiers & modifier) === modifier;
	}

	/** Добавить модификатор */
	addModifier(modifier: CellModifier): void
	{
		if (this.hasModifier(modifier)) return;

		if (modifier === CellModifier.Paint)
		{
			const tween = new AnTween({
				target: this,
				from: { alpha: 0, scale: { x: 0.5, y: 0.5 } },
				to: { alpha: 1, scale: { x: 1, y: 1 } },
				duration: 1.2,
				easing: AnEase.easeOutElastic,
				updater: this.getUpdater(),
			});
		}

		this._modifiers |= modifier;
		this.updateVisualModifiers();
	}

	/** Добавить все модификаторы */
	public addModifiers(mods: CellModifier[])
	{
		for (const mod of mods)
			this.addModifier(mod);
	}

	/** Убрать модификатор */
	removeModifier(modifier: CellModifier): void
	{
		if (!this.hasModifier(modifier)) return;
		this._modifiers &= ~modifier;
		this.updateVisualModifiers();
	}

	private updateVisualModifiers()
	{
		if (this.hasModifier(CellModifier.Paint))
		{
			this._grid.changeTexture('./cellPainted', 'atlases/game.ss.pixi.atlas');
			this._grid.alpha = 1;

			this.onSettingsColorUpdate(GameApp.self.gameData.color);
		}
		else
		{
			this._grid.changeTexture('./cell', 'atlases/game.ss.pixi.atlas');
			this._grid.alpha = G.UIBackgroundTransparent;
		}



		if (this.hasModifier(CellModifier.Cage))
		{
			if (this.modifierPic)
			{
				this.terminateUIElement(this.modifierPic);
				this.modifierPic = null;
			}

			this.modifierPic = new AnImage({
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './cellCage',
				anchor: AnAnchor.Center,
			});
			this.addUIElement(this.modifierPic);
			this.cellModifierLayer?.attach(this.modifierPic);
		}
		else
		{
			if (this.modifierPic)
			{
				const modifierPic = this.modifierPic;
				const tween = new AnTween({
					target: modifierPic,
					from: { alpha: 4, rotation: 0, position: { x: modifierPic.x, y: modifierPic.y } },
					to: { alpha: 0, rotation: AnRnd.float(-2 * Math.PI, 2 * Math.PI), position: { x: modifierPic.x + AnRnd.float(-CellSize * 2.5, CellSize * 2.5), y: modifierPic.y + CellSize * 5 } },
					duration: 1,
					easing: AnEase.easeInBack,
					updater: this.getUpdater(),
					callbacks: {
						onComplete: () => this.terminateUIElement(modifierPic)
					}
				});

				this.modifierPic = null;
			}
		}
	}


	public activateHighlight()
	{
		if (this.highlightPicTween)
		{
			this.highlightPicTween.terminate();
			this.highlightPicTween = null;
		}


		this.highlightPicTween = new AnTween({
			target: this.highlightPic,
			from: { alpha: 1, scale: { x: 1, y: 1 } },
			to: { alpha: 0, scale: { x: 0.7, y: 0.7 } },
			duration: 1,
			easing: AnEase.linear,
			updater: this.getUpdater(),
			callbacks: {
				onStart: () => this.highlightPic!.visible = true,
				onComplete: () =>
				{
					this.highlightPic!.visible = false;
					this.highlightPicTween = null;
				}

			}
		});
	}


	public static getCellPaintedColor(color: number): number
	{
		return getSplitComplementaryColors(color).color2;
	}

}