import { AnText, AnTextSource, AnTextAlign, AnTextConfig, AnTextStyleConfig } from "angine/2D/AnText";
import { Default, PIXI } from "angine/singleton";
import { AnUIElement, AnUIElementConfig as AnUIElementConfig, AnUIResizeStrategyFunc } from "angine/ui/AnUIElement";
import { AnViewport, scaled } from "angine/core/AnViewport";
import { safeDestroyFunc } from "angine/utils/AnHelpers";
import { AnLog } from "angine/utils/AnLog";


export interface AnLabelTextStyleConfig extends AnTextStyleConfig
{
	shadowOffsetX?: number;  // Смещение тени по оси X
	shadowOffsetY?: number;  // Смещение тени по оси Y
	shadowColor?: number;    // Цвет тени (по умолчанию черный)
	shadowAlpha?: number;    // Прозрачность тени (по умолчанию непрозрачный)
};

export interface AnLabelTextConfig extends AnTextConfig, AnLabelTextStyleConfig
{
};

export interface AnLabelConfig extends AnUIElementConfig
{
	text: AnLabelTextConfig;
	labelAlign?: AnTextAlign; // выравнивание текста внутри заданных границ по ширине
	backgroundColor?: number;
	backgroundAlpha?: number;
	backgroundPadding?: number;
}

export class AnLabel extends AnUIElement
{
	private textObj: AnText;
	private shadowTextObj: AnText | null = null; // Добавляем объект для тени
	// private baseFontSize: number;
	// private baseLine: number;
	protected background: PIXI.Graphics | null = null;
	protected backgroundColor: number;
	protected backgroundAlpha: number;
	protected backgroundPadding: number;
	private labelAlign: AnTextAlign;

	// Параметры тени
	private shadowOffsetX?: number;
	private shadowOffsetY?: number;
	private shadowColor?: number;
	private shadowAlpha?: number;

	constructor(config: AnLabelConfig)
	{
		super(config);

		// Создаем текстовый объект AnText
		//this.baseFontSize = config.text.fontSize ?? 43;
		this.textObj = new AnText({ ...config.text });
		this.backgroundColor = config.backgroundColor ?? 0;
		this.backgroundAlpha = config.backgroundAlpha ?? 1;
		this.backgroundPadding = config.backgroundPadding ?? 1;
		this.labelAlign = config.labelAlign ?? AnTextAlign.Left;

		//this.baseLine = AnAssets.getFontData(config.text.fontName) ?? this.baseFontSize * 0.79;


		// Добавляем фон, если задан цвет
		if (config.backgroundColor !== undefined)
			this.createBackground();

		// Создаем тень, если заданы параметры тени
		//*
		if (config.text.shadowOffsetX !== undefined ||
			config.text.shadowOffsetY !== undefined ||
			config.text.shadowColor !== undefined ||
			config.text.shadowAlpha !== undefined)
		{
			// Сохраняем параметры тени с значениями по умолчанию
			this.shadowOffsetX = config.text.shadowOffsetX ?? 2;
			this.shadowOffsetY = config.text.shadowOffsetY ?? 2;
			this.shadowColor = config.text.shadowColor ?? 0x000000;
			this.shadowAlpha = config.text.shadowAlpha ?? 1;

			// Создаем объект тени
			this.shadowTextObj = new AnText({
				...config.text
			});

			// Устанавливаем цвет тени (через tint для BitmapText)
			this.shadowTextObj.tint = this.shadowColor;
			this.shadowTextObj.alpha = this.shadowAlpha;


			// Добавляем тень в контейнер
			this.addGraphics(this.shadowTextObj);
			this.addToCleanup(safeDestroyFunc(this.shadowTextObj));

			// для отладки, добавляем ярлык для элемента (pixi devtools)
			if (AnConfig.devMode) this.shadowTextObj.label = "shadow text";
		}
		//*/


		this.addGraphics(this.textObj);
		this.addToCleanup(safeDestroyFunc(this.textObj));
		// для отладки, добавляем ярлык для элемента (pixi devtools)
		if (AnConfig.devMode) this.textObj.label = "bitmap text";

		// const cross = createDebugCross();
		// this.addChild(cross);
		// this.addToCleanup(safeDestroyFunc(cross));

		// +++ resize strategy +++
		this.defaultResizeStrategy = () =>
		{
			this.textObj.applyFontResize();

			const textBounds = this.textObj.getLocalBounds();
			const offsetY = scaled(this.textObj.calcOffsetY());



			if (this._scaledWidth !== null && this._scaledHeight !== null)
			{
				const finalScale = Math.min(1, this.scaledWidth / textBounds.width, this.scaledHeight / textBounds.height);

				//Обновляем позицию и размер текста
				this.textObj.applyResize(finalScale);

				switch (this.labelAlign)
				{
					case AnTextAlign.Left: this.textObj.x = 0; break;
					case AnTextAlign.Right: this.textObj.x = this.scaledWidth - this.textObj.width; break;
					case AnTextAlign.Center: this.textObj.x = (this.scaledWidth - this.textObj.width) * 0.5; break;
				}

				this.textObj.y = this.scaledHeight * 0.5 - this.textObj.height * 0.5 - offsetY * finalScale;
			}
			else
			{
				this.textObj.x = 0;
				this.textObj.y = -offsetY;

				if (this.textObj.style.wordWrap && this.scaledWidth !== null)
				{
					this.textObj.style.wordWrapWidth = this.scaledWidth;
				}
			}


			// Обновляем тень
			if (this.shadowTextObj)
			{
				this.shadowTextObj.applyFontResize();
				this.shadowTextObj.applyResize(this.textObj.scale.x);
				this.shadowTextObj.position.set(this.textObj.x + this.shadowOffsetX! * AnViewport.scale, this.textObj.y + this.shadowOffsetY! * AnViewport.scale);

				if (this.shadowTextObj.style.wordWrap && this.scaledWidth !== null)
				{
					this.shadowTextObj.style.wordWrapWidth = this.scaledWidth;
				}
			}

			// Обновляем фон
			if (this.background)
			{
				const scaledPadding = scaled(this.backgroundPadding);
				this.background.x = this.background.y = -scaledPadding;

				if (this._scaledWidth !== null && this._scaledHeight !== null)
				{
					this.background.width = this._scaledWidth;
					this.background.height = this._scaledHeight;
				}
				else
				{
					this.background.width = this.textObj.width;
					this.background.height = this.textObj.height;
				}
				this.background.width += scaledPadding * 2;
				this.background.height += scaledPadding * 2;

				// this.background.pivot.x = this.background.width * 0.5;
				// this.background.position.x += this.background.width * 0.5;// - scaledPadding;
				// this.background.pivot.y = this.background.height * 0.5;
				// this.background.position.y += this.background.height * 0.5; //- scaledPadding;
			}
		}

		this.configResizeStrategy(config.resizeStrategy);
	}

	public updateShadowRealPixels()
	{
		this.shadowTextObj?.position.set(this.textObj.x + this.shadowOffsetX!, this.textObj.y + this.shadowOffsetY!);
	}

	public get textOffsetY(): number
	{
		return this.textObj.calcOffsetY();
	}

	public get textColor()
	{
		return this.textObj.textColor;
	}
	public set textColor(color: number)
	{
		this.textObj.textColor = color;
	}

	public getText()
	{
		return this.textObj.resolveTextSource();
	}

	public getTextWidth()
	{
		return this.textObj.getLocalBounds().width;
	}
	public getTextHeight()
	{
		return this.textObj.getLocalBounds().height;
	}

	public setText(text: AnTextSource)
	{
		this.textObj.textSource = text;
		if (this.shadowTextObj) this.shadowTextObj.textSource = text;

		this.updateText();
	}

	public updateText()
	{
		this.textObj.updateText();
		this.shadowTextObj?.updateText();

		//? возможно стоит оставить только применение TextAlign?
		this.applyDefaultResizeStrategy();
	}

	private createBackground()
	{
		this.background = new PIXI.Graphics();
		this.addToCleanup(safeDestroyFunc(this.background));
		this.background.rect(0, 0, 100, 100);
		this.background.fill({ color: this.backgroundColor, alpha: this.backgroundAlpha });

		// Добавление в контейнер
		this.addGraphics(this.background);
		// для отладки, добавляем ярлык для элемента (pixi devtools)
		if (AnConfig.devMode) this.background.label = "background";
	}
}
