import { AnUIGroupElement, AnUIGroupElementConfig } from "angine/ui/AnUIGroupElement.js";
import { AnProgressBar } from "angine/ui/AnProgressBar.js";
import { AnLabel } from "angine/ui/AnLabel.js";
import { AnEvents } from "angine/utils/AnEvents.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnLog } from "angine/utils/AnLog.js";
import { AnUpdatableConfig, AnUpdatableInterface, AnUpdatableMixin } from "angine/mixins/AnUpdatableMixin.js";
import { enhance } from "angine/utils/AnHelpers.js";
import { AnViewport, scaled } from "angine/core/AnViewport.js";
import { AnUI } from "angine/ui/AnUI.js";
import { AnTextAlign } from "angine/2D/AnText.js";
import { Default, PIXI } from "angine/singleton.js";
import { AnTween } from "angine/anim/AnTween.js";
import { AnEase } from "angine/anim/AnEase.js";
import { AnCore } from "angine/core/AnCore.js";
import { AnUIResizeStrategyFunc } from "angine/ui/AnUIElement.js";
import { AnSounds } from "angine/audio/AnSounds.js";
import { AnMath } from "angine/utils/AnMath.js";

/**
 * Конфиг для компонента UIGoalProgress
 */
export interface UIGoalProgressConfig extends AnUIGroupElementConfig
{
	totalCount: number; // нужно для расчета ширины поля
}

export class UIGoalProgress
	extends enhance(AnUIGroupElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{

	private totalCount: number; // сохраняем это значение т.к. оно не меняется
	private progressBar: AnProgressBar;
	private labelCurrentScore: AnLabel;
	private labelTotalScore: AnLabel;

	private labelTween: AnTween | null = null;

	constructor(config: UIGoalProgressConfig)
	{
		config.anchor = config.anchor ?? AnAnchor.Center;
		super(config); // Передаем конфиг в базовый класс

		const strTotalCount = config.totalCount.toString();
		this.totalCount = config.totalCount;

		this.progressBar = this.addUIElement(
			"progressBar",
			new AnProgressBar({
				value: 0,
				anchor: AnAnchor.Center,
				foreground: {
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './button',
					slice9: {
						left: 20, right: 20, top: 20, bottom: 20
					}
				},
				background: {
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './buttonHover',
					slice9: {
						left: 20, right: 20, top: 20, bottom: 20
					}
				},
			})
		);

		this.labelCurrentScore = this.addUIElement(
			"currentScoreLabel",
			new AnLabel({
				text: {
					textSource: "0",
					fontName: "mainFont",
					fontSize: 50,
					textAlign: AnTextAlign.Center,
					autoUpdateLang: false,
					shadowAlpha: 0.7,
				},
				//backgroundColor: 0x333333,
				labelAlign: AnTextAlign.Center,
				anchor: AnAnchor.Center,
			})
		);

		this.labelTotalScore = this.addUIElement(
			"totalScoreLabel",
			new AnLabel({
				text: {
					textSource: strTotalCount,
					fontName: "mainFont",
					fontSize: 50,
					textAlign: AnTextAlign.Center,
					autoUpdateLang: false,
					shadowAlpha: 0.7,
				},
				//backgroundColor: 0x333333,
				labelAlign: AnTextAlign.Center,
				anchor: AnAnchor.Center,
			})
		);


		// +++ resize strategy +++
		this.defaultResizeStrategy =
			() =>
			{
				// 26 пикселей для цифры примерно
				const scoreWidth = scaled(26 * strTotalCount.length);
				const scorePadding = scaled(5);
				const scoreOffsetY = -scaled(AnUI.styleParams.shadowOffset);
				//const scoreOffsetY = 0;

				this.progressBar.scaledWidth = this.scaledWidth - (scoreWidth + scorePadding) * 2;
				this.progressBar.scaledHeight = this.scaledHeight * 0.7;
				this.progressBar.applyDefaultResizeStrategy();
				this.progressBar.position.set(scoreWidth + scorePadding + this.progressBar.scaledWidth * 0.5, this.progressBar.scaledHeight * 0.5);

				this.labelCurrentScore.scaledWidth = scoreWidth;
				this.labelCurrentScore.scaledHeight = this.progressBar.scaledHeight * 2;
				this.labelCurrentScore.applyDefaultResizeStrategy();
				this.labelCurrentScore.position.set(this.progressBar.left - scorePadding - scoreWidth * 0.5, this.progressBar.y + scoreOffsetY);

				this.labelTotalScore.scaledWidth = scoreWidth;
				this.labelTotalScore.scaledHeight = this.progressBar.scaledHeight * 2;
				this.labelTotalScore.applyDefaultResizeStrategy();
				this.labelTotalScore.position.set(this.progressBar.right + scorePadding + scoreWidth * 0.5, this.progressBar.y + scoreOffsetY);

			};

		this.configResizeStrategy(config.resizeStrategy);
	}

	public getGoalGlobalPos(): PIXI.Point
	{
		const globalLabelPos = this.labelCurrentScore.getGlobalPosition();
		return new PIXI.Point(globalLabelPos.x + this.labelCurrentScore.scaledWidth * 0.5, globalLabelPos.y);
	}

	private isGoalReachedLast = false;
	public updateValue(currentValue: number, withAnim: boolean = true): void
	{
		const current = Math.min(currentValue, this.totalCount);
		this.progressBar.value = current / this.totalCount;
		this.labelCurrentScore.setText(current.toString());
		this.labelTotalScore.updateText();

		if (AnMath.floatEqual(current, this.totalCount) && !this.isGoalReachedLast)
		{
			this.isGoalReachedLast = true;
			AnSounds.play(
				`sounds/goal.snd.mp3`,
				0.6,
			);
		}

		if (withAnim)
		{
			if (this.labelTween)
			{
				this.labelTween.terminate();
				this.labelTween = null;
			}

			this.labelTween = new AnTween({
				target: this.labelCurrentScore,
				from: { scale: { x: 1.5, y: 1.5 }, tint: 0x00ff00 },
				to: { scale: { x: 1, y: 1 }, tint: 0xffffff },
				duration: 1,
				easing: AnEase.easeOutBounce,
				updater: this.getUpdater(),
				autoRemove: true,
				callbacks: {
					onComplete: () => this.labelTween = null
				}
			});
		}
	}


	public update(dt: number)
	{
		super.update(dt);
		this.progressBar.update(dt);
	}
} 