import { AnEase } from 'angine/anim/AnEase';
import { AnMath } from 'angine/utils/AnMath';
import { AnProgressBar } from "angine/ui/AnProgressBar";
import { AnImage } from "angine/ui/AnImage";
import { AnLabel } from "angine/ui/AnLabel";
import { AnFader } from "angine/ui/AnFader";
import { AnAnchor } from "angine/ui/AnAnchor";
import { AnLog } from "angine/utils/AnLog";



type AnPreloaderConfig = {
	preloaderBundle?: string;
	assetsBundle?: string;
	skipExitAnimations?: boolean;
	//totalProgressDistribution: Record<string, number[]>;
};

