export type AnPreloaderCallbacks = {
	/** Вызывается при начале показа прелоадера */
	onStart?: () => void;

	/** Вызывается при прогрессе процента загрузки (0...100) */
	onProgress?: (percent: number) => void;

	/** Вызывается при завершении прелоадера */
	onComplete?: () => void;
};

export class AnPreloader extends AnMenu
{
	//private textTween: AnTween | null = null;

	private skipExitAnimations: boolean;

	private preloaderBundle: string;
	private assetsBundle: string;

	public constructor(
		private readonly config: AnPreloaderConfig,
		private readonly callbacks?: AnPreloaderCallbacks)
	{
		super();

		this.preloaderBundle = config.preloaderBundle ?? "preloader.zip";
		this.assetsBundle = config.assetsBundle ?? "assets.zip";
		this.skipExitAnimations = config.skipExitAnimations ?? false;
	}


	public async start()
	{
		//сначала загружаем ресурсы для прелоадера
		const preloaderBundle = (await AnLoader.loadBundles([{ urls: [this.preloaderBundle] }]))[0];
		//загружаем рессурсы прелоадера в ассеты
		await AnAssets.load(preloaderBundle);

		//создаём интерфейс прелоадера
		this.createUI();
		this.resizeUI();

		// показываем прелоадер
		this.show();


		//теперь все готово для начала загрузки основных ассетов
		this.callbacks?.onStart?.();

		//на всякий случай
		this.callbacks?.onProgress?.(0);


		//сначала загружаем основные ресурсы
		const assetsBundle = (await AnLoader.loadBundles(
			[{ urls: this.assetsBundle.split(",") }],
			{
				onProgress: (loaded, total, index) =>
				{
					(this.elements['progressBar'] as AnProgressBar).value = (loaded / total);
					(this.elements['textPercent'] as AnLabel).updateText();
					const percent = Math.trunc((loaded / total) * 100);//.toFixed(1);

					this.callbacks?.onProgress?.(AnMath.clamp(percent, 0, 100));

					// if (percent % 10 == 0)
					// 	this.textTween?.start();
					//AnLog.info(`Бандл ${index + 1}: ${percent}%`);
				},
			}
		))[0];
		//загружаем основные ресурсы в ассеты
		await AnAssets.load(assetsBundle, "all", [],
			{
				/** Вызывается при начале загрузки всех ассетов */
				onStart: (total: number) =>
				{
				},

				/** Вызывается при успешной загрузке одного ассета */
				onAssetLoaded: (path: string, metadata: AnAssetMetadata) =>
				{
				},

				/** Вызывается при завершении всей загрузки */
				onComplete: (successCount: number, errorCount: number) =>
				{
				}
			}
		);

		// делаем оставшиеся важные загрузки
		// ...

		//на всякий случай
		this.callbacks?.onProgress?.(100);

		//загрузка полностью завершена, можно закрыть прелоадер
		this.callbacks?.onComplete?.();
	}

	protected override createUI()
	{
		//создаём фон
		const background = this.addUIElement("background",
			new AnImage({
				sprite: 'preloader/preloaderBG.tex.pixi.jpg',
				tint: 0xFF3249,
				anchor: AnAnchor.TopLeft,
				resizeStrategy: () =>
				{
					background.position.set(0, 0);
					background.setSize(AnViewport.width, AnViewport.height);
				}
			}
			)
		);

		//создаём лого
		const logo = this.addUIElement("logo",
			new AnImage({
				sprite: 'preloader/anegLogo.tex.pixi.png',
				anchor: AnAnchor.Center,
				resizeStrategy: () =>
				{
					logo.applyDefaultResizeStrategy();
					logo.position.set(AnViewport.width * 0.5, AnViewport.height * 0.5);
				}
			})
		);

		// создаём прогрессбар
		const progressBar = this.addUIElement("progressBar",
			new AnProgressBar(
				{
					value: 0,
					anchor: AnAnchor.Center,
					resizeStrategy: () =>
					{
						progressBar.scaledWidth = logo.width * 1.2;
						progressBar.scaledHeight = 15 * AnViewport.scale;

						progressBar.applyDefaultResizeStrategy();

						progressBar.position.set(AnViewport.width * 0.5, logo.bottom + 50 * AnViewport.scale);
					}
				})
		);

		// создаём текст с процентами загрузки
		const textPercent = this.addUIElement("textPercent",
			new AnLabel(
				{
					text: {
						textSource: () => (progressBar.value * 100).toFixed(0) + "%",
						fontName: "sysFont",
						fontSize: 40,
						autoUpdateLang: false,
					},
					anchor: AnAnchor.Center,
					resizeStrategy: () =>
					{
						textPercent.applyDefaultResizeStrategy();
						textPercent.position.set(AnViewport.width * 0.5, progressBar.bottom + 50 * AnViewport.scale);

					}
				})
		);

		// this.textTween = new AnTween({
		// 	target: this.elements['textPercent'],
		// 	from: { scale: { x: 1.3, y: 1.3 } },
		// 	to: { scale: { x: 1, y: 1 } },
		// 	duration: 2,
		// 	easing: AnEase.easeOutBounce,
		// 	updater: this.localUpdater,
		// 	autoStart: false,
		// 	autoRemove: false
		// 	//tags: ['terminate']
		// });
	}

	//создать твины анимации входа меню
	protected override createEntranceTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		///////////////////////////////////////
		// ENTRANCE
		///////////////////////////////////////

		tweens.push(new AnTween({
			target: this.elements['logo'],
			from: { alpha: 0, scale: { x: 0.1, y: 0.1 }, rotation: 10 * AnMath.toRad },
			to: { alpha: 1, scale: { x: 1, y: 1 }, rotation: 0 },
			delay: 1, duration: 5,
			easing: AnEase.easeOutElastic,
		}));


		tweens.push(new AnTween({
			target: this.elements['progressBar'],
			from: { alpha: 0, scale: { x: 0.1, y: 1 } },
			to: { alpha: 1, scale: { x: 1, y: 1 } },
			delay: 1, duration: 2,
			easing: AnEase.easeOutBack,
		}));


		tweens.push(new AnTween({
			target: this.elements['textPercent'],
			from: { alpha: 0 },
			to: { alpha: 1 },
			delay: 3, duration: 4,
			easing: AnEase.easeOut,
		}));

		AnRender2D.addToFront(new AnFader({ type: 'out' }));

		return tweens;
	}

	//создать твины анимации выхода из меню
	protected override createExitTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		//можно пропустить анимации прелоадера, чтобы ускорить переход к игре
		if (this.skipExitAnimations) return [];

		///////////////////////////////////////
		// EXIT
		///////////////////////////////////////

		tweens.push(new AnTween({
			target: this.elements['logo'],
			to: { alpha: 0, scale: { x: 0.1, y: 0.1 } },
			from: { alpha: 1, scale: { x: 1, y: 1 } },
			delay: 0, duration: 4,
			tags: ['terminate'],
			easing: AnEase.easeInElastic,
		}));


		tweens.push(new AnTween({
			target: this.elements['progressBar'],
			to: { alpha: 0, scale: { x: 0.1, y: 1 } },
			from: { alpha: 1, scale: { x: 1, y: 1 } },
			delay: 0, duration: 2,
			easing: AnEase.easeInBack,
		}));


		tweens.push(new AnTween({
			target: this.elements['textPercent'],
			to: { alpha: 0, scale: { x: 0.5, y: 0.5 }, y: this.elements['textPercent'].y + 50 * AnViewport.scale },
			from: { alpha: 1, scale: { x: 1, y: 1 }, y: this.elements['textPercent'].y },
			delay: 1, duration: 3,
			easing: AnEase.easeOut,
		}));

		AnRender2D.addToFront(new AnFader({ type: 'in', delay: 2 }));

		return tweens;
	}

}
