import seedrandom from 'seedrandom';
import { AnVoidCallback } from './AnHelpers';


export type AnChanceAction =
	{
		chance: number; // Вероятность события (от 0 до 1)
		action: AnVoidCallback;     // Функция, которая будет вызвана
	};


/**
 * Класс для генерации случайных чисел. 
 * При статическом использовании - простая генерация,
 * при создании экземпляра - используется указанное зерно.
 */
export class AnRnd
{
	private rng: seedrandom.PRNG;
	private _seed: string;

	/**
	 * Создает экземпляр генератора случайных чисел
	 * @param seed Зерно для генератора. Если не указано, генерируется случайная строка.
	 */
	constructor(seed: string = '')
	{
		if (seed === '')
		{
			seed = AnRnd.string(20);
		}

		this.rng = seedrandom(seed);
		this._seed = seed;
	}

	/** Получить текущее зерно генератора */
	get seed(): string
	{
		return this._seed;
	}

	/** Установить новое зерно генератора */
	set seed(seed: string)
	{
		this._seed = seed;
		this.rng = seedrandom(seed);
	}

	// =========== МЕТОДЫ ЭКЗЕМПЛЯРА (С ЗЕРНОМ) ===========

	/** Получить случайный знак (-1 или 1) */
	public seed_sgn(): number
	{
		return this.rng() > 0.5 ? -1 : 1;
	}

	/** 
	 * Получить случайное булево значение
	 * @param chanceToTrue Вероятность true (0.8 = 80% chance)
	 */
	public seed_bool(chanceToTrue: number = 0.5): boolean
	{
		return this.rng() < chanceToTrue;
	}

	/** 
	 * Получить случайное число с плавающей точкой из диапазона
	 * @param clow Нижняя граница диапазона
	 * @param chigh Верхняя граница диапазона
	 */
	public seed_float(clow: number = 0.0, chigh: number = 1.0): number
	{
		return this.rng() * (chigh - clow) + clow;
	}

	/** 
	 * Получить целое случайное число из диапазона
	 * @param clow Нижняя граница диапазона
	 * @param chigh Верхняя граница диапазона
	 */
	public seed_int(clow: number, chigh: number): number
	{
		return Math.floor(this.rng() * (chigh - clow + 1)) + clow;
	}

	/** 
	 * Получить случайную строку заданной длины
	 * @param length Длина строки
	 * @param charactersToUse Набор символов для генерации (по умолчанию a-zA-Z0-9)
	 */
	public seed_string(length: number, charactersToUse: string = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"): string
	{
		let str = "";
		for (let i = 0; i < length; i++)
		{
			str += charactersToUse.charAt(this.seed_int(0, charactersToUse.length - 1));
		}
		return str;
	}

	// =========== СТАТИЧЕСКИЕ МЕТОДЫ (БЕЗ ЗЕРНА) ===========

	/** Получить случайный знак (-1 или 1) */
	public static sgn(): number
	{
		return Math.random() > 0.5 ? -1 : 1;
	}

	/** 
	 * Получить случайное булево значение
	 * @param chanceToTrue Вероятность true (0.8 = 80% chance)
	 */
	public static bool(chanceToTrue: number = 0.5): boolean
	{
		return Math.random() < chanceToTrue;
	}

	/** 
	 * Получить случайное число с плавающей точкой из диапазона
	 * @param clow Нижняя граница диапазона
	 * @param chigh Верхняя граница диапазона
	 */
	public static float(clow: number = 0.0, chigh: number = 1.0): number
	{
		return Math.random() * (chigh - clow) + clow;
	}

	/** 
	 * Получить целое случайное число из диапазона
	 * @param clow Нижняя граница диапазона
	 * @param chigh Верхняя граница диапазона
	 */
	public static int(clow: number, chigh: number): number
	{
		return Math.floor(Math.random() * (chigh - clow + 1)) + clow;
	}

	/** 
	 * Получить случайную строку заданной длины
	 * @param length Длина строки
	 * @param charactersToUse Набор символов для генерации (по умолчанию a-zA-Z0-9)
	 */
	public static string(length: number, charactersToUse: string = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"): string
	{
		let str = "";
		for (let i = 0; i < length; i++)
		{
			str += charactersToUse.charAt(AnRnd.int(0, charactersToUse.length - 1));
		}
		return str;
	}

	// инициация события по вероятности (с нормализацией вероятностей)
	public static executeByChance<T>(events: AnChanceAction[], rnd?: AnRnd)
	{
		// Нормализация вероятностей (на случай, если сумма не равна 1)
		const totalProbability = events.reduce((sum, event) => sum + event.chance, 0);
		if (totalProbability <= 0)
		{
			return; // Нет событий для выполнения
		}

		// Генерация случайного числа от 0 до 1
		const randomValue = (rnd ? rnd.seed_float() : AnRnd.float()) * totalProbability;
		let cumulativeProbability = 0;

		// Поиск события, которое должно сработать
		for (const event of events)
		{
			cumulativeProbability += event.chance;
			if (randomValue <= cumulativeProbability)
			{
				event.action(); // Вызов функции при выпадении нужной вероятности
				return;
			}
		}

		return; // На случай ошибки (не должно происходить, если сумма вероятностей > 0)
	}
}