import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnButton, AnButtonConfig } from "angine/ui/AnButton.js";
import { UIGoalCounter } from "./UIGoalCounter.js";
import { scaled, AnViewport } from "angine/core/AnViewport.js";
import { AnCounterLayout } from "angine/ui/AnCounter.js";
import { AnRnd } from "angine/utils/AnRnd.js";
import { AnLabel } from "angine/ui/AnLabel.js";
import { AnTextAlign } from "angine/2D/AnText.js";
import { GameColor, GameColorsDB, GameTheme } from "./Game.js";
import { AnImage } from "angine/ui/AnImage.js";
import { PropBlockTypeArray } from "./Block.js";
import { getSpriteXCentralDistribution } from "angine/utils/AnHelpers.js";

export interface AnShopButtonConfig extends AnButtonConfig
{
	id: number,
	theme?: GameTheme;
	color?: GameColor;
}


export class UIShopButton extends AnButton
{
	private coinsCounter!: UIGoalCounter;
	private title!: AnLabel;
	private selector!: AnImage;

	private isThemeButton: boolean = false;
	private themeIcons: AnImage[] = [];

	constructor(config: AnShopButtonConfig)
	{
		const isThemeButton = config.theme !== undefined;

		// добавляем иконку цветов
		if (!isThemeButton)
		{
			config = {
				...config,

				icon: {
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './colorChoose',
					tint: GameColorsDB[config.color!].shopColorTint ?? GameColorsDB[config.color!].baseColorTint,
				},
				iconScale: { x: 0.55, y: 0.95 }
			};
		}

		super(config);

		this.isThemeButton = isThemeButton;


		if (isThemeButton)
			this.addThemeIcons(config.theme!);

		this.coinsCounter = this.addUIElement("coinsCounter",
			new UIGoalCounter(
				{
					currentCount: 0,
					maxCount: Infinity,
					iconType: "coin_mod",
					anchor: AnAnchor.LeftCenter,
					layout: AnCounterLayout.Horizontal,
					resizeStrategy: () =>
					{
						this.coinsCounter.scaledWidth = this.scaledWidth * 0.9;
						this.coinsCounter.scaledHeight = this.scaledHeight * 0.5;
						this.coinsCounter.applyDefaultResizeStrategy();

						this.coinsCounter.position.set(this.scaledWidth * 0.5 - this.coinsCounter.width * 0.5, this.scaledHeight * 0.5);
					}
				}
			)
		);


		this.title = this.addUIElement(
			"title",
			new AnLabel({
				text: {
					textSource: () => "???",
					fontName: "mainFont",
					fontSize: 60,
					textAlign: AnTextAlign.Center,
					autoUpdateLang: false,
					shadowAlpha: 0.7,
					//anchor: AnAnchor.TopLeft,
				},
				//backgroundColor: 0x333333,
				labelAlign: AnTextAlign.Center,
				anchor: AnAnchor.Center,
				resizeStrategy: () =>
				{
					this.title!.scaledWidth = this.scaledWidth;
					this.title!.scaledHeight = this.scaledHeight;
					this.title!.applyDefaultResizeStrategy();
					this.title!.position.set(this.scaledWidth * 0.5, this.scaledHeight * 0.5);
				}
			})
		);

		this.selector = this.addUIElement("selector",
			new AnImage(
				{
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: `./selItem`,
					anchor: AnAnchor.Center,
					slice9: {
						left: 40, right: 40, top: 40, bottom: 40
					},
					resizeStrategy: () =>
					{
						this.selector.scaledWidth = this.scaledWidth + scaled(20);
						this.selector.scaledHeight = this.scaledHeight + scaled(20);
						this.selector.scale9Adopt = AnViewport.scale * 0.7;
						this.selector.applyDefaultResizeStrategy();

						this.selector.position.set(this.scaledWidth * 0.5, this.scaledHeight * 0.5);
					}
				})
		);
		this.selector.tint = 0x11dd00;
	}

	private addThemeIcons(theme: GameTheme)
	{
		const propCount = PropBlockTypeArray.length;


		for (let i = 0; i < propCount; ++i)
		{
			const icon = this.addUIElement("icon" + i,
				new AnImage(
					{
						atlas: 'atlases/game.ss.pixi.atlas',
						sprite: `./prop_${i}_${theme}`,
						anchor: AnAnchor.Center,
						resizeStrategy: () =>
						{
							const paddingFactor = 1;
							const iconSize = paddingFactor * this.scaledHeight * 0.7;

							icon.scaledWidth = iconSize;
							icon.scaledHeight = iconSize;
							icon.applyDefaultResizeStrategy();

							icon.y = this.scaledHeight * (0.5 /*+ (i % 2 === 0 ? -0.05 : 0.05)*/);
							icon.x = getSpriteXCentralDistribution(i, iconSize, this.scaledWidth * paddingFactor, propCount, -1) + 0.5 * (this.scaledWidth * (1.0 - paddingFactor));
						}
					})
			);

			this.themeIcons.push(icon);
		}
	}

	public showAsUnlocked(showSelector: boolean = false)
	{
		this.sprite.changeTexture('./button', 'atlases/game.ss.pixi.atlas');
		this.coinsCounter.visible = false;
		this.selector.visible = showSelector;
		if (this.icon)
		{
			this.icon.alpha = 1;
			this.icon.visible = true;
		}
		this.title.visible = false;

		if (this.themeIcons.length)
			for (const theme of this.themeIcons)
			{
				theme.visible = true;
				theme.alpha = 1.0;
			}
	}

	public showAsItemToBuy(cost: number, totalCoins: number)
	{
		this.sprite.changeTexture('./buttonHover', 'atlases/game.ss.pixi.atlas');
		this.coinsCounter.visible = true;
		this.coinsCounter.updateValue(cost, false);
		this.coinsCounter.updateTextColor(cost > totalCoins ? 0xff4034 : 0xffffff);
		this.selector.visible = false;
		if (this.icon)
		{
			this.icon.alpha = 0.5;
			this.icon.visible = true;
		}
		this.title.visible = false;

		if (this.themeIcons.length)
			for (const theme of this.themeIcons)
			{
				theme.visible = true;
				theme.alpha = 0.1;
			}
	}

	public showAsLocked()
	{
		this.sprite.changeTexture('./buttonHover', 'atlases/game.ss.pixi.atlas');
		this.coinsCounter.visible = false;
		if (this.icon) this.icon.visible = false;
		this.title.visible = true;
		this.selector.visible = false;

		if (this.themeIcons.length)
			for (const theme of this.themeIcons)
				theme.visible = false;
	}
}