import { AnTextAlign } from "angine/2D/AnText.js";
import { AnTween } from "angine/anim/AnTween.js";
import { AnViewport } from "angine/core/AnViewport.js";
import { AnMenu, AnMenuConfig } from "angine/menu/AnMenu.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnImage } from "angine/ui/AnImage.js";
import { AnLabel } from "angine/ui/AnLabel.js";
import { AnLog } from "angine/utils/AnLog.js";
import { AnDialogue } from 'angine/ui/AnDialogue.js';
import { AnVoidCallback, runAfter, runAfterSafe } from "angine/utils/AnHelpers.js";
import { AnEase } from "angine/anim/AnEase.js";


export interface IntroCallbacks 
{
	onComplete?: AnVoidCallback;
}

export interface IntroConfig extends AnMenuConfig
{
	callbacks?: IntroCallbacks;
}

export class Intro extends AnMenu
{
	private callbacks: IntroCallbacks;

	public constructor(config: IntroConfig)
	{
		super(config);

		this.callbacks = config.callbacks ?? {};
	}


	public start()
	{
		this.createUI();
		this.resizeUI();
		this.show();
	}

	protected createUI(): void
	{
		const background = this.addUIElement("background",
			new AnImage({
				sprite: 'images/background.tex.pixi.jpg',
				anchor: AnAnchor.TopLeft,
				resizeStrategy: () =>
				{
					background.position.set(0, 0);
					background.scaledWidth = AnViewport.width;
					background.scaledHeight = AnViewport.height;
					background.applyDefaultResizeStrategy();

				}
			}
			)
		);

		// const label = this.addUIElement(
		// 	"label",
		// 	new AnLabel({
		// 		text: {
		// 			textSource: "Привет! Рад тебя видеть в моей игре. Правила очень простые. Начнем?\n CHAIN & GAIN",
		// 			fontName: "mainFont",
		// 			fontSize: 90,
		// 			textAlign: AnTextAlign.Center,
		// 			autoUpdateLang: false,
		// 			shadowAlpha: 0.7,
		// 			wordWarp: false,
		// 		},
		// 		backgroundColor: 0x333333,
		// 		labelAlign: AnTextAlign.Center,
		// 		anchor: AnAnchor.Center,

		// 		resizeStrategy: () =>
		// 		{
		// 			label.scaledWidth = AnViewport.width;
		// 			label.applyDefaultResizeStrategy();
		// 			label.position.set(AnViewport.halfWidth, AnViewport.halfHeight);

		// 		}
		// 	})
		// );

		const dialogue = this.addUIElement("dialogue", new AnDialogue({
			text: {
				textSource: "Привет! Рад тебя видеть в игре. Правила очень простые. Начинаем?",
				fontName: "mainFont",
				fontSize: 100,
				textAlign: AnTextAlign.Center,
				autoUpdateLang: false,
				shadowAlpha: 0.4,
				shadowOffsetX: 3,
				shadowOffsetY: 3,
			},
			anchor: AnAnchor.Center,
			speedFactor: 0.5,
			baseRealWidth: 800,
			resizeStrategy: () =>
			{
				const dialogueWidth = AnViewport.width * 0.7;
				dialogue.setScaledSize(dialogueWidth, dialogueWidth / dialogue.realSizeRatio);
				dialogue.applyDefaultResizeStrategy();

				dialogue.position.set(AnViewport.halfWidth, AnViewport.halfHeight);
			}

		}));


		const frame = this.addUIElement("frame",
			new AnImage(
				{
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './cell',
					anchor: AnAnchor.Center,
					slice9: {
						left: 18,
						right: 18,
						top: 18,
						bottom: 20,
					},
					resizeStrategy: () =>
					{
						const frameWidth = AnViewport.width * 0.9;
						frame.scaledWidth = frameWidth;
						frame.scaledHeight = frameWidth / dialogue.realSizeRatio * 1.1;
						frame.applyDefaultResizeStrategy();

						frame.position.set(AnViewport.halfWidth, AnViewport.halfHeight);
					}
				})
		);

	}

	protected createEntranceTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		tweens.push(new AnTween({
			target: this.elements['frame'],
			from: { alpha: 0, scale: { x: 0.7, y: 0.7 } },
			to: { alpha: 2, scale: { x: 1, y: 1 } },
			delay: 0.5, duration: 2,
			easing: AnEase.easeOutBack,
		}));


		runAfterSafe(2, this, () => (this.elements['dialogue'] as AnDialogue).startAnimation(() =>
			runAfterSafe(1, this, () => this.hide(this.callbacks.onComplete))));


		return tweens;
	}

	protected createExitTweens(): AnTween[]
	{
		const tweens: AnTween[] = [];

		tweens.push(new AnTween({
			target: this.elements['frame'],
			to: { alpha: 0, scale: { x: 0.7, y: 0.7 } },
			from: { alpha: 2, scale: { x: 1, y: 1 } },
			delay: 2, duration: 2,
			easing: AnEase.easeOut,
			tags: ["terminate"]
		}));

		(this.elements['dialogue'] as AnDialogue).exitAnimation();

		return tweens;
	}
}