import { GameAnalytics as GA } from 'gameanalytics'; //! remove duplicate enums !
import { forbidAnalyticsForPlatform, Platform } from '../platform/Platform.js';
import { AnLog } from 'angine/utils/AnLog.js';

enum EGAErrorSeverity
{
	Undefined = 0,
	Debug = 1,
	Info = 2,
	Warning = 3,
	Error = 4,
	Critical = 5
}
enum EGAProgressionStatus
{
	Undefined = 0,
	Start = 1,
	Complete = 2,
	Fail = 3
}
enum EGAResourceFlowType
{
	Undefined = 0,
	Source = 1,
	Sink = 2
}
enum EGAAdAction
{
	Undefined = 0,
	Clicked = 1,
	Show = 2,
	FailedShow = 3,
	RewardReceived = 4
}
enum EGAAdError
{
	Undefined = 0,
	Unknown = 1,
	Offline = 2,
	NoFill = 3,
	InternalError = 4,
	InvalidRequest = 5,
	UnableToPrecache = 6
}
enum EGAAdType
{
	Undefined = 0,
	Video = 1,
	RewardedVideo = 2,
	Playable = 3,
	Interstitial = 4,
	OfferWall = 5,
	Banner = 6
}

const GAME_KEY = "5686b74dfde74f7d94a65ec8bc63c784";
const SECRET_KEY = "5d0d624a01aca2785541970ec175a605f9383936";

// можно запретить посылать данные в аналитику в режиме разработки
const NO_ANALYTICS_IN_DEVMODE = true;


// проверка отключена ли аналитика
function forbidAnalytics(): boolean { return (AnConfig.devMode && NO_ANALYTICS_IN_DEVMODE) || forbidAnalyticsForPlatform(); }

// определяем рекламную сетку (совпадает с платформой)
function sdkName(): string { return String(Platform.type).toLowerCase(); }

export class Analytics
{

	public static init(config: { currencies: string[], itemTypes: string[] })
	{
		if (forbidAnalytics()) return;

		const ver = `${AnConfig.platform} ${AnConfig.gameVersion}`;

		if (AnConfig.devMode)
			AnLog.debug(`Аналитика работает: ${ver}`);

		GA.configureBuild(ver);
		GA.configureAvailableResourceCurrencies(config.currencies);
		GA.configureAvailableResourceItemTypes(config.itemTypes);

		GA.initialize(GAME_KEY, SECRET_KEY);

		if (AnConfig.devMode)
			GA.setEnabledInfoLog(true);
	}


	// *********************** ADS ***********************

	public static onRewardedAdShow(placement: string)
	{
		if (forbidAnalytics()) return;
		GA.addAdEvent(EGAAdAction.Show, EGAAdType.RewardedVideo, sdkName(), placement);
	}
	public static onRewardedAdReceived(placement: string)
	{
		if (forbidAnalytics()) return;
		GA.addAdEvent(EGAAdAction.RewardReceived, EGAAdType.RewardedVideo, sdkName(), placement);
	}
	public static onRewardedAdError(placement: string)
	{
		if (forbidAnalytics()) return;
		GA.addAdEvent(EGAAdAction.FailedShow, EGAAdType.RewardedVideo, sdkName(), placement);
	}

	public static onFullscreenAdShow(placement: string)
	{
		if (forbidAnalytics()) return;
		GA.addAdEvent(EGAAdAction.Show, EGAAdType.Interstitial, sdkName(), placement);
	}
	public static onFullscreenAdError(placement: string)
	{
		if (forbidAnalytics()) return;
		GA.addAdEvent(EGAAdAction.FailedShow, EGAAdType.Interstitial, sdkName(), placement);
	}

	// *********************** RESOURCE ***********************

	public static onGetResource(resource: string, amount: number, type?: string, item?: string)
	{
		if (forbidAnalytics()) return;
		GA.addResourceEvent(EGAResourceFlowType.Source, resource, amount, type, item);
	}

	// type - категория предмета который куплен (weapons)
	// item - конкретное название предмета (big_sword)
	public static onLostResource(resource: string, amount: number, type?: string, item?: string)
	{
		if (forbidAnalytics()) return;
		GA.addResourceEvent(EGAResourceFlowType.Sink, resource, amount, type, item);
	}

	// *********************** PROGRESS ***********************

	public static onLevelStart(level: string)
	{
		if (forbidAnalytics()) return;
		GA.addProgressionEvent(EGAProgressionStatus.Start, level);
	}

	public static onLevelFail(level: string, score?: number)
	{
		if (forbidAnalytics()) return;
		GA.addProgressionEvent(EGAProgressionStatus.Fail, level, undefined, undefined, score);
	}

	public static onLevelComplete(level: string, score?: number)
	{
		if (forbidAnalytics()) return;
		GA.addProgressionEvent(EGAProgressionStatus.Complete, level, undefined, undefined, score);
	}

	// *********************** CUSTOM ***********************

	// The eventId is a hierarchy string that can consist of 
	// 1 - 5 segments separated by ‘:’. Each segment can have 
	// a max length of 32.
	// e.g: StartGame:ClassLevel1_5
	// 
	// value - result in sum & mean values being available.
	public static onEvent(event: string, value?: number)
	{
		if (forbidAnalytics()) return;
		GA.addDesignEvent(event, value);
	}

}