import { AnVoidCallback, Constructor, runAfter, runAfterSafe, shuffle } from "angine/utils/AnHelpers.js";
import { CellSize, CellHalfSize, Field, GridPos } from "./Field.js";
import { AnEase } from "angine/anim/AnEase.js";
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnFX } from "angine/ui/AnFX.js";
import { AnLog } from "angine/utils/AnLog.js";
import { AnMath } from "angine/utils/AnMath.js";
import { AnRnd } from "angine/utils/AnRnd.js";
import { AnTimer } from "angine/utils/AnTimer.js";
import { Block } from "./Block.js";
import { G } from "./G.js";
import { CellModifier } from "./Cell.js";
import { AnMainLoop } from "angine/core/AnMainLoop.js";
import { AnEvents } from "angine/utils/AnEvents.js";
import { GameApp } from "../GameApp.js";
import { GameTutorial } from "./GameTutorialMixin.js";
import { AnSounds } from "angine/audio/AnSounds.js";


export function FieldSpecialsMixin<TBase extends Constructor>(Base: TBase)
{
	return class extends Base
	{
		constructor(...args: any[])
		{
			super(...args);

			// Дополнительная проверка во время выполнения
			if (!(this instanceof Field))
				throw new Error('FieldSpecialsMixin может использоваться только с классом Field!');
		}

		protected activateStone(stone: Block, destroyFunc?: AnVoidCallback)
		{
			const field = this as unknown as Field;
			const pixelPos = stone.gridPos.toPixelPos();
			const debrisCount = 10;

			stone.renderable = false;

			AnSounds.play(
				`sounds/spec_stone0${AnRnd.int(1, 3)}.snd.mp3`,
				0.6,
				AnMath.remapClamp(stone.gridPos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
				AnRnd.float(0.9, 1.1)
			);

			const blastCount = 3;
			for (let i = 0; i < blastCount; ++i)
			{
				const maxScale = AnRnd.float(2, 3);
				const blastFX = new AnFX({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './fxBlastMini',
					anchor: AnAnchor.Center,
					loopTween: {
						from: {
							alpha: 0.7,
							scale: { x: 0.6, y: 0.6 }
						},
						to: {
							alpha: 0,
							scale: { x: maxScale, y: maxScale }
						},
						duration: AnRnd.float(1, 2),
						easing: AnEase.easeOut,
					},
					updater: field.getUpdater(),
				});
				blastFX.position.set(pixelPos.x + AnRnd.float(-CellHalfSize * 0.5, CellHalfSize * 0.5), pixelPos.y + AnRnd.float(-CellHalfSize * 0.5, CellHalfSize * 0.5));
				blastFX.blendMode = G.forceLowQulity ? "normal" : "add";
				field.fxLayer.attach(blastFX);
				field.addGraphics(blastFX);
			}




			for (let i = 0; i < debrisCount; ++i)
			{
				const targetPosX = AnRnd.float(-CellSize * 2.5, CellSize * 2.5);// + AnRnd.float(-CellHalfSize, CellHalfSize);
				const targetPosY = AnRnd.float(-CellSize * 2.5, CellSize * 2.5);// + AnRnd.float(-CellHalfSize, CellHalfSize);
				const debrisFX = new AnFX({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './fxStoneDeb' + AnRnd.int(0, 3),
					anchor: AnAnchor.Center,
					loopTween: {
						from: { alpha: 3, scale: { x: AnRnd.float(0.3, 0.6), y: AnRnd.float(0.3, 0.6) }, rotation: 0, position: { x: pixelPos.x, y: pixelPos.y } },
						to: { alpha: 0, scale: { x: AnRnd.float(0.5, 1.2), y: AnRnd.float(0.5, 1.2) }, rotation: AnRnd.float(-Math.PI, Math.PI), position: { x: pixelPos.x + targetPosX, y: pixelPos.y + targetPosY } },
						duration: AnRnd.float(1, 2.5) * 0.6,
						easing: AnEase.easeOut,
					},
					updater: field.getUpdater(),
				});
				field.animLayer.attach(debrisFX);
				field.addGraphics(debrisFX);
			}

			AnEvents.emit("gameplay:other:apply", { type: "spec_stone", score: 1 });

			destroyFunc?.();
		}

		protected activateHeart(heart: Block, destroyFunc?: AnVoidCallback)
		{
			const field = this as unknown as Field;
			const block = new Block({
				pos: heart.gridPos,
				type: "prop_heart",
				skipCreatingAnim: true,
				updater: field.getUpdater(),
				selectionLayer: field.selectionLayer,
				blockLayer: field.blockLayer,
			});


			AnSounds.play(
				`sounds/spec_heart.snd.mp3`,
				0.6,
				AnMath.remapClamp(heart.gridPos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
				AnRnd.float(0.9, 1.1)
			);

			field.cells[heart.gridPos.row][heart.gridPos.col].block = block;
			field.blocks.push(block);
			field.addUIElement(block);
			field.applyBlock(block);

			const pixelPos = heart.gridPos.toPixelPos();
			const debrisCount = 25;
			for (let i = 0; i < debrisCount; ++i)
			{
				const targetPosX = AnRnd.float(-CellSize * 2.5, CellSize * 2.5);// + AnRnd.float(-CellHalfSize, CellHalfSize);
				const targetPosY = AnRnd.float(-CellSize * 2.5, CellSize * 2.5);// + AnRnd.float(-CellHalfSize, CellHalfSize);
				const debrisFX = new AnFX({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './fxChainDeb' + AnRnd.int(0, 5),
					anchor: AnAnchor.Center,
					loopTween: {
						from: { alpha: 3, scale: { x: AnRnd.float(0.6, 1), y: AnRnd.float(0.6, 1) }, rotation: 0, position: { x: pixelPos.x, y: pixelPos.y } },
						to: { alpha: 0, scale: { x: AnRnd.float(1, 1.2), y: AnRnd.float(1, 1.2) }, rotation: AnRnd.float(-Math.PI, Math.PI), position: { x: pixelPos.x + targetPosX, y: pixelPos.y + targetPosY } },
						duration: AnRnd.float(1, 2.5) * 0.6,
						easing: AnEase.easeOut,
					},
					updater: field.getUpdater(),
				});
				field.animLayer.attach(debrisFX);
				field.addGraphics(debrisFX);
			}


			heart.renderable = false;
			destroyFunc?.();
		}

		protected activateDice(dice: Block, destroyFunc?: AnVoidCallback)
		{
			// Проверяем, установлен ли activatedType
			if (!dice.activatedType)
			{
				destroyFunc?.();
				return;
			}

			const pos = dice.gridPos;
			//runAfter(0.1, () =>
			//{
			AnSounds.play(
				`sounds/spec_dice.snd.mp3`,
				0.6,
				AnMath.remapClamp(pos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
				AnRnd.float(0.9, 1.1)
			)
			//});

			const field = this as unknown as Field;
			const affectedBlocks: Block[] = [];

			// Проходим по всему полю и собираем ВСЕ блоки
			for (let row = 0; row < field.rowsCount; row++)
			{
				for (let col = 0; col < field.colsCount; col++)
				{
					const cell = field.getCell(row, col);
					if (cell)
					{
						const block = cell.block;
						if (block && block.prop &&
							!block.highlighted &&
							block.type !== dice.activatedType &&
							!cell.hasModifier(CellModifier.Cage))
						{
							const rndSeed = field.colRndSeed[col];
							// С вероятностью 30% добавляем блок в affectedBlocks
							if (rndSeed.seed_bool(0.3))
							{
								block.highlighted = true;
								affectedBlocks.push(block);
							}
						}
					}
				}
			}

			if (!affectedBlocks.length)
			{
				destroyFunc?.();
				return;
			}

			// Перемешиваем блоки для случайного порядка анимации
			shuffle(affectedBlocks);

			let currentIndex = 0;

			// Создаем таймер для последовательного изменения блоков
			new AnTimer({
				duration: 0.05,
				loopCount: affectedBlocks.length - 1,
				updater: field.getUpdater(),
				callbacks: {
					onComplete: () =>
					{
						const block = affectedBlocks[currentIndex];

						// если спешалы активируют краску тоже
						if (G.specialsSpreyPaint)
							block.activatedAndPainted = dice.activatedAndPainted;

						// Создаем анимацию изменения
						const pixelPos = block.gridPos.toPixelPos();
						const miniBlastCount = 1;
						for (let i = 0; i < miniBlastCount; ++i)
						{
							const diceFX = new AnFX({
								atlas: 'atlases/game.ss.pixi.atlas',
								sprite: './spec_dice',
								anchor: AnAnchor.Center,
								entranceTween: {
									from: {
										alpha: 0,
										//rotation: 0,
										scale: { x: 0.3, y: 0.3 }
									},
									to: {
										alpha: 0.5,
										//rotation: Math.PI / 8,
										scale: { x: 1.3, y: 1.3 }
									},
									duration: 1,
									easing: AnEase.easeOutBack,
								},
								exitTween: {
									to: {
										alpha: 0,
										//rotation: 0,
										scale: { x: 0.3, y: 0.3 }
									},
									duration: 1,
									easing: AnEase.easeInElastic,
									callbacks: {
										onComplete: () =>
										{
											block.highlighted = false
										}
									}
								},
								updater: field.getUpdater()
							});

							block.type = dice.activatedType!;


							// AnSounds.play(
							// 	`sounds/spec_dice.snd.mp3`,
							// 	AnRnd.float(0.4, 0.6) * 0.5,
							// 	AnMath.remapClamp(block.gridPos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
							// 	AnRnd.float(0.9, 1.1)
							// )

							const offsetX = i === 0 ? 0 : AnRnd.float(-CellSize * 0.5, CellSize * 0.5);
							const offsetY = i === 0 ? 0 : AnRnd.float(-CellSize * 0.5, CellSize * 0.5);
							diceFX.position.set(pixelPos.x + offsetX, pixelPos.y + offsetY);
							//diceFX.blendMode = G.forceLowQulity ? "normal" : "add";
							//field.fxLayer.attach(diceFX);
							field.addGraphics(diceFX);
						}

						// Увеличиваем счетчик
						currentIndex++;

						// Если это последний блок, вызываем destroyFunc
						if (currentIndex === affectedBlocks.length)
						{
							destroyFunc?.();
						}
					}
				}
			});
		}

		protected activateMirror(mirror: Block, destroyFunc?: AnVoidCallback)
		{
			if (!mirror.activatedBlocks || mirror.activatedBlocks.length === 0)
			{
				destroyFunc?.();
				return;
			}

			const field = this as unknown as Field;

			// Получаем позицию зеркального блока
			const mirrorPos = mirror.gridPos;

			// Получаем позиции выделенных блоков 
			const selectedBlocksPoses = mirror.activatedBlocks.map(block => block.gridPos.clone());

			// Собираем блоки для удаления (включая оригинальные и их отражения)
			//const blocksToRemove = new Set<Block>();
			const posToRemoveH: GridPos[] = [];
			const posToRemoveV: GridPos[] = [];

			// Находим отраженные позиции и добавляем соответствующие блоки
			for (const pos of selectedBlocksPoses)
			{
				// Горизонтальное отражение относительно зеркала (отражение по вертикальной оси)
				const hCol = mirrorPos.col + (mirrorPos.col - pos.col);
				const hRow = pos.row;
				if (!field.isOutOfBounds(hRow, hCol))
					posToRemoveH.push(new GridPos(hRow, hCol));

				// Вертикальное отражение относительно зеркала (отражение по горизонтальной оси)
				const vCol = pos.col;
				const vRow = mirrorPos.row + (mirrorPos.row - pos.row);
				if (!field.isOutOfBounds(vRow, vCol))
					posToRemoveV.push(new GridPos(vRow, vCol));
			}

			if (posToRemoveH.length === 0 && posToRemoveV.length === 0)
			{
				destroyFunc?.();
				return;
			}

			const createConnectionLine = (gridPosFrom: GridPos, gridPosTo: GridPos) =>
			{
				const colors = [0x9fe2ec, 0xa2f1f8, 0x96f0fd, 0x5cd4ed, 0xacf7fc, 0x80ebf9, 0xbaf8fd];

				const posFrom = gridPosFrom.toPixelPos();
				const posTo = gridPosTo.toPixelPos();


				AnSounds.play(
					`sounds/spec_mirror.snd.mp3`,
					0.6,
					AnMath.remapClamp(gridPosFrom.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
					AnRnd.float(0.9, 1.1)
				);


				// Вычисляем расстояние и угол между блоками
				const dx = posTo.x - posFrom.x;
				const dy = posTo.y - posFrom.y;
				const distance = Math.sqrt(dx * dx + dy * dy);
				const angle = Math.atan2(dy, dx);
				const lineScale = (distance + CellSize * 0.2) / 256;

				const rndSeed = field.colRndSeed[gridPosFrom.col];
				const lineFX = new AnFX({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './selectLine',
					anchor: AnAnchor.Center,
					loopTween: {
						from: { alpha: 0.3, scale: { y: 0.3, x: lineScale } },
						to: { alpha: 3, scale: { y: 1, x: lineScale } },
						tolerance: 0.2,
						duration: (2 - rndSeed.seed_float(0, 0.5)) / 2,
						easing: AnEase.easeOutElastic,
					},
					exitTween: {
						from: { alpha: 2, scale: { y: 1, x: lineScale } },
						to: { alpha: 0, scale: { y: 0.1, x: lineScale } },
						tolerance: 0.2,
						duration: 0.8,
						easing: AnEase.easeOut,
					},
					tint: colors[AnRnd.int(0, colors.length - 1)],
					updater: field.getUpdater()
				}
				);

				lineFX.scale.set(lineScale, 1);
				lineFX.rotation = angle;
				lineFX.position.set(posFrom.x + dx / 2, posFrom.y + dy / 2);
				lineFX.blendMode = G.forceLowQulity ? "normal" : "add";
				field.addGraphics(lineFX);
				field.fxLayer.attach(lineFX);
			}


			const makeMirrorConnections = (positions: GridPos[], andCallDestroyFunc: boolean = false) =>
			{
				let currentIndex = 0;
				new AnTimer({
					duration: 0.1,
					loopCount: positions.length - 1,
					updater: field.getUpdater(),
					callbacks: {
						onComplete: () =>
						{
							const gridPos = positions[currentIndex];

							let prevGridPos;
							if (currentIndex > 0)
								prevGridPos = positions[currentIndex - 1];


							//рисуем анимированные линии
							if (prevGridPos)
								createConnectionLine(gridPos, prevGridPos);
							else
								createConnectionLine(gridPos, mirrorPos);

							// Создаем анимацию удаления
							const cell = field.getCell(gridPos.row, gridPos.col);
							if (cell)
							{
								const block = cell.block;
								if (block && !block.highlighted && !cell.hasModifier(CellModifier.Cage))
								{
									// если спешалы активируют краску тоже
									if (G.specialsSpreyPaint)
										block.activatedAndPainted = mirror.activatedAndPainted;

									block.highlighted = true;
									const pixelPos = gridPos.toPixelPos();

									const blastFX = new AnFX({
										atlas: 'atlases/game.ss.pixi.atlas',
										sprite: './fxBlastMini',
										anchor: AnAnchor.Center,
										loopTween: {
											from: {
												alpha: 0.7,
												scale: { x: 0.6, y: 0.6 }
											},
											to: {
												alpha: 0,
												scale: { x: 2, y: 2 }
											},
											duration: 0.5,
											easing: AnEase.easeOut,
											callbacks: {
												onComplete: () =>
												{
													// Удаляем блок
													if (block.special) block.activatedType = mirror.activatedType;
													field.applyBlock(block);
												}
											}
										},
										updater: field.getUpdater(),
									});

									blastFX.position.set(pixelPos.x, pixelPos.y);
									blastFX.blendMode = G.forceLowQulity ? "normal" : "add";
									field.fxLayer.attach(blastFX);
									field.addGraphics(blastFX);


								}
							}

							// Увеличиваем счетчик
							currentIndex++;

							// Если это последний блок, вызываем destroyFunc
							if (currentIndex === positions.length && andCallDestroyFunc)
							{
								destroyFunc?.();
							}
						}
					}
				});
			}

			const destroyInH = posToRemoveH.length > posToRemoveV.length;
			if (posToRemoveH.length)
				makeMirrorConnections(posToRemoveH, destroyInH);
			if (posToRemoveV.length)
				makeMirrorConnections(posToRemoveV, !destroyInH);
		}

		protected activateChest(block: Block, destroyFunc?: AnVoidCallback)
		{
			const game = GameApp.self.game;
			const field = this as unknown as Field;

			const pos = block.gridPos;
			AnSounds.play(
				`sounds/spec_chest.snd.mp3`,
				0.6,
				AnMath.remapClamp(pos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
				AnRnd.float(0.9, 1.1)
			);

			// дропаем случайный бонус из сундука
			// 0 - ходы 1 - монеты 2 - блоки
			let bonus = -1;

			do
			{
				bonus = field.specRndSeed.seed_int(0, 2);
			}
			while (bonus === field.chestLastBonus);
			field.chestLastBonus = bonus;

			//детерминируем для обучения
			if (game.tutorial === GameTutorial.Chests)
			{
				if (game.tutorialStage === 1) bonus = 0; else
					if (game.tutorialStage === 2) bonus = 1;
			}

			let stayTime = 0.1;
			switch (bonus)
			{
				case 0:
					game.addMoves(G.chestBonusMovesCount);
					break;
				case 1:
					stayTime = 1;
					game.addCoins(G.chestBonusCoinsCount, block.gridPos);
					break;
				case 2:
					stayTime = 2;
					game.addActualProps(G.chestBonusPropsCount, block.gridPos);
					break;
			}

			block.setTypeNoAnim("spec_chest_opened");

			runAfterSafe(stayTime, field, () => destroyFunc?.());
		}

		protected activateRainbow(rainbow: Block, destroyFunc?: AnVoidCallback)
		{
			if (!rainbow.activatedType)
			{
				AnLog.error(`activatedType не установлен для rainbow!`);
				destroyFunc?.();
				return;
			}

			const field = this as unknown as Field;


			const pos = rainbow.gridPos;
			AnSounds.play(
				`sounds/spec_rainbow.snd.mp3`,
				0.6,
				AnMath.remapClamp(pos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
				AnRnd.float(0.9, 1.1)
			);

			const affectedBlocks: Block[] = [];

			// Проходим по всему полю и собираем блоки указанного типа
			for (let row = 0; row < field.rowsCount; row++)
			{
				for (let col = 0; col < field.colsCount; col++)
				{
					const cell = field.getCell(row, col);
					if (cell)
					{
						const block = cell.block;
						if (block &&
							block.type === rainbow.activatedType &&
							!block.highlighted &&
							!cell.hasModifier(CellModifier.Cage))
						{
							block.highlighted = true;
							affectedBlocks.push(block);
						}
					}
				}
			}

			if (!affectedBlocks.length)
			{
				destroyFunc?.();
				return;
			}

			shuffle(affectedBlocks);

			const createRainbowLine = (id: number, rainbow: Block, affectedBlock: Block) =>
			{
				const rainbowColors = [0xFF0000, 0xFF7F00, 0xFFFF00, 0x00FF00, 0x0000FF, 0x4B0082, 0x9400D3];

				const posA = rainbow.gridPos.toPixelPos();
				const posB = affectedBlock.gridPos.toPixelPos();


				// Вычисляем расстояние и угол между блоками
				const dx = posB.x - posA.x;
				const dy = posB.y - posA.y;
				const distance = Math.sqrt(dx * dx + dy * dy);
				const angle = Math.atan2(dy, dx);
				const lineScale = (distance + CellSize * 0.25) / 256;

				const rndSeed = field.colRndSeed[affectedBlock.gridPos.col];
				const lineFX = new AnFX({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './selectLine',
					anchor: AnAnchor.Center,
					loopTween: {
						from: { alpha: 0.3, scale: { y: 0.3, x: lineScale } },
						to: { alpha: 3, scale: { y: 1, x: lineScale } },
						tolerance: 0.2,
						duration: (2 - rndSeed.seed_float(0, 0.5)) / 2,
						delay: id * 0.1,
						easing: AnEase.easeOutElastic,
					},
					exitTween: {
						from: { alpha: 2, scale: { y: 1, x: lineScale } },
						to: { alpha: 0, scale: { y: 0.1, x: lineScale } },
						tolerance: 0.2,
						duration: 0.5,
						easing: AnEase.easeOut,
						callbacks: {
							onComplete: () =>
							{
								// если спешалы активируют краску тоже
								if (G.specialsSpreyPaint)
									affectedBlock.activatedAndPainted = rainbow.activatedAndPainted;

								if (affectedBlock.special) affectedBlock.activatedType = rainbow.activatedType;

								field.applyBlock(affectedBlock);

								if (id === affectedBlocks.length - 1) // последний блок уничтожен 
									destroyFunc?.();
							}
						}
					},
					tint: rainbowColors[AnRnd.int(0, rainbowColors.length - 1)],
					updater: field.getUpdater()
				}
				);

				lineFX.scale.set(lineScale, 1);
				lineFX.rotation = angle;
				lineFX.position.set(posA.x + dx / 2, posA.y + dy / 2);
				lineFX.blendMode = G.forceLowQulity ? "normal" : "add";
				field.addGraphics(lineFX);
				field.fxLayer.attach(lineFX);
			}


			for (let i = 0; i < affectedBlocks.length; ++i)
				createRainbowLine(i, rainbow, affectedBlocks[i]);

		}


		protected activateBomb(bomb: Block, destroyFunc?: AnVoidCallback)
		{
			const field = this as unknown as Field;
			const affectedBlocks: Block[] = [];
			const gridPos = bomb.gridPos.clone();
			const pixelPos = gridPos.toPixelPos();

			AnSounds.play(
				`sounds/spec_bomb.snd.mp3`,
				0.6,
				AnMath.remapClamp(gridPos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
				AnRnd.float(0.9, 1.1)
			);

			const blastFX = new AnFX({
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './fxBlastBig',
				anchor: AnAnchor.Center,
				loopTween: {
					from: {
						alpha: 1,
						scale: {
							x: 0.2,
							y: 0.2
						}
					},
					to: {
						alpha: 0,
						scale: {
							x: 2,
							y: 2
						}
					},
					duration: 2,
					easing: AnEase.easeOut,
				},
				updater: field.getUpdater()
			});
			// Добавляем анимацию на сцену
			blastFX.position.set(pixelPos.x, pixelPos.y);
			blastFX.blendMode = G.forceLowQulity ? "normal" : "add";
			field.fxLayer.attach(blastFX);
			field.addGraphics(blastFX);

			// Проверяем все 8 соседних позиций
			for (let row = gridPos.row - 1; row <= gridPos.row + 1; row++)
			{
				for (let col = gridPos.col - 1; col <= gridPos.col + 1; col++)
				{
					// Пропускаем саму бомбу
					if (row === gridPos.row && col === gridPos.col) continue;

					const cell = field.getCell(row, col);
					if (cell)
					{
						const neighbor = cell.block;
						if (neighbor && !neighbor.highlighted && !cell.hasModifier(CellModifier.Cage))
						{
							neighbor.highlighted = true;
							affectedBlocks.push(neighbor);
						}
					}
				}
			}

			// если нет задействованых блоков - просто выходим
			if (!affectedBlocks.length)
			{
				destroyFunc?.();
				return;
			}

			// перемешиваем в случайном порядке
			shuffle(affectedBlocks);

			let currentIndex = 0;
			const timer = new AnTimer({
				duration: 0.2,
				loopCount: affectedBlocks.length - 1,
				updater: field.getUpdater(),
				callbacks: {
					onComplete: () =>
					{
						const block = affectedBlocks[currentIndex];

						// если спешалы активируют краску тоже
						if (G.specialsSpreyPaint)
							block.activatedAndPainted = bomb.activatedAndPainted;

						const pixelPos = block.gridPos.toPixelPos();

						const miniBlastCount = 3;
						for (let i = 0; i < miniBlastCount; ++i)
						{
							const blastFX = new AnFX({
								atlas: 'atlases/game.ss.pixi.atlas',
								sprite: './fxBlastMini',
								anchor: AnAnchor.Center,
								loopTween: {
									from: {
										alpha: 0.7,
										scale: {
											x: 0.3,
											y: 0.3
										}
									},
									to: {
										alpha: 0,
										scale: {
											x: 3,
											y: 3
										}
									},
									duration: 1.5,
									easing: AnEase.easeOut,
								},
								updater: field.getUpdater()
							});
							// Добавляем анимацию на сцену
							const offsetX = AnRnd.float(-CellSize * 0.3, CellSize * 0.3);
							const offsetY = AnRnd.float(-CellSize * 0.3, CellSize * 0.3);
							blastFX.position.set(pixelPos.x + offsetX, pixelPos.y + offsetY);
							blastFX.blendMode = G.forceLowQulity ? "normal" : "add";
							field.fxLayer.attach(blastFX);
							field.addGraphics(blastFX);
						}

						if (block.special) block.activatedType = bomb.activatedType;
						field.applyBlock(block);

						if (currentIndex === affectedBlocks.length - 1) // последний блок уничтожен 
							destroyFunc?.();

						++currentIndex;
					}
				}
			});


		}

		protected activateRocket(rocket: Block, destroyFunc?: AnVoidCallback)
		{
			const field = this as unknown as Field;
			const pos = rocket.gridPos;

			AnSounds.play(
				`sounds/spec_rocket.snd.mp3`,
				0.6,
				AnMath.remapClamp(pos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
				AnRnd.float(0.9, 1.1)
			);

			// Определяем направление ракеты по ее типу
			let rowStep = 0;
			let colStep = 0;
			let rotationAngle = 0; // Угол поворота ракеты

			switch (rocket.type)
			{
				case 'spec_rocket_horizontal':
					colStep = 1;
					rotationAngle = Math.PI / 2;
					break;
				case 'spec_rocket_vertical':
					rowStep = 1;
					rotationAngle = Math.PI;
					break;
				case 'spec_rocket_diagonal1':
					rowStep = 1;
					colStep = 1;
					rotationAngle = 3 * Math.PI / 4;
					break;
				case 'spec_rocket_diagonal2':
					rowStep = 1;
					colStep = -1;
					rotationAngle = -3 * Math.PI / 4;
					break;
			}

			// === Добавляем анимацию полета ракеты ===
			// Функция для создания анимации ракеты в заданном направлении
			const createRocketAnimation = (startRow: number, startCol: number, directionRow: number, directionCol: number, angle: number) =>
			{
				// Определяем начальную позицию
				const startPos = new GridPos(startRow, startCol).toPixelPos();
				// startPos.x += CellHalfSize;
				// startPos.y += CellHalfSize;

				// Определяем конечную позицию в заданном направлении
				let endRow = startRow;
				let endCol = startCol;

				while (!field.isOutOfBounds(endRow + directionRow, endCol + directionCol))
				{
					endRow += directionRow;
					endCol += directionCol;
				}

				const endPos = new GridPos(endRow, endCol).toPixelPos();
				// endPos.x += CellHalfSize;
				// endPos.y += CellHalfSize;

				const duration = AnMath.distance(startPos, endPos) / CellSize * 0.1;

				// Создаем анимацию полета ракеты
				let trailTimer: AnTimer | null = null;
				const rocketFX = new AnFX({
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './fxRocket',
					anchor: AnAnchor.Center,
					loopTween: {
						from: {
							position: {
								x: startPos.x,
								y: startPos.y
							}
						},
						to: {
							position: {
								x: endPos.x,
								y: endPos.y
							},
						},
						duration,
						easing: AnEase.linear,
						callbacks: {
							onComplete: () => trailTimer?.terminate()
						}
					},
					updater: field.getUpdater()
				});

				trailTimer = new AnTimer({
					duration: 0.025,
					updater: field.getUpdater(),
					loopCount: Infinity,
					callbacks: {
						onComplete: () =>
						{
							const blastFX = new AnFX({
								atlas: 'atlases/game.ss.pixi.atlas',
								sprite: './fxBlastMini',
								anchor: AnAnchor.Center,
								loopTween: {
									from: {
										alpha: 0.7,
										scale: {
											x: 0.3,
											y: 0.3
										}
									},
									to: {
										alpha: 0,
										scale: {
											x: 2,
											y: 2
										}
									},
									duration: 1,
									easing: AnEase.easeOut,
								},
								updater: field.getUpdater()
							});
							// Добавляем анимацию на сцену
							blastFX.position.set(rocketFX.x, rocketFX.y);
							blastFX.blendMode = G.forceLowQulity ? "normal" : "add";
							field.fxLayer.attach(blastFX);
							field.addGraphics(blastFX);
						}
					}
				});

				// Устанавливаем начальный поворот
				rocketFX.rotation = angle;

				rocketFX.scale.set(1.6, 1.6);
				// Добавляем анимацию на сцену
				field.addGraphics(rocketFX);
				field.animLayer.attach(rocketFX);
			};

			// Запускаем анимации для обоих направлений
			createRocketAnimation(pos.row, pos.col, rowStep, colStep, rotationAngle);
			createRocketAnimation(pos.row, pos.col, -rowStep, -colStep, rotationAngle + Math.PI);

			// Функция для запуска таймера в заданном направлении
			const startDirectionTimer = (rowDir: number, colDir: number) =>
			{
				let step = 1;

				const timer = new AnTimer({
					duration: 0.1,
					loopCount: Infinity,
					updater: field.getUpdater(),
					callbacks: {
						onComplete: () =>
						{
							const row = pos.row + rowDir * step;
							const col = pos.col + colDir * step;

							// Проверяем выход за границы
							if (field.isOutOfBounds(row, col))
							{
								timer.stop();
								return;
							}


							const cell = field.getCell(row, col);
							if (cell)
							{
								const block = cell.block;
								if (block && !block.highlighted && !cell.hasModifier(CellModifier.Cage))
								{
									block.highlighted = true;

									new AnTimer({
										duration: 0.5,
										updater: field.getUpdater(),
										callbacks: {
											onComplete: () =>
											{
												// если спешалы активируют краску тоже
												if (G.specialsSpreyPaint)
													block.activatedAndPainted = rocket.activatedAndPainted;

												if (block.special) block.activatedType = rocket.activatedType;
												field.applyBlock(block);
											}
										}
									});
								}
							}

							step++;
						}
					}
				});
			};

			// Запускаем таймеры для обоих направлений
			startDirectionTimer(rowStep, colStep);
			startDirectionTimer(-rowStep, -colStep);

			destroyFunc?.();
		}

	}
}