// platform/PlatformYandex.ts
import { AnSaveData } from 'angine/utils/AnStorage.js';
import { PlatformInterface, PlatformBase, PlatformAds, PlatformAdsCallbacks, PlatformEvent } from './Platform.js';
import { AnLog } from 'angine/utils/AnLog.js';
import { AnVoidCallback, struct } from 'angine/utils/AnHelpers.js';


export class PlatformGameMonetize extends PlatformBase implements PlatformInterface
{
	private sdk: any | null = null;

	private onAdsOpenCallback: AnVoidCallback | null = null;
	private onAdsCloseCallback: AnVoidCallback | null = null;

	async init(): Promise<void>
	{
		return new Promise<void>((resolve, reject) =>
		{
			// Локальная функция для инициализации SDK
			const initializeSdk = () =>
			{
				if (!this._initialized)
				{
					// @ts-ignore
					if (!window.sdk)
						throw new Error('[GameMonetize SDK] не загружен, произошла ошибка!');


					// @ts-ignore
					this.sdk = window.sdk;
					this._initialized = true;
					AnLog.info('[GameMonetize SDK] успешно загружен и проинициализирован');
				}
			};

			// назначаем обработчик событий
			// AD_CANCELED - реклама не сработала
			// AD_SDK_FINISHED  IMA is ready for new requests.
			// @ts-ignore
			window.sdkRouteEvent = (e) =>
			{
				if (AnConfig.devMode)
					AnLog.debug(`[GameMonetize SDK] Событие: ${e.name}`);

				switch (e.name)
				{
					case "SDK_GAME_PAUSE":
						// pause game logic / mute audio
						this.onAdsOpenCallback?.();
						this.onAdsOpenCallback = null;
						break;
					case "SDK_GAME_START":
						// advertisement done, resume game logic and unmute audio
						this.onAdsCloseCallback?.();
						this.onAdsCloseCallback = null;
						break;
					case "SDK_READY":
						try
						{
							initializeSdk();
							resolve();
						} catch (error)
						{
							reject(error);
						}
						break;
				}
			}

			// Проверяем, что SDK уже не загружен
			try
			{
				// @ts-ignore
				if (window.sdk)
				{
					initializeSdk();
					resolve();
				}
			}
			catch (error)
			{
				reject(error);
			}
		});
	}


	// модификация параметров игры исходя из платформы
	public modifyGameParams(G: any): void
	{
		super.modifyGameParams(G);

		G.moreGamesURL = "https://olegantipov.com/";
		G.btnDoubleReward = true;
		G.btnMoreMoves = true;
		G.musicStreaming = false;

		// показать рекламу сразу после загрузки
		G.adsShowAfterLoading = true;

	};


	// === Реклама ===
	private get adsAvailable()
	{
		return Boolean(
			this.sdk &&
			typeof this.sdk.showBanner === 'function'
		);
	}

	public showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks)
	{
		super.showAds(type, callbacks);

		if (!this.adsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug(`[GameMonetize SDK] реклама не доступна!`);
			callbacks.onError?.();
			return;
		}

		switch (type)
		{
			case PlatformAds.Fullscreen:

				this.onAdsOpenCallback = callbacks.onOpen ?? null;
				this.onAdsCloseCallback = callbacks.onClose ?? null;
				this.sdk.showBanner();

				break;
			case PlatformAds.Rewarded:
				this.onAdsOpenCallback = callbacks.onOpen ?? null;
				this.onAdsCloseCallback = callbacks.onCloseRewarded ?? null;
				this.sdk.showBanner();

				break;
		}
	}
}