import { CellHalfSize, CellSize, GridPos } from "./Field.js";
import { AnVoidCallback, enhance } from "angine/utils/AnHelpers.js";
import { AnUpdatableMixin, AnUpdatableInterface, AnUpdatableConfig } from "angine/mixins/AnUpdatableMixin.js";
import { AnUIGroupElement, AnUIGroupElementConfig } from "angine/ui/AnUIGroupElement.js";
import { AnImage } from "angine/ui/AnImage.js";
import { AnTween } from "angine/anim/AnTween.js";
import { AnUpdater } from "angine/utils/AnUpdater.js";
import { AnCore } from "angine/core/AnCore.js";
import { AnEase } from "angine/anim/AnEase.js";
import { AnRnd } from "angine/utils/AnRnd.js";
import { AnTask } from "angine/utils/AnTask.js";
import { PIXI } from "angine/singleton.js";
import { safeDestroyFunc } from 'angine/utils/AnHelpers.js';
import { AnAnchor } from "angine/ui/AnAnchor.js";
import { AnLog } from "angine/utils/AnLog.js";
import { IRenderLayer } from "pixi.js";
import { GameTheme } from "./Game.js";
import { AnEvent, AnEvents } from "angine/utils/AnEvents.js";
import { AnSounds } from "angine/audio/AnSounds.js";
import { AnMath } from "angine/utils/AnMath.js";
import { GameApp } from "../GameApp.js";
import { G } from "./G.js";



export type BlockTypeProps = 0 | 1 | 2 | 3 | 4 | 5 | 6;


export const BonusSpecBlockTypeArray = [
	"spec_bomb",
	"spec_dice",
	"spec_rainbow",
	"spec_mirror",
	"spec_chest",
	"spec_rocket_horizontal",
	"spec_rocket_vertical",
	"spec_rocket_diagonal1",
	"spec_rocket_diagonal2",
] as const;

export const SpecBlockTypeArray = [...BonusSpecBlockTypeArray, "spec_heart", "spec_stone"] as const;

export const PropBlockTypeArray = [
	"prop_0",
	"prop_1",
	"prop_2",
	"prop_3",
	"prop_4",
	"prop_5",
	"prop_6",
] as const;

export type SpecBlockType = typeof SpecBlockTypeArray[number];
export type PropBlockType = typeof PropBlockTypeArray[number];
export type BlockType = SpecBlockType | PropBlockType | "prop_heart" | "spec_chest_opened";


export interface BlockConfig extends AnUpdatableConfig, AnUIGroupElementConfig
{
	pos: GridPos;
	type: BlockType;
	theme?: GameTheme;
	skipCreatingAnim?: boolean;
	makeMarkableAnim?: boolean;
	delayCreatingAnim?: number,
	blockLayer?: PIXI.IRenderLayer;
	selectionLayer?: PIXI.IRenderLayer;
}

export class Block
	extends enhance(AnUIGroupElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{
	public theme: GameTheme | null;
	private _type: BlockType;
	private pic: AnImage;
	private selector1: AnImage;
	private selector2: AnImage;
	private selectorSpecial: AnImage | null = null;

	private _gridPos: GridPos = new GridPos(0, 0);
	private _targetPos: GridPos = new GridPos(0, 0);

	private tweenPic: AnTween | null = null;
	private tweenPicTypeChange: AnTween | null = null;
	private tweenSelector1: AnTween | null = null;
	private tweenSelector2: AnTween | null = null;
	private tweenSelectorSpecial: AnTween | null = null;
	private tweenPos: AnTween | null = null;

	private selector1_update: AnTask | null = null;
	private selector2_update: AnTask | null = null;

	private _canMove: boolean = false;
	private _highlighted: boolean = false;
	private _selected: boolean = false;


	// для спец блоков - каким типом они были активированны
	public activatedType: BlockType | null = null;
	// для спец блоков - сохраняем выделенные удаляемые блоки
	public activatedBlocks: Block[] | null = null;
	// блок активирован на закрашенной ячейке
	public activatedAndPainted: boolean = false;


	// помечаем сразу удаленные блоки, чтобы исключить дальнейшие проверки по массивам
	private _removed: boolean = false;

	constructor(config: BlockConfig)
	{
		config.anchor = config.anchor ?? AnAnchor.Center;
		super(config);

		//? не нужно?
		if (config.updater) this.addToUpdater(config.updater);

		this.theme = config.theme ?? null;
		this.scaledWidth = CellSize;
		this.scaledHeight = CellSize;
		this._type = config.type;
		this._gridPos.set(config.pos);
		this._targetPos.set(config.pos);

		const { x, y } = config.pos.toPixelPos();
		this.position.set(x, y);



		this.selector1 = new AnImage(
			{
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './selector',
				anchor: AnAnchor.Center, // отключаем стратегию адоптации, будем весь контейнер масштабировать
			});
		this.selector1.position.set(CellHalfSize, CellHalfSize);
		this.addUIElement("selector1", this.selector1);

		this.selector2 = new AnImage(
			{
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: './selector',
				anchor: AnAnchor.Center,// отключаем стратегию адоптации, будем весь контейнер масштабировать
			});
		this.selector2.position.set(CellHalfSize, CellHalfSize);
		this.addUIElement("selector2", this.selector2);

		this.selector1.visible = this.selector2.visible = false;
		this.selector1.blendMode = G.forceLowQulity ? "normal" : "add";
		this.selector2.blendMode = G.forceLowQulity ? "normal" : "add";

		if (config.selectionLayer)
		{
			config.selectionLayer.attach(this.selector1);
			config.selectionLayer.attach(this.selector2);
		}


		this.addToCleanup(() =>
		{
			if (this.selector1_update)
			{
				this.selector1_update.removeFromUpdater();
				this.selector1_update = null;
			}

			if (this.selector2_update)
			{
				this.selector2_update.removeFromUpdater();
				this.selector2_update = null;
			}
		});


		// добавляем основную иконку
		this.pic = new AnImage(
			{
				atlas: 'atlases/game.ss.pixi.atlas',
				sprite: `./${this._type}` + (this.theme ? `_${this.theme}` : ""),
				anchor: AnAnchor.Center, // отключаем стратегию адоптации, будем весь контейнер масштабировать
			});
		this.pic.position.set(CellHalfSize, CellHalfSize);
		this.addUIElement("pic", this.pic);
		if (config.blockLayer)
			config.blockLayer.attach(this.pic);


		if (this.special)
		{
			const durationAnim = 3;
			let addSpecialTweenAnim = true;

			// не добавляем анимацию для этих типов блоков
			if (this.specialStone)// || this.specialHeart)
			{
				addSpecialTweenAnim = false;
			}

			// для спецблока выделяем анимацией иконку
			if (addSpecialTweenAnim)
			{
				this.tweenPic = new AnTween({
					target: this.pic,
					from: { scale: { x: 1.0, y: 1.0 } },
					to: { scale: { x: 1.15, y: 1.15 } },
					duration: durationAnim,
					easing: AnEase.easeInOut,
					repeat: Infinity,
					reverse: true,
					updater: this.getUpdater(),
				});
			}

			// добавляем подсветку если это спецблок
			this.selectorSpecial = new AnImage(
				{
					atlas: 'atlases/game.ss.pixi.atlas',
					sprite: './selectorSpecial',
					anchor: AnAnchor.Center, // отключаем стратегию адоптации, будем весь контейнер масштабировать
				});

			// подсветку также анимируем
			if (addSpecialTweenAnim)
			{
				this.tweenSelectorSpecial = new AnTween({
					target: this.selectorSpecial,
					from: { alpha: 0.6, scale: { x: 3.5, y: 3.5 } },
					to: { alpha: 0.7, scale: { x: 4.5, y: 4.5 } },
					duration: durationAnim,
					easing: AnEase.easeInOutBack,
					repeat: Infinity,
					reverse: true,
					updater: this.getUpdater(),
				});
			}

			this.addUIElement("selectorSpecial", this.selectorSpecial);
			this.selectorSpecial.blendMode = G.forceLowQulity ? "normal" : "add";
			if (config.selectionLayer)
				config.selectionLayer.attach(this.selectorSpecial);

			this.selectorSpecial.position.set(this.pic.x, this.pic.y);
			//this.selectorSpecial.scale.set(4.5);

		}



		if (!config.skipCreatingAnim)
		{
			const makeMarkableAnim: boolean = this.specialStone || this.specialHeart || (config.makeMarkableAnim ?? false);

			// анимация создания блока сверху поля
			let sndBlockPlayed = false;
			const snd_name = this.specialStone ? `stone` : (this.specialHeart ? `heart` : ``);
			new AnTween({
				target: this,
				from: { alpha: 0, scale: makeMarkableAnim ? { x: 2, y: 2 } : { x: 0.4, y: 0.4 }, position: { x: this.x, y: this.y - 80 } },
				//to: { alpha: 1, scale: { x: 0.9, y: 0.9 } },
				to: { alpha: 1, scale: { x: 1, y: 1 }, position: { x: this.x, y: this.y } },
				tolerance: makeMarkableAnim ? 0.1 : 0.3,
				duration: makeMarkableAnim ? 1.5 : 0.4,
				delay: config.delayCreatingAnim ?? 0,
				easing: makeMarkableAnim ? AnEase.easeOutBounce : AnEase.easeOutBack,
				updater: this.getUpdater(),
				callbacks: {
					onUpdate: (tween: AnTween, progress: number) =>
					{
						if (snd_name.length && progress > 0.5 && !sndBlockPlayed)
						{
							sndBlockPlayed = true;
							AnSounds.play(
								`sounds/${snd_name}.snd.mp3`,
								AnRnd.float(0.4, 0.6),
								AnMath.remapClamp(this._gridPos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
								AnRnd.float(0.9, 1.1)
							);
						}
					},
					onComplete: () => this._canMove = true
				}
			});
		}
		else
			this._canMove = true;


		this.addToCleanup(() => 
		{
			this.tweenPic?.terminate();
			this.tweenPicTypeChange?.terminate();
			this.tweenPos?.terminate();
			this.tweenSelector1?.terminate();
			this.tweenSelector2?.terminate()
			this.tweenSelectorSpecial?.terminate();
		});


		this.addToCleanup(AnEvents.on("storage:theme:update",
			(e: AnEvent) => this.onSettingsThemeUpdate(e.data.value as GameTheme)).unsub);
	}

	private onSettingsThemeUpdate(theme: GameTheme): void
	{
		if (this.prop && this.type != "prop_heart")
		{
			this.theme = theme;
			this.updatePic();
		}
	}

	public prepareToApply()
	{
		// if (this.destroyed)
		// {
		// 	AnLog.error(`prepareToApply: блок уже удалён [${this.type}]!`);
		// 	return;
		// }


		this.highlighted = false;

		if (!this.selector1.destroyed)
		{
			this.selector1.visible = false;
			this.selector1.parentRenderLayer.detach(this.selector1);
		}

		if (!this.selector2.destroyed)
		{
			this.selector2.visible = false;
			this.selector2.parentRenderLayer.detach(this.selector2);
		}

		if (this.selectorSpecial && !this.selectorSpecial.destroyed)
		{
			this.selectorSpecial.visible = false;
			this.selectorSpecial.parentRenderLayer.detach(this.selectorSpecial);
		}

		if (!this.pic.destroyed)
		{
			this.pic.parentRenderLayer.detach(this.pic);
		}

		this.tweenPos?.stop();
	}


	// отдельный метод для контроля, чтобы случайно не пометить как удаленный через свойство
	public markAsRemoved()
	{
		this._removed = true;
	}

	get removed(): boolean
	{
		return this._removed;
	}

	get moving(): boolean
	{
		return this.tweenPos?.running ?? false;
	}

	public get type(): BlockType
	{
		return this._type;
	}

	public showSelectors()
	{
		this.selector1.renderable = true;
		this.selector2.renderable = true;
	}

	public hideSelectors()
	{
		this.selector1.renderable = false;
		this.selector2.renderable = false;
	}

	public setTypeNoAnim(type: BlockType)
	{
		if (this._type === type) return;

		this._type = type;
		this.updatePic();
	}

	private updatePic()
	{
		this.pic.changeTexture('./' + this._type + (this.prop ? `_${this.theme}` : ""), 'atlases/game.ss.pixi.atlas');
	}

	public set type(type: BlockType)
	{
		if (this._type === type) return;

		this._type = type;

		if (this.tweenPicTypeChange)
		{
			this.tweenPicTypeChange.finish();
			this.tweenPicTypeChange.terminate();
			this.tweenPicTypeChange = null;
		}

		this.tweenPicTypeChange = new AnTween({
			target: this.pic,
			from: { alpha: 1, rotation: 0 },
			to: { alpha: 0, rotation: Math.PI },
			duration: 1,
			easing: AnEase.easeInElastic,
			updater: this.getUpdater(),
			callbacks: {
				onComplete: () =>
				{
					if (this.tweenPicTypeChange)
					{
						//this.tweenPicTypeChange.finish();
						this.tweenPicTypeChange.terminate();
						this.tweenPicTypeChange = null;
					}

					this.pic.changeTexture('./' + this._type + (this.prop ? `_${this.theme}` : ""), 'atlases/game.ss.pixi.atlas');

					this.tweenPicTypeChange = new AnTween({
						target: this.pic,
						from: { alpha: 0, rotation: Math.PI },
						to: { alpha: 1, rotation: 0 },
						duration: 0.5,
						easing: AnEase.easeOutBack,
						updater: this.getUpdater(),
					});
				}
			}
		});
	}

	public get canMoveNotHighlighted(): boolean
	{
		return this._canMove && !this.highlighted;
	}

	public get canMove(): boolean
	{
		return this._canMove;
	}

	public get selected(): boolean
	{
		return this._selected;
	}
	public set selected(value: boolean)
	{
		this._selected = value;
	}

	public get highlighted(): boolean
	{
		return this._highlighted;
	}

	public set highlighted(value: boolean)
	{
		if (this._highlighted === value) return;
		this._highlighted = value;

		if (this.tweenPic)
		{
			this.tweenPic.finish();
			this.tweenPic.terminate();
			this.tweenPic = null;
		}

		if (this.tweenSelector1)
		{
			this.tweenSelector1.finish();
			this.tweenSelector1.terminate();
			this.tweenSelector1 = null;
		}

		if (this.tweenSelectorSpecial)
		{
			this.tweenSelectorSpecial.finish();
			this.tweenSelectorSpecial.terminate();
			this.tweenSelectorSpecial = null;
		}

		if (this.tweenSelector2)
		{
			this.tweenSelector2.finish();
			this.tweenSelector2.terminate();
			this.tweenSelector2 = null;
		}

		const selectorScale = 1.45;
		const selectorAlpha = 0.4;
		const selectorRotationSpeed1 = 0.15;
		const selectorRotationSpeed2 = 0.15;
		if (this._highlighted)
		{

			this.tweenPic = new AnTween({
				target: this.pic,
				from: { scale: { x: 1, y: 1 } },
				to: { scale: { x: 1.25, y: 1.25 } },
				duration: 1,
				easing: AnEase.easeOutElastic,
				updater: this.getUpdater(),
			});

			this.selector1.visible = true;
			this.tweenSelector1 = new AnTween({
				target: this.selector1,
				from: { alpha: 0, scale: { x: 0.2, y: 0.2 } },
				to: { alpha: selectorAlpha, scale: { x: selectorScale, y: selectorScale } },
				duration: 1,
				easing: AnEase.easeOutBack,
				updater: this.getUpdater(),
			});

			this.selector1_update = new AnTask({
				handler: (dt: number) => this.selector1.rotation += selectorRotationSpeed1 * dt,
				updater: this.getUpdater(),
			});

			this.selector2.visible = true;
			this.tweenSelector2 = new AnTween({
				target: this.selector2,
				from: { alpha: 0, scale: { x: 0.2, y: 0.2 } },
				to: { alpha: selectorAlpha, scale: { x: selectorScale, y: selectorScale } },
				duration: 1,
				easing: AnEase.easeOutBack,
				updater: this.getUpdater(),
			});

			this.selector2_update = new AnTask({
				handler: (dt: number) => this.selector2.rotation -= selectorRotationSpeed2 * dt,
				updater: this.getUpdater(),
			});
		}
		else
		{
			this.tweenPic = new AnTween({
				target: this.pic,
				to: { scale: { x: 1, y: 1 } },
				from: { scale: { x: 1.25, y: 1.25 } },
				duration: 1,
				easing: AnEase.easeOut,
				updater: this.getUpdater(),
			});

			this.tweenSelector1 = new AnTween({
				target: this.selector1,
				to: { alpha: 0, scale: { x: 0.2, y: 0.2 } },
				from: { alpha: selectorAlpha, scale: { x: selectorScale, y: selectorScale } },
				duration: 1,
				easing: AnEase.easeOut,
				updater: this.getUpdater(),
				callbacks: {
					onComplete: () => this.selector1.visible = false,
				}
			});
			if (this.selector1_update)
			{
				this.selector1_update.removeFromUpdater();
				this.selector1_update = null;
			}

			this.tweenSelector2 = new AnTween({
				target: this.selector2,
				to: { alpha: 0, scale: { x: 0.2, y: 0.2 } },
				from: { alpha: selectorAlpha, scale: { x: selectorScale, y: selectorScale } },
				duration: 1,
				easing: AnEase.easeOut,
				updater: this.getUpdater(),
				callbacks: {
					onComplete: () => this.selector2.visible = false,
				}
			});
			if (this.selector2_update)
			{
				this.selector2_update.removeFromUpdater();
				this.selector2_update = null;
			}
		}
	}

	public updateGridPos(row: number, col: number)
	{
		this._gridPos.row = row;
		this._gridPos.col = col;
	}

	public calcGridPos(): GridPos
	{
		return new GridPos(
			Math.floor(this.position.y / CellSize),// - CellHalfSize),
			Math.floor(this.position.x / CellSize),// - CellHalfSize),
		);
	}
	public syncGridPosWithPixelPos(): void
	{
		const pos = this.calcGridPos();
		this._gridPos.set(pos);
		this._targetPos.set(pos);
	}


	// это специальный блок
	public get special(): boolean
	{
		return this._type.startsWith("spec_");
	}

	public get specialStone(): boolean
	{
		return this._type.startsWith("spec_stone");
	}

	public get specialHeart(): boolean
	{
		return this._type.startsWith("spec_heart");
	}

	public get specialRocket(): boolean
	{
		return this._type.startsWith("spec_rocket");
	}

	public get specialBomb(): boolean
	{
		return this._type.startsWith("spec_bomb");
	}
	public get specialRainbow(): boolean
	{
		return this._type.startsWith("spec_rainbow");
	}

	public get specialDice(): boolean
	{
		return this._type.startsWith("spec_dice");
	}

	public get specialMirror(): boolean
	{
		return this._type.startsWith("spec_mirror");
	}

	public get specialChest(): boolean
	{
		return this._type.startsWith("spec_chest");
	}

	// это обычный блок
	public get prop(): boolean
	{
		return this._type.startsWith("prop_");
	}

	public get gridPos(): GridPos
	{
		return this._gridPos;
	}

	public get targetPos(): GridPos
	{
		return this._targetPos;
	}


	public moveTo(pos: GridPos, dropAnims: boolean = false)
	{
		const oldPos = this._gridPos;
		const newPos = pos;

		this._targetPos.set(pos);

		if (this.tweenPos)
			this.tweenPos.terminate();


		const duration = (newPos.row - oldPos.row) * (dropAnims ? 0.35 : 0.3);

		let sndBlockPlayed = false;
		this.tweenPos = new AnTween({
			target: this,
			from: { position: oldPos.toPixelPos() },
			to: { position: newPos.toPixelPos() },
			duration,
			delay: dropAnims ? AnRnd.float(0, 0.2) : 0,
			//easing: duration >= 1.5 ? AnEase.easeOutBounce : (duration <= 0.5 ? AnEase.easeOut : AnEase.easeOutBack),
			easing: dropAnims ? AnEase.easeOutBounce : AnEase.easeOutBack,
			updater: this.getUpdater(),
			callbacks:
			{
				onUpdate: (tween: AnTween, progress: number) =>
				{
					const pos = this.calcGridPos();
					this._gridPos.set(pos);

					if (progress > 0.5 && !sndBlockPlayed)
					{
						sndBlockPlayed = true;
						AnSounds.play(
							`sounds/block0${AnRnd.int(1, 5)}.snd.mp3`,
							AnRnd.float(0.4, 0.6) * 0.5,
							AnMath.remapClamp(pos.col, 0, GameApp.self.game.field.colsCount - 1, -0.5, 0.5),
							AnRnd.float(0.9, 1.1)
						);
					}
				},
				onComplete: () =>
				{
					this._gridPos.set(newPos);
				}
			}
		});
	}

}