	/**
	 * Распаковывает данные с помощью fflate с поддержкой пароля
	 * @param data - Бинарные данные ZIP-архива
	 * @returns Promise с распакованными файлами в формате Record<string, Uint8Array>
	 * @throws Error при ошибках распаковки
	 * @private
	 */
	private static async unzip(data: Uint8Array): Promise<Record<string, Uint8Array>>
	{
		return new Promise((resolve, reject) =>
		{
			unzip(
				new Uint8Array(data),
				{},
				(err, unzipped) =>
				{
					if (err)
					{
						reject(new Error(`Ошибка распаковки архива: ${err.message}`));
					} else
					{
						resolve(unzipped);
					}
				}
			);
		});
	}

