// platform/PlatformYandex.ts
import { AnSaveData } from 'angine/utils/AnStorage.js';
import { PlatformInterface, PlatformBase, PlatformAds, PlatformAdsCallbacks, PlatformEvent } from './Platform.js';
import { AnLog } from 'angine/utils/AnLog.js';
import { AnVoidCallback } from 'angine/utils/AnHelpers.js';

export class PlatformWGPlayground extends PlatformBase implements PlatformInterface
{
	//private sdk: any | null = null;

	private get sdk(): any
	{
		// @ts-ignore
		return window[window.preroll.config.loaderObjectName];
	}

	async init(): Promise<void>
	{

		//! костыль для их SDK
		await this.waitForSDKFullLoaded();


		// @ts-ignore
		if (!(window.preroll?.config?.loaderObjectName))
			throw new Error('[WGPlayground SDK] не загружен, произошла ошибка!');


		// @ts-ignore
		//this.sdk = window[window.preroll.config.loaderObjectName];


		// if (!this.sdk)
		// 	throw new Error('[WGPlayground SDK] не инициализирован, произошла ошибка!');

		this.sdk.registerRewardCallbacks({
			onReady: () => { if (AnConfig.devMode) AnLog.debug('[WGPlayground SDK] rewarded реклама готова') },//called when a rewarded ad is ready to be displayed
			onSuccess: () => { if (AnConfig.devMode) AnLog.debug('[WGPlayground SDK] rewarded onSuccess'); this.onCloseRewarded?.(); this.onCloseRewarded = null; },//the ad is finished, user should be rewarded with the prize
			onFail: () => { if (AnConfig.devMode) AnLog.debug('[WGPlayground SDK] rewarded onFail'); this.onClose?.(); this.onClose = null; } //the ad dispaly was canceled, user should not be rewarded with the prize
		});


		this._initialized = true;
		AnLog.info('[WGPlayground SDK] успешно загружен и проинициализирован');
	}

	//! костыль, но без этого SDK инициализируется просто в случайный момент
	private waitForSDKFullLoaded(): Promise<void>
	{
		return new Promise((resolve) =>
		{
			const checkInterval = setInterval(() =>
			{
				// @ts-ignore
				if (window.preroll?.config?.loaderObjectName !== undefined && this.sdk)
				{
					clearInterval(checkInterval); // Останавливаем проверку
					resolve(); // Разрешаем Promise
				}
			}, 100); // Проверяем каждые 100 мс
		});
	}

	// модификация параметров игры исходя из платформы
	public modifyGameParams(G: any): void
	{
		super.modifyGameParams(G);

		// Параметры для яндекса
		G.moreGamesURL = "";
		G.btnDoubleReward = true;
		G.btnMoreMoves = true;
		G.musicStreaming = false;
	};


	// === Реклама ===
	private get adsAvailable()
	{
		return Boolean(
			this.sdk &&
			typeof this.sdk.showRewardAd === 'function' &&
			typeof this.sdk.refetchAd === 'function'
		);
	}

	private onCloseRewarded: AnVoidCallback | null = null;
	private onClose: AnVoidCallback | null = null;
	public showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks)
	{
		super.showAds(type, callbacks);

		if (!this.adsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug(`[WGPlayground SDK] реклама не доступна!`);
			callbacks.onError?.();
			return;
		}

		switch (type)
		{
			case PlatformAds.Fullscreen:
				callbacks.onOpen?.();

				this.sdk.refetchAd(() => callbacks.onClose?.());

				break;
			case PlatformAds.Rewarded:

				// this.sdk.registerRewardCallbacks({
				// 	onReady: () => { if (AnConfig.devMode) AnLog.debug('[WGPlayground SDK] rewarded реклама готова') },//called when a rewarded ad is ready to be displayed
				// 	onSuccess: () => callbacks.onCloseRewarded?.(),//the ad is finished, user should be rewarded with the prize
				// 	onFail: () => callbacks.onClose?.() //the ad dispaly was canceled, user should not be rewarded with the prize
				// });

				this.onCloseRewarded = () => callbacks.onCloseRewarded?.();
				this.onClose = () => callbacks.onClose?.();

				this.sdk.showRewardAd();
				break;
		}
	}

}