import { PIXI } from "angine/singleton";
import { AnVoidCallback, Constructor } from "angine/utils/AnHelpers";
import { AnUpdater } from "angine/utils/AnUpdater";

/**
 * Интерфейс позволяет сразу добавить объект в нужный апдейтер
 */
export interface AnUpdatableConfig
{
	updater?: AnUpdater | null;
}


/**
 * Интерфейс для объектов, которые могут обновляться через AnUpdater.
 * 
 * Содержит:
 * 1. Ссылку на текущий AnUpdater (_updater)
 * 2. Методы для привязки/удаления из AnUpdater
 * 3. Обязательный метод update(dt)
 * 
 * Реализуется автоматически через AnMixinUpdatable.
 */
export interface AnUpdatableInterface
{
	/**
	 * Добавляет объект в менеджер обновлений
	 * возвращает функцию отписки
	 */
	addToUpdater(updater: AnUpdater): AnVoidCallback;

	/** Получить ссылку на текущий AnUpdater */
	getUpdater(): AnUpdater | null;

	/** Отвязывает объект от текущего AnUpdater */
	removeFromUpdater(): void;

	/**
	 * Вызывается каждый кадр для обновления состояния.
	 * @param dt - Дельта времени в секундах с последнего кадра
	 */
	update(dt: number): void;
}

/** проверка что объект использует миксин AnUpdatableMixin*/
export function isAnUpdatable(object: any)
{
	return object && object['AnUpdatableMixin'] === 'AnUpdatableMixin';
}

/**
 * Миксин для добавления функциональности обновляемого объекта
 * 
 * Что добавляет в класс:
 * 1. Автоматическую привязку к AnUpdater
 * 2. Методы для управления подпиской на обновления
 * 3. Базовую реализацию системы обновления
 * 
 * @param Base - Базовый класс для расширения
 * @returns Класс с добавленной функциональностью
 */
export function AnUpdatableMixin<TBase extends Constructor>(Base: TBase)
{
	return class AnUpdatable extends Base implements AnUpdatableInterface
	{
		/** Метка идентификации миксина */
		public readonly AnUpdatableMixin = 'AnUpdatableMixin';


		/** Ссылка на текущий AnUpdater */
		private updater: AnUpdater | null = null;


		/**
		 * Привязывает объект к менеджеру обновлений
		 * @param updater - Экземпляр AnUpdater
		 */
		private bind(updater: AnUpdater): void
		{
			if (this.updater !== null)
			{ // если был привязан к другому - удаляемся из него
				this.removeFromUpdater();
			}
			updater.add(this);
			this.updater = updater;
		}

		/**
		 * Получить ссылку на текущий AnUpdater
		 */
		public getUpdater(): AnUpdater | null
		{
			return this.updater;
		}

		/**
		 * Добавляет объект в менеджер обновлений
		 * возвращает функцию отписки
		 */
		public addToUpdater(updater: AnUpdater): AnVoidCallback
		{
			this.bind(updater);
			return () => this.removeFromUpdater();
		}

		/**
		 * Удаляет объект из текущего менеджера обновлений
		 */
		public removeFromUpdater(): void
		{
			this.updater?.remove(this);
			this.updater = null;
		}



		/**
		 * Базовый метод обновления (требует переопределения)
		 * @param dt - Дельта времени в секундах
		 */
		public update(dt: number): void
		{
			//throw new Error("Метод update() должен быть реализован");
		}
	};
}