import { Constructor } from "angine/utils/AnHelpers";

/**
 * Интерфейс для объектов, поддерживающих работу с тегами
 */
export interface AnTaggableInterface
{
	/**
	 * Добавляет тег к объекту
	 * @param tag - Добавляемый тег
	 * @returns Возвращает сам объект для чейнинга
	 */
	addTag(tag: string): this;

	/**
	 * Удаляет тег из объекта
	 * @param tag - Удаляемый тег
	 * @returns Возвращает сам объект для чейнинга
	 */
	removeTag(tag: string): this;

	/**
	 * Проверяет наличие тега у объекта
	 * @param tag - Проверяемый тег
	 * @returns true если тег присутствует
	 */
	hasTag(tag: string): boolean;

	/**
	 * Возвращает список всех тегов объекта
	 * @returns Массив строк с тегами
	 */
	getTags(): string[];

	/**
	 * Очищает все теги объекта
	 * @returns Возвращает сам объект для чейнинга
	 */
	clearTags(): this;
}


/**
 * Миксин для добавления функциональности работы с тегами
 * @param Base - Базовый класс для расширения
 * @returns Класс с добавленной функциональностью работы с тегами
 */
export function AnTaggableMixin<TBase extends Constructor>(Base: TBase)
{
	return class AnTaggable extends Base implements AnTaggableInterface
	{
		private _tags: Set<string> = new Set();

		/**
		 * Добавляет тег к объекту
		 * @param tag - Добавляемый тег
		 * @returns Возвращает сам объект для чейнинга
		 */
		public addTag(tag: string): this
		{
			this._tags.add(tag.toLowerCase());
			return this;
		}

		/**
		 * Удаляет тег из объекта
		 * @param tag - Удаляемый тег
		 * @returns Возвращает сам объект для чейнинга
		 */
		public removeTag(tag: string): this
		{
			this._tags.delete(tag.toLowerCase());
			return this;
		}

		/**
		 * Проверяет наличие тега у объекта
		 * @param tag - Проверяемый тег
		 * @returns true если тег присутствует
		 */
		public hasTag(tag: string): boolean
		{
			return this._tags.has(tag.toLowerCase());
		}

		/**
		 * Возвращает список всех тегов объекта
		 * @returns Массив строк с тегами
		 */
		public getTags(): string[]
		{
			return Array.from(this._tags);
		}

		/**
		 * Очищает все теги объекта
		 * @returns Возвращает сам объект для чейнинга
		 */
		public clearTags(): this
		{
			this._tags.clear();
			return this;
		}
	};
}
