// Перечисление состояний кнопки
export enum AnButtonState
{
	Normal = "normal",
	Hover = "hover",
	Pressed = "pressed",
}

export enum AnButtonDisabledStyle
{
	Opacity = "opacity", // alpha = 0.5
	Darken = "darken", // tint = 0.333333
}


export enum AnIconAlign
{
	Left = "left",
	Right = "right",
	Center = "center"
}


export interface AnButtonCallbacks
{
	onClick?: AnVoidCallback;
}


export interface AnButtonConfig extends AnUIGroupElementConfig
{
	sprite: AnImageConfig;
	spriteAdoptSlice9Factor?: number;
	hoverSprite?: AnImageConfig;
	hoverScale?: { x: number, y: number };
	pressOffset?: { x: number, y: number };
	padding?: number;
	icon?: AnImageConfig;
	hoverIcon?: AnImageConfig;
	iconAlign?: AnIconAlign; // выравнивание для случая иконка + текст
	iconScale?: { x: number, y: number };
	labelText?: AnLabelConfig;
	labelTextOffset?: { x: number, y: number };
	labelTextColorHover?: number;
	disabledStyle?: AnButtonDisabledStyle;
	callbacks?: AnButtonCallbacks;
}

/**
 * Класс кнопки с поддержкой различных состояний и возможностью добавления текста/иконки
 * Наследуется от AnUIGroupElement для группировки элементов (фон, текст, иконка)
 */
export class AnButton
	extends enhance(AnUIGroupElement).with(AnUpdatableMixin)
	implements AnUpdatableInterface
{

	private _state: AnButtonState = AnButtonState.Normal;

	private padding: number;

	protected sprite: AnImage;
	protected spriteAdoptSlice9Factor: number;
	protected hoverSprite: AnImage | null = null;

	protected icon: AnImage | null = null;
	protected hoverIcon: AnImage | null = null;
	private iconAlign: AnIconAlign;
	private labelText: AnLabel | null = null;
	private labelTextColor: number | null = null;
	private labelTextHoverColor: number | null = null;

	private stateTween: AnTween | null = null;
	// private posTween: AnTween | null = null;

	private _enabled: boolean = true; // Состояние вкл/выкл кнопки
	private disabledStyle: AnButtonDisabledStyle;

	private callbacks: AnButtonCallbacks;

	constructor(config: AnButtonConfig)
	{
		super(config);

		this.callbacks = config.callbacks ?? {};

		this.padding = config.padding ?? 0;
		this.spriteAdoptSlice9Factor = config.spriteAdoptSlice9Factor ?? 1;

		this.sprite = this.addUIElement("sprite", new AnImage(config.sprite));
		if (config.hoverSprite)
		{
			this.hoverSprite = this.addUIElement("hoverSprite", new AnImage(config.hoverSprite));
			this.hoverSprite.visible = false;
		}

		if (config.labelText)
		{
			this.labelText = this.addUIElement("labelText",
				new AnLabel(
					{
						...config.labelText,
						anchor: AnAnchor.Center
					}
				));

			if (config.labelTextColorHover)
			{
				this.labelTextColor = this.labelText.textColor;
				this.labelTextHoverColor = config.labelTextColorHover;
			}
		}

		if (config.icon)
		{
			this.icon = this.addUIElement("icon",
				new AnImage({
					...config.icon,
					anchor: AnAnchor.Center,
				})
			);
		}

		this.iconAlign = config.iconAlign ?? AnIconAlign.Center;


		// +++ resize strategy +++
		this.defaultResizeStrategy = () =>
		{
			// отступы с края кнопки и между содержимым
			const padding = scaled(this.padding);

			// Общее масштабирование фона
			this.sprite.scale9Adopt = AnViewport.scale * this.spriteAdoptSlice9Factor;
			if (this.hoverSprite) this.hoverSprite.scale9Adopt = AnViewport.scale * this.spriteAdoptSlice9Factor;

			this.sprite.setScaledSize(this.scaledWidth, this.scaledHeight);
			this.hoverSprite?.setScaledSize(this.scaledWidth, this.scaledHeight);

			this.sprite.applyDefaultResizeStrategy();
			this.hoverSprite?.applyDefaultResizeStrategy();

			// === Подготовка общих значений ===
			const buttonCenterX = this.scaledWidth * 0.5;
			const buttonCenterY = this.scaledHeight * 0.5;
			const labelOffsetX = scaled(config.labelTextOffset?.x ?? 0);
			const labelOffsetY = scaled(config.labelTextOffset?.y ?? 0);


			// Если есть иконка — настраиваем её размер
			if (this.icon)
			{
				const iconHeight = this.scaledHeight - padding * 2;
				const iconWidth = iconHeight * this.icon.realSizeRatio;
				const iconScaleX = config.iconScale?.x ?? 1;
				const iconScaleY = config.iconScale?.y ?? 1;
				this.icon.setScaledSize(iconWidth * iconScaleX, iconHeight * iconScaleY);
				this.icon.applyDefaultResizeStrategy();
			}

			// === Настраиваем размер текста (если есть) ===
			if (this.labelText)
			{
				let textWidth = this.scaledWidth - padding * 2;

				// Уменьшаем ширину текста, если рядом с ним есть иконка (кроме Center)
				if (this.icon && this.iconAlign !== AnIconAlign.Center)
				{
					textWidth -= this.icon?.scaledWidth + padding * 2;
				}

				this.labelText.setScaledSize(textWidth, this.scaledHeight - padding * 2);
				this.labelText.applyDefaultResizeStrategy();
			}

			// === Позиционирование элементов ===
			if (this.icon && this.labelText)
			{
				// Случай: иконка + текст
				switch (this.iconAlign)
				{
					case AnIconAlign.Left:
						this.icon.position.set(this.icon.scaledWidth / 2 + padding * 2, buttonCenterY);
						this.labelText.position.set(this.scaledWidth + labelOffsetX - this.labelText.scaledWidth / 2 - padding, buttonCenterY + labelOffsetY);
						break;
					case AnIconAlign.Right:
						this.icon.position.set(this.scaledWidth - this.icon.scaledWidth / 2 - padding * 2, buttonCenterY);
						this.labelText.position.set(labelOffsetX + this.labelText.scaledWidth / 2 + padding, buttonCenterY + labelOffsetY);
						break;
					case AnIconAlign.Center:
					default:
						this.icon.position.set(buttonCenterX, buttonCenterY);
						this.labelText.position.set(buttonCenterX + labelOffsetX, buttonCenterY + labelOffsetY);
						break;
				}
			}
			else if (this.icon)
			{
				// Только иконка
				this.icon.position.set(buttonCenterX, buttonCenterY);
			}
			else if (this.labelText)
			{
				// Только текст
				this.labelText.position.set(buttonCenterX + labelOffsetX, buttonCenterY + labelOffsetY);
			}
		}

		this.configResizeStrategy(config.resizeStrategy);

		this.setupEventHandlers();

		this.disabledStyle = config.disabledStyle ?? AnButtonDisabledStyle.Darken;
		this.setEnabled(this._enabled);

		// Очищаем твин
		this.addToCleanup(() => this.stateTween?.terminate());
	}


	public get enabled(): boolean
	{
		return this._enabled;
	}

	public set enabled(value: boolean)
	{
		this.setEnabled(value);
	}

	/**
	 * Включает или отключает кнопку
	 * @param enabled true для включения, false для отключения
	 */
	public setEnabled(enabled: boolean): void
	{
		if (this._enabled === enabled) return;

		this._enabled = enabled;

		if (enabled)
		{
			switch (this.disabledStyle)
			{
				case AnButtonDisabledStyle.Opacity:
					// Восстанавливаем нормальное состояние
					this.sprite.alpha = 1;
					if (this.hoverSprite) this.hoverSprite.alpha = 1;
					if (this.labelText) this.labelText.alpha = 1;
					if (this.icon) this.icon.alpha = 1;
					break;
				case AnButtonDisabledStyle.Darken:
					this.sprite.tint = 0xffffff;
					if (this.hoverSprite) this.hoverSprite.tint = 0xffffff;
					break;
			}
		} else
		{
			// Применяем стиль отключенного состояния
			switch (this.disabledStyle)
			{
				case AnButtonDisabledStyle.Opacity:
					this.sprite.alpha = 0.5;
					if (this.hoverSprite) this.hoverSprite.alpha = 0.5;
					if (this.labelText) this.labelText.alpha = 0.5;
					if (this.icon) this.icon.alpha = 0.5;
					break;
				case AnButtonDisabledStyle.Darken:
					this.sprite.tint = 0x555555;
					if (this.hoverSprite) this.hoverSprite.tint = 0x555555;
					break;
			}

			// Если кнопка была нажата или в состоянии hover при отключении
			if (this._state !== AnButtonState.Normal)
			{
				this.state = AnButtonState.Normal;
			}
		}
	}

	public setIcon(icon: string, atlas: string)
	{
		if (!this.icon) return;

		this.icon.changeTexture(icon, atlas);
	}

	private setupEventHandlers()
	{
		if (!AnControls.isTouchEnabled)
			this.addToCleanup(AnEvents.on(this.controlsRouter + AnControlsEvent.PointerMove, this.onMove.bind(this)).unsub);

		this.addToCleanup(AnEvents.on(this.controlsRouter + AnControlsEvent.PointerDown, this.onDown.bind(this)).unsub);
		this.addToCleanup(AnEvents.on(this.controlsRouter + AnControlsEvent.PointerUp, this.onUp.bind(this)).unsub);
	}

	private onMove(e: AnEvent): void
	{
		// Если кнопка отключена, не реагируем на события
		if (!this._enabled || !this.visible) return;

		const pixelPos = new PIXI.Point(e.data.x, e.data.y);
		const isPointInside = this.isPointInside(pixelPos);
		if (this._state === AnButtonState.Pressed)
		{
			if (!isPointInside) this.state = AnButtonState.Normal;
			return;
		}


		this.state = isPointInside ? AnButtonState.Hover : AnButtonState.Normal;
	}
	private onDown(e: AnEvent): void
	{
		// Если кнопка отключена, не реагируем на события
		if (!this._enabled || !this.visible) return;

		if (this._state === AnButtonState.Pressed) return;

		const pixelPos = new PIXI.Point(e.data.x, e.data.y);
		this.state = this.isPointInside(pixelPos) ? AnButtonState.Pressed : AnButtonState.Normal;
	}
	private onUp(e: AnEvent): void
	{
		// Если кнопка отключена, не реагируем на события
		if (!this._enabled || !this.visible) return;

		if (this._state !== AnButtonState.Pressed) return;

		const pixelPos = new PIXI.Point(e.data.x, e.data.y);
		this.state = this.isPointInside(pixelPos) && !AnControls.isTouchEnabled ? AnButtonState.Hover : AnButtonState.Normal;

		//! стоит убрать хардкод в будущем
		AnSounds.play(
			`sounds/click.snd.mp3`,
			0.6,
		);
		AnControls.vibrate(50);

		this.callbacks.onClick?.();
	}

	public setText(text: AnTextSource)
	{
		this.labelText?.setText(text);
	}

	public get state(): AnButtonState
	{
		return this._state;
	}
	public set state(value: AnButtonState)
	{
		// Если кнопка отключена, всегда держим normal состояние
		if (!this._enabled)
			value = AnButtonState.Normal;

		if (this._state === value) return;

		this._state = value;


		if (this.stateTween)
		{
			//this.stateTween.finish();
			this.stateTween.terminate();
			this.stateTween = null;
		}


		switch (this.state)
		{
			case AnButtonState.Normal:

				if (this.hoverSprite)
				{
					this.sprite.visible = true;
					this.hoverSprite.visible = false;
				}

				if (this.labelText && this.labelTextColor)
					this.labelText.textColor = this.labelTextColor;


				this.stateTween = new AnTween({
					target: this,
					to: { scale: { x: 1, y: 1 } },
					duration: 0.6,
					easing: AnEase.easeOutBack,
					updater: this.getUpdater(),
					autoRemove: true,
					callbacks: {
						onComplete: () => this.stateTween = null
					}
				});
				break;
			case AnButtonState.Hover:

				if (this.hoverSprite)
				{
					this.sprite.visible = false;
					this.hoverSprite.visible = true;
				}

				if (this.labelText && this.labelTextHoverColor)
					this.labelText.textColor = this.labelTextHoverColor;

				this.stateTween = new AnTween({
					target: this,
					to: { scale: { x: 1.1, y: 1.1 } },
					duration: 0.6,
					easing: AnEase.easeOutBack,
					updater: this.getUpdater(),
					autoRemove: true,
					callbacks: {
						onComplete: () => this.stateTween = null
					}
				});
				break;
			case AnButtonState.Pressed:

				if (this.hoverSprite)
				{
					this.sprite.visible = false;
					this.hoverSprite.visible = true;
				}

				if (this.labelText && this.labelTextHoverColor)
					this.labelText.textColor = this.labelTextHoverColor;

				this.stateTween = new AnTween({
					target: this,
					to: { scale: { x: 0.95, y: 0.95 } },
					duration: 0.6,
					easing: AnEase.easeOutBack,
					updater: this.getUpdater(),
					autoRemove: true,
					callbacks: {
						onComplete: () => this.stateTween = null
					}
				});
				break;
		}
	}
}