import { PIXI } from "angine/singleton";


export type AnBounds =
	{
		left: number;
		right: number;
		top: number;
		bottom: number;
	}

/**Набор вспомогательных математических функций**/
export class AnMath
{

	public static readonly toDeg: number = 57.295779513082320876798154814105;
	public static readonly toRad: number = 0.017453292519943295769236907684886;


	/**
	 * число четное
	 */
	public static isEven(val: number): boolean
	{
		return val % 2 === 0;
	}

	/**
	 * число нечетное
	 */
	public static isOdd(val: number): boolean
	{
		return val % 2 !== 0;
	}


	/**
	 * Переводит число val из диапазона A..B в диапазон C..D
	 */
	public static remap(val: number, A: number, B: number, C: number, D: number): number
	{
		return C + (D - C) * (val - A) / (B - A);
	}

	/**
	 * Переводит число val из диапазона A..B в диапазон C..D c ограничением до этого диапазона
	 */
	public static remapClamp(val: number, A: number, B: number, C: number, D: number): number
	{
		return AnMath.remap(AnMath.clamp(val, A, B), A, B, C, D);
	}

	public static distance(point1: { x: number, y: number }, point2: { x: number, y: number }): number
	{
		const dx = point2.x - point1.x;
		const dy = point2.y - point1.y;
		return Math.sqrt(dx * dx + dy * dy);
	}

	/**
	 * Сравнивает два числа с плавающей запятой с заданной погрешностью.
	 * @param a Первое число.
	 * @param b Второе число.
	 * @param eps Погрешность (по умолчанию 1e-9).
	 * @returns `true`, если числа равны с учётом погрешности, иначе `false`.
	 */
	public static floatEqual(a: number, b: number, eps: number = 1e-9): boolean
	{
		return Math.abs(a - b) < eps;
	}

	/**
	 * Линейная интерполяция между двумя значениями.
	 * @param start Начальное значение.
	 * @param end Конечное значение.
	 * @param t Коэффициент интерполяции (от 0 до 1).
	 * @returns Интерполированное значение.
	 */
	public static lerp(start: number, end: number, t: number): number
	{
		return start * (1 - t) + end * t;
	}

	public static lerpColor(start: number, end: number, progress: number): number
	{
		// Извлекаем компоненты RGB для начального и конечного цветов
		const startR = (start >> 16) & 0xff;
		const startG = (start >> 8) & 0xff;
		const startB = start & 0xff;

		const endR = (end >> 16) & 0xff;
		const endG = (end >> 8) & 0xff;
		const endB = end & 0xff;

		// Интерполируем каждый компонент
		const r = AnMath.clamp(Math.round(startR + (endR - startR) * progress), 0, 255);
		const g = AnMath.clamp(Math.round(startG + (endG - startG) * progress), 0, 255);
		const b = AnMath.clamp(Math.round(startB + (endB - startB) * progress), 0, 255);

		// Возвращаем результат в формате number (0xRRGGBB)
		return (r << 16) | (g << 8) | b;
	}

	/**
	 * Обрезать число до диапазона from..to
	 */
	public static clamp(val: number, from: number, to: number)
	{
		return val < from ? from : (val > to ? to : val);
	}

	/**
	 * Находится ли число в диапазоне от lRange до uRange
	 */
	public static inRange(Num: number, lRange: number, uRange: number): boolean
	{
		return (Num >= lRange) && (Num <= uRange);
	}

	/**
	 * Получить ближайшее число к arg — Val1 или Val2
	 */
	public static closest(arg: number, Val1: number, Val2: number): number
	{
		return (Math.abs(arg - Val1) < Math.abs(arg - Val2)) ? Val1 : Val2;
	}


	public static rotate90<T>(matrix: T[][]): T[][]
	{
		const rows = matrix.length;
		const cols = matrix[0].length;
		const result: T[][] = [];

		// Поворот на 90° по часовой стрелке
		for (let j = 0; j < cols; j++)
		{
			const newRow: T[] = [];
			for (let i = rows - 1; i >= 0; i--)
			{
				newRow.push(matrix[i][j]);
			}
			result.push(newRow);
		}

		return result;
	}

	public static rotate180<T>(matrix: T[][]): T[][]
	{
		const rows = matrix.length;
		const cols = matrix[0].length;
		const result: T[][] = [];

		// Поворот на 180° - переворачиваем и строки и столбцы
		for (let i = rows - 1; i >= 0; i--)
		{
			const newRow: T[] = [];
			for (let j = cols - 1; j >= 0; j--)
			{
				newRow.push(matrix[i][j]);
			}
			result.push(newRow);
		}

		return result;
	}

	public static rotate270<T>(matrix: T[][]): T[][]
	{
		const rows = matrix.length;
		const cols = matrix[0].length;
		const result: T[][] = [];

		// Поворот на 270° по часовой стрелке (90° против часовой)
		for (let j = cols - 1; j >= 0; j--)
		{
			const newRow: T[] = [];
			for (let i = 0; i < rows; i++)
			{
				newRow.push(matrix[i][j]);
			}
			result.push(newRow);
		}

		return result;
	}



	// вписать один прямоугольник во второй
	public static fitRectangleToRectangle(
		width: number,
		height: number,
		width2: number,
		height2: number
	): { width: number, height: number }
	{
		// Рассчитываем пропорции для вписывания по ширине
		const widthRatio = width / width2;
		const heightByWidth = height2 * widthRatio;

		// Рассчитываем пропорции для вписывания по высоте
		const heightRatio = height / height2;
		const widthByHeight = width2 * heightRatio;

		// Выбираем вариант с максимальной площадью
		if (heightByWidth <= height)
		{
			return { width, height: heightByWidth };
		} else
		{
			return { width: widthByHeight, height };
		}
	}


	/**
	 * Округляет число ВНИЗ до ближайшего кратного значения
	 * @param value - Исходное число
	 * @param multiple - Кратность (по умолчанию 10)
	 * @returns Округленное число
	 */
	public static floorToMultiple(value: number, multiple: number = 10): number
	{
		return Math.floor(value / multiple) * multiple;
	}

	/**
	 * Округляет число ВВЕРХ до ближайшего кратного значения
	 * @param value - Исходное число
	 * @param multiple - Кратность (по умолчанию 10)
	 * @returns Округленное число
	 */
	public static ceilToMultiple(value: number, multiple: number = 10): number
	{
		return Math.ceil(value / multiple) * multiple;
	}

	/**
	 * Округляет число до ближайшего кратного значения
	 * @param value - Исходное число  
	 * @param multiple - Кратность (по умолчанию 10)
	 * @returns Округленное число
	 */
	public static roundToMultiple(value: number, multiple: number = 10): number
	{
		return Math.round(value / multiple) * multiple;
	}
}