// platform/PlatformYandex.ts
import { AnSaveData } from 'angine/utils/AnStorage.js';
import { PlatformInterface, PlatformBase, PlatformAds, PlatformAdsCallbacks, PlatformEvent } from './Platform.js';
import { AnLog } from 'angine/utils/AnLog.js';
import { SDK, Player } from 'ysdk';

export class PlatformYandex extends PlatformBase implements PlatformInterface
{
	private sdk: SDK | null = null;
	private player: Player | null = null;

	async init(): Promise<void>
	{
		// @ts-ignore
		if (!window.YaGames)
			throw new Error('[Yandex SDK] не загружен, произошла ошибка!');


		// @ts-ignore
		this.sdk = await window.YaGames.init();


		if (!this.sdk)
			throw new Error('[Yandex SDK] не инициализирован, произошла ошибка!');


		this.player = await this.sdk.getPlayer();

		if (!this.player)
			AnLog.warn(`[Yandex SDK] данные игрока не получены!`);


		this._initialized = true;
		AnLog.info('[Yandex SDK] успешно загружен и проинициализирован');
	}

	// переопределяем визуальное отображение платформы (копирайты ага)
	public get visualName(): string | null
	{
		return 'yg';
	};


	// модификация параметров игры исходя из платформы
	public modifyGameParams(G: any): void
	{
		super.modifyGameParams(G);

		// Параметры для яндекса
		G.moreGamesURL = "";
		G.btnDoubleReward = true;
		G.btnMoreMoves = true;
		G.musicStreaming = false;

	};


	// === Пользователь ===

	get playerName(): string
	{
		//return this.playerLoggedIn ? this.player!.getName() : "";
		return "";
	};

	get playerLoggedIn(): boolean
	{
		return this.player?.isAuthorized() ?? false;
	};

	get currentLanguage(): string | null
	{
		const lang = this.sdk?.environment.i18n.lang ?? null;

		if (lang === null)
			return null;

		// ru для be, kk, uk, uz;
		// en для остальных языков.

		if (['ru', 'be', 'kk', 'uk', 'uz'].includes(lang)) return 'ru';

		return 'en';
	}

	// === Разметка событий для платформы ===
	public reportEvent(event: PlatformEvent): void
	{
		super.reportEvent(event);

		if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] Сообщаем о новом событии: ${event}`);

		switch (event)
		{
			case PlatformEvent.GameLoaded:
				this.sdk?.features.LoadingAPI.ready();
				break;
			case PlatformEvent.GameplayStart:
				this.sdk?.features.GameplayAPI.start();
				break;
			case PlatformEvent.GameplayStop:
				this.sdk?.features.GameplayAPI.stop();
				break;
		}
	}

	// === Таблицы рекордов ===
	private get leaderboardsAvailable()
	{
		return Boolean(
			this.sdk &&
			this.sdk.leaderboards &&
			typeof this.sdk.leaderboards.setScore === 'function'
		);
	}


	public sendScoreToLeaderboard(boardID: string, score: number): void
	{
		if (!this.leaderboardsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] таблицы рекордов не доступны!`);
			return;
		}

		if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] пробуем отправить данные [${score}] в таблицу рекордов ${boardID}...`);

		this.sdk!.leaderboards.setScore(boardID, score)
			.then(() =>
			{
				if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] успешно отправили данные в таблицу рекордов!`);
			})
			.catch((error: unknown) =>
			{
				if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] ошибка при отправке данных в таблицу рекордов: ${error}`);
			});
	}

	// === Реклама ===
	private get adsAvailable()
	{
		return Boolean(
			this.sdk &&
			this.sdk.adv &&
			typeof this.sdk.adv.showFullscreenAdv === 'function' &&
			typeof this.sdk.adv.showRewardedVideo === 'function'
		);
	}

	public showAds(type: PlatformAds, callbacks: PlatformAdsCallbacks)
	{
		super.showAds(type, callbacks);

		if (!this.adsAvailable)
		{
			if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] реклама не доступна!`);
			callbacks.onError?.();
			return;
		}

		switch (type)
		{
			case PlatformAds.Fullscreen:
				this.sdk!.adv.showFullscreenAdv({
					callbacks: {
						onOpen: () => callbacks.onOpen?.(),
						onClose: () => callbacks.onClose?.(),
						onError: () => callbacks.onError?.(),
						onOffline: () => callbacks.onError?.(),
					}
				});
				break;
			case PlatformAds.Rewarded:
				{
					let rewarded = false;
					this.sdk!.adv.showRewardedVideo({
						callbacks: {
							onOpen: () => callbacks.onOpen?.(),
							onError: () => callbacks.onError?.(),

							onClose: () =>
							{
								if (rewarded)
									callbacks.onCloseRewarded?.();
								else
									callbacks.onClose?.();
							},

							onRewarded: () => rewarded = true,
						}
					});
				}
				break;
		}
	}

	// === Облачные сохранения ===

	private get cloudDataAvailable()
	{
		return Boolean(
			this.player &&
			typeof this.player.getData === 'function' &&
			typeof this.player.setData === 'function'
		);
	}

	public async loadData(): Promise<AnSaveData>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		let data: any = null;

		try
		{
			data = await this.player?.getData();
		}
		catch (error)
		{
			throw new Error('Ошибка чтения данных из облачного хранилища!');
		}

		if (!data)
			throw new Error('Данные в облачном хранилище недоступны!');

		if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] данные успешно загружены из облачного хранилища`);

		return data;
	}

	public async saveData(data: AnSaveData): Promise<void>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		try
		{
			await this.player!.setData(data);
			if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] данные успешно сохранены в облачном хранилище`);
			return;
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] данные НЕ сохранены, ошибка в облачном хранилище: ${error}`);
			return;
		}
	}

	public async clearData(): Promise<void>
	{
		if (!this.cloudDataAvailable) throw new Error('облачное сохранение не доступно!');

		try
		{
			await this.player!.setData({});
			if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] облачное хранилище успешно очищено`);
			return;
		}
		catch (error)
		{
			if (AnConfig.devMode) AnLog.debug(`[Yandex SDK] ошибка очистки облачного хранилища: ${error}`);
			return;
		}
	}
}